@Test
void testGetClassSimpleNameFromFqName() {
    assertThat(getClassSimpleNameFromFqName("com.example.OuterClass")).isEqualTo("OuterClass");
    assertThat(getClassSimpleNameFromFqName("com.example.OuterClass.InnerClass")).isEqualTo("InnerClass");
    assertThat(getClassSimpleNameFromFqName("com.example.OuterClass$InnerClass")).isEqualTo("InnerClass");
}

@Test
void testInvalidInput() {
    assertThatThrownBy(() -> getClassSimpleNameFromFqName(null)).isInstanceOf(NullPointerException.class).hasMessage("Fully qualified class name cannot be null");
    assertThatThrownBy(() -> getClassSimpleNameFromFqName("")).isInstanceOf(IllegalArgumentException.class).hasMessage("Fully qualified class name cannot be empty");
    assertThatThrownBy(() -> getClassSimpleNameFromFqName("  ")).isInstanceOf(IllegalArgumentException.class).hasMessage("Fully qualified class name cannot be empty");
}

@Test
void testGetClientTimeout() {
    Configuration configuration = new Configuration();
    configuration.set(ClientOptions.CLIENT_TIMEOUT, Duration.ofSeconds(10));
    assertThat(configuration.get(ClientOptions.CLIENT_TIMEOUT)).isEqualTo(Duration.ofSeconds(10));
    configuration = new Configuration();
    configuration.set(ClientOptions.CLIENT_TIMEOUT, Duration.ofSeconds(20));
    assertThat(configuration.get(ClientOptions.CLIENT_TIMEOUT)).isEqualTo(Duration.ofSeconds(20));
    configuration = new Configuration();
    assertThat(configuration.get(ClientOptions.CLIENT_TIMEOUT)).isEqualTo(ClientOptions.CLIENT_TIMEOUT.defaultValue());
}

