    PackagedProgram prg = PackagedProgram.newBuilder().setEntryPointClassName(TestExecutionPlan.class.getName()).setArguments("/dev/random", "/tmp").build();
    Pipeline pipeline = PackagedProgramUtils.getPipelineFromProgram(prg, new Configuration(), 666, true);
    String jsonExecutionPlan = FlinkPipelineTranslationUtil.translateToJSONExecutionPlan(prg.getUserCodeClassLoader(), pipeline);
    assertThat(jsonExecutionPlan).isNotNull();
    assertThat(jsonExecutionPlan).contains("\"type\" : \"Source: MySource\"", "\"type\" : \"MyMap\",", "\"type\" : \"MySink: Writer\",");
    assertThat(jsonExecutionPlan).contains("\"parallelism\" : 666");
    assertThat(jsonExecutionPlan).doesNotContain("\\");
    System.out.println(jsonExecutionPlan);
}

