void testThatIntermittentlyFailingEntriesAreEnqueuedOnToTheBufferWithCorrectSize() throws IOException, InterruptedException {
    AsyncSinkWriterImpl sink = new AsyncSinkWriterImplBuilder().context(sinkInitContext).maxRecordSizeInBytes(110).simulateFailures(true).build();
    // Buffer: 100/110B; 1/10 elements; 0 inflight
    sink.write(String.valueOf(225));
    //   Buffer: 104/110B; 2/10 elements; 0 inflight
    sink.write(String.valueOf(1));
    //   Buffer: 108/110B; 3/10 elements; 0 inflight
    sink.write(String.valueOf(2));
    //   Buffer: 112/110B; 4/10 elements; 0 inflight -- flushing
    sink.write(String.valueOf(3));
    assertThat(res.size()).isEqualTo(// Request was [225, 1, 2], element 225 failed on first attempt
    2);
    //   Buffer:   8/110B; 2/10 elements; 1 inflight
    sink.write(String.valueOf(4));
    //   Buffer:  12/110B; 3/10 elements; 1 inflight
    sink.write(String.valueOf(5));
    //   Buffer:  16/110B; 4/10 elements; 1 inflight
    sink.write(String.valueOf(6));
    // Buffer: 116/110B; 5/10 elements; 1 inflight -- flushing
    sink.write(String.valueOf(325));
    // inflight request is processed, buffer: [225, 3, 4, 5, 6, 325]
    assertThat(res).isEqualTo(Arrays.asList(1, 2, 225, 3, 4));
    // Buffer: [5, 6, 325]; 0 inflight
}

