    // buffer: [225, 2], inflight: [], destination: [0, 1]
    sink.flush(false);
    assertThat(res).isEqualTo(Arrays.asList(0, 1));
    assertThatBufferStatesAreEqual(sink.wrapRequests(225, 2), getWriterState(sink));
