/**
 * This test is somewhat testing the implementation instead of contract. This is because the
 * test is trying to make sure the element queue draining thread is not tight looping.
 */
@Test
public void testCloseBlockingWaitingForFetcherShutdown() throws Exception {
    final String splitId = "testSplit";
    // create a reader which blocks on close().
    final AwaitingReader<Integer, TestingSourceSplit> reader = new AwaitingReader<>();
    final SplitFetcherManager<Integer, TestingSourceSplit> fetcherManager = createFetcher(splitId, reader, new Configuration());
    // Now close the fetcher manager. The fetcher should still be running when the fetcher
    // manager returns.
    Thread closingThread = new Thread(() -> {
        try {
            fetcherManager.close(Long.MAX_VALUE);
        } catch (Exception e) {
            fail("failed.");
            throw new RuntimeException(e);
        }
    }, "closingThread");
    closingThread.start();
    waitUntil(() -> findThread(SplitFetcherManager.THREAD_NAME_PREFIX).size() == 2, Duration.ofSeconds(30), "The element queue draining thread should have started.");
    for (Thread t : findThread(SplitFetcherManager.THREAD_NAME_PREFIX)) {
        waitUntil(() -> t.getState().equals(Thread.State.WAITING) || t.getState().equals(Thread.State.TIMED_WAITING), Duration.ofSeconds(30), "All the executor threads should be in waiting status.");
    }
    assertThat(fetcherManager.getQueue().getAvailabilityFuture().getNumberOfDependents()).as("The future should have just one dependent stage").isLessThanOrEqualTo(1);
    assertThat(fetcherManager.fetchers.size()).isEqualTo(1);
    reader.triggerThrowException();
    reader.triggerClose();
    waitUntil(fetcherManager.fetchers::isEmpty, "The fetcher should be closed now.");
    closingThread.join();
}

@Test
void testIdleShutdownSplitFetcherWaitsUntilRecordProcessed() throws Exception {
    final String splitId = "testSplit";
    final AwaitingReader<Integer, TestingSourceSplit> reader = new AwaitingReader<>(new IOException("Should not happen"), new RecordsBySplits<>(Collections.emptyMap(), Collections.singleton(splitId)));
    final SplitFetcherManager<Integer, TestingSourceSplit> fetcherManager = createFetcher(splitId, reader, new Configuration());
    try {
        FutureCompletingBlockingQueue<RecordsWithSplitIds<Integer>> queue = fetcherManager.getQueue();
        // Wait util the data batch is emitted.
        queue.getAvailabilityFuture().get();
        waitUntil(() -> {
            fetcherManager.maybeShutdownFinishedFetchers();
            return fetcherManager.getNumAliveFetchers() == 0;
        }, Duration.ofSeconds(1), "The fetcher should have already been removed from the alive fetchers.");
        // There should be two fetches available, one for data (although empty), one for the
        // shutdown synchronization (also empty).
        waitUntil(() -> queue.size() == 2, Duration.ofSeconds(1), "The element queue should have 2 batches when the fetcher is closed.");
        // Finish the first batch (data batch).
        queue.poll().recycle();
        assertThat(reader.isClosed).as("The reader should have not been closed.").isFalse();
        // Finish the second batch (synchronization batch).
        queue.poll().recycle();
        waitUntil(() -> reader.isClosed, Duration.ofSeconds(1), "The reader should hava been closed.");
    } finally {
        fetcherManager.close(30_000);
    }
}

/**
