void testPerSplitWatermark(boolean emitRecordBeforeSplitAddition) throws Exception {
    MockSplitReader mockSplitReader = MockSplitReader.newBuilder().setNumRecordsPerSplitPerFetch(3).setBlockingFetch(true).build();
    MockSourceReader reader = new MockSourceReader(() -> mockSplitReader, new Configuration(), new TestingReaderContext());
    SourceOperator<Integer, MockSourceSplit> sourceOperator = createTestOperator(reader, WatermarkStrategy.forGenerator((context) -> new OnEventWatermarkGenerator()), true);
