        harness.processElement(new StreamRecord<>(Either.Left(new CommittableWithLineage<>(committable("0", ".6", 7), 3L, 0))));
        // new pending file written this time
        harness.processElement(new StreamRecord<>(Either.Left(new CommittableWithLineage<>(committable("0", "7", 8), 3L, 0))));
        harness.processElement(new StreamRecord<>(Either.Left(new CommittableSummary<>(0, 1, 4L, 0, 0, 0))));
        harness.processElement(new StreamRecord<>(Either.Left(new CommittableSummary<>(0, 1, 5L, 3, 3, 0))));
        // 1 summary + (1 compacted committable + 1 compacted cleanup) * 6 + 1 hidden + 1 normal
        // + 1 summary + 1 cleanup + 1 summary
        ListAssert<CommittableMessage<FileSinkCommittable>> results = assertThat(harness.extractOutputValues()).hasSize(18);
        results.element(0, as(committableSummary()));
        List<FileSinkCommittable> expectedResult = Arrays.asList(committable("0", "compacted-0", 1), cleanupPath("0", ".0"), committable("0", "compacted-1", 2), cleanupPath("0", ".1"), committable("0", "compacted-2", 3), cleanupPath("0", ".2"), committable("0", "compacted-3", 4), cleanupPath("0", ".3"), committable("0", "compacted-4", 5), cleanupPath("0", ".4"), committable("0", "compacted-5", 6), cleanupPath("0", ".5"), committable("0", "compacted-6", 7), committable("0", "7", 8));
        for (int i = 0; i < expectedResult.size(); ++i) {
            results.element(i + 1, as(committableWithLineage())).hasCommittable(expectedResult.get(i));
        }
        results.element(15, as(committableSummary()));
        results.element(16, as(committableWithLineage())).hasCommittable(cleanupPath("0", ".6"));
        results.element(17, as(committableSummary()));
    }
}

