    DynamicFileSplitEnumerator<TestSplit> enumerator = new DynamicFileSplitEnumerator<>(context, () -> new TestDynamicFileEnumerator(splits, remainingSplits), SimpleSplitAssigner::new);
    enumerator.handleSplitRequest(0, null);
    List<String> alreadyAssigned = getAssignedSplits(context);
    enumerator.handleSourceEvent(0, mockDynamicFilteringEvent());
