void testListTaskTemporaryPaths() throws Exception {
    // only accept task-0-attempt-1
    final BiPredicate<Integer, Integer> taskAttemptFilter = (subtaskIndex, attemptNumber) -> subtaskIndex == 0 && attemptNumber == 1;
    final FileSystem fs = FileSystem.get(tmpPath.toUri());
    // invalid attempt number
    fs.mkdirs(new Path(tmpPath.toUri() + "/task-0-attempt-0"));
    // valid
    fs.mkdirs(new Path(tmpPath.toUri() + "/task-0-attempt-1"));
    // invalid subtask index
    fs.mkdirs(new Path(tmpPath.toUri() + "/task-1-attempt-0"));
    // invisible dir
    fs.mkdirs(new Path(tmpPath.toUri() + "/.task-0-attempt-1"));
    // not a task dir
    fs.mkdirs(new Path(tmpPath.toUri() + "/_SUCCESS"));
    final List<Path> taskTmpPaths = PartitionTempFileManager.listTaskTemporaryPaths(fs, new Path(tmpPath.toUri()), taskAttemptFilter);
    final List<String> taskDirs = taskTmpPaths.stream().map(Path::getName).collect(Collectors.toList());
    assertThat(taskDirs).hasSize(1).containsExactly("task-0-attempt-1");
}

