@Test
void testWithWatermarkAlignment() {
    final String watermarkGroup = "group-1";
    final Duration maxAllowedWatermarkDrift = Duration.ofMillis(200);
    final WatermarkStrategy<String> strategy = WatermarkStrategy.<String>forMonotonousTimestamps().withWatermarkAlignment(watermarkGroup, maxAllowedWatermarkDrift).// we call a different builder method on top of watermark alignment
    // to make sure it can be properly mixed
    withIdleness(Duration.ofMillis(200));
    // ensure that the closure can be cleaned
    ClosureCleaner.clean(strategy, ExecutionConfig.ClosureCleanerLevel.RECURSIVE, true);
    final WatermarkAlignmentParams alignmentParameters = strategy.getAlignmentParameters();
    assertThat(alignmentParameters.getWatermarkGroup()).isEqualTo(watermarkGroup);
    assertThat(alignmentParameters.getMaxAllowedWatermarkDrift()).isEqualTo(maxAllowedWatermarkDrift.toMillis());
    assertThat(alignmentParameters.getUpdateInterval()).isEqualTo(WatermarksWithWatermarkAlignment.DEFAULT_UPDATE_INTERVAL.toMillis());
    assertThat(strategy.createTimestampAssigner(assignerContext())).isInstanceOf(RecordTimestampAssigner.class);
    assertThat(strategy.createWatermarkGenerator(generatorContext())).isInstanceOf(WatermarksWithIdleness.class);
}

