@Test
void testGetStatisticsSingleFileWithCachedVersion() throws IOException {
    final String myString = "my mocked line 1\nmy mocked line 2\n";
    final Path tempFile = createTempFilePath(myString);
    final long size = myString.length();
    final long fakeSize = 10065;
    DelimitedInputFormat<String> format = new MyTextInputFormat();
    format.setFilePath(tempFile);
    format.configure(new Configuration());
    FileBaseStatistics stats = format.getStatistics(null);
    assertThat(stats).isNotNull();
    assertThat(stats.getTotalInputSize()).as("The file size from the statistics is wrong.").isEqualTo(size);
    format = new MyTextInputFormat();
    format.setFilePath(tempFile);
    format.configure(new Configuration());
    FileBaseStatistics newStats = format.getStatistics(stats);
    assertThat(newStats).as("Statistics object was changed.").isEqualTo(stats);
    // insert fake stats with the correct modification time. the call should return the fake
    // stats
    format = new MyTextInputFormat();
    format.setFilePath(tempFile);
    format.configure(new Configuration());
    FileBaseStatistics fakeStats = new FileBaseStatistics(stats.getLastModificationTime(), fakeSize, BaseStatistics.AVG_RECORD_BYTES_UNKNOWN);
    BaseStatistics latest = format.getStatistics(fakeStats);
    assertThat(latest.getTotalInputSize()).as("The file size from the statistics is wrong.").isEqualTo(fakeSize);
    // insert fake stats with the expired modification time. the call should return new accurate
    // stats
    format = new MyTextInputFormat();
    format.setFilePath(tempFile);
    format.configure(new Configuration());
    FileBaseStatistics outDatedFakeStats = new FileBaseStatistics(stats.getLastModificationTime() - 1, fakeSize, BaseStatistics.AVG_RECORD_BYTES_UNKNOWN);
    BaseStatistics reGathered = format.getStatistics(outDatedFakeStats);
    assertThat(reGathered.getTotalInputSize()).as("The file size from the statistics is wrong.").isEqualTo(size);
}

