@Test
void testJoinRich() throws Exception {
    final AtomicBoolean opened = new AtomicBoolean(false);
    final AtomicBoolean closed = new AtomicBoolean(false);
    final String taskName = "Test rich join function";
    final RichFlatJoinFunction<String, String, Integer> joiner = new RichFlatJoinFunction<String, String, Integer>() {

        @Override
        public void open(OpenContext openContext) {
            opened.compareAndSet(false, true);
            assertThat(getRuntimeContext().getTaskInfo().getIndexOfThisSubtask()).isZero();
            assertThat(getRuntimeContext().getTaskInfo().getNumberOfParallelSubtasks()).isOne();
        }

        @Override
        public void close() {
            closed.compareAndSet(false, true);
        }

        @Override
        public void join(String first, String second, Collector<Integer> out) {
            out.collect(first.length());
            out.collect(second.length());
        }
    };
    InnerJoinOperatorBase<String, String, Integer, RichFlatJoinFunction<String, String, Integer>> base = new InnerJoinOperatorBase<>(joiner, new BinaryOperatorInformation<>(BasicTypeInfo.STRING_TYPE_INFO, BasicTypeInfo.STRING_TYPE_INFO, BasicTypeInfo.INT_TYPE_INFO), new int[0], new int[0], taskName);
    final List<String> inputData1 = new ArrayList<>(Arrays.asList("foo", "bar", "foobar"));
    final List<String> inputData2 = new ArrayList<>(Arrays.asList("foobar", "foo"));
    final List<Integer> expected = new ArrayList<>(Arrays.asList(3, 3, 6, 6));
    final TaskInfo taskInfo = new TaskInfoImpl(taskName, 1, 0, 1, 0);
    final HashMap<String, Accumulator<?, ?>> accumulatorMap = new HashMap<>();
    final HashMap<String, Future<Path>> cpTasks = new HashMap<>();
    ExecutionConfig executionConfig = new ExecutionConfig();
    executionConfig.disableObjectReuse();
    List<Integer> resultSafe = base.executeOnCollections(inputData1, inputData2, new RuntimeUDFContext(taskInfo, null, executionConfig, cpTasks, accumulatorMap, UnregisteredMetricsGroup.createOperatorMetricGroup()), executionConfig);
    executionConfig.enableObjectReuse();
    List<Integer> resultRegular = base.executeOnCollections(inputData1, inputData2, new RuntimeUDFContext(taskInfo, null, executionConfig, cpTasks, accumulatorMap, UnregisteredMetricsGroup.createOperatorMetricGroup()), executionConfig);
    assertThat(resultSafe).isEqualTo(expected);
    assertThat(resultRegular).isEqualTo(expected);
    assertThat(opened).isTrue();
    assertThat(closed).isTrue();
}

