@Test
void testMapWithRuntimeContext() throws Exception {
    final String taskName = "Test Task";
    final AtomicBoolean opened = new AtomicBoolean();
    final AtomicBoolean closed = new AtomicBoolean();
    final MapFunction<String, Integer> parser = new RichMapFunction<String, Integer>() {

        @Override
        public void open(OpenContext openContext) {
            opened.set(true);
            RuntimeContext ctx = getRuntimeContext();
            assertThat(ctx.getTaskInfo().getIndexOfThisSubtask()).isZero();
            assertThat(ctx.getTaskInfo().getNumberOfParallelSubtasks()).isOne();
            assertThat(ctx.getTaskInfo().getTaskName()).isEqualTo(taskName);
        }

        @Override
        public Integer map(String value) {
            return Integer.parseInt(value);
        }

        @Override
        public void close() {
            closed.set(true);
        }
    };
    MapOperatorBase<String, Integer, MapFunction<String, Integer>> op = new MapOperatorBase<>(parser, new UnaryOperatorInformation<>(BasicTypeInfo.STRING_TYPE_INFO, BasicTypeInfo.INT_TYPE_INFO), taskName);
    List<String> input = new ArrayList<>(asList("1", "2", "3", "4", "5", "6"));
    final HashMap<String, Accumulator<?, ?>> accumulatorMap = new HashMap<>();
    final HashMap<String, Future<Path>> cpTasks = new HashMap<>();
    final TaskInfo taskInfo = new TaskInfoImpl(taskName, 1, 0, 1, 0);
    ExecutionConfig executionConfig = new ExecutionConfig();
    executionConfig.disableObjectReuse();
    List<Integer> resultMutableSafe = op.executeOnCollections(input, new RuntimeUDFContext(taskInfo, null, executionConfig, cpTasks, accumulatorMap, UnregisteredMetricsGroup.createOperatorMetricGroup()), executionConfig);
    executionConfig.enableObjectReuse();
    List<Integer> resultRegular = op.executeOnCollections(input, new RuntimeUDFContext(taskInfo, null, executionConfig, cpTasks, accumulatorMap, UnregisteredMetricsGroup.createOperatorMetricGroup()), executionConfig);
    assertThat(resultMutableSafe).isEqualTo(asList(1, 2, 3, 4, 5, 6));
    assertThat(resultRegular).isEqualTo(asList(1, 2, 3, 4, 5, 6));
    assertThat(opened).isTrue();
    assertThat(closed).isTrue();
}

