@Test
void testReconfiguration() {
    // mock the previous ordering of enum constants to be BAR, PAULA, NATHANIEL
    PublicEnum[] mockPreviousOrder = { PublicEnum.BAR, PublicEnum.PAULA, PublicEnum.NATHANIEL };
    // now, the actual order of FOO, BAR, PETER, NATHANIEL, EMMA, PAULA will be the "new wrong
    // order"
    EnumSerializer<PublicEnum> serializer = new EnumSerializer<>(PublicEnum.class);
    // verify that the serializer is first using the "wrong order" (i.e., the initial new
    // configuration)
    assertThat(serializer.getValueToOrdinal().get(PublicEnum.FOO).intValue()).isEqualTo(PublicEnum.FOO.ordinal());
    assertThat(serializer.getValueToOrdinal().get(PublicEnum.BAR).intValue()).isEqualTo(PublicEnum.BAR.ordinal());
    assertThat(serializer.getValueToOrdinal().get(PublicEnum.PETER).intValue()).isEqualTo(PublicEnum.PETER.ordinal());
    assertThat(serializer.getValueToOrdinal().get(PublicEnum.NATHANIEL).intValue()).isEqualTo(PublicEnum.NATHANIEL.ordinal());
    assertThat(serializer.getValueToOrdinal().get(PublicEnum.EMMA).intValue()).isEqualTo(PublicEnum.EMMA.ordinal());
    assertThat(serializer.getValueToOrdinal().get(PublicEnum.PAULA).intValue()).isEqualTo(PublicEnum.PAULA.ordinal());
    // reconfigure and verify compatibility
    EnumSerializer.EnumSerializerSnapshot serializerSnapshot = new EnumSerializer.EnumSerializerSnapshot(PublicEnum.class, mockPreviousOrder);
    TypeSerializerSchemaCompatibility compatibility = serializer.snapshotConfiguration().resolveSchemaCompatibility(serializerSnapshot);
    assertThat(compatibility.isCompatibleWithReconfiguredSerializer()).isTrue();
    // after reconfiguration, the order should be first the original BAR, PAULA, NATHANIEL,
    // followed by the "new enum constants" FOO, PETER, EMMA
    PublicEnum[] expectedOrder = { PublicEnum.BAR, PublicEnum.PAULA, PublicEnum.NATHANIEL, PublicEnum.FOO, PublicEnum.PETER, PublicEnum.EMMA };
    EnumSerializer<PublicEnum> configuredSerializer = (EnumSerializer<PublicEnum>) compatibility.getReconfiguredSerializer();
    int i = 0;
    for (PublicEnum constant : expectedOrder) {
        assertThat(configuredSerializer.getValueToOrdinal().get(constant).intValue()).isEqualTo(i);
        i++;
    }
    assertThat(configuredSerializer.getValues()).isEqualTo(expectedOrder);
}

@Test
void testConfigurationSnapshotSerialization() throws Exception {
    EnumSerializer<PublicEnum> serializer = new EnumSerializer<>(PublicEnum.class);
    byte[] serializedConfig;
    try (ByteArrayOutputStream out = new ByteArrayOutputStream()) {
        TypeSerializerSnapshotSerializationUtil.writeSerializerSnapshot(new DataOutputViewStreamWrapper(out), serializer.snapshotConfiguration());
        serializedConfig = out.toByteArray();
    }
    TypeSerializerSnapshot<PublicEnum> restoredConfig;
    try (ByteArrayInputStream in = new ByteArrayInputStream(serializedConfig)) {
        restoredConfig = TypeSerializerSnapshotSerializationUtil.readSerializerSnapshot(new DataInputViewStreamWrapper(in), Thread.currentThread().getContextClassLoader());
    }
    TypeSerializerSchemaCompatibility<PublicEnum> compatResult = serializer.snapshotConfiguration().resolveSchemaCompatibility(restoredConfig);
    assertThat(compatResult.isCompatibleAsIs()).isTrue();
    assertThat(serializer.getValueToOrdinal().get(PublicEnum.FOO).intValue()).isEqualTo(PublicEnum.FOO.ordinal());
    assertThat(serializer.getValueToOrdinal().get(PublicEnum.BAR).intValue()).isEqualTo(PublicEnum.BAR.ordinal());
    assertThat(serializer.getValueToOrdinal().get(PublicEnum.PETER).intValue()).isEqualTo(PublicEnum.PETER.ordinal());
    assertThat(serializer.getValueToOrdinal().get(PublicEnum.NATHANIEL).intValue()).isEqualTo(PublicEnum.NATHANIEL.ordinal());
    assertThat(serializer.getValueToOrdinal().get(PublicEnum.EMMA).intValue()).isEqualTo(PublicEnum.EMMA.ordinal());
    assertThat(serializer.getValueToOrdinal().get(PublicEnum.PAULA).intValue()).isEqualTo(PublicEnum.PAULA.ordinal());
    assertThat(serializer.getValues()).isEqualTo(PublicEnum.values());
}

