@Test
void testHashcodeAndEquals() throws Exception {
    final T[] testData = getTestData();
    final TypeInformation<?> unrelatedTypeInfo = new UnrelatedTypeInfo();
    for (T typeInfo : testData) {
        // check for implemented hashCode and equals
        if (typeInfo.getClass().getMethod("hashCode").getDeclaringClass() == Object.class) {
            throw new AssertionError("Type information does not implement own hashCode method: " + typeInfo.getClass().getCanonicalName());
        }
        if (typeInfo.getClass().getMethod("equals", Object.class).getDeclaringClass() == Object.class) {
            throw new AssertionError("Type information does not implement own equals method: " + typeInfo.getClass().getCanonicalName());
        }
        // compare among test data
        for (T otherTypeInfo : testData) {
            // test equality
            if (typeInfo == otherTypeInfo) {
                assertThat(typeInfo.hashCode()).as("hashCode() returns inconsistent results.").isEqualTo(otherTypeInfo.hashCode());
                assertThat(typeInfo).as("equals() is false for same object.").isEqualTo(otherTypeInfo);
            } else // test inequality
            {
                assertThat(typeInfo).as("equals() returned true for different objects.").isNotEqualTo(otherTypeInfo);
            }
        }
        // compare with unrelated type
        assertThat(typeInfo.canEqual(unrelatedTypeInfo)).as("Type information allows to compare with unrelated type.").isFalse();
        assertThat(typeInfo).isNotEqualTo(unrelatedTypeInfo);
    }
}

