@Test
void testReaderCheckpoints() throws Exception {
    final long from = 177;
    final long mid = 333;
    final long to = 563;
    final long elementsPerCycle = (to - from) / 3;
    final TestingReaderOutput<Long> out = new TestingReaderOutput<>();
    SourceReader<Long, NumberSequenceSource.NumberSequenceSplit> reader = createReader();
    reader.addSplits(Arrays.asList(new NumberSequenceSource.NumberSequenceSplit("split-1", from, mid), new NumberSequenceSource.NumberSequenceSplit("split-2", mid + 1, to)));
    long remainingInCycle = elementsPerCycle;
    while (reader.pollNext(out) != InputStatus.END_OF_INPUT) {
        if (--remainingInCycle <= 0) {
            remainingInCycle = elementsPerCycle;
            // checkpoint
            List<NumberSequenceSource.NumberSequenceSplit> splits = reader.snapshotState(1L);
            // re-create and restore
            reader = createReader();
            if (splits.isEmpty()) {
                reader.notifyNoMoreSplits();
            } else {
                reader.addSplits(splits);
            }
        }
    }
    final List<Long> result = out.getEmittedRecords();
    validateSequence(result, from, to);
}

@Test
void testGetNewNodeIdIsThreadSafe() throws Exception {
    final int numThreads = 10;
    final int numIdsPerThread = 100;
    final List<CheckedThread> threads = new ArrayList<>();
    final OneShotLatch startLatch = new OneShotLatch();
    final List<List<Integer>> idLists = Collections.synchronizedList(new ArrayList<>());
    for (int x = 0; x < numThreads; x++) {
        threads.add(new CheckedThread() {

            @Override
            public void go() throws Exception {
                startLatch.await();
                final List<Integer> ids = new ArrayList<>();
                for (int c = 0; c < numIdsPerThread; c++) {
                    ids.add(Transformation.getNewNodeId());
                }
                idLists.add(ids);
            }
        });
    }
    threads.forEach(Thread::start);
    startLatch.trigger();
    for (CheckedThread thread : threads) {
        thread.sync();
    }
    final Set<Integer> deduplicatedIds = idLists.stream().flatMap(List::stream).collect(Collectors.toSet());
    assertThat(deduplicatedIds).hasSize(numThreads * numIdsPerThread);
}

