@Test
void testDeprecationFlagForMixedAlternativeKeys() {
    final ConfigOption<Integer> optionWithMixedKeys = ConfigOptions.key("key").intType().defaultValue(0).withDeprecatedKeys("deprecated1", "deprecated2").withFallbackKeys("fallback1", "fallback2");
    final List<String> fallbackKeys = new ArrayList<>(2);
    final List<String> deprecatedKeys = new ArrayList<>(2);
    for (final FallbackKey alternativeKey : optionWithMixedKeys.fallbackKeys()) {
        if (alternativeKey.isDeprecated()) {
            deprecatedKeys.add(alternativeKey.getKey());
        } else {
            fallbackKeys.add(alternativeKey.getKey());
        }
    }
    assertThat(fallbackKeys).hasSize(2);
    assertThat(deprecatedKeys).hasSize(2);
    assertThat(fallbackKeys).containsExactlyInAnyOrder("fallback1", "fallback2");
    assertThat(deprecatedKeys).containsExactlyInAnyOrder("deprecated1", "deprecated2");
}

@Test
void testConfigurationWithLegacyYAML() throws FileNotFoundException {
    File confFile = new File(tmpDir, ConfigurationFileMigrationUtils.LEGACY_FLINK_CONF_FILENAME);
    try (PrintWriter pw = new PrintWriter(confFile)) {
        // should be skipped
        pw.println("###########################");
        // should be skipped
        pw.println("# Some : comments : to skip");
        // should be skipped
        pw.println("###########################");
        // OK, simple correct case
        pw.println("mykey1: myvalue1");
        // OK, whitespace before colon is correct
        pw.println("mykey2       : myvalue2");
        // SKIP, missing white space after colon
        pw.println("mykey3:myvalue3");
        // SKIP
        pw.println(" some nonsense without colon and whitespace separator");
        // SKIP
        pw.println(" :  ");
        // SKIP (silently)
        pw.println("   ");
        // SKIP (silently)
        pw.println(" ");
        // OK, skip comments only
        pw.println("mykey4: myvalue4# some comments");
        // OK, trim unnecessary whitespace
        pw.println("   mykey5    :    myvalue5    ");
        // OK, only use first ': ' as separator
        pw.println("mykey6: my: value6");
        // SKIP, no value provided
        pw.println("mykey7: ");
        // SKIP, no key provided
        pw.println(": myvalue8");
        // OK
        pw.println("mykey9: myvalue9");
        // OK, overwrite last value
        pw.println("mykey9: myvalue10");
    }
    Map<String, String> conf = ConfigurationFileMigrationUtils.loadLegacyYAMLResource(confFile);
    // all distinct keys from confFile1 + confFile2 key
    assertThat(conf.keySet()).hasSize(6);
    // keys 1, 2, 4, 5, 6, 7, 8 should be OK and match the expected values
    assertThat(conf.getOrDefault("mykey1", null)).isEqualTo("myvalue1");
    assertThat(conf.getOrDefault("mykey1", null)).isEqualTo("myvalue1");
    assertThat(conf.getOrDefault("mykey2", null)).isEqualTo("myvalue2");
    assertThat(conf.getOrDefault("mykey3", "null")).isEqualTo("null");
    assertThat(conf.getOrDefault("mykey4", null)).isEqualTo("myvalue4");
    assertThat(conf.getOrDefault("mykey5", null)).isEqualTo("myvalue5");
    assertThat(conf.getOrDefault("mykey6", null)).isEqualTo("my: value6");
    assertThat(conf.getOrDefault("mykey7", "null")).isEqualTo("null");
    assertThat(conf.getOrDefault("mykey8", "null")).isEqualTo("null");
    assertThat(conf.getOrDefault("mykey9", null)).isEqualTo("myvalue10");
}

