@Test
void testConfigurationWithStandardYAML() throws FileNotFoundException {
    File confFile = new File(tmpDir, GlobalConfiguration.FLINK_CONF_FILENAME);
    try (final PrintWriter pw = new PrintWriter(confFile)) {
        pw.println("Key1: ");
        pw.println("    Key2: v1");
        pw.println("    Key3: 'v2'");
        pw.println("Key4: 1");
        pw.println("Key5: '1'");
        pw.println("Key6: '*'");
        pw.println("Key7: true");
        pw.println("Key8: 'true'");
        pw.println("Key9: [a, b, '*', 1, '2',  true, 'true']");
        pw.println("Key10: {k1: v1, k2: '2', k3: 3}");
        pw.println("Key11: [{k1: v1, k2: '2', k3: 3}, {k4: true}]");
    }
    Configuration conf = GlobalConfiguration.loadConfiguration(tmpDir.getAbsolutePath());
    assertThat(conf.keySet()).hasSize(12);
    assertThat(conf.get(ConfigOptions.key("Key1.Key2").stringType().noDefaultValue())).isEqualTo("v1");
    assertThat(conf.get(ConfigOptions.key("Key1.Key3").stringType().noDefaultValue())).isEqualTo("v2");
    assertThat(conf.get(ConfigOptions.key("Key4").intType().noDefaultValue())).isOne();
    assertThat(conf.get(ConfigOptions.key("Key5").stringType().noDefaultValue())).isEqualTo("1");
    assertThat(conf.get(ConfigOptions.key("Key6").stringType().noDefaultValue())).isEqualTo("*");
    assertThat(conf.get(ConfigOptions.key("Key7").booleanType().noDefaultValue())).isTrue();
    assertThat(conf.get(ConfigOptions.key("Key8").stringType().noDefaultValue())).isEqualTo("true");
    assertThat(conf.get(ConfigOptions.key("Key9").stringType().asList().noDefaultValue())).isEqualTo(Arrays.asList("a", "b", "*", "1", "2", "true", "true"));
    Map<String, String> map = new HashMap<>();
    map.put("k1", "v1");
    map.put("k2", "2");
    map.put("k3", "3");
    assertThat(conf.get(ConfigOptions.key("Key10").mapType().noDefaultValue())).isEqualTo(map);
    Map<String, String> map2 = new HashMap<>();
    map2.put("k4", "true");
    assertThat(conf.get(ConfigOptions.key("Key11").mapType().asList().noDefaultValue())).isEqualTo(Arrays.asList(map, map2));
}

