@Test
void testOpenTimeoutOutputStreams() throws Exception {
    final long openTimeout = 50L;
    final int maxConcurrentOpen = 2;
    final LimitedConnectionsFileSystem limitedFs = new LimitedConnectionsFileSystem(LocalFileSystem.getSharedInstance(), // limited total
    maxConcurrentOpen, // small opening timeout
    openTimeout, // infinite inactivity timeout
    0L);
    // create the threads that block all streams
    final BlockingWriterThread[] threads = new BlockingWriterThread[maxConcurrentOpen];
    for (int i = 0; i < maxConcurrentOpen; i++) {
        Path path = new Path(File.createTempFile("junit", null, tempFolder).toURI());
        threads[i] = new BlockingWriterThread(limitedFs, path, Integer.MAX_VALUE, maxConcurrentOpen);
        threads[i].start();
    }
    // wait until all are open
    while (limitedFs.getTotalNumberOfOpenStreams() < maxConcurrentOpen) {
        Thread.sleep(1);
    }
    // try to open another thread
    assertThatThrownBy(() -> limitedFs.create(new Path(File.createTempFile("junit", null, tempFolder).toURI()), WriteMode.OVERWRITE)).isInstanceOf(IOException.class);
    // clean shutdown
    for (BlockingWriterThread t : threads) {
        t.wakeup();
        t.sync();
    }
}

