@Test
void testPerThreadThrowUserExit() throws Exception {
    FlinkSecurityManager flinkSecurityManager = new FlinkSecurityManager(ClusterOptions.UserSystemExitMode.THROW, false);
    ExecutorService executorService = EXECUTOR_RESOURCE.getExecutor();
    // Async thread test before enabling monitoring ensures it does not throw while prestarting
    // worker thread, which is to be unmonitored and tested after enabling monitoring enabled.
    CompletableFuture<Void> future = CompletableFuture.runAsync(() -> flinkSecurityManager.checkExit(TEST_EXIT_CODE), executorService);
    future.get();
    flinkSecurityManager.monitorUserSystemExit();
    assertThatThrownBy(() -> flinkSecurityManager.checkExit(TEST_EXIT_CODE)).isInstanceOf(UserSystemExitException.class);
    // This threaded exit should be allowed as thread is not spawned while monitor is enabled.
    future = CompletableFuture.runAsync(() -> flinkSecurityManager.checkExit(TEST_EXIT_CODE), executorService);
    future.get();
}

