@Test
void basicSyncComplete() {
    StateFutureImpl.CallbackRunner runner = new TestCallbackRunner(null);
    final AtomicInteger counter = new AtomicInteger(0);
    StateFutureImpl<Integer> stateFuture1 = new StateFutureImpl<>(runner, exceptionHandler);
    stateFuture1.thenAccept(counter::addAndGet);
    assertThat(counter).hasValue(0);
    stateFuture1.complete(5);
    assertThat(counter).hasValue(5);
    StateFutureImpl<Integer> stateFuture2 = new StateFutureImpl<>(runner, exceptionHandler);
    StateFuture<String> stateFuture3 = stateFuture2.thenApply((v) -> String.valueOf(counter.addAndGet(v)));
    assertThat(counter).hasValue(5);
    stateFuture2.complete(3);
    assertThat(counter).hasValue(8);
    stateFuture3.thenAccept((v) -> counter.addAndGet(-Integer.parseInt(v)));
    assertThat(counter).hasValue(0);
    StateFutureImpl<Integer> stateFuture4 = new StateFutureImpl<>(runner, exceptionHandler);
    StateFutureImpl<Integer> stateFuture5 = new StateFutureImpl<>(runner, exceptionHandler);
    stateFuture4.thenCompose((v) -> {
        counter.addAndGet(v);
        return stateFuture5;
    }).thenAccept(counter::addAndGet);
    assertThat(counter).hasValue(0);
    stateFuture4.complete(6);
    assertThat(counter).hasValue(6);
    stateFuture5.complete(3);
    assertThat(counter).hasValue(9);
    StateFutureImpl<Integer> stateFuture6 = new StateFutureImpl<>(runner, exceptionHandler);
    StateFutureImpl<Integer> stateFuture7 = new StateFutureImpl<>(runner, exceptionHandler);
    stateFuture6.thenCombine(stateFuture7, (v1, v2) -> {
        counter.addAndGet(v1 - v2);
        return StateFutureUtils.completedVoidFuture();
    });
    assertThat(counter).hasValue(9);
    stateFuture6.complete(4);
    assertThat(counter).hasValue(9);
    stateFuture7.complete(4 + 9);
    assertThat(counter).hasValue(0);
    StateFutureUtils.completedFuture(3).thenAccept(counter::addAndGet);
    assertThat(counter).hasValue(3);
    counter.set(0);
    ArrayList<StateFutureImpl<Integer>> futures = new ArrayList<>();
    for (int i = 0; i < 5; i++) {
        futures.add(new StateFutureImpl<>(runner, exceptionHandler));
    }
    StateFutureUtils.combineAll(futures).thenAccept((c) -> {
        int sum = 0;
        for (Integer v : c) {
            sum *= 10;
            sum += v;
        }
        counter.addAndGet(sum);
    });
    assertThat(counter).hasValue(0);
    for (int i = 0; i < 5; i++) {
        futures.get(i).complete(i + 1);
        if (i != 4) {
            assertThat(counter).hasValue(0);
        }
    }
    assertThat(counter).hasValue(12345);
}

@Test
void testRunOnCorrectThread() throws Exception {
    final AtomicInteger threadIdProvider = new AtomicInteger(0);
    final ThreadLocal<Integer> threadId = ThreadLocal.withInitial(threadIdProvider::getAndIncrement);
    final AtomicReference<Throwable> exception = new AtomicReference<>();
    final CountDownLatch latch = new CountDownLatch(1);
    assertThat(threadId.get()).isZero();
    ExecutorService executor = Executors.newSingleThreadExecutor(new ExecutorThreadFactory(this.getClass().getSimpleName()));
    executor.execute(() -> {
        try {
            assertThat(threadId.get()).isOne();
        } catch (Throwable e) {
            exception.set(e);
        } finally {
            latch.countDown();
        }
    });
    latch.await(20, TimeUnit.SECONDS);
    assertThat(latch.getCount()).isZero();
    assertThat(exception).hasValue(null);
    MockValueState valueState = new MockValueState(executor);
    Runnable threadChecker = () -> {
        try {
            assertThat(threadId.get()).isOne();
        } catch (Throwable e) {
            exception.set(e);
        }
    };
    final CountDownLatch latch2 = new CountDownLatch(2);
    final ArrayList<Integer> list = new ArrayList<>();
    executor.execute(() -> {
        ArrayList<StateFuture<Integer>> futures = new ArrayList<>();
        for (int i = 0; i < 5; i++) {
            futures.add(valueState.get());
        }
        StateFutureUtils.combineAll(futures).thenCombine(valueState.get(), (c, v) -> {
            list.addAll(c);
            list.add(v);
            threadChecker.run();
            return 0;
        }).thenCompose((v) -> {
            threadChecker.run();
            return valueState.get();
        }).thenApply((v) -> {
            list.add(v);
            threadChecker.run();
            return 0;
        }).thenAccept((v) -> {
            threadChecker.run();
            latch2.countDown();
        });
        latch2.countDown();
    });
    latch2.await(20, TimeUnit.SECONDS);
    assertThat(latch2.getCount()).isZero();
    assertThat(exception.get()).isNull();
    assertThat(list).hasSize(7);
}

@Test
void testConditionally() {
    StateFutureImpl.CallbackRunner runner = new TestCallbackRunner(null);
    final AtomicInteger counter = new AtomicInteger(0);
    // accept
    StateFutureImpl<Integer> stateFuture1 = new StateFutureImpl<>(runner, exceptionHandler);
    stateFuture1.thenConditionallyAccept(e -> e > 0, counter::addAndGet, v -> counter.addAndGet(-v)).thenConditionallyAccept(e -> !e, v -> counter.incrementAndGet(), v -> counter.decrementAndGet());
    assertThat(counter).hasValue(0);
    stateFuture1.complete(-5);
    assertThat(counter).hasValue(6);
    // apply
    StateFutureImpl<Integer> stateFuture2 = new StateFutureImpl<>(runner, exceptionHandler);
    stateFuture2.thenConditionallyApply(v -> v > 0, v -> String.valueOf(counter.addAndGet(v)), v -> String.valueOf(counter.addAndGet(-v))).thenConditionallyApply(e -> !e.f0, e -> counter.addAndGet(Integer.parseInt((String) e.f1) * 2), e -> counter.addAndGet(Integer.parseInt((String) e.f1) * 3));
    assertThat(counter).hasValue(6);
    stateFuture2.complete(-3);
    assertThat(counter).hasValue(27);
    // compose
    StateFutureImpl<Integer> stateFuture3 = new StateFutureImpl<>(runner, exceptionHandler);
    StateFutureImpl<Integer> stateFuture4 = new StateFutureImpl<>(runner, exceptionHandler);
    StateFutureImpl<Integer> stateFuture5 = new StateFutureImpl<>(runner, exceptionHandler);
    stateFuture3.thenConditionallyCompose(v -> v > 0, (v) -> {
        counter.addAndGet(v);
        return stateFuture4;
    }, (v) -> {
        counter.addAndGet(-v);
        return stateFuture5;
    }).thenConditionallyCompose(t -> !t.f0, (t) -> {
        counter.addAndGet((Integer) t.f1 * 2);
        return StateFutureUtils.completedVoidFuture();
    }, (t) -> {
        counter.addAndGet((Integer) t.f1 * 3);
        return StateFutureUtils.completedVoidFuture();
    });
    assertThat(counter).hasValue(27);
    counter.set(0);
    stateFuture3.complete(3);
    assertThat(counter).hasValue(3);
    stateFuture5.complete(5);
    assertThat(counter).hasValue(3);
    stateFuture4.complete(4);
    assertThat(counter).hasValue(15);
}

/**
 * Verifies initialize, registered mBean and retrieval via attribute.
 */
@Test
void testJMXServiceRegisterMBean() throws Exception {
    TestObject testObject = new TestObject();
    ObjectName testObjectName = new ObjectName("org.apache.flink.management", "key", "value");
    MBeanServer mBeanServer = ManagementFactory.getPlatformMBeanServer();
    try {
        Optional<JMXServer> server = JMXService.getInstance();
        assertThat(server).isPresent();
        mBeanServer.registerMBean(testObject, testObjectName);
        JMXServiceURL url = new JMXServiceURL("service:jmx:rmi://localhost:" + server.get().getPort() + "/jndi/rmi://localhost:" + server.get().getPort() + "/jmxrmi");
        JMXConnector jmxConn = JMXConnectorFactory.connect(url);
        MBeanServerConnection mbeanConnConn = jmxConn.getMBeanServerConnection();
        assertThat((int) mbeanConnConn.getAttribute(testObjectName, "Foo")).isOne();
        mBeanServer.unregisterMBean(testObjectName);
        assertThatThrownBy(() -> mbeanConnConn.getAttribute(testObjectName, "Foo")).isInstanceOf(InstanceNotFoundException.class);
    } finally {
        JMXService.stopInstance();
    }
}

