@Test
void testDeepEqualsAndHashCodePositioned() {
    final Map<String, byte[]> originalMap = new HashMap<>();
    originalMap.put("k1", new byte[] { 1, 2, 3 });
    originalMap.put("k2", new byte[] { 3, 4, 6 });
    final Row originalRow = Row.ofKind(RowKind.INSERT, true, new Integer[] { 1, null, 3 }, Arrays.asList(1, null, 3), originalMap, Collections.emptyMap(), new int[][] { { 1, 2, 3 }, {}, { 4, 5 } }, 1.44);
    assertThat(originalRow).isEqualTo(originalRow);
    assertThat(originalRow).hasSameHashCodeAs(originalRow);
    {
        // no diff
        final Row row = Row.ofKind(RowKind.INSERT, true, new Integer[] { 1, null, 3 }, Arrays.asList(1, null, 3), originalMap, Collections.emptyMap(), new int[][] { { 1, 2, 3 }, {}, { 4, 5 } }, 1.44);
        assertThat(originalRow).isEqualTo(row);
        assertThat(originalRow).hasSameHashCodeAs(row);
    }
    {
        final Map<String, byte[]> map = new HashMap<>();
        map.put("k1", new byte[] { 1, 2, 3 });
        map.put("k2", new byte[] { 3, 4, 6 });
        final Row row = Row.ofKind(RowKind.INSERT, true, // diff here
        new Integer[] { 1, null, 3, 99 }, Arrays.asList(1, null, 3), map, Collections.emptyMap(), new int[][] { { 1, 2, 3 }, {}, { 4, 5 } }, 1.44);
        assertThat(originalRow).isNotEqualTo(row);
        assertThat(originalRow).doesNotHaveSameHashCodeAs(row);
    }
    {
        final Map<String, byte[]> map = new HashMap<>();
        // diff here
        map.put("k1", new byte[] { 1, 2, 2 });
        map.put("k2", new byte[] { 3, 4, 6 });
        final Row row = Row.ofKind(RowKind.INSERT, true, new Integer[] { 1, null, 3 }, Arrays.asList(1, null, 3), map, Collections.emptyMap(), new int[][] { { 1, 2, 3 }, {}, { 4, 5 } }, 1.44);
        assertThat(originalRow).isNotEqualTo(row);
        assertThat(originalRow).doesNotHaveSameHashCodeAs(row);
    }
    {
        final Map<String, byte[]> map = new HashMap<>();
        map.put("k1", new byte[] { 1, 2, 3 });
        map.put("k2", new byte[] { 3, 4, 6 });
        final Row row = Row.ofKind(RowKind.INSERT, true, new Integer[] { 1, null, 3 }, Arrays.asList(1, null, 3), map, Collections.emptyMap(), // diff here
        new Integer[][] { { 1, 2, 3 }, {}, { 4, 5 } }, 1.44);
        assertThat(originalRow).isNotEqualTo(row);
        assertThat(originalRow).doesNotHaveSameHashCodeAs(row);
    }
}

