        }
    }, EXECUTOR_RESOURCE.getExecutor()), retries, throwable -> ExceptionUtils.findThrowable(throwable, FlinkException.class).isPresent(), EXECUTOR_RESOURCE.getExecutor());
    assertThatFuture(retryFuture).eventuallyFailsWith(ExecutionException.class).extracting(FlinkAssertions::chainOfCauses, FlinkAssertions.STREAM_THROWABLE).last().isEqualTo(nonRetryableException);
    assertThat(atomicInteger).hasValue(notRetry);
}

