 * delay.
 */
@Test
void testRetryWithDelayRetryStrategy() {
    final int retries = 4;
    final AtomicInteger countDown = new AtomicInteger(retries);
    long start = System.currentTimeMillis();
    CompletableFuture<Boolean> retryFuture = FutureUtils.retryWithDelay(() -> {
        if (countDown.getAndDecrement() == 0) {
            return CompletableFuture.completedFuture(true);
        } else {
            return FutureUtils.completedExceptionally(new FlinkException("Test exception."));
        }
    }, new ExponentialBackoffRetryStrategy(retries, Duration.ofMillis(2L), Duration.ofMillis(5L)), new ScheduledExecutorServiceAdapter(EXECUTOR_RESOURCE.getExecutor()));
    assertThatFuture(retryFuture).eventuallySucceeds().isEqualTo(true);
    long completionTime = System.currentTimeMillis() - start;
    assertThat(completionTime).as("The completion time should be at least retries times delay between retries.").isGreaterThanOrEqualTo(2 + 4 + 5 + 5);
}

/**
 * Tests that all scheduled tasks are canceled if the retry future is being cancelled.
 */
@Test
void testRetryWithDelayRetryStrategyCancellation() {
    final ManuallyTriggeredScheduledExecutor scheduledExecutor = new ManuallyTriggeredScheduledExecutor();
    CompletableFuture<?> retryFuture = FutureUtils.retryWithDelay(() -> FutureUtils.completedExceptionally(new FlinkException("Test exception")), new FixedRetryStrategy(1, TestingUtils.infiniteDuration()), scheduledExecutor);
    assertThat(retryFuture).isNotDone();
    final Collection<ScheduledFuture<?>> scheduledTasks = scheduledExecutor.getActiveScheduledTasks();
    assertThat(scheduledTasks).isNotEmpty();
    final ScheduledFuture<?> scheduledFuture = scheduledTasks.iterator().next();
    assertThat(scheduledFuture.isDone()).isFalse();
    retryFuture.cancel(false);
    assertThat(retryFuture).isCancelled();
    assertThat(scheduledFuture.isCancelled()).isTrue();
}

