@Test
void testRetryWithDelayRetryStrategyAndPredicate() {
    final ScheduledExecutorService retryExecutor = EXECUTOR_RESOURCE.getExecutor();
    final String retryableExceptionMessage = "first exception";
    final String expectedErrorMessage = "should propagate";
    class TestStringSupplier implements Supplier<CompletableFuture<String>> {

        private final AtomicInteger counter = new AtomicInteger();

        @Override
        public CompletableFuture<String> get() {
            if (counter.getAndIncrement() == 0) {
                return FutureUtils.completedExceptionally(new RuntimeException(retryableExceptionMessage));
            } else {
                return FutureUtils.completedExceptionally(new RuntimeException(expectedErrorMessage));
            }
        }
    }
    final CompletableFuture<String> resultFuture = FutureUtils.retryWithDelay(new TestStringSupplier(), new FixedRetryStrategy(1, Duration.ZERO), throwable -> throwable instanceof RuntimeException && throwable.getMessage().contains(retryableExceptionMessage), new ScheduledExecutorServiceAdapter(retryExecutor));
    assertThatFuture(resultFuture).eventuallyFailsWith(ExecutionException.class).withMessageContaining(expectedErrorMessage);
}

