@Test
void testFreePortRangeUtility() {
    // inspired by Hadoop's example for "yarn.app.mapreduce.am.job.client.port-range"
    String rangeDefinition = // this also contains some whitespaces
    "50000-50050, 50100-50200,51234 ";
    Iterator<Integer> portsIter = NetUtils.getPortRangeFromString(rangeDefinition);
    Set<Integer> ports = new HashSet<>();
    while (portsIter.hasNext()) {
        assertThat(ports.add(portsIter.next())).isTrue();
    }
    assertThat(ports).hasSize(51 + 101 + 1);
    // check first range
    assertThat(ports).contains(50000, 50001, 50002, 50050);
    // check second range and last point
    assertThat(ports).contains(50100, 50101, 50110, 50200, 51234);
    // check that only ranges are included
    assertThat(ports).doesNotContain(50051, 50052, 1337, 50201, 49999, 50099);
    // test single port "range":
    portsIter = NetUtils.getPortRangeFromString(" 51234");
    assertThat(portsIter.hasNext()).isTrue();
    assertThat((int) portsIter.next()).isEqualTo(51234);
    assertThat(portsIter).isExhausted();
    // test port list
    portsIter = NetUtils.getPortRangeFromString("5,1,2,3,4");
    assertThat(portsIter.hasNext()).isTrue();
    assertThat((int) portsIter.next()).isEqualTo(5);
    assertThat((int) portsIter.next()).isOne();
    assertThat((int) portsIter.next()).isEqualTo(2);
    assertThat((int) portsIter.next()).isEqualTo(3);
    assertThat((int) portsIter.next()).isEqualTo(4);
    assertThat(portsIter).isExhausted();
    Throwable error = null;
    // try some wrong values: String
    try {
        NetUtils.getPortRangeFromString("localhost");
    } catch (Throwable t) {
        error = t;
    }
    assertThat(error).isInstanceOf(NumberFormatException.class);
    error = null;
    // incomplete range
    try {
        NetUtils.getPortRangeFromString("5-");
    } catch (Throwable t) {
        error = t;
    }
    assertThat(error).isInstanceOf(NumberFormatException.class);
    error = null;
    // incomplete range
    try {
        NetUtils.getPortRangeFromString("-5");
    } catch (Throwable t) {
        error = t;
    }
    assertThat(error).isInstanceOf(NumberFormatException.class);
    error = null;
    // empty range
    try {
        NetUtils.getPortRangeFromString(",5");
    } catch (Throwable t) {
        error = t;
    }
    assertThat(error).isInstanceOf(NumberFormatException.class);
    // invalid port
    try {
        NetUtils.getPortRangeFromString("70000");
    } catch (Throwable t) {
        error = t;
    }
    assertThat(error).isInstanceOf(IllegalConfigurationException.class);
    // invalid start
    try {
        NetUtils.getPortRangeFromString("70000-70001");
    } catch (Throwable t) {
        error = t;
    }
    assertThat(error).isInstanceOf(IllegalConfigurationException.class);
    // invalid end
    try {
        NetUtils.getPortRangeFromString("0-70000");
    } catch (Throwable t) {
        error = t;
    }
    assertThat(error).isInstanceOf(IllegalConfigurationException.class);
    // same range
    try {
        NetUtils.getPortRangeFromString("5-5");
    } catch (Throwable t) {
        error = t;
    }
    assertThat(error).isInstanceOf(IllegalConfigurationException.class);
}

@Test
void testFormatAddress() {
    assertThat(NetUtils.unresolvedHostAndPortToNormalizedString(null, 42)).isEqualTo("127.0.0.1" + ":" + 42);
    // IPv4
    assertThat(NetUtils.unresolvedHostAndPortToNormalizedString("1.2.3.4", 42)).isEqualTo("1.2.3.4" + ":" + 42);
    // IPv6
    assertThat(NetUtils.unresolvedHostAndPortToNormalizedString("2001:0db8:85a3:0000:0000:8a2e:0370:7334", 42)).isEqualTo("[2001:db8:85a3::8a2e:370:7334]:" + 42);
    // [IPv6]
    assertThat(NetUtils.unresolvedHostAndPortToNormalizedString("[2001:0db8:85a3:0000:0000:8a2e:0370:7334]", 42)).isEqualTo("[2001:db8:85a3::8a2e:370:7334]:" + 42);
    // Hostnames
    assertThat(NetUtils.unresolvedHostAndPortToNormalizedString("somerandomhostname", 99)).isEqualTo("somerandomhostname" + ":" + 99);
    // Whitespace
    assertThat(NetUtils.unresolvedHostAndPortToNormalizedString("  somerandomhostname  ", 99)).isEqualTo("somerandomhostname" + ":" + 99);
    // Illegal hostnames
    assertThatThrownBy(() -> NetUtils.unresolvedHostAndPortToNormalizedString("illegalhost.", 42)).isInstanceOf(IllegalConfigurationException.class);
    assertThatThrownBy(() -> NetUtils.unresolvedHostAndPortToNormalizedString("illegalhost:fasf", 42)).isInstanceOf(IllegalConfigurationException.class);
    // Illegal port ranges
    assertThatThrownBy(() -> NetUtils.unresolvedHostAndPortToNormalizedString("1.2.3.4", -1)).isInstanceOf(Exception.class);
    // lower case conversion of hostnames
    assertThat(NetUtils.unresolvedHostAndPortToNormalizedString("CamelCaseHostName", 99)).isEqualTo("camelcasehostname" + ":" + 99);
}

