@Test
void testAcquireReleaseClose() throws IOException {
    ResourceGuard resourceGuard = new ResourceGuard();
    ResourceGuard.Lease lease = resourceGuard.acquireResource();
    assertThat(resourceGuard.getLeaseCount()).isOne();
