@Test
void testApplyToAllPartitions() throws Exception {
    AtomicInteger counter = new AtomicInteger(0);
    List<Integer> collectedData = new ArrayList<>();
    TestingTimestampCollector<Integer> collector = TestingTimestampCollector.<Integer>builder().setCollectConsumer(collectedData::add).build();
    CompletableFuture<Void> cf = new CompletableFuture<>();
    StreamingRuntimeContext operatorRuntimeContext = ContextTestUtils.createStreamingRuntimeContext();
    DefaultRuntimeContext runtimeContext = new DefaultRuntimeContext(operatorRuntimeContext.getJobInfo().getJobName(), operatorRuntimeContext.getJobType(), 1, 2, "mock-task", 0, 0, operatorRuntimeContext.getMetricGroup());
    DefaultPartitionedContext<Integer> partitionedContext = new DefaultPartitionedContext<>(runtimeContext, Optional::empty, (r, k) -> {
        cf.complete(null);
        r.run();
        cf.complete(null);
    }, UnsupportedProcessingTimeManager.INSTANCE, ContextTestUtils.createStreamingRuntimeContext(), new MockOperatorStateStore());
    DefaultNonPartitionedContext<Integer> nonPartitionedContext = new DefaultNonPartitionedContext<>(runtimeContext, partitionedContext, collector, false, null, null, Collections.emptyMap());
    partitionedContext.setNonPartitionedContext(nonPartitionedContext);
    nonPartitionedContext.applyToAllPartitions((out, ctx) -> {
        counter.incrementAndGet();
        out.collect(10);
    });
    assertThat(counter.get()).isEqualTo(1);
    assertThat(cf).isNotCompleted();
    assertThat(collectedData).containsExactly(10);
}

@Test
void testKeyedApplyToAllPartitions() throws Exception {
    AtomicInteger counter = new AtomicInteger(0);
    List<Integer> collectedData = new ArrayList<>();
    TestingTimestampCollector<Integer> collector = TestingTimestampCollector.<Integer>builder().setCollectConsumer(collectedData::add).build();
    // put all keys
    Set<Object> allKeys = new HashSet<>();
    allKeys.add(1);
    allKeys.add(2);
    allKeys.add(3);
    AtomicInteger currentKey = new AtomicInteger(-1);
    StreamingRuntimeContext operatorRuntimeContext = ContextTestUtils.createStreamingRuntimeContext();
    DefaultRuntimeContext runtimeContext = new DefaultRuntimeContext(operatorRuntimeContext.getJobInfo().getJobName(), operatorRuntimeContext.getJobType(), 1, 2, "mock-task", 0, 0, operatorRuntimeContext.getMetricGroup());
    DefaultPartitionedContext<Integer> partitionedContext = new DefaultPartitionedContext<>(runtimeContext, currentKey::get, (r, k) -> {
        Integer oldKey = currentKey.get();
        currentKey.set((Integer) k);
        r.run();
        currentKey.set(oldKey);
    }, UnsupportedProcessingTimeManager.INSTANCE, ContextTestUtils.createStreamingRuntimeContext(), new MockOperatorStateStore());
    DefaultNonPartitionedContext<Integer> nonPartitionedContext = new DefaultNonPartitionedContext<>(runtimeContext, partitionedContext, collector, true, allKeys, null, Collections.emptyMap());
    partitionedContext.setNonPartitionedContext(nonPartitionedContext);
    nonPartitionedContext.applyToAllPartitions((out, ctx) -> {
        counter.incrementAndGet();
        Integer key = ctx.getStateManager().getCurrentKey();
        assertThat(key).isIn(allKeys);
        out.collect(key);
    });
    assertThat(counter.get()).isEqualTo(allKeys.size());
    assertThat(collectedData).containsExactlyInAnyOrder(1, 2, 3);
}

