@Test
void testApplyToAllPartitions() throws Exception {
    AtomicInteger counter = new AtomicInteger(0);
    List<Integer> collectedFromFirstOutput = new ArrayList<>();
    List<Long> collectedFromSecondOutput = new ArrayList<>();
    TestingTimestampCollector<Integer> firstCollector = TestingTimestampCollector.<Integer>builder().setCollectConsumer(collectedFromFirstOutput::add).build();
    TestingTimestampCollector<Long> secondCollector = TestingTimestampCollector.<Long>builder().setCollectConsumer(collectedFromSecondOutput::add).build();
    CompletableFuture<Void> cf = new CompletableFuture<>();
    StreamingRuntimeContext operatorRuntimeContext = ContextTestUtils.createStreamingRuntimeContext();
    DefaultRuntimeContext runtimeContext = new DefaultRuntimeContext(operatorRuntimeContext.getJobInfo().getJobName(), operatorRuntimeContext.getJobType(), 1, 2, "mock-task", 0, 0, operatorRuntimeContext.getMetricGroup());
    DefaultTwoOutputPartitionedContext<Integer, Long> partitionedContext = new DefaultTwoOutputPartitionedContext<>(runtimeContext, Optional::empty, (r, k) -> {
        cf.complete(null);
        r.run();
        cf.complete(null);
    }, UnsupportedProcessingTimeManager.INSTANCE, ContextTestUtils.createStreamingRuntimeContext(), new MockOperatorStateStore());
    DefaultTwoOutputNonPartitionedContext<Integer, Long> nonPartitionedContext = new DefaultTwoOutputNonPartitionedContext<>(runtimeContext, partitionedContext, firstCollector, secondCollector, false, null, null, Collections.emptyMap());
    partitionedContext.setNonPartitionedContext(nonPartitionedContext);
    nonPartitionedContext.applyToAllPartitions((firstOutput, secondOutput, ctx) -> {
        counter.incrementAndGet();
        firstOutput.collect(10);
        secondOutput.collect(20L);
    });
    assertThat(counter.get()).isEqualTo(1);
    assertThat(cf).isNotCompleted();
    assertThat(collectedFromFirstOutput).containsExactly(10);
    assertThat(collectedFromSecondOutput).containsExactly(20L);
}

@Test
void testKeyedApplyToAllPartitions() throws Exception {
    AtomicInteger counter = new AtomicInteger(0);
    List<Integer> collectedFromFirstOutput = new ArrayList<>();
    List<Long> collectedFromSecondOutput = new ArrayList<>();
    TestingTimestampCollector<Integer> firstCollector = TestingTimestampCollector.<Integer>builder().setCollectConsumer(collectedFromFirstOutput::add).build();
    TestingTimestampCollector<Long> secondCollector = TestingTimestampCollector.<Long>builder().setCollectConsumer(collectedFromSecondOutput::add).build();
    // put all keys
    Set<Object> allKeys = new HashSet<>();
    allKeys.add(1);
    allKeys.add(2);
    allKeys.add(3);
    AtomicInteger currentKey = new AtomicInteger(-1);
    StreamingRuntimeContext operatorRuntimeContext = ContextTestUtils.createStreamingRuntimeContext();
    DefaultRuntimeContext runtimeContext = new DefaultRuntimeContext(operatorRuntimeContext.getJobInfo().getJobName(), operatorRuntimeContext.getJobType(), 1, 2, "mock-task", 0, 0, operatorRuntimeContext.getMetricGroup());
    DefaultTwoOutputPartitionedContext<Integer, Long> partitionedContext = new DefaultTwoOutputPartitionedContext<>(runtimeContext, currentKey::get, (r, k) -> {
        Integer oldKey = currentKey.get();
        currentKey.set((Integer) k);
        r.run();
        currentKey.set(oldKey);
    }, UnsupportedProcessingTimeManager.INSTANCE, ContextTestUtils.createStreamingRuntimeContext(), new MockOperatorStateStore());
    DefaultTwoOutputNonPartitionedContext<Integer, Long> nonPartitionedContext = new DefaultTwoOutputNonPartitionedContext<>(runtimeContext, partitionedContext, firstCollector, secondCollector, true, allKeys, null, Collections.emptyMap());
    partitionedContext.setNonPartitionedContext(nonPartitionedContext);
    nonPartitionedContext.applyToAllPartitions((firstOut, secondOut, ctx) -> {
        counter.incrementAndGet();
        Integer key = ctx.getStateManager().getCurrentKey();
        assertThat(key).isIn(allKeys);
        firstOut.collect(key);
        secondOut.collect(Long.valueOf(key));
    });
    assertThat(counter.get()).isEqualTo(allKeys.size());
    assertThat(collectedFromFirstOutput).containsExactlyInAnyOrder(1, 2, 3);
    assertThat(collectedFromSecondOutput).containsExactlyInAnyOrder(1L, 2L, 3L);
}

