@Test
void testGetInternalWatermarkDeclarationsFromStreamGraph() throws ReflectiveOperationException {
    StreamGraph streamGraph = getStreamGraph(watermarkDeclarations);
    Set<AbstractInternalWatermarkDeclaration<?>> internalWatermarkDeclarationSet = WatermarkUtils.getInternalWatermarkDeclarationsFromStreamGraph(streamGraph);
    ArrayList<AbstractInternalWatermarkDeclaration<?>> internalWatermarkDeclarations = new ArrayList<>(internalWatermarkDeclarationSet);
    internalWatermarkDeclarations.sort(Comparator.comparing(WatermarkDeclaration::getIdentifier));
    assertThat(internalWatermarkDeclarations.size()).isEqualTo(watermarkDeclarations.size());
    for (int i = 0; i < internalWatermarkDeclarations.size(); i++) {
        judgeWatermarkDeclarationEqual(watermarkDeclarations.get(i), internalWatermarkDeclarations.get(i));
    }
}

