        int runningSize = 0;
        for (int i = 0; i < numChanges; i++) {
            List<StateChangeSet> changes = getChanges(changeSize);
            runningSize += changes.stream().mapToLong(StateChangeSet::getSize).sum();
            upload(store, changes);
