@Test
void testTimeout() throws Exception {
    int numAttempts = 2;
    int timeout = 500;
    CompletableFuture<Long> firstStart = new CompletableFuture<>();
    CompletableFuture<Long> secondStart = new CompletableFuture<>();
    testPolicy(numAttempts, RetryPolicy.fixed(Integer.MAX_VALUE, timeout, 0), a -> {
        long now = System.nanoTime();
        if (a < numAttempts) {
            firstStart.complete(now);
            // cause timeout
            secondStart.get();
        } else {
            secondStart.complete(now);
        }
    }, Executors.newScheduledThreadPool(2));
    /* future completion can be delayed arbitrarily causing start delta be less than timeout */
    assertThat(((double) secondStart.get() - firstStart.get()) / 1_000_000).isGreaterThanOrEqualTo(timeout * .75);
}

