@ParameterizedTest
@EnumSource(value = BatchShuffleMode.class, names = { "ALL_EXCHANGES_BLOCKING" // Remove hybrid shuffle types to unblock CI. This have to reactive when we find the
// reason.
// "ALL_EXCHANGES_HYBRID_FULL",
// "ALL_EXCHANGES_HYBRID_SELECTIVE"
// Only above shuffle modes are supported by the adaptive batch scheduler
// , "ALL_EXCHANGES_PIPELINE"
})
public void testBatchSQL(BatchShuffleMode shuffleMode, @TempDir Path tmpDir) throws Exception {
    LOG.info("Results for this test will be stored at: {}", tmpDir);
    String sqlStatement = new String(Files.readAllBytes(sqlPath));
    TableEnvironment tEnv = TableEnvironment.create(EnvironmentSettings.inBatchMode());
    tEnv.getConfig().set(ExecutionOptions.BATCH_SHUFFLE_MODE, shuffleMode);
    tEnv.createTable("table1", TableDescriptor.forConnector(GeneratorTableSourceFactory.CONNECTOR_ID).schema(GeneratorTableSourceFactory.getSchema()).option(GeneratorTableSourceFactory.NUM_KEYS, 10).option(GeneratorTableSourceFactory.ROWS_PER_KEY_PER_SECOND, 100f).option(GeneratorTableSourceFactory.DURATION_SECONDS, 60).option(GeneratorTableSourceFactory.OFFSET_SECONDS, 0).build());
    tEnv.createTable("table2", TableDescriptor.forConnector(GeneratorTableSourceFactory.CONNECTOR_ID).schema(GeneratorTableSourceFactory.getSchema()).option(GeneratorTableSourceFactory.NUM_KEYS, 5).option(GeneratorTableSourceFactory.ROWS_PER_KEY_PER_SECOND, 0.2f).option(GeneratorTableSourceFactory.DURATION_SECONDS, 60).option(GeneratorTableSourceFactory.OFFSET_SECONDS, 5).build());
    tEnv.createTable("sinkTable", TableDescriptor.forConnector("filesystem").schema(Schema.newBuilder().column("f0", DataTypes.INT()).column("f1", DataTypes.TIMESTAMP(3)).build()).option("path", tmpDir.toString()).format(FormatDescriptor.forFormat("csv").option(CsvFormatOptions.FIELD_DELIMITER, ",").option(CsvFormatOptions.DISABLE_QUOTE_CHARACTER, true).build()).build());
    LOG.info("Submitting job");
    TableResult result = tEnv.executeSql(sqlStatement);
    // Wait for the job to finish.
    JobClient jobClient = result.getJobClient().orElseThrow(() -> new IllegalStateException("Job client is not present"));
    jobClient.getJobExecutionResult().get();
    final String expected = "1980,1970-01-01 00:00:00\n" + "1980,1970-01-01 00:00:20\n" + "1980,1970-01-01 00:00:40\n";
    LOG.info("Job finished");
    List<String> files = Stream.of(Objects.requireNonNull(new File(tmpDir.toString()).listFiles())).filter(file -> !file.isDirectory()).map(File::getPath).collect(Collectors.toList());
    assertEquals(1, files.size());
    Path resultFile = Paths.get(files.get(0));
    LOG.info("Result found at {}", resultFile);
    String actual = new String(Files.readAllBytes(resultFile));
    LOG.info("Actual result is: '{}'", actual);
    assertEquals(expected, actual);
}

