    String[] messages = new String[] { "{\"timestamp\": \"2018-03-12T08:00:00Z\", \"user\": \"Alice\", \"event\": { \"type\": \"WARNING\", \"message\": \"This is a warning.\"}}", "{\"timestamp\": \"2018-03-12T08:10:00Z\", \"user\": \"Alice\", \"event\": { \"type\": \"WARNING\", \"message\": \"This is a warning.\"}}", "{\"timestamp\": \"2018-03-12T09:00:00Z\", \"user\": \"Bob\", \"event\": { \"type\": \"WARNING\", \"message\": \"This is another warning.\"}}", "{\"timestamp\": \"2018-03-12T09:10:00Z\", \"user\": \"Alice\", \"event\": { \"type\": \"INFO\", \"message\": \"This is a info.\"}}", "{\"timestamp\": \"2018-03-12T09:20:00Z\", \"user\": \"Steve\", \"event\": { \"type\": \"INFO\", \"message\": \"This is another info.\"}}", "{\"timestamp\": \"2018-03-12T09:30:00Z\", \"user\": \"Steve\", \"event\": { \"type\": \"INFO\", \"message\": \"This is another info.\"}}", "{\"timestamp\": \"2018-03-12T09:30:00Z\", \"user\": null, \"event\": { \"type\": \"WARNING\", \"message\": \"This is a bad message because the user is missing.\"}}", "{\"timestamp\": \"2018-03-12T10:40:00Z\", \"user\": \"Bob\", \"event\": { \"type\": \"ERROR\", \"message\": \"This is an error.\"}}" };
    sendMessages("test-json", messages);
    List<String> sqlLines = Arrays.asList("CREATE FUNCTION RegReplace AS 'org.apache.flink.table.toolbox.StringRegexReplaceFunction';", "", "CREATE TABLE JsonSourceTable (", "    `timestamp` TIMESTAMP_LTZ(3),", "    `user` STRING,", "    `event` ROW<type STRING, message STRING>,", "    `rowtime` AS `timestamp`,", "    WATERMARK FOR `rowtime` AS `rowtime` - INTERVAL '2' SECOND", ") WITH (", "    'connector' = 'kafka',", "    'topic' = 'test-json',", "    'properties.bootstrap.servers' = '" + INTER_CONTAINER_KAFKA_ALIAS + ":9092',", "    'scan.startup.mode' = 'earliest-offset',", "    'format' = 'json',", "    'json.timestamp-format.standard' = 'ISO-8601'", ");", "", "CREATE TABLE AppendSinkTable (", "    user_id INT,", "    user_name STRING,", "    user_count BIGINT", "  ) WITH (", "    'connector' = 'upsert-files',", "    'key.format' = 'json',", "    'value.format' = 'json',", "    'output-filepath' = '" + outputFilepath + "'", "  );", "", "INSERT INTO AppendSinkTable", "  SELECT 1 as user_id, T.userName as user_name, cast(1 as BIGINT) as user_count", "  FROM (", "    SELECT `user`, `rowtime`", "    FROM JsonSourceTable", "    WHERE `user` IS NOT NULL)", "  MATCH_RECOGNIZE (", "    ORDER BY rowtime", "    MEASURES", "        `user` as userName", "    PATTERN (A)", "    DEFINE", "        A as `user` = 'Alice'", "  ) as T;");
    executeSql(sqlLines);
    verifyNumberOfResultRecords(outputFilepath, 1);
