    // suppress sysout messages from this example
    final PrintStream originalSysout = System.out;
    final PrintStream originalSyserr = System.err;
    final ByteArrayOutputStream errorMessages = new ByteArrayOutputStream();
    System.setOut(new PrintStream(new NullStream()));
    System.setErr(new PrintStream(errorMessages));
    try {
        try (ServerSocket server = new ServerSocket(0, 10, localhost)) {
            final ServerThread serverThread = new ServerThread(server);
            serverThread.setDaemon(true);
            serverThread.start();
            final int serverPort = server.getLocalPort();
            System.out.println("Server listening on port " + serverPort);
            if (asyncState) {
                SocketWindowWordCount.main(new String[] { "--port", String.valueOf(serverPort), "--async-state" });
            } else {
                SocketWindowWordCount.main(new String[] { "--port", String.valueOf(serverPort) });
            }
            if (errorMessages.size() != 0) {
                fail("Found error message: " + new String(errorMessages.toByteArray(), ConfigConstants.DEFAULT_CHARSET));
            }
            serverThread.join();
            serverThread.checkError();
        }
    } finally {
        System.setOut(originalSysout);
        System.setErr(originalSyserr);
    }
}

@Test
public void testWindowJoin() throws Exception {
    final String resultPath = Files.createTempDirectory("result-path").toUri().toString();
    final class Parser implements MapFunction<String, Tuple2<String, Integer>> {

        @Override
        public Tuple2<String, Integer> map(String value) throws Exception {
            String[] fields = value.split(",");
            return new Tuple2<>(fields[1], Integer.parseInt(fields[2]));
        }
    }
    try {
        final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        DataStream<Tuple2<String, Integer>> grades = env.fromData(WindowJoinData.GRADES_INPUT.split("\n")).assignTimestampsAndWatermarks(IngestionTimeWatermarkStrategy.create()).map(new Parser());
        DataStream<Tuple2<String, Integer>> salaries = env.fromData(WindowJoinData.SALARIES_INPUT.split("\n")).assignTimestampsAndWatermarks(IngestionTimeWatermarkStrategy.create()).map(new Parser());
        org.apache.flink.streaming.examples.join.WindowJoin.runWindowJoin(grades, salaries, 100).sinkTo(FileSink.forRowFormat(new Path(resultPath), new SimpleStringEncoder<Tuple3<String, Integer, Integer>>()).build());
        env.execute();
        // since the two sides of the join might have different speed
        // the exact output can not be checked just whether it is well-formed
        // checks that the result lines look like e.g. (bob, 2, 2015)
        checkLinesAgainstRegexp(resultPath, "^\\([a-z]+,(\\d),(\\d)+\\)");
    } finally {
        try {
            FileUtils.deleteDirectory(new File(resultPath));
        } catch (Throwable ignored) {
        }
    }
}

