@Test
// OS must support SLEEP command
@DisabledOnOs({ OS.WINDOWS, OS.OTHER })
public void testCopyCommandInterruptible(@TempDir File temporaryDirectory) throws Exception {
    File cmdFile = new File(temporaryDirectory, "cmd");
    FileUtils.writeStringToFile(cmdFile, "sleep 1000", Charset.defaultCharset());
    Preconditions.checkState(cmdFile.setExecutable(true), "Cannot set script file executable.");
    final Configuration conf = new Configuration();
    conf.set(S5CMD_PATH, cmdFile.getAbsolutePath());
    conf.set(S5CMD_EXTRA_ARGS, "");
    conf.set(ACCESS_KEY, "test-access-key");
    conf.set(SECRET_KEY, "test-secret-key");
    conf.set(ENDPOINT, "test-endpoint");
    TestS3FileSystemFactory factory = new TestS3FileSystemFactory();
    factory.configure(conf);
    FlinkS3FileSystem fs = (FlinkS3FileSystem) factory.create(new URI("s3://test"));
    AtomicReference<IOException> actualException = new AtomicReference<>();
    CountDownLatch registerLatch = new CountDownLatch(1);
    ICloseableRegistry closeableRegistry = new CloseableRegistry() {

        @Override
        protected void doRegister(@Nonnull Closeable closeable, @Nonnull Map<Closeable, Object> closeableMap) {
            super.doRegister(closeable, closeableMap);
            registerLatch.countDown();
        }
    };
    Thread thread = new Thread(() -> {
        try {
            fs.copyFiles(Collections.singletonList(CopyRequest.of(Path.fromLocalFile(new File("")), Path.fromLocalFile(new File("")), 100L)), closeableRegistry);
        } catch (IOException ex) {
            actualException.set(ex);
        }
    });
    thread.start();
    registerLatch.await();
    closeableRegistry.close();
    thread.join(60_000L);
    Assertions.assertThat(thread.isAlive()).isFalse();
    Assertions.assertThat(actualException.get()).hasStackTraceContaining("Copy process destroyed by CloseableRegistry.");
}

@ParameterizedTest
@ValueSource(ints = { 1, 7, 10, 14, Integer.MAX_VALUE })
// POSIX OS only to run shell script
@EnabledOnOs({ OS.LINUX, OS.MAC })
public void testCopyCommandBatching(int batchSize, @TempDir File temporaryDirectory) throws Exception {
    final int numFiles = 10;
    File cmdFile = new File(temporaryDirectory, "cmd");
    File inputToCmd = new File(temporaryDirectory, "input");
    Preconditions.checkState(inputToCmd.mkdir());
    String cmd = String.format("file=$(mktemp %s/s5cmd-input-XXX)\n" + "while read line; do echo $line >> $file; done < /dev/stdin", inputToCmd.getAbsolutePath());
    FileUtils.writeStringToFile(cmdFile, cmd);
    Preconditions.checkState(cmdFile.setExecutable(true), "Cannot set script file executable.");
    final Configuration conf = new Configuration();
    conf.set(S5CMD_PATH, cmdFile.getAbsolutePath());
    conf.set(S5CMD_EXTRA_ARGS, "");
    conf.set(S5CMD_BATCH_MAX_FILES, batchSize);
    conf.set(ACCESS_KEY, "test-access-key");
    conf.set(SECRET_KEY, "test-secret-key");
    conf.set(ENDPOINT, "test-endpoint");
    TestS3FileSystemFactory factory = new TestS3FileSystemFactory();
    factory.configure(conf);
    FlinkS3FileSystem fs = (FlinkS3FileSystem) factory.create(new URI("s3://test"));
    List<CopyRequest> tasks = IntStream.range(0, numFiles).mapToObj(i -> CopyRequest.of(new Path("file:///src-" + i), new Path("file:///dst-" + i), 123L)).collect(Collectors.toList());
    fs.copyFiles(tasks, ICloseableRegistry.NO_OP);
    File[] files = inputToCmd.listFiles();
    Assertions.assertThat(files).isNotNull();
    Assertions.assertThat(files.length).describedAs("Wrong number of s5cmd subcommand batches for input tasks: %s", tasks).isEqualTo(numFiles / batchSize + (numFiles % batchSize > 0 ? 1 : 0));
    int totalSubcommands = 0;
    for (File file : files) {
        List<String> subcommands = FileUtils.readLines(file, StandardCharsets.UTF_8);
        Assertions.assertThat(subcommands.size()).describedAs("Too many s5cmd subcommands issued per batch: %s\n(input files: %s)", subcommands, tasks).isLessThanOrEqualTo(batchSize);
        totalSubcommands += subcommands.size();
    }
    Assertions.assertThat(totalSubcommands).describedAs("The total number of issued s5cmd subcommands did not match the number of copy tasks:\n%s,\n%s", totalSubcommands, tasks).isEqualTo(numFiles);
}

