@Test
void testRecoveryWithS5Cmd(@InjectMiniCluster MiniCluster flinkCluster) throws Exception {
    final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
    env.setParallelism(2);
    env.enableCheckpointing(CHECKPOINT_INTERVAL);
    RestartStrategyUtils.configureFixedDelayRestartStrategy(env, 1, 0L);
    StateBackendUtils.configureRocksDBStateBackend(env);
    // Disable changelog, to make sure state is stored in the RocksDB, not in changelog, as
    // currently only RocksDB is using s5cmd.
    env.enableChangelogStateBackend(false);
    try (CloseableIterator<Record> results = env.addSource(new FailingSource()).keyBy(x -> x.key).reduce((ReduceFunction<Record>) (record1, record2) -> {
        checkState(record1.key == record2.key);
        return new Record(record1.key, record1.value + record2.value);
    }).collectAsync()) {
        env.execute();
        // verify that the max emitted values are exactly the sum of all emitted records
        long maxValue1 = 0;
        long maxValue2 = 0;
        while (results.hasNext()) {
            Record next = results.next();
            if (next.key == FailingSource.FIRST_KEY) {
                maxValue1 = Math.max(maxValue1, next.value);
            } else if (next.key == FailingSource.SECOND_KEY) {
                maxValue2 = Math.max(maxValue2, next.value);
            } else {
                throw new Exception("This shouldn't happen: " + next);
            }
        }
        assertThat(maxValue1).isEqualTo((FailingSource.LAST_EMITTED_VALUE + 1) * FailingSource.LAST_EMITTED_VALUE / 2);
        assertThat(maxValue2).isEqualTo((FailingSource.LAST_EMITTED_VALUE + 1) * FailingSource.LAST_EMITTED_VALUE);
    }
}

