@Test
void testKryoInChildClasspath() throws Exception {
    final Class<?> avroClass = AvroKryoSerializerUtils.class;
    final URL avroLocation = avroClass.getProtectionDomain().getCodeSource().getLocation();
    final URL kryoLocation = Kryo.class.getProtectionDomain().getCodeSource().getLocation();
    final ClassLoader parentClassLoader = new FilteredClassLoader(avroClass.getClassLoader(), AvroKryoSerializerUtils.class.getName());
    final ClassLoader userAppClassLoader = FlinkUserCodeClassLoaders.childFirst(new URL[] { avroLocation, kryoLocation }, parentClassLoader, CoreOptions.ALWAYS_PARENT_FIRST_LOADER_PATTERNS.defaultValue().toArray(new String[0]), NOOP_EXCEPTION_HANDLER, true);
    final Class<?> userLoadedAvroClass = Class.forName(avroClass.getName(), false, userAppClassLoader);
    assertThat(userLoadedAvroClass).isNotEqualTo(avroClass);
    // call the 'addAvroGenericDataArrayRegistration(...)' method
    final Method m = userLoadedAvroClass.getMethod("addAvroGenericDataArrayRegistration", LinkedHashMap.class);
    final LinkedHashMap<String, ?> map = new LinkedHashMap<>();
    m.invoke(userLoadedAvroClass.newInstance(), map);
    assertThat(map).hasSize(1);
}

/**
 * Tests that the registered classes in Kryo did not change.
 *
 * <p>Once we have proper serializer versioning this test will become obsolete. But currently a
 * change in the serializers can break savepoint backwards compatibility between Flink versions.
 */
@Test
void testDefaultKryoRegisteredClassesDidNotChange() throws Exception {
    final Kryo kryo = new KryoSerializer<>(Integer.class, new SerializerConfigImpl()).getKryo();
    try (BufferedReader reader = new BufferedReader(new InputStreamReader(getClass().getClassLoader().getResourceAsStream("flink_11-kryo_registrations")))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] split = line.split(",");
            final int tag = Integer.parseInt(split[0]);
            final String registeredClass = split[1];
            Registration registration = kryo.getRegistration(tag);
            if (registration == null) {
                fail(String.format("Registration for %d = %s got lost", tag, registeredClass));
            } else if (!registeredClass.equals(registration.getType().getName())) {
                fail(String.format("Registration for %d = %s changed to %s", tag, registeredClass, registration.getType().getName()));
            }
        }
    }
}

