/**
 * FLINK-35240 : Verifies that Jackson CSV writer does not flush per record but waits for a
 * flush signal from Flink.
 */
@Test
public void testNoDataIsWrittenBeforeFlinkFlush() throws Exception {
    Configuration config = new Configuration();
    config.set(RestartStrategyOptions.RESTART_STRATEGY, RestartStrategyOptions.RestartStrategyType.NO_RESTART_STRATEGY.getMainValue());
    StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment(config);
    env.setParallelism(1);
    env.enableCheckpointing(100);
    // Workaround serialization limitations
    File outDirRef = new File(outDir.getAbsolutePath());
    FileSink<Pojo> sink = FileSink.forBulkFormat(new org.apache.flink.core.fs.Path(outDir.getAbsolutePath()), out -> {
        FSDataOutputStreamWrapper outputStreamWrapper = new FSDataOutputStreamWrapper(out);
        return new CsvBulkWriterWrapper<>(CsvBulkWriter.forPojo(Pojo.class, outputStreamWrapper), outputStreamWrapper, outDirRef);
    }).build();
    List<Pojo> integers = Arrays.asList(new Pojo(1), new Pojo(2));
    DataGeneratorSource<Pojo> generatorSource = TestDataGenerators.fromDataWithSnapshotsLatch(integers, TypeInformation.of(Pojo.class));
    env.fromSource(generatorSource, WatermarkStrategy.noWatermarks(), "").sinkTo(sink);
    env.execute();
    assertThat(getResultsFromSinkFiles(outDir)).containsSequence("1", "2", "1", "2");
}

