@Test
void ignoreInvalidLines() throws Exception {
    String fileContent = "#description of the data\n" + "header1|header2|header3|\n" + "this is|1|2.0|\n" + "//a comment\n" + "a test|3|4.0|\n" + "#next|5|6.0|\n";
    FileInputSplit split = createTempFile(fileContent);
    TypeInformation[] fieldTypes = new TypeInformation[] { BasicTypeInfo.STRING_TYPE_INFO, BasicTypeInfo.INT_TYPE_INFO, BasicTypeInfo.DOUBLE_TYPE_INFO };
    RowCsvInputFormat.Builder builder = RowCsvInputFormat.builder(new RowTypeInfo(fieldTypes), PATH).setFieldDelimiter('|').setIgnoreParseErrors(false);
    RowCsvInputFormat format = builder.build();
    Configuration parameters = new Configuration();
    format.configure(parameters);
    format.open(split);
    Row result = new Row(3);
    RowCsvInputFormat finalFormat = format;
    Row finalResult = result;
    assertThatThrownBy(() -> finalFormat.nextRecord(finalResult)).isInstanceOf(IOException.class).hasRootCauseMessage("Row length mismatch. 3 fields expected but was 1.");
    RowCsvInputFormat finalFormat1 = format;
    Row finalResult1 = result;
    assertThatThrownBy(() -> finalFormat1.nextRecord(finalResult1)).isInstanceOf(IOException.class).hasRootCauseMessage("For input string: \"header2\"");
    result = format.nextRecord(result);
    assertThat(result).isNotNull();
    assertThat(result.getField(0)).isEqualTo("this is");
    assertThat(result.getField(1)).isEqualTo(1);
    assertThat(result.getField(2)).isEqualTo(2.0);
    RowCsvInputFormat finalFormat2 = format;
    Row finalResult2 = result;
    assertThatThrownBy(() -> finalFormat2.nextRecord(finalResult2)).isInstanceOf(IOException.class).hasRootCauseMessage("Row length mismatch. 3 fields expected but was 1.");
    result = format.nextRecord(result);
    assertThat(result).isNotNull();
    assertThat(result.getField(0)).isEqualTo("a test");
    assertThat(result.getField(1)).isEqualTo(3);
    assertThat(result.getField(2)).isEqualTo(4.0);
    result = format.nextRecord(result);
    assertThat(result).isNotNull();
    assertThat(result.getField(0)).isEqualTo("#next");
    assertThat(result.getField(1)).isEqualTo(5);
    assertThat(result.getField(2)).isEqualTo(6.0);
    result = format.nextRecord(result);
    assertThat(result).isNull();
    // re-open with lenient = true
    builder.setIgnoreParseErrors(true);
    format = builder.build();
    format.configure(parameters);
    format.open(split);
    result = new Row(3);
    result = format.nextRecord(result);
    assertThat(result).isNotNull();
    assertThat(result.getField(0)).isEqualTo("#description of the data");
    result = format.nextRecord(result);
    assertThat(result).isNotNull();
    assertThat(result.getField(0)).isEqualTo("header1");
    assertThat(result.getField(1)).isNull();
    assertThat(result.getField(2)).isNull();
    result = format.nextRecord(result);
    assertThat(result).isNotNull();
    assertThat(result.getField(0)).isEqualTo("this is");
    assertThat(result.getField(1)).isEqualTo(1);
    assertThat(result.getField(2)).isEqualTo(2.0);
    result = format.nextRecord(result);
    assertThat(result).isNotNull();
    assertThat(result.getField(0)).isEqualTo("//a comment");
    result = format.nextRecord(result);
    assertThat(result).isNotNull();
    assertThat(result.getField(0)).isEqualTo("a test");
    assertThat(result.getField(1)).isEqualTo(3);
    assertThat(result.getField(2)).isEqualTo(4.0);
    result = format.nextRecord(result);
    assertThat(result).isNotNull();
    assertThat(result.getField(0)).isEqualTo("#next");
    assertThat(result.getField(1)).isEqualTo(5);
    assertThat(result.getField(2)).isEqualTo(6.0);
    result = format.nextRecord(result);
    assertThat(result).isNull();
}

