/**
 * Tests if we could create {@link HadoopPathBasedBulkFormatBuilder} within user classloader. It
 * is mainly verify we have fixed the issue raised in
 * https://issues.apache.org/jira/browse/FLINK-19398.
 */
@Test
@SuppressWarnings({ "unchecked", "rawtypes" })
public void testCreatingBuildWithinUserClassLoader() throws Exception {
    ClassLoader appClassLoader = getClass().getClassLoader();
    assumeThat(appClassLoader).isInstanceOf(URLClassLoader.class);
    ClassLoader userClassLoader = new SpecifiedChildFirstUserClassLoader(HadoopPathBasedBulkFormatBuilder.class.getName(), appClassLoader, ((URLClassLoader) appClassLoader).getURLs());
    Class<HadoopPathBasedBulkFormatBuilder> userHadoopFormatBuildClass = (Class<HadoopPathBasedBulkFormatBuilder>) userClassLoader.loadClass(HadoopPathBasedBulkFormatBuilder.class.getName());
    Constructor<?> constructor = userHadoopFormatBuildClass.getConstructor(Path.class, HadoopPathBasedBulkWriter.Factory.class, Configuration.class, BucketAssigner.class);
    Object hadoopFormatBuilder = constructor.newInstance(new Path("/tmp"), new TestHadoopPathBasedBulkWriterFactory(), new Configuration(), new DateTimeBucketAssigner<>());
    Buckets<String, String> buckets = (Buckets<String, String>) userHadoopFormatBuildClass.getMethod("createBuckets", int.class).invoke(hadoopFormatBuilder, 0);
    assertThat(buckets).isNotNull();
}

