@Test
void testReadDecimalTypeFile() throws IOException {
    OrcColumnarRowInputFormat<?, FileSourceSplit> format = createFormat(DECIMAL_FILE_TYPE, new int[] { 0 });
    AtomicInteger cnt = new AtomicInteger(0);
    AtomicInteger nullCount = new AtomicInteger(0);
    // read all splits
    for (FileSourceSplit split : createSplits(decimalFile, 4)) {
        forEach(format, split, row -> {
            if (cnt.get() == 0) {
                // validate first row
                assertThat(row).isNotNull();
                assertThat(row.getArity()).isEqualTo(1);
                assertThat(row.getDecimal(0, 10, 5)).isEqualTo(DecimalDataUtils.castFrom(-1000.5d, 10, 5));
            } else {
                if (!row.isNullAt(0)) {
                    assertThat(row.getDecimal(0, 10, 5)).isNotNull();
                } else {
                    nullCount.incrementAndGet();
                }
            }
            cnt.incrementAndGet();
        });
