@ParameterizedTest
@MethodSource("parameters")
void testProjectionReadUnknownFieldAcrossFiles(int rowGroupSize) throws IOException {
    int number = 100;
    final List<RowData> records = IntStream.range(0, number).mapToObj(this::newRow).collect(Collectors.toList());
    // create parquet files for both legacy and new
    // f7 and f99 don’t exist in legacy parquet file
    // f99 doesn't exist in new parquet file
    // create legacy parquet file
    // assume f7 and following columns do not exist in legacy parquet file.
    RowType legacyParquetType = new RowType(IntStream.range(0, 6).mapToObj(i -> ROW_TYPE.getFields().get(i)).collect(Collectors.toList()));
    Path legacyParquetPath = createTempParquetFile(new File(folder, "legacy"), legacyParquetType, records, rowGroupSize);
    // create new parquet file
    Path newParquetPath = createTempParquetFile(new File(folder, "new"), records, rowGroupSize);
    // test reader
    // f7 and f99 do not exist in parquet file.
    String[] readerColumnNames = new String[] { "f7", "f2", "f4", "f99" };
    final LogicalType[] fieldTypes = Arrays.stream(readerColumnNames).map(ROW_TYPE::getFieldIndex).map(index -> (index != -1) ? ROW_TYPE.getTypeAt(index) : new VarCharType()).toArray(LogicalType[]::new);
    ParquetColumnarRowInputFormat<FileSourceSplit> format = new ParquetColumnarRowInputFormat<>(new Configuration(), RowType.of(fieldTypes, readerColumnNames), null, 500, false, true);
    AtomicInteger cnt = new AtomicInteger(0);
    // iterate data in both legacy and new parquet file separately
    // equivalent to the call function: FileSource.forBulkFileFormat(BulkFormat,Path...);
    // f7 is expected to be null in the legacy parquet file
    forEachRemaining(format.createReader(EMPTY_CONF, new FileSourceSplit("id", legacyParquetPath, 0, Long.MAX_VALUE, 0, Long.MAX_VALUE)), row -> {
        int i = cnt.get();
        assertThat(row.isNullAt(0)).isTrue();
        assertThat(row.getByte(1)).isEqualTo((byte) i);
        assertThat(row.getInt(2)).isEqualTo(i);
        assertThat(row.isNullAt(3)).isTrue();
        cnt.incrementAndGet();
    });
    // f7 is expected to exist in the new parquet file
    cnt.set(0);
    forEachRemaining(format.createReader(EMPTY_CONF, new FileSourceSplit("id", newParquetPath, 0, Long.MAX_VALUE, 0, Long.MAX_VALUE)), row -> {
        int i = cnt.get();
        assertThat(row.getDouble(0)).isEqualTo(i);
        assertThat(row.getByte(1)).isEqualTo((byte) i);
        assertThat(row.getInt(2)).isEqualTo(i);
        assertThat(row.isNullAt(3)).isTrue();
        cnt.incrementAndGet();
    });
}

