@Test
void testLeaderElectionAndRetrieval() throws Exception {
    final String componentId = "component-id";
    final String leaderAddress = "random-address";
    final String configMapName = LEADER_CONFIGMAP_NAME + UUID.randomUUID();
    final FlinkKubeClient flinkKubeClient = KUBERNETES_EXTENSION.getFlinkKubeClient();
    final Configuration configuration = KUBERNETES_EXTENSION.getConfiguration();
    final String clusterId = configuration.get(KubernetesConfigOptions.CLUSTER_ID);
    // This will make the leader election retrieval time out if we won't process already
    // existing leader information when starting it up.
    configuration.set(KubernetesHighAvailabilityOptions.KUBERNETES_LEASE_DURATION, Duration.ofHours(1));
    configuration.set(KubernetesHighAvailabilityOptions.KUBERNETES_RETRY_PERIOD, Duration.ofHours(1));
    configuration.set(KubernetesHighAvailabilityOptions.KUBERNETES_RENEW_DEADLINE, Duration.ofHours(1));
    final List<AutoCloseable> closeables = new ArrayList<>();
    final KubernetesConfigMapSharedWatcher configMapSharedWatcher = flinkKubeClient.createConfigMapSharedWatcher(configMapName);
    closeables.add(configMapSharedWatcher);
    final TestingLeaderElectionListener electionEventHandler = new TestingLeaderElectionListener();
    try {
        final KubernetesLeaderElectionDriver leaderElectionDriver = new KubernetesLeaderElectionDriver(new KubernetesLeaderElectionConfiguration(configMapName, UUID.randomUUID().toString(), configuration), flinkKubeClient, electionEventHandler, configMapSharedWatcher, EXECUTOR_EXTENSION.getExecutor());
        closeables.add(leaderElectionDriver);
        final KubernetesLeaderRetrievalDriverFactory driverFactory = new KubernetesLeaderRetrievalDriverFactory(configMapSharedWatcher, EXECUTOR_EXTENSION.getExecutor(), configMapName, componentId);
        final TestingFatalErrorHandler fatalErrorHandler = new TestingFatalErrorHandler();
        final TestingLeaderRetrievalEventHandler firstLeaderRetrievalEventHandler = new TestingLeaderRetrievalEventHandler();
        closeables.add(driverFactory.createLeaderRetrievalDriver(firstLeaderRetrievalEventHandler, fatalErrorHandler));
        // Wait for the driver to obtain leadership.
        electionEventHandler.await(LeaderElectionEvent.IsLeaderEvent.class);
        final LeaderInformation leaderInformation = LeaderInformation.known(UUID.randomUUID(), leaderAddress);
        leaderElectionDriver.publishLeaderInformation(componentId, leaderInformation);
        // Check if the leader retrieval driver is notified about the leader address
        awaitLeadership(firstLeaderRetrievalEventHandler, leaderInformation);
        // Start a second leader retrieval that should be notified immediately because we
        // already know who the leader is.
        final TestingLeaderRetrievalEventHandler secondRetrievalEventHandler = new TestingLeaderRetrievalEventHandler();
        closeables.add(driverFactory.createLeaderRetrievalDriver(secondRetrievalEventHandler, fatalErrorHandler));
        awaitLeadership(secondRetrievalEventHandler, leaderInformation);
    } finally {
        for (AutoCloseable closeable : closeables) {
            closeable.close();
        }
        flinkKubeClient.deleteConfigMap(configMapName).get();
        electionEventHandler.failIfErrorEventHappened();
    }
}

