@Test
void testCheckAndUpdateConfigMapWhenGetConfigMapFailed() throws Exception {
    final int configuredRetries = flinkConfig.get(KubernetesConfigOptions.KUBERNETES_TRANSACTIONAL_OPERATION_MAX_RETRIES);
    final KubernetesConfigMap configMap = buildTestingConfigMap();
    this.flinkKubeClient.createConfigMap(configMap).get();
    kubeClient.getConfiguration().setRequestRetryBackoffLimit(0);
    mockGetConfigMapFailed(configMap.getInternalResource());
    final int initialRequestCount = server.getRequestCount();
    assertThatThrownBy(() -> this.flinkKubeClient.checkAndUpdateConfigMap(TESTING_CONFIG_MAP_NAME, c -> {
        throw new AssertionError("The replace operation should have never been triggered.");
    }).get(), "checkAndUpdateConfigMap should fail without a PossibleInconsistentStateException being the cause when number of retries has been exhausted.").satisfies(anyCauseMatches("Could not complete the operation. Number of retries has been exhausted.")).satisfies(cause -> assertThatChainOfCauses(cause).withFailMessage("An error while retrieving the ConfigMap should not cause a PossibleInconsistentStateException.").isNotOfAnyClassIn(PossibleInconsistentStateException.class));
    final int actualRetryCount = server.getRequestCount() - initialRequestCount;
    assertThat(actualRetryCount).isEqualTo(configuredRetries + 1);
}

@Test
void testCheckAndUpdateConfigMapWhenReplaceConfigMapFailed() throws Exception {
    final int configuredRetries = flinkConfig.get(KubernetesConfigOptions.KUBERNETES_TRANSACTIONAL_OPERATION_MAX_RETRIES);
    final KubernetesConfigMap configMap = buildTestingConfigMap();
    this.flinkKubeClient.createConfigMap(configMap).get();
    mockReplaceConfigMapFailed(configMap.getInternalResource());
    final AtomicInteger retries = new AtomicInteger(0);
    assertThatThrownBy(() -> this.flinkKubeClient.checkAndUpdateConfigMap(TESTING_CONFIG_MAP_NAME, c -> {
        retries.incrementAndGet();
        return Optional.of(configMap);
    }).get(), "checkAndUpdateConfigMap should fail due to a PossibleInconsistentStateException when number of retries has been exhausted.").satisfies(anyCauseMatches("Could not complete the " + "operation. Number of retries has been exhausted.")).satisfies(anyCauseMatches(PossibleInconsistentStateException.class));
    assertThat(retries.get()).isEqualTo(configuredRetries + 1);
}

