@Test
void testWatchWithBlockHandler() throws Exception {
    final String configMapName = getConfigMapName(System.currentTimeMillis());
    try (KubernetesConfigMapSharedWatcher watcher = client.createConfigMapSharedWatcher(configMapName)) {
        final long block = 500;
        final long maxUpdateVal = 30;
        final CompletableFuture<Void> expectedFuture = new CompletableFuture<>();
        final CompletableFuture<Void> assertFuture = new CompletableFuture<>();
        final TestingWatchCallbackHandler handler = TestingWatchCallbackHandler.<KubernetesConfigMap>builder().setOnAddedConsumer((resources) -> onAddedOrModified(resources, maxUpdateVal, block, expectedFuture, assertFuture)).setOnModifiedConsumer((resources) -> onAddedOrModified(resources, maxUpdateVal, block, expectedFuture, assertFuture)).build();
        final Watch watch = watcher.watch(configMapName, handler, watchCallbackExecutorService);
        createConfigMap(configMapName);
        for (int i = 1; i <= maxUpdateVal; i++) {
            updateConfigMap(configMapName, ImmutableMap.of("val", String.valueOf(i)));
        }
        assertThatCode(() -> expectedFuture.get(120, TimeUnit.SECONDS)).as("expected value: " + maxUpdateVal + ", actual: " + blockVal).doesNotThrowAnyException();
        try {
            assertFuture.get(2 * block, TimeUnit.MILLISECONDS);
        } catch (TimeoutException e) {
            // expected
        }
        watch.close();
    }
}

