@Test
public void testSimplePatternCEP() throws Exception {
    StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment(envConfiguration);
    DataStream<Event> input = env.fromData(new Event(1, "barfoo", 1.0), new Event(2, "start", 2.0), new Event(3, "foobar", 3.0), new SubEvent(4, "foo", 4.0, 1.0), new Event(5, "middle", 5.0), new SubEvent(6, "middle", 6.0, 2.0), new SubEvent(7, "bar", 3.0, 3.0), new Event(42, "42", 42.0), new Event(8, "end", 1.0));
    Pattern<Event, ?> pattern = Pattern.<Event>begin("start").where(SimpleCondition.of(value -> value.getName().equals("start"))).followedByAny("middle").subtype(SubEvent.class).where(SimpleCondition.of(value -> value.getName().equals("middle"))).followedByAny("end").where(SimpleCondition.of(value -> value.getName().equals("end")));
    DataStream<String> result = CEP.pattern(input, pattern).inProcessingTime().flatSelect((p, o) -> {
        StringBuilder builder = new StringBuilder();
        builder.append(p.get("start").get(0).getId()).append(",").append(p.get("middle").get(0).getId()).append(",").append(p.get("end").get(0).getId());
        o.collect(builder.toString());
    }, Types.STRING);
    List<String> resultList = new ArrayList<>();
    result.executeAndCollect().forEachRemaining(resultList::add);
    assertEquals(Arrays.asList("2,6,8"), resultList);
}

