@Test
public void testTimeoutHandlingWithinFirstAndLast() throws Exception {
    StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment(envConfiguration);
    env.setParallelism(1);
    // (Event, timestamp)
    DataStream<Event> input = env.fromData(Tuple2.of(new Event(1, "start", 1.0), 1L), Tuple2.of(new Event(1, "middle", 2.0), 5L), Tuple2.of(new Event(1, "start", 2.0), 4L), Tuple2.of(new Event(1, "end", 2.0), 6L)).assignTimestampsAndWatermarks(new WatermarkStrategyWithPunctuatedWatermarks<Tuple2<Event, Long>>() {

        @Override
        public long extractTimestamp(Tuple2<Event, Long> element, long currentTimestamp) {
            return element.f1;
        }

        @Override
        public Watermark checkAndGetNextWatermark(Tuple2<Event, Long> lastElement, long extractedTimestamp) {
            return new Watermark(lastElement.f1 - 5);
        }
    }).map(new MapFunction<Tuple2<Event, Long>, Event>() {

        @Override
        public Event map(Tuple2<Event, Long> value) throws Exception {
            return value.f0;
        }
    });
    Pattern<Event, ?> pattern = Pattern.<Event>begin("start").where(SimpleCondition.of(value -> value.getName().equals("start"))).followedByAny("middle").where(SimpleCondition.of(value -> value.getName().equals("middle"))).followedByAny("end").where(SimpleCondition.of(value -> value.getName().equals("end"))).within(Duration.ofMillis(3));
    OutputTag<String> outputTag = new OutputTag<String>("side-output") {
    };
    SingleOutputStreamOperator<String> result = CEP.pattern(input, pattern).select(outputTag, new PatternTimeoutFunction<Event, String>() {

        @Override
        public String timeout(Map<String, List<Event>> pattern, long timeoutTimestamp) throws Exception {
            return pattern.get("start").get(0).getPrice() + "";
        }
    }, new PatternSelectFunction<Event, String>() {

        @Override
        public String select(Map<String, List<Event>> pattern) {
            StringBuilder builder = new StringBuilder();
            builder.append(pattern.get("start").get(0).getPrice()).append(",").append(pattern.get("middle").get(0).getPrice()).append(",").append(pattern.get("end").get(0).getPrice());
            return builder.toString();
        }
    });
    List<String> resultList = new ArrayList<>();
    result.executeAndCollect().forEachRemaining(resultList::add);
    resultList.sort(Comparator.comparing(Object::toString));
    List<String> timeoutList = new ArrayList<>();
    result.getSideOutput(outputTag).executeAndCollect().forEachRemaining(timeoutList::add);
    timeoutList.sort(Comparator.comparing(Object::toString));
    List<String> timeoutExpected = Arrays.asList("1.0", "2.0", "2.0");
    List<String> resultExpected = Arrays.asList("2.0,2.0,2.0");
    assertEquals(timeoutExpected, timeoutList);
    assertEquals(resultExpected, resultList);
}

