@Test
public void testPartialMatchTimeoutOutputCompletedMatch() throws Exception {
    StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment(envConfiguration);
    // (Event, timestamp)
    DataStream<Event> input = env.fromData(Tuple2.of(new Event(1, "start", 1.0), 0L), Tuple2.of(new Event(2, "start", 2.0), 1L), Tuple2.of(new Event(3, "start", 3.0), 2L), Tuple2.of(new Event(4, "start", 4.0), 3L), Tuple2.of(new Event(5, "end", 5.0), 4L)).assignTimestampsAndWatermarks(WatermarkStrategy.<Tuple2<Event, Long>>forBoundedOutOfOrderness(Duration.ofMillis(5)).withTimestampAssigner(TimestampAssignerSupplier.of((SerializableTimestampAssigner<Tuple2<Event, Long>>) (element, recordTimestamp) -> element.f1))).map((MapFunction<Tuple2<Event, Long>, Event>) value -> value.f0);
    Pattern<Event, ?> pattern = Pattern.<Event>begin("start", AfterMatchSkipStrategy.skipPastLastEvent()).where(SimpleCondition.of(value -> value.getName().equals("start"))).oneOrMore().consecutive().greedy().followedBy("middle").where(new IterativeCondition<Event>() {

        @Override
        public boolean filter(Event value, Context<Event> ctx) throws Exception {
            int count = 0;
            for (Event ignored : ctx.getEventsForPattern("start")) {
                count++;
            }
            if (count > 2) {
                return value.getName().equals("middle");
            } else {
                return value.getName().equals("end");
            }
        }
    }).within(Duration.ofMillis(100L));
    DataStream<String> result = CEP.pattern(input, pattern).select((PatternSelectFunction<Event, String>) pattern1 -> pattern1.get("start").get(0).getId() + "," + pattern1.get("middle").get(0).getId());
    List<String> resultList = new ArrayList<>();
    try (CloseableIterator<String> iterator = result.executeAndCollect()) {
        iterator.forEachRemaining(resultList::add);
    }
    resultList.sort(String::compareTo);
    assertEquals(Arrays.asList("3,5"), resultList);
}

