public void testIterativeWithPrevPatternDependency() throws Exception {
    List<StreamRecord<Event>> inputEvents = new ArrayList<>();
    inputEvents.add(new StreamRecord<>(startEvent1, 1L));
    inputEvents.add(new StreamRecord<>(startEvent2, 2L));
    inputEvents.add(new StreamRecord<>(endEvent, 4L));
    Pattern<Event, ?> pattern = Pattern.<Event>begin("start").where(SimpleCondition.of(value -> value.getName().equals("start"))).oneOrMore().followedBy("end").where(new IterativeCondition<Event>() {

        private static final long serialVersionUID = 7056763917392056548L;

        @Override
        public boolean filter(Event value, Context<Event> ctx) throws Exception {
            if (!value.getName().equals("end")) {
                return false;
            }
            double sum = 0.0;
            for (Event event : ctx.getEventsForPattern("start")) {
                sum += event.getPrice();
            }
            return Double.compare(sum, 2.0) >= 0;
        }
    });
    NFA<Event> nfa = compile(pattern, false);
    List<List<Event>> resultingPatterns = feedNFA(inputEvents, nfa);
    comparePatterns(resultingPatterns, Lists.<List<Event>>newArrayList(Lists.newArrayList(startEvent1, startEvent2, endEvent), Lists.newArrayList(startEvent2, endEvent)));
}

