@Test
public void testSharedBuffer() throws Exception {
    SharedBuffer<Event> sharedBuffer = TestSharedBuffer.createTestBuffer(Event.createTypeSerializer(), cacheConfig);
    int numberEvents = 8;
    Event[] events = new Event[numberEvents];
