@Test
@SuppressWarnings("unchecked")
public void testReadKeyedState() throws Exception {
    Configuration config = new Configuration();
    config.set(RUNTIME_MODE, RuntimeExecutionMode.BATCH);
    StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment(config);
    StreamTableEnvironment tEnv = StreamTableEnvironment.create(env);
    final String sql = "CREATE TABLE state_table (\n" + "  k bigint,\n" + "  KeyedPrimitiveValue bigint,\n" + "  KeyedPojoValue ROW<privateLong bigint, publicLong bigint>,\n" + "  KeyedPrimitiveValueList ARRAY<bigint>,\n" + "  KeyedPrimitiveValueMap MAP<bigint, bigint>,\n" + "  PRIMARY KEY (k) NOT ENFORCED\n" + ")\n" + "with (\n" + "  'connector' = 'savepoint',\n" + "  'state.path' = 'src/test/resources/table-state',\n" + "  'operator.uid' = 'keyed-state-process-uid',\n" + "  'fields.KeyedPojoValue.value-format' = 'com.example.state.writer.job.schema.PojoData'\n" + ")";
    tEnv.executeSql(sql);
    Table table = tEnv.sqlQuery("SELECT * FROM state_table");
    List<Row> result = tEnv.toDataStream(table).executeAndCollect(100);
    assertThat(result.size()).isEqualTo(10);
    // Check key
    List<Long> keys = result.stream().map(r -> (Long) r.getField("k")).collect(Collectors.toList());
    List<Long> expectedKeys = LongStream.range(0L, 10L).boxed().collect(Collectors.toList());
    assertThat(keys).containsExactlyInAnyOrderElementsOf(expectedKeys);
    // Check primitive value state
    Set<Long> primitiveValues = result.stream().map(r -> (Long) r.getField("KeyedPrimitiveValue")).collect(Collectors.toSet());
    assertThat(primitiveValues.size()).isEqualTo(1);
    assertThat(primitiveValues.iterator().next()).isEqualTo(1L);
    // Check pojo value state
    Set<Row> pojoValues = result.stream().map(r -> (Row) r.getField("KeyedPojoValue")).collect(Collectors.toSet());
    assertThat(pojoValues.size()).isEqualTo(1);
    Row pojoData = pojoValues.iterator().next();
    assertThat(pojoData.getField("publicLong")).isEqualTo(1L);
    assertThat(pojoData.getField("privateLong")).isEqualTo(1L);
    // Check list state
    Set<Tuple2<Long, Long[]>> listValues = result.stream().map(r -> Tuple2.of((Long) r.getField("k"), (Long[]) r.getField("KeyedPrimitiveValueList"))).flatMap(l -> Set.of(l).stream()).collect(Collectors.toSet());
    assertThat(listValues.size()).isEqualTo(10);
    for (Tuple2<Long, Long[]> tuple2 : listValues) {
        assertThat(tuple2.f0).isEqualTo(tuple2.f1[0]);
    }
    // Check map state
    Set<Tuple2<Long, Map<Long, Long>>> mapValues = result.stream().map(r -> Tuple2.of((Long) r.getField("k"), (Map<Long, Long>) r.getField("KeyedPrimitiveValueMap"))).flatMap(l -> Set.of(l).stream()).collect(Collectors.toSet());
    assertThat(mapValues.size()).isEqualTo(10);
    for (Tuple2<Long, Map<Long, Long>> tuple2 : mapValues) {
        assertThat(tuple2.f1.size()).isEqualTo(1);
        assertThat(tuple2.f0).isEqualTo(tuple2.f1.get(tuple2.f0));
    }
}

