/**
 * Tests that metrics registered on the JobManager are actually accessible via JMX.
 */
@Test
void testJobManagerJMXMetricAccess(@InjectClusterClient ClusterClient<?> client) throws Exception {
    Deadline deadline = Deadline.now().plus(Duration.ofMinutes(2));
    try {
        JobVertex sourceJobVertex = new JobVertex("Source");
        sourceJobVertex.setInvokableClass(BlockingInvokable.class);
        sourceJobVertex.setParallelism(1);
        final JobCheckpointingSettings jobCheckpointingSettings = new JobCheckpointingSettings(CheckpointCoordinatorConfiguration.builder().build(), null);
        final JobGraph jobGraph = JobGraphBuilder.newStreamingJobGraphBuilder().setJobName("TestingJob").addJobVertex(sourceJobVertex).setJobCheckpointingSettings(jobCheckpointingSettings).build();
        client.submitJob(jobGraph).get();
        FutureUtils.retrySuccessfulWithDelay(() -> client.getJobStatus(jobGraph.getJobID()), Duration.ofMillis(10), deadline, status -> status == JobStatus.RUNNING, new ScheduledExecutorServiceAdapter(EXECUTOR_RESOURCE.getExecutor())).get(deadline.timeLeft().toMillis(), TimeUnit.MILLISECONDS);
        MBeanServer mBeanServer = ManagementFactory.getPlatformMBeanServer();
        Set<ObjectName> nameSet = mBeanServer.queryNames(new ObjectName("org.apache.flink.jobmanager.job.lastCheckpointSize:job_name=TestingJob,*"), null);
        assertThat(nameSet).hasSize(1);
        assertThat(mBeanServer.getAttribute(nameSet.iterator().next(), "Value")).isEqualTo(-1L);
        BlockingInvokable.unblock();
    } finally {
        BlockingInvokable.unblock();
    }
}

@Test
public void testReportLogRecord() throws Exception {
    MetricConfig metricConfig = createMetricConfig();
    String scope = this.getClass().getCanonicalName();
    String attribute1Key = "foo";
    String attribute1Value = "bar";
    String attribute2Key = "<variable>";
    String expectedAttribute2Key = attribute2Key.substring(1, attribute2Key.length() - 1);
    String attribute2Value = "value";
    String intKey = "intKey";
    String longKey = "longKey";
    String floatKey = "floatKey";
    String doubleKey = "doubleKey";
    String booleanKey = "booleanKey";
    Integer intVal = 42;
    Long longVal = 4711L;
    Float floatVal = 1.0f;
    Double doubleVal = 2.2d;
    Boolean booleanVal = Boolean.TRUE;
    String body = "Test!";
    String eventName = "JobStatusChangeEvent";
    String severity = "INFO";
    long observedTimeMs = 123456L;
    reporter.open(metricConfig);
    try {
        reporter.notifyOfAddedEvent(Event.builder(this.getClass(), eventName).setAttribute(attribute1Key, attribute1Value).setAttribute(attribute2Key, attribute2Value).setAttribute(intKey, intVal).setAttribute(longKey, longVal).setAttribute(floatKey, floatVal).setAttribute(doubleKey, doubleVal).setAttribute(booleanKey, booleanVal).setBody(body).setObservedTsMillis(observedTimeMs).setSeverity(severity).build());
    } finally {
        reporter.close();
    }
    eventuallyConsumeJson((json) -> {
        JsonNode resourceLogs = json.findPath("resourceLogs").findPath("scopeLogs");
        assertThat(resourceLogs.findPath("scope").findPath("name").asText()).isEqualTo(scope);
        JsonNode logRecord = resourceLogs.findPath("logRecords");
        assertThat(logRecord.findPath("observedTimeUnixNano").asText()).isEqualTo(Long.toString(observedTimeMs * 1000_000));
        assertThat(logRecord.findPath("severityText").asText()).isEqualTo(severity);
        assertThat(logRecord.findPath("severityNumber").asText()).isEqualTo(Integer.toString(Severity.INFO.getSeverityNumber()));
        assertThat(resourceLogs.findPath("body").findPath("stringValue").asText()).isEqualTo(body);
        JsonNode attributes = logRecord.findPath("attributes");
        List<String> attributeKeys = attributes.findValues("key").stream().map(JsonNode::asText).collect(Collectors.toList());
        assertThat(attributeKeys).contains(attribute1Key, expectedAttribute2Key, intKey, longKey, floatKey, doubleKey, booleanKey);
        attributes.forEach(attribute -> {
            String key = attribute.get("key").asText();
            if (key.equals(attribute1Key)) {
                assertThat(attribute.at("/value/stringValue").asText()).isEqualTo(attribute1Value);
            } else if (key.equals(expectedAttribute2Key)) {
                assertThat(attribute.at("/value/stringValue").asText()).isEqualTo(attribute2Value);
            } else if (key.equals(intKey)) {
                assertThat(attribute.at("/value/intValue").asText()).isEqualTo(Integer.toString(intVal));
            } else if (key.equals(longKey)) {
                assertThat(attribute.at("/value/intValue").asText()).isEqualTo(Long.toString(longVal));
            } else if (key.equals(floatKey)) {
                assertThat(Float.parseFloat(attribute.at("/value/doubleValue").asText())).isEqualTo(floatVal);
            } else if (key.equals(doubleKey)) {
                assertThat(Double.parseDouble(attribute.at("/value/doubleValue").asText())).isEqualTo(doubleVal);
            } else if (key.equals(booleanKey)) {
                assertThat(attribute.at("/value/boolValue").asText()).isEqualTo(Boolean.toString(booleanVal));
            }
        });
    });
}

