    String attribute1KeyRoot = "foo";
    String attribute1ValueRoot = "bar";
    String attribute2KeyRoot = "<variable>";
    String attribute2ValueRoot = "value";
    String name = "root";
    Duration startTs = Duration.ofMillis(42);
    Duration endTs = Duration.ofMillis(64);
    reporter.open(metricConfig);
    try {
        SpanBuilder span = Span.builder(this.getClass(), name).setAttribute(attribute1KeyRoot, attribute1ValueRoot).setAttribute(attribute2KeyRoot, attribute2ValueRoot).setStartTsMillis(startTs.toMillis()).setEndTsMillis(endTs.toMillis());
