        assertThat(scopeSpans.findPath("scope").findPath("name").asText()).isEqualTo(scope);
        JsonNode spans = scopeSpans.findPath("spans");
        assertThat(spans.findPath("name").asText()).isEqualTo(name);
        assertThat(spans.findPath("startTimeUnixNano").asText()).isEqualTo(Long.toString(startTs.toNanos()));
        assertThat(spans.findPath("endTimeUnixNano").asText()).isEqualTo(Long.toString(endTs.toNanos()));
        assertThat(spans.findPath("name").asText()).isEqualTo(name);
        JsonNode attributes = spans.findPath("attributes");
        List<String> attributeKeys = attributes.findValues("key").stream().map(JsonNode::asText).collect(Collectors.toList());
