/**
 * Tests multiple clients querying multiple servers until 100k queries have been processed. At
 * this point, the client is shut down and its verified that all ongoing requests are failed.
 */
@Test
void testClientServerIntegration() throws Throwable {
    // Config
    final int numServers = 2;
    final int numServerEventLoopThreads = 2;
    final int numServerQueryThreads = 2;
    final int numClientEventLoopThreads = 4;
    final int numClientsTasks = 8;
    final int batchSize = 16;
    final int numKeyGroups = 1;
    AbstractStateBackend abstractBackend = new HashMapStateBackend();
    KvStateRegistry dummyRegistry = new KvStateRegistry();
    DummyEnvironment dummyEnv = new DummyEnvironment("test", 1, 0);
    dummyEnv.setKvStateRegistry(dummyRegistry);
    JobID jobID = new JobID();
    KeyGroupRange keyGroupRange = new KeyGroupRange(0, 0);
    TaskKvStateRegistry kvStateRegistry = dummyRegistry.createTaskRegistry(new JobID(), new JobVertexID());
    CloseableRegistry cancelStreamRegistry = new CloseableRegistry();
    AbstractKeyedStateBackend<Integer> backend = abstractBackend.createKeyedStateBackend(new KeyedStateBackendParametersImpl<>(dummyEnv, jobID, "test_op", IntSerializer.INSTANCE, numKeyGroups, keyGroupRange, kvStateRegistry, TtlTimeProvider.DEFAULT, new UnregisteredMetricsGroup(), Collections.emptyList(), cancelStreamRegistry));
    AtomicKvStateRequestStats clientStats = new AtomicKvStateRequestStats();
    final MessageSerializer<KvStateInternalRequest, KvStateResponse> serializer = new MessageSerializer<>(new KvStateInternalRequest.KvStateInternalRequestDeserializer(), new KvStateResponse.KvStateResponseDeserializer());
    Client<KvStateInternalRequest, KvStateResponse> client = null;
    ExecutorService clientTaskExecutor = null;
    final KvStateServerImpl[] server = new KvStateServerImpl[numServers];
    try {
        client = new Client<>("Test Client", numClientEventLoopThreads, serializer, clientStats);
        clientTaskExecutor = Executors.newFixedThreadPool(numClientsTasks);
        // Create state
        ValueStateDescriptor<Integer> desc = new ValueStateDescriptor<>("any", IntSerializer.INSTANCE);
        desc.setQueryable("any");
        // Create servers
        KvStateRegistry[] registry = new KvStateRegistry[numServers];
        AtomicKvStateRequestStats[] serverStats = new AtomicKvStateRequestStats[numServers];
        final KvStateID[] ids = new KvStateID[numServers];
        for (int i = 0; i < numServers; i++) {
            registry[i] = new KvStateRegistry();
            serverStats[i] = new AtomicKvStateRequestStats();
            server[i] = new KvStateServerImpl(InetAddress.getLocalHost().getHostName(), Collections.singletonList(0).iterator(), numServerEventLoopThreads, numServerQueryThreads, registry[i], serverStats[i]);
            server[i].start();
            backend.setCurrentKey(1010 + i);
            // Value per server
            ValueState<Integer> state = backend.getPartitionedState(VoidNamespace.INSTANCE, VoidNamespaceSerializer.INSTANCE, desc);
            state.update(201 + i);
            // we know it must be a KvState but this is not exposed to the user via State
            InternalKvState<Integer, ?, Integer> kvState = (InternalKvState<Integer, ?, Integer>) state;
            // Register KvState (one state instance for all server)
            ids[i] = registry[i].registerKvState(new JobID(), new JobVertexID(), new KeyGroupRange(0, 0), "any", kvState, getClass().getClassLoader());
        }
        final Client<KvStateInternalRequest, KvStateResponse> finalClient = client;
        Callable<Void> queryTask = () -> {
            while (true) {
                if (Thread.interrupted()) {
                    throw new InterruptedException();
                }
                // Random server permutation
                List<Integer> random = new ArrayList<>();
                for (int j = 0; j < batchSize; j++) {
                    random.add(j);
                }
                Collections.shuffle(random);
                // Dispatch queries
                List<CompletableFuture<KvStateResponse>> futures = new ArrayList<>(batchSize);
                for (int j = 0; j < batchSize; j++) {
                    int targetServer = random.get(j) % numServers;
                    byte[] serializedKeyAndNamespace = KvStateSerializer.serializeKeyAndNamespace(1010 + targetServer, IntSerializer.INSTANCE, VoidNamespace.INSTANCE, VoidNamespaceSerializer.INSTANCE);
                    KvStateInternalRequest request = new KvStateInternalRequest(ids[targetServer], serializedKeyAndNamespace);
                    futures.add(finalClient.sendRequest(server[targetServer].getServerAddress(), request));
                }
                // Verify results
                for (int j = 0; j < batchSize; j++) {
                    int targetServer = random.get(j) % numServers;
                    Future<KvStateResponse> future = futures.get(j);
                    byte[] buf = future.get().getContent();
                    int value = KvStateSerializer.deserializeValue(buf, IntSerializer.INSTANCE);
                    assertThat(value).isEqualTo(201L + targetServer);
                }
            }
        };
        // Submit tasks
        List<Future<Void>> taskFutures = new ArrayList<>();
        for (int i = 0; i < numClientsTasks; i++) {
            taskFutures.add(clientTaskExecutor.submit(queryTask));
        }
        long numRequests;
        while ((numRequests = clientStats.getNumRequests()) < 100_000L) {
            Thread.sleep(100L);
            LOG.info("Number of requests {}/100_000", numRequests);
        }
        try {
            client.shutdown().get();
        } catch (Exception e) {
            e.printStackTrace();
        }
        assertThat(client.isEventGroupShutdown()).isTrue();
        for (Future<Void> future : taskFutures) {
            try {
                future.get();
            } catch (Throwable throwable) {
                FlinkAssertions.assertThatChainOfCauses(throwable).anySatisfy(cause -> assertThat(cause).isInstanceOfAny(ClosedChannelException.class, IllegalStateException.class));
            }
        }
        assertThat(clientStats.getNumConnections()).withFailMessage("Connection leak (client)").isZero();
        for (int i = 0; i < numServers; i++) {
            boolean success = false;
            int numRetries = 0;
            while (!success) {
                try {
                    assertThat(serverStats[i].getNumConnections()).withFailMessage("Connection leak (server)").isZero();
                    success = true;
                } catch (Throwable t) {
                    if (numRetries < 10) {
                        LOG.info("Retrying connection leak check (server)");
                        Thread.sleep((numRetries + 1) * 50L);
                        numRetries++;
                    } else {
                        throw t;
                    }
                }
            }
        }
    } finally {
        if (client != null) {
            try {
                client.shutdown().get();
            } catch (Exception e) {
                e.printStackTrace();
            }
            assertThat(client.isEventGroupShutdown()).isTrue();
        }
        for (int i = 0; i < numServers; i++) {
            if (server[i] != null) {
                server[i].shutdown();
            }
        }
        if (clientTaskExecutor != null) {
            clientTaskExecutor.shutdown();
        }
    }
}

/**
 * Tests that on reads the expected callback methods are called and read buffers are recycled.
 */
@Test
void testReadCallbacksAndBufferRecycling() throws Exception {
    final TestingClientHandlerCallback callback = new TestingClientHandlerCallback();
    final MessageSerializer<KvStateInternalRequest, KvStateResponse> serializer = new MessageSerializer<>(new KvStateInternalRequest.KvStateInternalRequestDeserializer(), new KvStateResponse.KvStateResponseDeserializer());
    final EmbeddedChannel channel = new EmbeddedChannel(new ClientHandler<>("Test Client", serializer, callback));
    final byte[] content = new byte[0];
    final KvStateResponse response = new KvStateResponse(content);
    //
    // Request success
    //
    ByteBuf buf = MessageSerializer.serializeResponse(channel.alloc(), 1222112277L, response);
    // skip frame length
    buf.skipBytes(4);
    // Verify callback
    callback.reset();
    channel.writeInbound(buf);
    assertThat(callback.onRequestCnt).isEqualTo(1);
    assertThat(callback.onRequestId).isEqualTo(1222112277L);
    assertThat(callback.onRequestBody).isInstanceOf(KvStateResponse.class);
    assertThat(buf.refCnt()).isEqualTo(0).withFailMessage("Buffer not recycled");
    //
    // Request failure
    //
    buf = MessageSerializer.serializeRequestFailure(channel.alloc(), 1222112278, new RuntimeException("Expected test Exception"));
    // skip frame length
    buf.skipBytes(4);
    // Verify callback
    callback.reset();
    channel.writeInbound(buf);
    assertThat(callback.onRequestFailureCnt).isEqualTo(1);
    assertThat(callback.onRequestFailureId).isEqualTo(1222112278L);
    assertThat(callback.onRequestFailureBody).isInstanceOf(RuntimeException.class);
    assertThat(buf.refCnt()).isEqualTo(0).withFailMessage("Buffer not recycled");
    //
    // Server failure
    //
    buf = MessageSerializer.serializeServerFailure(channel.alloc(), new RuntimeException("Expected test Exception"));
    // skip frame length
    buf.skipBytes(4);
    // Verify callback
    callback.reset();
    channel.writeInbound(buf);
    assertThat(callback.onFailureCnt).isEqualTo(1);
    assertThat(callback.onFailureBody).isInstanceOf(RuntimeException.class);
    //
    // Unexpected messages
    //
    buf = channel.alloc().buffer(4).writeInt(1223823);
    // Verify callback
    callback.reset();
    channel.writeInbound(buf);
    assertThat(callback.onFailureCnt).isEqualTo(1);
    assertThat(callback.onFailureBody).isInstanceOf(RuntimeException.class);
    assertThat(buf.refCnt()).isEqualTo(0).withFailMessage("Buffer not recycled");
    //
    // Exception caught
    //
    callback.reset();
    channel.pipeline().fireExceptionCaught(new RuntimeException("Expected test Exception"));
    assertThat(callback.onFailureCnt).isEqualTo(1);
    assertThat(callback.onFailureBody).isInstanceOf(RuntimeException.class);
    //
    // Channel inactive
    //
    callback.reset();
    channel.pipeline().fireChannelInactive();
    assertThat(callback.onFailureCnt).isEqualTo(1);
    assertThat(callback.onFailureBody).isInstanceOf(ClosedChannelException.class);
}

