@Test
void testRpcService_ScheduleRunnableWithFixedRateSetsFlinkContextClassLoader() throws ExecutionException, InterruptedException {
    final int numberOfScheduledRuns = 2;
    final List<ClassLoader> contextClassLoaders = new ArrayList<>(numberOfScheduledRuns);
    final CompletableFuture<Void> terminalFuture = new CompletableFuture<>();
    pekkoRpcService.getScheduledExecutor().scheduleAtFixedRate(() -> {
        if (contextClassLoaders.size() < numberOfScheduledRuns) {
            contextClassLoaders.add(Thread.currentThread().getContextClassLoader());
        } else {
            terminalFuture.complete(null);
            throw new RuntimeException("cancel task");
        }
    }, 0, 1, TimeUnit.MILLISECONDS);
    terminalFuture.get();
    assertEquals(numberOfScheduledRuns, contextClassLoaders.size());
    assertThat(contextClassLoaders).allSatisfy(classLoader -> assertThat(classLoader).isSameAs(pretendFlinkClassLoader));
}

