@Test
public void testComplex() {
    SingleStepRunner runner = new SingleStepRunner();
    RecordContext<String> recordContext = buildRecordContext("a", "b");
    TestAsyncFrameworkExceptionHandler exceptionHandler = new TestAsyncFrameworkExceptionHandler();
    for (int i = 0; i < 32; i++) {
        // 2^5 for completion status combination
        // Each bit of 'i' represents the complete status when the user code executes.
        // 1 stands for the completion of corresponding future before the user code execution.
        // While 0, on the contrary, represents the scenario where the user code is executed
        // first and then the future completes.
        ArrayList<ContextStateFutureImpl<Void>> futures = new ArrayList<>(6);
        for (int j = 0; j < 5; j++) {
            ContextStateFutureImpl<Void> future = new ContextStateFutureImpl<>(runner::submit, exceptionHandler, recordContext);
            futures.add(future);
            // Complete future before user code.
            if (((i >>> j) & 1) == 1) {
                future.complete(null);
            }
        }
        // Simulate user code logic.
        StateFutureUtils.combineAll(Arrays.asList(futures.get(0), futures.get(1), futures.get(2))).thenCombine(futures.get(3), (a, b) -> {
            return 1L;
        }).thenCompose((a) -> {
            return futures.get(4);
        }).thenApply((e) -> {
            return 2L;
        }).thenAccept((b) -> {
        });
        // Complete unfinished future.
        for (int j = 0; j < 5; j++) {
            if (((i >>> j) & 1) == 0) {
                futures.get(j).complete(null);
            }
        }
        if (i == 31) {
            // All completed before user code.
            assertThat(recordContext.getReferenceCount()).withFailMessage("The reference counted tests fail for profile id %d", i).isEqualTo(0);
            assertThat(runner.runThrough()).withFailMessage("The reference counted tests fail for profile id %d", i).isFalse();
        } else {
            assertThat(recordContext.getReferenceCount()).withFailMessage("The reference counted tests fail for profile id %d", i).isGreaterThan(0);
            assertThat(runner.runThrough()).withFailMessage("The reference counted tests fail for profile id %d", i).isTrue();
            assertThat(recordContext.getReferenceCount()).withFailMessage("The reference counted tests fail for profile id %d", i).isEqualTo(0);
        }
    }
}

@Test
void testBasic() {
    EpochManager epochManager = new EpochManager(null);
    Epoch epoch1 = epochManager.onRecord();
    Epoch epoch2 = epochManager.onRecord();
    assertThat(epoch1).isEqualTo(epoch2);
    assertThat(epoch1.ongoingRecordCount).isEqualTo(2);
    AtomicInteger output = new AtomicInteger(0);
    epochManager.onNonRecord(null, () -> output.incrementAndGet(), ParallelMode.PARALLEL_BETWEEN_EPOCH);
    // record3 is in a new epoch
    Epoch epoch3 = epochManager.onRecord();
    assertThat(epoch3).isNotEqualTo(epoch1);
    assertThat(epochManager.outputQueue.size()).isEqualTo(1);
    assertThat(epochManager.outputQueue.peek().status).isEqualTo(EpochStatus.CLOSED);
    // records in first epoch are not finished, so the non-record action is not executed
    assertThat(output.get()).isEqualTo(0);
    epochManager.completeOneRecord(epoch1);
    epochManager.completeOneRecord(epoch2);
    epochManager.completeOneRecord(epoch3);
    // records in first epoch are finished, so the non-record action is executed
    assertThat(output.get()).isEqualTo(1);
    // records in second epoch are finished, but no newly arrived non-record, so the second
    // epoch is still open
    assertThat(epochManager.outputQueue.size()).isEqualTo(0);
    assertThat(epochManager.activeEpoch.ongoingRecordCount).isEqualTo(0);
    assertThat(epochManager.activeEpoch.status).isEqualTo(EpochStatus.OPEN);
    // Test if in the action there is a record processing. Should not be any error.
    epochManager.onNonRecord(null, () -> {
        output.incrementAndGet();
        Epoch epoch4 = epochManager.onRecord();
        epochManager.completeOneRecord(epoch4);
    }, ParallelMode.PARALLEL_BETWEEN_EPOCH);
    assertThat(output.get()).isEqualTo(2);
}

