@Test
void testSharedStateRegistrationOnRestore() throws Exception {
    for (RecoveryClaimMode recoveryClaimMode : RecoveryClaimMode.values()) {
        JobVertexID jobVertexID1 = new JobVertexID();
        int parallelism1 = 2;
        int maxParallelism1 = 4;
        ExecutionGraph graph = new CheckpointCoordinatorTestingUtils.CheckpointExecutionGraphBuilder().addJobVertex(jobVertexID1, parallelism1, maxParallelism1).build(EXECUTOR_RESOURCE.getExecutor());
        ExecutionJobVertex jobVertex1 = graph.getJobVertex(jobVertexID1);
        List<CompletedCheckpoint> checkpoints = Collections.emptyList();
        SharedStateRegistry firstInstance = SharedStateRegistry.DEFAULT_FACTORY.create(org.apache.flink.util.concurrent.Executors.directExecutor(), checkpoints, recoveryClaimMode);
        final EmbeddedCompletedCheckpointStore store = new EmbeddedCompletedCheckpointStore(10, checkpoints, firstInstance);
        // set up the coordinator and validate the initial state
        final CheckpointCoordinatorBuilder coordinatorBuilder = new CheckpointCoordinatorBuilder().setTimer(manuallyTriggeredScheduledExecutor);
        final CheckpointCoordinator coordinator = coordinatorBuilder.setCompletedCheckpointStore(store).build(graph);
        final int numCheckpoints = 3;
        List<KeyGroupRange> keyGroupPartitions1 = StateAssignmentOperation.createKeyGroupPartitions(maxParallelism1, parallelism1);
        for (int i = 0; i < numCheckpoints; ++i) {
            performIncrementalCheckpoint(graph.getJobID(), coordinator, jobVertex1, keyGroupPartitions1, i);
        }
        List<CompletedCheckpoint> completedCheckpoints = coordinator.getSuccessfulCheckpoints();
        assertThat(completedCheckpoints.size()).isEqualTo(numCheckpoints);
        int sharedHandleCount = 0;
        List<List<HandleAndLocalPath>> sharedHandlesByCheckpoint = new ArrayList<>(numCheckpoints);
        for (int i = 0; i < numCheckpoints; ++i) {
            sharedHandlesByCheckpoint.add(new ArrayList<>(2));
        }
        int cp = 0;
        for (CompletedCheckpoint completedCheckpoint : completedCheckpoints) {
            for (OperatorState taskState : completedCheckpoint.getOperatorStates().values()) {
                for (OperatorSubtaskState subtaskState : taskState.getStates()) {
                    for (KeyedStateHandle keyedStateHandle : subtaskState.getManagedKeyedState()) {
                        // test we are once registered with the current registry
                        verify(keyedStateHandle, times(1)).registerSharedStates(firstInstance, completedCheckpoint.getCheckpointID());
                        IncrementalRemoteKeyedStateHandle incrementalKeyedStateHandle = (IncrementalRemoteKeyedStateHandle) keyedStateHandle;
                        sharedHandlesByCheckpoint.get(cp).addAll(incrementalKeyedStateHandle.getSharedState());
                        for (HandleAndLocalPath handleAndLocalPath : incrementalKeyedStateHandle.getSharedState()) {
                            StreamStateHandle streamStateHandle = handleAndLocalPath.getHandle();
                            assertThat(streamStateHandle instanceof PlaceholderStreamStateHandle).isFalse();
                            DiscardRecordedStateObject.verifyDiscard(streamStateHandle, TernaryBoolean.FALSE);
                            ++sharedHandleCount;
                        }
                        for (HandleAndLocalPath handleAndLocalPath : incrementalKeyedStateHandle.getPrivateState()) {
                            DiscardRecordedStateObject.verifyDiscard(handleAndLocalPath.getHandle(), TernaryBoolean.FALSE);
                        }
                        verify(incrementalKeyedStateHandle.getMetaDataStateHandle(), never()).discardState();
                    }
                    verify(subtaskState, never()).discardState();
                }
            }
            ++cp;
        }
        // 2 (parallelism) x (1 (CP0) + 2 (CP1) + 2 (CP2)) = 10
        assertThat(sharedHandleCount).isEqualTo(10);
        // discard CP0
        store.removeOldestCheckpoint();
        // we expect no shared state was discarded because the state of CP0 is still referenced
        // by CP1
        for (List<HandleAndLocalPath> cpList : sharedHandlesByCheckpoint) {
            for (HandleAndLocalPath handleAndLocalPath : cpList) {
                DiscardRecordedStateObject.verifyDiscard(handleAndLocalPath.getHandle(), TernaryBoolean.FALSE);
            }
        }
        // shutdown the store
        store.shutdown(JobStatus.SUSPENDED, new CheckpointsCleaner());
        // restore the store
        Set<ExecutionJobVertex> tasks = new HashSet<>();
        tasks.add(jobVertex1);
        assertThat(store.getShutdownStatus().orElse(null)).isEqualTo(JobStatus.SUSPENDED);
        SharedStateRegistry secondInstance = SharedStateRegistry.DEFAULT_FACTORY.create(org.apache.flink.util.concurrent.Executors.directExecutor(), store.getAllCheckpoints(), recoveryClaimMode);
        final EmbeddedCompletedCheckpointStore secondStore = new EmbeddedCompletedCheckpointStore(10, store.getAllCheckpoints(), secondInstance);
        final CheckpointCoordinator secondCoordinator = coordinatorBuilder.setCompletedCheckpointStore(secondStore).build(graph);
        assertThat(secondCoordinator.restoreLatestCheckpointedStateToAll(tasks, false)).isTrue();
        // validate that all shared states are registered again after the recovery.
        cp = 0;
        for (CompletedCheckpoint completedCheckpoint : completedCheckpoints) {
            for (OperatorState taskState : completedCheckpoint.getOperatorStates().values()) {
                for (OperatorSubtaskState subtaskState : taskState.getStates()) {
                    for (KeyedStateHandle keyedStateHandle : subtaskState.getManagedKeyedState()) {
                        VerificationMode verificationMode;
                        // test we are once registered with the new registry
                        if (cp > 0) {
                            verificationMode = times(1);
                        } else {
                            verificationMode = never();
                        }
                        // check that all are registered with the new registry
                        verify(keyedStateHandle, verificationMode).registerSharedStates(secondInstance, completedCheckpoint.getCheckpointID());
                    }
                }
            }
            ++cp;
        }
        // discard CP1
        secondStore.removeOldestCheckpoint();
        // we expect that all shared state from CP0 is no longer referenced and discarded. CP2
        // is
        // still live and also
        // references the state from CP1, so we expect they are not discarded.
        verifyDiscard(sharedHandlesByCheckpoint, cpId -> recoveryClaimMode == RecoveryClaimMode.CLAIM && cpId == 0 ? TernaryBoolean.TRUE : TernaryBoolean.FALSE);
        // discard CP2
        secondStore.removeOldestCheckpoint();
        // still expect shared state not to be discarded because it may be used in later
        // checkpoints
        verifyDiscard(sharedHandlesByCheckpoint, cpId -> cpId == 1 ? TernaryBoolean.FALSE : TernaryBoolean.UNDEFINED);
    }
}

