@Test
void testSavepointScheduledInUnalignedMode() throws Exception {
    int maxConcurrentCheckpoints = 1;
    int checkpointRequestsToSend = 10;
    int activeRequests = 0;
    ExecutionGraph graph = new CheckpointCoordinatorTestingUtils.CheckpointExecutionGraphBuilder().addJobVertex(new JobVertexID()).build(EXECUTOR_RESOURCE.getExecutor());
    CheckpointCoordinator coordinator = new CheckpointCoordinatorBuilder().setCheckpointCoordinatorConfiguration(CheckpointCoordinatorConfiguration.builder().setUnalignedCheckpointsEnabled(true).setMaxConcurrentCheckpoints(maxConcurrentCheckpoints).build()).setTimer(manuallyTriggeredScheduledExecutor).build(graph);
    try {
        List<Future<?>> checkpointFutures = new ArrayList<>(checkpointRequestsToSend);
        coordinator.startCheckpointScheduler();
        while (activeRequests < checkpointRequestsToSend) {
            checkpointFutures.add(coordinator.triggerCheckpoint(true));
            activeRequests++;
        }
        manuallyTriggeredScheduledExecutor.triggerAll();
        assertThat(coordinator.getNumQueuedRequests()).isEqualTo(activeRequests - maxConcurrentCheckpoints);
        Future<?> savepointFuture = coordinator.triggerSavepoint("/tmp", SavepointFormatType.CANONICAL);
        manuallyTriggeredScheduledExecutor.triggerAll();
        assertThat(coordinator.getNumQueuedRequests()).isEqualTo(++activeRequests - maxConcurrentCheckpoints);
        coordinator.receiveDeclineMessage(new DeclineCheckpoint(graph.getJobID(), createExecutionAttemptId(), 1L, new CheckpointException(CHECKPOINT_DECLINED)), "none");
        manuallyTriggeredScheduledExecutor.triggerAll();
        // savepoint triggered
        activeRequests--;
        assertThat(coordinator.getNumQueuedRequests()).isEqualTo(activeRequests - maxConcurrentCheckpoints);
        assertThat(checkpointFutures.stream().filter(Future::isDone).count()).isOne();
        assertThat(savepointFuture.isDone()).isFalse();
        assertThat(coordinator.getNumberOfPendingCheckpoints()).isEqualTo(maxConcurrentCheckpoints);
        CheckpointProperties props = coordinator.getPendingCheckpoints().values().iterator().next().getProps();
        assertThat(props.isSavepoint()).isTrue();
        assertThat(props.forceCheckpoint()).isFalse();
    } finally {
        coordinator.shutdown();
    }
}

