    CheckpointCoordinator checkpointCoordinator = new CheckpointCoordinatorBuilder().setCheckpointIDCounter(new UnstableCheckpointIDCounter(id -> id == 0)).setTimer(manuallyTriggeredScheduledExecutor).build(EXECUTOR_RESOURCE.getExecutor());
    checkpointCoordinator.startCheckpointScheduler();
    final CompletableFuture<CompletedCheckpoint> onCompletionPromise1 = triggerPeriodicCheckpoint(checkpointCoordinator);
    assertThat(checkpointCoordinator.isTriggering()).isTrue();
    assertThat(checkpointCoordinator.getTriggerRequestQueue()).isEmpty();
    manuallyTriggeredScheduledExecutor.triggerAll();
    try {
        onCompletionPromise1.get();
        fail("This checkpoint should fail through UnstableCheckpointIDCounter");
    } catch (ExecutionException e) {
        final Optional<CheckpointException> checkpointExceptionOptional = ExceptionUtils.findThrowable(e, CheckpointException.class);
        assertThat(checkpointExceptionOptional.isPresent()).isTrue();
        assertThat(checkpointExceptionOptional.get().getCheckpointFailureReason()).isEqualTo(CheckpointFailureReason.TRIGGER_CHECKPOINT_FAILURE);
    }
    assertThat(checkpointCoordinator.isTriggering()).isFalse();
    assertThat(checkpointCoordinator.getTriggerRequestQueue()).isEmpty();
    final CompletableFuture<CompletedCheckpoint> onCompletionPromise2 = triggerPeriodicCheckpoint(checkpointCoordinator);
    assertThat(checkpointCoordinator.isTriggering()).isTrue();
    manuallyTriggeredScheduledExecutor.triggerAll();
    assertThat(onCompletionPromise2).isNotCompletedExceptionally();
    assertThat(checkpointCoordinator.isTriggering()).isFalse();
    assertThat(checkpointCoordinator.getTriggerRequestQueue()).isEmpty();
}

@Test
void testTriggerCheckpointSnapshotMasterHookFailed() throws Exception {
    JobVertexID jobVertexID = new JobVertexID();
    CheckpointCoordinatorTestingUtils.CheckpointRecorderTaskManagerGateway gateway = new CheckpointCoordinatorTestingUtils.CheckpointRecorderTaskManagerGateway();
    ExecutionGraph graph = new CheckpointCoordinatorTestingUtils.CheckpointExecutionGraphBuilder().addJobVertex(jobVertexID).setTaskManagerGateway(gateway).build(EXECUTOR_RESOURCE.getExecutor());
    ExecutionVertex vertex = graph.getJobVertex(jobVertexID).getTaskVertices()[0];
    ExecutionAttemptID attemptID = vertex.getCurrentExecutionAttempt().getAttemptId();
    // set up the coordinator and validate the initial state
    CheckpointCoordinator checkpointCoordinator = createCheckpointCoordinator();
    final CompletableFuture<String> masterHookCheckpointFuture = new CompletableFuture<>();
    checkpointCoordinator.addMasterHook(new TestingMasterHook(masterHookCheckpointFuture));
    checkpointCoordinator.startCheckpointScheduler();
    final CompletableFuture<CompletedCheckpoint> onCompletionPromise = triggerPeriodicCheckpoint(checkpointCoordinator);
    // checkpoint trigger will not finish since master hook checkpoint is not finished yet
    manuallyTriggeredScheduledExecutor.triggerAll();
    assertThat(checkpointCoordinator.isTriggering()).isTrue();
    // continue triggering
    masterHookCheckpointFuture.completeExceptionally(new Exception("by design"));
    manuallyTriggeredScheduledExecutor.triggerAll();
    assertThat(checkpointCoordinator.isTriggering()).isFalse();
    try {
        onCompletionPromise.get();
        fail("Should not reach here");
    } catch (ExecutionException e) {
        final Optional<CheckpointException> checkpointExceptionOptional = ExceptionUtils.findThrowable(e, CheckpointException.class);
        assertThat(checkpointExceptionOptional).isPresent().map(CheckpointException::getCheckpointFailureReason).get().isEqualTo(CheckpointFailureReason.TRIGGER_CHECKPOINT_FAILURE);
    }
    // it doesn't really trigger task manager to do checkpoint
    assertThat(gateway.getTriggeredCheckpoints(attemptID)).isEmpty();
    assertThat(checkpointCoordinator.getTriggerRequestQueue()).isEmpty();
}

/**
 * This test only fails eventually.
 */
@Test
void discardingTriggeringCheckpointWillExecuteNextCheckpointRequest() throws Exception {
    final ScheduledExecutorService scheduledExecutorService = Executors.newSingleThreadScheduledExecutor();
    final CheckpointCoordinator checkpointCoordinator = new CheckpointCoordinatorTestingUtils.CheckpointCoordinatorBuilder().setTimer(new ScheduledExecutorServiceAdapter(scheduledExecutorService)).setCheckpointCoordinatorConfiguration(CheckpointCoordinatorConfiguration.builder().build()).// Since timer thread != main thread we should override the default main
    // thread executor because it initially requires triggering a checkpoint
    // from the main test thread.
    build(new CheckpointCoordinatorTestingUtils.CheckpointExecutionGraphBuilder().addJobVertex(new JobVertexID()).setMainThreadExecutor(ComponentMainThreadExecutorServiceAdapter.forSingleThreadExecutor(new DirectScheduledExecutorService())).build(EXECUTOR_RESOURCE.getExecutor()));
    final CompletableFuture<String> masterHookCheckpointFuture = new CompletableFuture<>();
    final OneShotLatch triggerCheckpointLatch = new OneShotLatch();
    checkpointCoordinator.addMasterHook(new TestingMasterHook(masterHookCheckpointFuture, triggerCheckpointLatch));
    try {
        checkpointCoordinator.triggerCheckpoint(false);
        final CompletableFuture<CompletedCheckpoint> secondCheckpoint = checkpointCoordinator.triggerCheckpoint(false);
        triggerCheckpointLatch.await();
        masterHookCheckpointFuture.complete("Completed");
        // discard triggering checkpoint
        checkpointCoordinator.abortPendingCheckpoints(new CheckpointException(CheckpointFailureReason.CHECKPOINT_DECLINED));
        try {
            // verify that the second checkpoint request will be executed and eventually times
            // out
            secondCheckpoint.get();
            fail("Expected the second checkpoint to fail.");
        } catch (ExecutionException ee) {
            assertThat(ExceptionUtils.stripExecutionException(ee)).isInstanceOf(CheckpointException.class);
        }
    } finally {
        checkpointCoordinator.shutdown();
        ExecutorUtils.gracefulShutdown(10L, TimeUnit.SECONDS, scheduledExecutorService);
    }
}

