        }
    };
    JobVertexID jobVertexID = new JobVertexID();
    ExecutionGraph graph = new CheckpointCoordinatorTestingUtils.CheckpointExecutionGraphBuilder().addJobVertex(jobVertexID).build(EXECUTOR_RESOURCE.getExecutor());
    CheckpointStatsTracker stats = new DefaultCheckpointStatsTracker(0, metricGroup);
    // Make sure to adjust this test if metrics are added/removed
    assertThat(registeredGauges).hasSize(13);
    // Check initial values
    Gauge<Long> numCheckpoints = (Gauge<Long>) registeredGauges.get(DefaultCheckpointStatsTracker.NUMBER_OF_CHECKPOINTS_METRIC);
    Gauge<Integer> numInProgressCheckpoints = (Gauge<Integer>) registeredGauges.get(DefaultCheckpointStatsTracker.NUMBER_OF_IN_PROGRESS_CHECKPOINTS_METRIC);
    Gauge<Long> numCompletedCheckpoints = (Gauge<Long>) registeredGauges.get(DefaultCheckpointStatsTracker.NUMBER_OF_COMPLETED_CHECKPOINTS_METRIC);
    Gauge<Long> numFailedCheckpoints = (Gauge<Long>) registeredGauges.get(DefaultCheckpointStatsTracker.NUMBER_OF_FAILED_CHECKPOINTS_METRIC);
    Gauge<Long> latestRestoreTimestamp = (Gauge<Long>) registeredGauges.get(DefaultCheckpointStatsTracker.LATEST_RESTORED_CHECKPOINT_TIMESTAMP_METRIC);
    Gauge<Long> latestCompletedSize = (Gauge<Long>) registeredGauges.get(DefaultCheckpointStatsTracker.LATEST_COMPLETED_CHECKPOINT_SIZE_METRIC);
    Gauge<Long> latestCompletedFullSize = (Gauge<Long>) registeredGauges.get(DefaultCheckpointStatsTracker.LATEST_COMPLETED_CHECKPOINT_FULL_SIZE_METRIC);
    Gauge<Long> latestCompletedDuration = (Gauge<Long>) registeredGauges.get(DefaultCheckpointStatsTracker.LATEST_COMPLETED_CHECKPOINT_DURATION_METRIC);
    Gauge<Long> latestProcessedData = (Gauge<Long>) registeredGauges.get(DefaultCheckpointStatsTracker.LATEST_COMPLETED_CHECKPOINT_PROCESSED_DATA_METRIC);
    Gauge<Long> latestPersistedData = (Gauge<Long>) registeredGauges.get(DefaultCheckpointStatsTracker.LATEST_COMPLETED_CHECKPOINT_PERSISTED_DATA_METRIC);
    Gauge<String> latestCompletedExternalPath = (Gauge<String>) registeredGauges.get(DefaultCheckpointStatsTracker.LATEST_COMPLETED_CHECKPOINT_EXTERNAL_PATH_METRIC);
    Gauge<Long> latestCompletedId = (Gauge<Long>) registeredGauges.get(DefaultCheckpointStatsTracker.LATEST_COMPLETED_CHECKPOINT_ID_METRIC);
    Gauge<Long> latestCompletedTimestamp = (Gauge<Long>) registeredGauges.get(DefaultCheckpointStatsTracker.LATEST_CHECKPOINT_COMPLETED_TIMESTAMP);
    assertThat(numCheckpoints.getValue()).isZero();
    assertThat(numInProgressCheckpoints.getValue()).isZero();
    assertThat(numCompletedCheckpoints.getValue()).isZero();
    assertThat(numFailedCheckpoints.getValue()).isZero();
    assertThat(latestRestoreTimestamp.getValue()).isEqualTo(-1);
    assertThat(latestCompletedSize.getValue()).isEqualTo(-1);
    assertThat(latestCompletedFullSize.getValue()).isEqualTo(-1);
    assertThat(latestCompletedDuration.getValue()).isEqualTo(-1);
    assertThat(latestProcessedData.getValue()).isEqualTo(-1);
    assertThat(latestPersistedData.getValue()).isEqualTo(-1);
    assertThat(latestCompletedExternalPath.getValue()).isEqualTo("n/a");
    assertThat(latestCompletedId.getValue()).isEqualTo(-1);
    assertThat(latestCompletedTimestamp.getValue()).isEqualTo(-1);
    PendingCheckpointStats pending = stats.reportPendingCheckpoint(0, 0, CheckpointProperties.forCheckpoint(CheckpointRetentionPolicy.NEVER_RETAIN_AFTER_TERMINATION), singletonMap(jobVertexID, 1));
    // Check counts
    assertThat(numCheckpoints.getValue()).isOne();
    assertThat(numInProgressCheckpoints.getValue()).isOne();
    assertThat(numCompletedCheckpoints.getValue()).isZero();
    assertThat(numFailedCheckpoints.getValue()).isZero();
    long ackTimestamp = 11231230L;
    long checkpointedSize = 123L;
    long fullCheckpointSize = 12381238L;
    long processedData = 4242L;
    long persistedData = 4444L;
    long ignored = 0;
    String externalPath = "myexternalpath";
    SubtaskStateStats subtaskStats = new SubtaskStateStats(0, ackTimestamp, checkpointedSize, fullCheckpointSize, ignored, ignored, processedData, persistedData, ignored, ignored, false, true);
    assertThat(pending.reportSubtaskStats(jobVertexID, subtaskStats)).isTrue();
    stats.reportCompletedCheckpoint(pending.toCompletedCheckpointStats(externalPath));
    // Verify completed checkpoint updated
    assertThat(numCheckpoints.getValue()).isOne();
    assertThat(numInProgressCheckpoints.getValue()).isZero();
    assertThat(numCompletedCheckpoints.getValue()).isOne();
    assertThat(numFailedCheckpoints.getValue()).isZero();
    assertThat(latestRestoreTimestamp.getValue()).isEqualTo(-1);
    assertThat(latestCompletedSize.getValue()).isEqualTo(checkpointedSize);
    assertThat(latestCompletedFullSize.getValue()).isEqualTo(fullCheckpointSize);
    assertThat(latestProcessedData.getValue()).isEqualTo(processedData);
    assertThat(latestPersistedData.getValue()).isEqualTo(persistedData);
    assertThat(latestCompletedDuration.getValue()).isEqualTo(ackTimestamp);
    assertThat(latestCompletedExternalPath.getValue()).isEqualTo(externalPath);
    assertThat(latestCompletedId.getValue()).isZero();
    assertThat(latestCompletedTimestamp.getValue()).isEqualTo(ackTimestamp);
    // Check failed
    PendingCheckpointStats nextPending = stats.reportPendingCheckpoint(1, 11, CheckpointProperties.forCheckpoint(CheckpointRetentionPolicy.NEVER_RETAIN_AFTER_TERMINATION), singletonMap(jobVertexID, 1));
    long failureTimestamp = 1230123L;
    stats.reportFailedCheckpoint(nextPending.toFailedCheckpoint(failureTimestamp, null));
    // Verify updated
    assertThat(numCheckpoints.getValue()).isEqualTo(2);
    assertThat(numInProgressCheckpoints.getValue()).isZero();
    assertThat(numCompletedCheckpoints.getValue()).isOne();
    // one failed now
    assertThat(numFailedCheckpoints.getValue()).isOne();
    assertThat(latestCompletedId.getValue()).isZero();
    // Check restore
    long restoreTimestamp = 183419283L;
    RestoredCheckpointStats restored = new RestoredCheckpointStats(1, CheckpointProperties.forCheckpoint(CheckpointRetentionPolicy.NEVER_RETAIN_AFTER_TERMINATION), restoreTimestamp, null, 42);
    stats.reportInitializationStarted(Collections.emptySet(), restoreTimestamp);
    reportRestoredCheckpoint(stats, restored);
    assertThat(numCheckpoints.getValue()).isEqualTo(2);
    assertThat(numInProgressCheckpoints.getValue()).isZero();
    assertThat(numCompletedCheckpoints.getValue()).isOne();
    assertThat(numFailedCheckpoints.getValue()).isOne();
    assertThat(latestCompletedId.getValue()).isZero();
    assertThat(latestRestoreTimestamp.getValue()).isEqualTo(restoreTimestamp);
    // Check Internal Checkpoint Configuration
    PendingCheckpointStats thirdPending = stats.reportPendingCheckpoint(2, 5000, CheckpointProperties.forCheckpoint(CheckpointRetentionPolicy.NEVER_RETAIN_AFTER_TERMINATION), singletonMap(jobVertexID, 1));
    thirdPending.reportSubtaskStats(jobVertexID, subtaskStats);
    stats.reportCompletedCheckpoint(thirdPending.toCompletedCheckpointStats(null));
    assertThat(latestCompletedId.getValue()).isEqualTo(2);
    // Verify external path is "n/a", because internal checkpoint won't generate external path.
    assertThat(latestCompletedExternalPath.getValue()).isEqualTo("n/a");
}

