/**
 * Tests that {@link CheckpointCoordinator#abortPendingCheckpoints(CheckpointException)} called
 * on job failover could handle the {@code currentPeriodicTrigger} null case well.
 */
@Test
void testAbortPendingCheckpointsWithTriggerValidation() throws Exception {
    final int maxConcurrentCheckpoints = ThreadLocalRandom.current().nextInt(10) + 1;
    ExecutionGraph graph = new CheckpointCoordinatorTestingUtils.CheckpointExecutionGraphBuilder().addJobVertex(new JobVertexID()).setTransitToRunning(false).build(EXECUTOR_RESOURCE.getExecutor());
    CheckpointCoordinatorConfiguration checkpointCoordinatorConfiguration = new CheckpointCoordinatorConfiguration(Integer.MAX_VALUE, Integer.MAX_VALUE, 0, maxConcurrentCheckpoints, CheckpointRetentionPolicy.NEVER_RETAIN_AFTER_TERMINATION, true, false, 0, 0);
    CheckpointCoordinator checkpointCoordinator = new CheckpointCoordinator(graph.getJobID(), checkpointCoordinatorConfiguration, Collections.emptyList(), new StandaloneCheckpointIDCounter(), new StandaloneCompletedCheckpointStore(1), new JobManagerCheckpointStorage(), Executors.directExecutor(), new CheckpointsCleaner(), manualThreadExecutor, mock(CheckpointFailureManager.class), new DefaultCheckpointPlanCalculator(graph.getJobID(), new ExecutionGraphCheckpointPlanCalculatorContext(graph), graph.getVerticesTopologically(), false), mock(CheckpointStatsTracker.class));
    // switch current execution's state to running to allow checkpoint could be triggered.
    graph.transitionToRunning();
    graph.getAllExecutionVertices().forEach(task -> task.getCurrentExecutionAttempt().transitionState(ExecutionState.RUNNING));
    checkpointCoordinator.startCheckpointScheduler();
    assertThat(checkpointCoordinator.isCurrentPeriodicTriggerAvailable()).isTrue();
    // only trigger the periodic scheduling
    // we can't trigger all scheduled task, because there is also a cancellation scheduled
    manualThreadExecutor.triggerNonPeriodicScheduledTasks(CheckpointCoordinator.ScheduledTrigger.class);
    manualThreadExecutor.triggerAll();
    assertThat(checkpointCoordinator.getNumberOfPendingCheckpoints()).isOne();
    for (int i = 1; i < maxConcurrentCheckpoints; i++) {
        checkpointCoordinator.triggerCheckpoint(false);
        manualThreadExecutor.triggerAll();
        assertThat(checkpointCoordinator.getNumberOfPendingCheckpoints()).isEqualTo(i + 1);
        assertThat(checkpointCoordinator.isCurrentPeriodicTriggerAvailable()).isTrue();
    }
    // as we only support limited concurrent checkpoints, after checkpoint triggered more than
    // the limits,
    // the currentPeriodicTrigger would been assigned as null.
    checkpointCoordinator.triggerCheckpoint(false);
    manualThreadExecutor.triggerAll();
    assertThat(checkpointCoordinator.getNumberOfPendingCheckpoints()).isEqualTo(maxConcurrentCheckpoints);
    checkpointCoordinator.abortPendingCheckpoints(new CheckpointException(CheckpointFailureReason.JOB_FAILOVER_REGION));
    // after aborting checkpoints, we ensure currentPeriodicTrigger still available.
    assertThat(checkpointCoordinator.isCurrentPeriodicTriggerAvailable()).isTrue();
    assertThat(checkpointCoordinator.getNumberOfPendingCheckpoints()).isZero();
}

@Test
void testCreateAndReuseFiles() throws IOException {
    try (FileMergingSnapshotManagerBase fmsm = (FileMergingSnapshotManagerBase) createFileMergingSnapshotManager(checkpointBaseDir)) {
        fmsm.registerSubtaskForSharedStates(subtaskKey1);
        fmsm.registerSubtaskForSharedStates(subtaskKey2);
        // firstly, we try shared state.
        PhysicalFile file1 = fmsm.getOrCreatePhysicalFileForCheckpoint(subtaskKey1, 0, CheckpointedStateScope.SHARED);
        assertThat(file1.getFilePath().getParent()).isEqualTo(fmsm.getManagedDir(subtaskKey1, CheckpointedStateScope.SHARED));
        // allocate another
        PhysicalFile file2 = fmsm.getOrCreatePhysicalFileForCheckpoint(subtaskKey1, 0, CheckpointedStateScope.SHARED);
        assertThat(file2.getFilePath().getParent()).isEqualTo(fmsm.getManagedDir(subtaskKey1, CheckpointedStateScope.SHARED));
        assertThat(file2).isNotEqualTo(file1);
        assertThat(fmsm.spaceStat.physicalFileCount.get()).isEqualTo(2);
        // return for reuse
        fmsm.returnPhysicalFileForNextReuse(subtaskKey1, 0, file1);
        assertThat(fmsm.spaceStat.physicalFileCount.get()).isEqualTo(2);
        // allocate for another subtask
        PhysicalFile file3 = fmsm.getOrCreatePhysicalFileForCheckpoint(subtaskKey2, 0, CheckpointedStateScope.SHARED);
        assertThat(file3.getFilePath().getParent()).isEqualTo(fmsm.getManagedDir(subtaskKey2, CheckpointedStateScope.SHARED));
        assertThat(file3).isNotEqualTo(file1);
        assertThat(fmsm.spaceStat.physicalFileCount.get()).isEqualTo(3);
        // allocate for another checkpoint
        PhysicalFile file4 = fmsm.getOrCreatePhysicalFileForCheckpoint(subtaskKey1, 1, CheckpointedStateScope.SHARED);
        assertThat(file4.getFilePath().getParent()).isEqualTo(fmsm.getManagedDir(subtaskKey1, CheckpointedStateScope.SHARED));
        assertThat(file4).isEqualTo(file1);
        assertThat(fmsm.spaceStat.physicalFileCount.get()).isEqualTo(3);
        // a physical file whose size is bigger than maxPhysicalFileSize cannot be reused
        file4.incSize(fmsm.maxPhysicalFileSize);
        fmsm.returnPhysicalFileForNextReuse(subtaskKey1, 1, file4);
        // file4 is discarded because it's size is bigger than maxPhysicalFileSize
        assertThat(fmsm.spaceStat.physicalFileCount.get()).isEqualTo(2);
        PhysicalFile file5 = fmsm.getOrCreatePhysicalFileForCheckpoint(subtaskKey1, 1, CheckpointedStateScope.SHARED);
        assertThat(file5.getFilePath().getParent()).isEqualTo(fmsm.getManagedDir(subtaskKey1, CheckpointedStateScope.SHARED));
        assertThat(file5).isNotEqualTo(file4);
        assertThat(fmsm.spaceStat.physicalFileCount.get()).isEqualTo(3);
        // Secondly, we try private state
        PhysicalFile file6 = fmsm.getOrCreatePhysicalFileForCheckpoint(subtaskKey1, 1, CheckpointedStateScope.EXCLUSIVE);
        assertThat(file6.getFilePath().getParent()).isEqualTo(fmsm.getManagedDir(subtaskKey1, CheckpointedStateScope.EXCLUSIVE));
        assertThat(fmsm.spaceStat.physicalFileCount.get()).isEqualTo(4);
        // allocate another
        PhysicalFile file7 = fmsm.getOrCreatePhysicalFileForCheckpoint(subtaskKey1, 1, CheckpointedStateScope.EXCLUSIVE);
        assertThat(file7.getFilePath().getParent()).isEqualTo(fmsm.getManagedDir(subtaskKey1, CheckpointedStateScope.EXCLUSIVE));
        assertThat(file7).isNotEqualTo(file5);
        assertThat(fmsm.spaceStat.physicalFileCount.get()).isEqualTo(5);
        // return for reuse
        fmsm.returnPhysicalFileForNextReuse(subtaskKey1, 0, file6);
        assertThat(fmsm.spaceStat.physicalFileCount.get()).isEqualTo(5);
        // allocate for another checkpoint
        PhysicalFile file8 = fmsm.getOrCreatePhysicalFileForCheckpoint(subtaskKey1, 2, CheckpointedStateScope.EXCLUSIVE);
        assertThat(file8.getFilePath().getParent()).isEqualTo(fmsm.getManagedDir(subtaskKey1, CheckpointedStateScope.EXCLUSIVE));
        assertThat(file8).isEqualTo(file6);
        assertThat(fmsm.spaceStat.physicalFileCount.get()).isEqualTo(5);
        // return for reuse
        fmsm.returnPhysicalFileForNextReuse(subtaskKey1, 0, file8);
        assertThat(fmsm.spaceStat.physicalFileCount.get()).isEqualTo(5);
        // allocate for this checkpoint but another subtask
        PhysicalFile file9 = fmsm.getOrCreatePhysicalFileForCheckpoint(subtaskKey2, 2, CheckpointedStateScope.EXCLUSIVE);
        assertThat(file9.getFilePath().getParent()).isEqualTo(fmsm.getManagedDir(subtaskKey2, CheckpointedStateScope.EXCLUSIVE));
        assertThat(file9).isEqualTo(file6);
        assertThat(fmsm.spaceStat.physicalFileCount.get()).isEqualTo(5);
        // a physical file whose size is bigger than maxPhysicalFileSize cannot be reused
        file9.incSize(fmsm.maxPhysicalFileSize);
        fmsm.returnPhysicalFileForNextReuse(subtaskKey1, 2, file9);
        assertThat(fmsm.spaceStat.physicalFileCount.get()).isEqualTo(4);
        PhysicalFile file10 = fmsm.getOrCreatePhysicalFileForCheckpoint(subtaskKey1, 2, CheckpointedStateScope.SHARED);
        assertThat(file10.getFilePath().getParent()).isEqualTo(fmsm.getManagedDir(subtaskKey1, CheckpointedStateScope.SHARED));
        assertThat(file10).isNotEqualTo(file9);
        assertThat(fmsm.spaceStat.physicalFileCount.get()).isEqualTo(5);
        assertThat(fmsm.getManagedDir(subtaskKey2, CheckpointedStateScope.EXCLUSIVE)).isEqualTo(fmsm.getManagedDir(subtaskKey1, CheckpointedStateScope.EXCLUSIVE));
    }
}

@Test
public void testCheckpointNotification() throws Exception {
    try (FileMergingSnapshotManagerBase fmsm = (FileMergingSnapshotManagerBase) createFileMergingSnapshotManager(checkpointBaseDir);
        CloseableRegistry closeableRegistry = new CloseableRegistry()) {
        fmsm.registerSubtaskForSharedStates(subtaskKey1);
        fmsm.registerSubtaskForSharedStates(subtaskKey2);
        BiFunctionWithException<FileMergingSnapshotManager.SubtaskKey, Long, SegmentFileStateHandle, Exception> writer = ((subtaskKey, checkpointId) -> {
            return writeCheckpointAndGetStream(subtaskKey, checkpointId, CheckpointedStateScope.SHARED, fmsm, closeableRegistry).closeAndGetHandle();
        });
        SegmentFileStateHandle cp1StateHandle1 = writer.apply(subtaskKey1, 1L);
        SegmentFileStateHandle cp1StateHandle2 = writer.apply(subtaskKey2, 1L);
        fmsm.notifyCheckpointComplete(subtaskKey1, 1);
        assertFileInManagedDir(fmsm, cp1StateHandle1);
        assertFileInManagedDir(fmsm, cp1StateHandle2);
        assertThat(fmsm.spaceStat.physicalFileCount.get()).isEqualTo(2);
        assertThat(fmsm.spaceStat.logicalFileCount.get()).isEqualTo(2);
        // complete checkpoint-2
        SegmentFileStateHandle cp2StateHandle1 = writer.apply(subtaskKey1, 2L);
        SegmentFileStateHandle cp2StateHandle2 = writer.apply(subtaskKey2, 2L);
        fmsm.notifyCheckpointComplete(subtaskKey1, 2);
        fmsm.notifyCheckpointComplete(subtaskKey2, 2);
        assertFileInManagedDir(fmsm, cp2StateHandle1);
        assertFileInManagedDir(fmsm, cp2StateHandle2);
        assertThat(fmsm.spaceStat.physicalFileCount.get()).isEqualTo(2);
        assertThat(fmsm.spaceStat.logicalFileCount.get()).isEqualTo(4);
        assertThat(fmsm.isCheckpointDiscard(1)).isFalse();
        // subsume checkpoint-1
        assertThat(fileExists(cp1StateHandle1)).isTrue();
        assertThat(fileExists(cp1StateHandle2)).isTrue();
        fmsm.notifyCheckpointSubsumed(subtaskKey1, 1);
        assertThat(fileExists(cp1StateHandle1)).isTrue();
