/**
 * This tests attempts to test (almost) the full space of significantly different options for
 * verifying and prioritizing {@link OperatorSubtaskState} options for local recovery over
 * primary/remote state handles.
 */
@Test
void testPrioritization() {
    for (int i = 0; i < 81; ++i) {
        // 3^4 possible configurations.
        OperatorSubtaskState primaryAndFallback = generateForConfiguration(i);
        for (int j = 0; j < 9; ++j) {
            // we test 3^2 configurations.
            CreateAltSubtaskStateMode modeFirst = CreateAltSubtaskStateMode.byCode(j % 3);
            OperatorSubtaskState bestAlternative = modeFirst.createAlternativeSubtaskState(primaryAndFallback);
            CreateAltSubtaskStateMode modeSecond = CreateAltSubtaskStateMode.byCode((j / 3) % 3);
            OperatorSubtaskState secondBestAlternative = modeSecond.createAlternativeSubtaskState(primaryAndFallback);
            List<OperatorSubtaskState> orderedAlternativesList = Arrays.asList(bestAlternative, secondBestAlternative);
            List<OperatorSubtaskState> validAlternativesList = new ArrayList<>(3);
            if (modeFirst == CreateAltSubtaskStateMode.ONE_VALID_STATE_HANDLE) {
                validAlternativesList.add(bestAlternative);
            }
            if (modeSecond == CreateAltSubtaskStateMode.ONE_VALID_STATE_HANDLE) {
                validAlternativesList.add(secondBestAlternative);
            }
            validAlternativesList.add(primaryAndFallback);
            PrioritizedOperatorSubtaskState.Builder builder = new PrioritizedOperatorSubtaskState.Builder(primaryAndFallback, orderedAlternativesList);
            PrioritizedOperatorSubtaskState prioritizedOperatorSubtaskState = builder.build();
            OperatorSubtaskState[] validAlternatives = validAlternativesList.toArray(new OperatorSubtaskState[0]);
            OperatorSubtaskState[] onlyPrimary = new OperatorSubtaskState[] { primaryAndFallback };
            assertThat(checkResultAsExpected(OperatorSubtaskState::getManagedOperatorState, PrioritizedOperatorSubtaskState::getPrioritizedManagedOperatorState, prioritizedOperatorSubtaskState, primaryAndFallback.getManagedOperatorState().size() == 1 ? validAlternatives : onlyPrimary)).isTrue();
            StateObjectCollection<KeyedStateHandle> expManagedKeyed = computeExpectedMixedState(orderedAlternativesList, primaryAndFallback, OperatorSubtaskState::getManagedKeyedState, KeyedStateHandle::getKeyGroupRange);
            assertResultAsExpected(expManagedKeyed, primaryAndFallback.getManagedKeyedState(), prioritizedOperatorSubtaskState.getPrioritizedManagedKeyedState());
            assertThat(checkResultAsExpected(OperatorSubtaskState::getRawOperatorState, PrioritizedOperatorSubtaskState::getPrioritizedRawOperatorState, prioritizedOperatorSubtaskState, primaryAndFallback.getRawOperatorState().size() == 1 ? validAlternatives : onlyPrimary)).isTrue();
            StateObjectCollection<KeyedStateHandle> expRawKeyed = computeExpectedMixedState(orderedAlternativesList, primaryAndFallback, OperatorSubtaskState::getRawKeyedState, KeyedStateHandle::getKeyGroupRange);
            assertResultAsExpected(expRawKeyed, primaryAndFallback.getRawKeyedState(), prioritizedOperatorSubtaskState.getPrioritizedRawKeyedState());
        }
    }
}

