void uploadAndSetUserArtifacts() throws Exception {
    java.nio.file.Path tmpDir = TempDirUtils.newFolder(temporaryFolder).toPath();
    JobGraph jobGraph = JobGraphTestUtils.emptyJobGraph();
    Collection<DistributedCache.DistributedCacheEntry> localArtifacts = Arrays.asList(new DistributedCache.DistributedCacheEntry(Files.createFile(tmpDir.resolve("art1")).toString(), true, true), new DistributedCache.DistributedCacheEntry(Files.createFile(tmpDir.resolve("art2")).toString(), true, false), new DistributedCache.DistributedCacheEntry(Files.createFile(tmpDir.resolve("art3")).toString(), false, true), new DistributedCache.DistributedCacheEntry(Files.createFile(tmpDir.resolve("art4")).toString(), true, false));
    Collection<DistributedCache.DistributedCacheEntry> distributedArtifacts = Collections.singletonList(new DistributedCache.DistributedCacheEntry("hdfs://localhost:1234/test", true, false));
    for (DistributedCache.DistributedCacheEntry entry : localArtifacts) {
        jobGraph.addUserArtifact(entry.filePath, entry);
    }
    for (DistributedCache.DistributedCacheEntry entry : distributedArtifacts) {
        jobGraph.addUserArtifact(entry.filePath, entry);
    }
    final int totalNumArtifacts = localArtifacts.size() + distributedArtifacts.size();
    assertThat(jobGraph.getUserArtifacts()).hasSize(totalNumArtifacts);
    assertThat(jobGraph.getUserArtifacts().values().stream().filter(entry -> entry.blobKey != null)).isEmpty();
    ClientUtils.extractAndUploadExecutionPlanFiles(jobGraph, () -> new BlobClient(new InetSocketAddress("localhost", blobServer.getPort()), new Configuration()));
    assertThat(jobGraph.getUserArtifacts()).hasSize(totalNumArtifacts);
    assertThat(jobGraph.getUserArtifacts().values().stream().filter(entry -> entry.blobKey != null)).hasSameSizeAs(localArtifacts);
    assertThat(jobGraph.getUserArtifacts().values().stream().filter(entry -> entry.blobKey == null)).hasSameSizeAs(distributedArtifacts);
    // 1 unique key for each local artifact, and null for distributed artifacts
    assertThat(jobGraph.getUserArtifacts().values().stream().map(entry -> entry.blobKey).distinct()).hasSize(localArtifacts.size() + 1);
    for (DistributedCache.DistributedCacheEntry original : localArtifacts) {
