@Test
void testWriteConfigurationAndReloadWithStandardYaml() throws Exception {
    final File flinkConfDir = TempDirUtils.newFolder(temporaryFolder).getAbsoluteFile();
    final Configuration flinkConfig = new Configuration();
    final ConfigOption<List<String>> listStringConfigOption = ConfigOptions.key("test-list-string-key").stringType().asList().noDefaultValue();
    final List<String> list = Arrays.asList("A,B,C,D", "A'B'C'D", "A;BCD", "AB\"C\"D", "AB'\"D:B");
    flinkConfig.set(listStringConfigOption, list);
    assertThat(flinkConfig.get(listStringConfigOption)).containsExactlyInAnyOrderElementsOf(list);
    final ConfigOption<List<Duration>> listDurationConfigOption = ConfigOptions.key("test-list-duration-key").durationType().asList().noDefaultValue();
    final List<Duration> durationList = Arrays.asList(Duration.ofSeconds(3), Duration.ofMinutes(1));
    flinkConfig.set(listDurationConfigOption, durationList);
    assertThat(flinkConfig.get(listDurationConfigOption)).containsExactlyInAnyOrderElementsOf(durationList);
    final ConfigOption<List<MemorySize>> listMemoryConfigOption = ConfigOptions.key("test-list-memory-key").memoryType().asList().noDefaultValue();
    final List<MemorySize> memorySizeList = Arrays.asList(MemorySize.ofMebiBytes(10), MemorySize.ofMebiBytes(20), MemorySize.ZERO);
    flinkConfig.set(listMemoryConfigOption, memorySizeList);
    assertThat(flinkConfig.get(listMemoryConfigOption)).containsExactlyInAnyOrderElementsOf(memorySizeList);
    final ConfigOption<Map<String, String>> mapConfigOption = ConfigOptions.key("test-map-key").mapType().noDefaultValue();
    final Map<String, String> map = new HashMap<>();
    map.put("key1", "A,B,C,D");
    map.put("key2", "A;BCD");
    map.put("key3", "A'B'C'D");
    map.put("key4", "AB\"C\"D");
    map.put("key5", "AB'\"D:B");
    flinkConfig.set(mapConfigOption, map);
    assertThat(flinkConfig.get(mapConfigOption)).containsAllEntriesOf(map);
    final ConfigOption<List<Map<String, String>>> listMapConfigOption = ConfigOptions.key("test-list-map-key").mapType().asList().noDefaultValue();
    List<Map<String, String>> listMap = Collections.singletonList(map);
    flinkConfig.set(listMapConfigOption, listMap);
    assertThat(flinkConfig.get(listMapConfigOption)).containsExactlyInAnyOrderElementsOf(listMap);
    final ConfigOption<Duration> durationConfigOption = ConfigOptions.key("test-duration-key").durationType().noDefaultValue();
    final Duration duration = Duration.ofMillis(3000);
    flinkConfig.set(durationConfigOption, duration);
    assertThat(flinkConfig.get(durationConfigOption)).isEqualTo(duration);
    final ConfigOption<MemorySize> memoryConfigOption = ConfigOptions.key("test-memory-key").memoryType().noDefaultValue();
    MemorySize memorySize = MemorySize.ofMebiBytes(10);
    flinkConfig.set(memoryConfigOption, memorySize);
    assertThat(memorySize).isEqualTo(flinkConfig.get(memoryConfigOption));
    BootstrapTools.writeConfiguration(flinkConfig, new File(flinkConfDir, GlobalConfiguration.getFlinkConfFilename()));
    final Configuration loadedFlinkConfig;
    loadedFlinkConfig = GlobalConfiguration.loadConfiguration(flinkConfDir.getAbsolutePath());
    assertThat(loadedFlinkConfig.get(listStringConfigOption)).containsExactlyInAnyOrderElementsOf(list);
    assertThat(loadedFlinkConfig.get(listDurationConfigOption)).containsExactlyInAnyOrderElementsOf(durationList);
    assertThat(loadedFlinkConfig.get(mapConfigOption)).containsAllEntriesOf(map);
    assertThat(loadedFlinkConfig.get(durationConfigOption)).isEqualTo(duration);
}

