    List<IntermediateResultPartitionID> partitions = createPartitions();
    ConsumedPartitionGroup consumedPartitionGroup = ConsumedPartitionGroup.fromMultiplePartitions(4, partitions, BLOCKING);
    ConsumedSubpartitionContext context = ConsumedSubpartitionContext.buildConsumedSubpartitionContext(consumedSubpartitionGroups, consumedPartitionGroup, partitions::get);
