@Test
void testTaskInformationCache() throws IOException, ClassNotFoundException {
    try (BlobServer blobServer = setupBlobServer()) {
        // Serialize taskInformation to blobServer and get the permanentBlobKey
        Either<SerializedValue<TaskInformation>, PermanentBlobKey> taskInformationOrBlobKey = BlobWriter.serializeAndTryOffload(taskInformation, jobID, blobServer);
        assertThat(taskInformationOrBlobKey.isRight()).isTrue();
        PermanentBlobKey permanentBlobKey = taskInformationOrBlobKey.right();
        GroupCache<JobID, PermanentBlobKey, TaskInformation> taskInformationCache = new DefaultGroupCache.Factory<JobID, PermanentBlobKey, TaskInformation>().create();
        // Test for tdd1
        final TaskDeploymentDescriptor tdd1 = createTaskDeploymentDescriptor(new TaskDeploymentDescriptor.NonOffloaded<>(serializedJobInformation), new TaskDeploymentDescriptor.Offloaded<>(permanentBlobKey));
        assertThat(taskInformationCache.get(jobID, permanentBlobKey)).isNull();
        tdd1.loadBigData(blobServer, new NoOpGroupCache<>(), taskInformationCache, new NoOpGroupCache<>());
        TaskInformation taskInformation1 = tdd1.getTaskInformation();
        assertThat(taskInformation1).isEqualTo(taskInformation);
        // The TaskInformation is cached in taskInformationCache, and it's equals to
        // taskInformation1.
        assertThat(taskInformationCache.get(jobID, permanentBlobKey)).isNotNull().isEqualTo(taskInformation1);
        // Test for tdd2
        final TaskDeploymentDescriptor tdd2 = createTaskDeploymentDescriptor(new TaskDeploymentDescriptor.NonOffloaded<>(serializedJobInformation), new TaskDeploymentDescriptor.Offloaded<>(permanentBlobKey));
        tdd2.loadBigData(blobServer, new NoOpGroupCache<>(), taskInformationCache, new NoOpGroupCache<>());
        TaskInformation taskInformation2 = tdd2.getTaskInformation();
        // The TaskInformation2 is equals to taskInformation1 and original taskInformation, but
        // they are not same.
        assertThat(taskInformation2).isNotNull().isEqualTo(taskInformation1).isNotSameAs(taskInformation1).isEqualTo(taskInformation);
        // Configuration may be changed by subtask, so the configuration must be not same.
        assertThat(taskInformation2.getTaskConfiguration()).isNotNull().isEqualTo(taskInformation1.getTaskConfiguration()).isNotSameAs(taskInformation1.getTaskConfiguration());
    }
}

