@Test
void testSuccessfulCloseAsyncAfterStart() throws Exception {
    final CompletableFuture<JobStatus> completedCheckpointStoreShutdownFuture = new CompletableFuture<>();
    final CompletableFuture<JobStatus> checkpointIdCounterShutdownFuture = new CompletableFuture<>();
    final HaltingCheckpointRecoveryFactory checkpointRecoveryFactory = new HaltingCheckpointRecoveryFactory(completedCheckpointStoreShutdownFuture, checkpointIdCounterShutdownFuture);
    final CheckpointResourcesCleanupRunner testInstance = new TestInstanceBuilder().withCheckpointRecoveryFactory(checkpointRecoveryFactory).withExecutor(EXECUTOR_EXTENSION.getExecutor()).build();
    testInstance.start();
    assertThat(completedCheckpointStoreShutdownFuture).as("The CompletedCheckpointStore shouldn't have been shut down, yet.").isNotCompleted();
    assertThat(checkpointIdCounterShutdownFuture).as("The CheckpointIDCounter shouldn't have been shut down, yet.").isNotCompleted();
    assertThat(testInstance.closeAsync()).as("closeAsync shouldn't have been completed, yet, since the shutdown of the components is not completed.").isNotCompleted();
    checkpointRecoveryFactory.triggerCreation();
    assertThatFuture(completedCheckpointStoreShutdownFuture).as("The CompletedCheckpointStore should have been shut down properly.").eventuallySucceeds().isEqualTo(JobStatus.FINISHED);
    assertThatFuture(checkpointIdCounterShutdownFuture).as("The CheckpointIDCounter should have been shut down properly.").eventuallySucceeds().isEqualTo(JobStatus.FINISHED);
    assertThatFuture(testInstance.closeAsync()).eventuallySucceeds();
}

