@Test
public void testCleanupThroughRetries() throws Exception {
    final JobGraph jobGraph = createJobGraph();
    final JobID jobId = jobGraph.getJobID();
    // ExecutionPlanStore
    final AtomicInteger actualGlobalCleanupCallCount = new AtomicInteger();
    final OneShotLatch successfulCleanupLatch = new OneShotLatch();
    final int numberOfErrors = 5;
    final RuntimeException temporaryError = new RuntimeException("Expected RuntimeException: Unable to remove job graph.");
    final AtomicInteger failureCount = new AtomicInteger(numberOfErrors);
    final ExecutionPlanStore executionPlanStore = TestingExecutionPlanStore.newBuilder().setGlobalCleanupFunction((ignoredJobId, ignoredExecutor) -> {
        actualGlobalCleanupCallCount.incrementAndGet();
        if (failureCount.getAndDecrement() > 0) {
            return FutureUtils.completedExceptionally(temporaryError);
        }
        successfulCleanupLatch.trigger();
        return FutureUtils.completedVoidFuture();
    }).build();
    executionPlanStore.start(NoOpExecutionPlanListener.INSTANCE);
    haServices.setExecutionPlanStore(executionPlanStore);
    // Construct leader election.
    final TestingLeaderElection leaderElection = new TestingLeaderElection();
    haServices.setJobMasterLeaderElection(jobId, leaderElection);
    // start the dispatcher with enough retries on cleanup
    final JobManagerRunnerRegistry jobManagerRunnerRegistry = new DefaultJobManagerRunnerRegistry(2);
    final Dispatcher dispatcher = createTestingDispatcherBuilder().setResourceCleanerFactory(new DispatcherResourceCleanerFactory(ForkJoinPool.commonPool(), TestingRetryStrategies.createWithNumberOfRetries(numberOfErrors), jobManagerRunnerRegistry, haServices.getExecutionPlanStore(), blobServer, haServices, UnregisteredMetricGroups.createUnregisteredJobManagerMetricGroup())).build(rpcService);
    dispatcher.start();
    toTerminate.add(dispatcher);
    final CompletableFuture<LeaderInformation> confirmedLeaderInformation = leaderElection.isLeader(UUID.randomUUID());
    final DispatcherGateway dispatcherGateway = dispatcher.getSelfGateway(DispatcherGateway.class);
    dispatcherGateway.submitJob(jobGraph, TIMEOUT).get();
    waitForJobToFinish(confirmedLeaderInformation, dispatcherGateway, jobId);
    successfulCleanupLatch.await();
    assertThat(actualGlobalCleanupCallCount.get()).isEqualTo(numberOfErrors + 1);
    assertThat(haServices.getExecutionPlanStore().getJobIds()).as("The JobGraph should be removed from ExecutionPlanStore.").isEmpty();
    CommonTestUtils.waitUntilCondition(() -> haServices.getJobResultStore().hasJobResultEntryAsync(jobId).get());
}

