@Test
public void testCleanupAfterLeadershipChange() throws Exception {
    final JobGraph jobGraph = createJobGraph();
    final JobID jobId = jobGraph.getJobID();
    // Construct execution plan store.
    final AtomicInteger actualGlobalCleanupCallCount = new AtomicInteger();
    final OneShotLatch firstCleanupTriggered = new OneShotLatch();
    final CompletableFuture<JobID> successfulJobGraphCleanup = new CompletableFuture<>();
    final ExecutionPlanStore executionPlanStore = TestingExecutionPlanStore.newBuilder().setGlobalCleanupFunction((actualJobId, ignoredExecutor) -> {
        final int callCount = actualGlobalCleanupCallCount.getAndIncrement();
        firstCleanupTriggered.trigger();
        if (callCount < 1) {
            return FutureUtils.completedExceptionally(new RuntimeException("Expected RuntimeException: Unable to remove job graph."));
        }
        successfulJobGraphCleanup.complete(actualJobId);
        return FutureUtils.completedVoidFuture();
    }).build();
    executionPlanStore.start(NoOpExecutionPlanListener.INSTANCE);
    haServices.setExecutionPlanStore(executionPlanStore);
    // Construct leader election.
    final TestingLeaderElection leaderElection = new TestingLeaderElection();
    haServices.setJobMasterLeaderElection(jobId, leaderElection);
    // start the dispatcher with no retries on cleanup
    configuration.set(CleanupOptions.CLEANUP_STRATEGY, CleanupOptions.NONE_PARAM_VALUES.iterator().next());
    final Dispatcher dispatcher = createTestingDispatcherBuilder().build(rpcService);
    dispatcher.start();
    toTerminate.add(dispatcher);
    final CompletableFuture<LeaderInformation> confirmedLeaderInformation = leaderElection.isLeader(UUID.randomUUID());
    final DispatcherGateway dispatcherGateway = dispatcher.getSelfGateway(DispatcherGateway.class);
    dispatcherGateway.submitJob(jobGraph, TIMEOUT).get();
    waitForJobToFinish(confirmedLeaderInformation, dispatcherGateway, jobId);
    firstCleanupTriggered.await();
    assertThat(actualGlobalCleanupCallCount.get()).as("The cleanup should have been triggered only once.").isOne();
    assertThat(successfulJobGraphCleanup.isDone()).as("The cleanup should not have reached the successful cleanup code path.").isFalse();
    assertThat(haServices.getExecutionPlanStore().getJobIds()).as("The JobGraph is still stored in the ExecutionPlanStore.").containsExactly(jobId);
    assertThat(haServices.getJobResultStore().getDirtyResults().stream().map(JobResult::getJobId).collect(Collectors.toSet())).as("The JobResultStore should have this job marked as dirty.").containsExactly(jobId);
    // Run a second dispatcher, that restores our finished job.
    final Dispatcher secondDispatcher = createTestingDispatcherBuilder().setRecoveredDirtyJobs(haServices.getJobResultStore().getDirtyResults()).build(rpcService);
    secondDispatcher.start();
    toTerminate.add(secondDispatcher);
    leaderElection.isLeader(UUID.randomUUID());
    CommonTestUtils.waitUntilCondition(() -> haServices.getJobResultStore().getDirtyResults().isEmpty());
    assertThat(haServices.getExecutionPlanStore().getJobIds()).as("The JobGraph is not stored in the ExecutionPlanStore.").isEmpty();
    assertThat(haServices.getJobResultStore().hasJobResultEntryAsync(jobId).get()).as("The JobResultStore has the job listed as clean.").isTrue();
    assertThat(successfulJobGraphCleanup.get()).isEqualTo(jobId);
    assertThat(actualGlobalCleanupCallCount.get()).isEqualTo(2);
}

