    testingJobManagerRunner.completeResultFuture(JobManagerRunnerResult.forInitializationFailure(new ExecutionGraphInfo(ArchivedExecutionGraph.createSparseArchivedExecutionGraph(jobId, jobGraph.getName(), JobStatus.FAILED, null, testFailure, jobGraph.getCheckpointingSettings(), 1L)), testFailure));
    // wait till job has failed
    dispatcher.getJobTerminationFuture(jobId, TIMEOUT).get();
    // get failure cause
    ArchivedExecutionGraph execGraph = dispatcherGateway.requestJob(jobGraph.getJobID(), TIMEOUT).get();
    assertThat(execGraph.getState()).isSameAs(JobStatus.FAILED);
    Assert.assertNotNull(execGraph.getFailureInfo());
