    configuration.set(JobManagerOptions.SCHEDULER, JobManagerOptions.SchedulerType.Adaptive);
    final AtomicReference<CompletableFuture<Void>> jobGraphPersistedFutureRef = new AtomicReference<>();
    final TestingExecutionPlanStore executionPlanStore = TestingExecutionPlanStore.newBuilder().setPutExecutionPlanConsumer(jobGraph -> Optional.ofNullable(jobGraphPersistedFutureRef.get()).map(f -> f.complete(null))).build();
