@Test
public void testJobResourceRequirementsAreGuardedAgainstConcurrentModification() throws Exception {
    final CompletableFuture<Acknowledge> blockedUpdatesToJobMasterFuture = new CompletableFuture<>();
    final JobManagerRunnerWithBlockingJobMasterFactory blockingJobMaster = new JobManagerRunnerWithBlockingJobMasterFactory(builder -> withRequestJobResponse(builder).setUpdateJobResourceRequirementsFunction(jobResourceRequirements -> blockedUpdatesToJobMasterFuture));
    dispatcher = createAndStartDispatcher(heartbeatServices, haServices, blockingJobMaster);
    final DispatcherGateway dispatcherGateway = dispatcher.getSelfGateway(DispatcherGateway.class);
    // We intentionally perform the test on two jobs to make sure the
    // concurrent modification is only prevented on the per-job level.
    final JobGraph firstJobGraph = InstantiationUtil.clone(jobGraph);
    firstJobGraph.setJobID(JobID.generate());
    final JobGraph secondJobGraph = InstantiationUtil.clone(jobGraph);
    secondJobGraph.setJobID(JobID.generate());
    final CompletableFuture<?> firstPendingUpdateFuture = testConcurrentModificationIsPrevented(dispatcherGateway, blockingJobMaster, firstJobGraph);
    final CompletableFuture<?> secondPendingUpdateFuture = testConcurrentModificationIsPrevented(dispatcherGateway, blockingJobMaster, secondJobGraph);
    assertThat(firstPendingUpdateFuture).isNotCompleted();
    assertThat(secondPendingUpdateFuture).isNotCompleted();
    blockedUpdatesToJobMasterFuture.complete(Acknowledge.get());
    assertThatFuture(firstPendingUpdateFuture).eventuallySucceeds();
    assertThatFuture(secondPendingUpdateFuture).eventuallySucceeds();
}

