    // We can update the JRR once the job transitions to RUNNING.
    awaitStatus(dispatcherGateway, jobId, JobStatus.RUNNING);
    for (int x = 0; x < 2; x++) {
        assertThatFuture(dispatcherGateway.updateJobResourceRequirements(this.jobGraph.getJobID(), getJobRequirements())).eventuallySucceeds();
    }
}

