/**
 * See FLINK-11843. This is a probabilistic test which needs to be executed several times to
 * fail.
 */
@Test
void leaderChange_withBlockingJobManagerTermination_doesNotAffectNewLeader() throws Exception {
    final TestingJobMasterServiceLeadershipRunnerFactory jobManagerRunnerFactory = new TestingJobMasterServiceLeadershipRunnerFactory(1);
    final TestingCleanupRunnerFactory cleanupRunnerFactory = new TestingCleanupRunnerFactory();
    dispatcherRunnerFactory = DefaultDispatcherRunnerFactory.createSessionRunner(new TestingDispatcherFactory(jobManagerRunnerFactory, cleanupRunnerFactory));
    executionPlanStore.start(null);
    executionPlanStore.putExecutionPlan(jobGraph);
    try (final DispatcherRunner dispatcherRunner = createDispatcherRunner()) {
        // initial run
        dispatcherLeaderElection.isLeader(UUID.randomUUID()).get();
        try (final TestingJobManagerRunner testingJobManagerRunner = jobManagerRunnerFactory.takeCreatedJobManagerRunner()) {
            dispatcherLeaderElection.notLeader();
            LOG.info("Re-grant leadership first time.");
            dispatcherLeaderElection.isLeader(UUID.randomUUID());
            // give the Dispatcher some time to recover jobs
            Thread.sleep(1L);
            dispatcherLeaderElection.notLeader();
            LOG.info("Re-grant leadership second time.");
            final UUID leaderSessionId = UUID.randomUUID();
            final CompletableFuture<LeaderInformation> confirmedLeaderInformation = dispatcherLeaderElection.isLeader(leaderSessionId);
            assertThat(confirmedLeaderInformation).isNotDone();
            LOG.info("Complete the termination of the first job manager runner.");
            testingJobManagerRunner.completeTerminationFuture();
            final LeaderInformation actualConfirmedLeaderInformation = confirmedLeaderInformation.join();
            assertThat(actualConfirmedLeaderInformation.getLeaderSessionID()).isEqualTo(leaderSessionId);
            // Wait for job to recover...
            final DispatcherGateway leaderGateway = rpcServiceExtensionWrapper.getCustomExtension().getTestingRpcService().connect(actualConfirmedLeaderInformation.getLeaderAddress(), DispatcherId.fromUuid(actualConfirmedLeaderInformation.getLeaderSessionID()), DispatcherGateway.class).get();
            assertThatFuture(leaderGateway.listJobs(TIMEOUT)).eventuallySucceeds().isEqualTo(Collections.singleton(jobGraph.getJobID()));
        }
    }
}

