@Test
void testRecoveryWhileExecutionPlanRecoveryIsScheduledConcurrently() throws Exception {
    final JobResult dirtyJobResult = TestingJobResultStore.createSuccessfulJobResult(new JobID());
    OneShotLatch recoveryInitiatedLatch = new OneShotLatch();
    OneShotLatch jobGraphAddedLatch = new OneShotLatch();
    executionPlanStore = TestingExecutionPlanStore.newBuilder().// mimic behavior when recovering a ExecutionPlan that is marked for
    // deletion
    setRecoverExecutionPlanFunction((jobId, jobs) -> null).build();
    jobResultStore = TestingJobResultStore.builder().withGetDirtyResultsSupplier(() -> {
        recoveryInitiatedLatch.trigger();
        try {
            jobGraphAddedLatch.await();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        return Collections.singleton(dirtyJobResult);
    }).build();
    final CompletableFuture<Collection<ExecutionPlan>> recoveredExecutionPlansFuture = new CompletableFuture<>();
    final CompletableFuture<Collection<JobResult>> recoveredDirtyJobResultsFuture = new CompletableFuture<>();
    dispatcherServiceFactory = (ignoredDispatcherId, recoveredJobs, recoveredDirtyJobResults, ignoredExecutionPlanWriter, ignoredJobResultStore) -> {
        recoveredExecutionPlansFuture.complete(recoveredJobs);
        recoveredDirtyJobResultsFuture.complete(recoveredDirtyJobResults);
        return TestingDispatcherGatewayService.newBuilder().build();
    };
    try (final SessionDispatcherLeaderProcess dispatcherLeaderProcess = createDispatcherLeaderProcess()) {
        dispatcherLeaderProcess.start();
        // start returns without the initial recovery being completed
        // mimic ZK message about an added jobgraph while the recovery is ongoing
        recoveryInitiatedLatch.await();
        dispatcherLeaderProcess.onAddedExecutionPlan(dirtyJobResult.getJobId());
        jobGraphAddedLatch.trigger();
        assertThatFuture(recoveredExecutionPlansFuture).eventuallySucceeds().satisfies(recoverExecutionPlans -> assertThat(recoverExecutionPlans).isEmpty());
        assertThatFuture(recoveredDirtyJobResultsFuture).eventuallySucceeds().satisfies(recoveredDirtyJobResults -> assertThat(recoveredDirtyJobResults).containsExactly(dirtyJobResult));
    }
}

