    jobVertex.setParallelism(1);
    final int storedParallelism = 4;
    final int storedMaxParallelism = 8;
    final DefaultVertexParallelismStore initialParallelismStore = new DefaultVertexParallelismStore();
    initialParallelismStore.setParallelismInfo(jobVertex.getID(), new DefaultVertexParallelismInfo(storedParallelism, storedMaxParallelism, ignored -> Optional.empty()));
    final ArchivedExecutionGraph archivedGraph = ArchivedExecutionGraph.createSparseArchivedExecutionGraphWithJobVertices(new JobID(), "TestJob", JobStatus.INITIALIZING, JobType.STREAMING, null, null, System.currentTimeMillis(), Arrays.asList(jobVertex), initialParallelismStore);
