/**
 * Tests normal FailureHandlingResult.
 */
@ParameterizedTest
@ValueSource(booleans = { true, false })
void testNormalFailureHandlingResult(boolean isNewAttempt) throws Exception {
    // create a normal FailureHandlingResult
    Execution execution = createExecution(EXECUTOR_RESOURCE.getExecutor());
    Set<ExecutionVertexID> tasks = new HashSet<>();
    tasks.add(execution.getVertex().getID());
    final long delay = 1234;
    final Throwable error = new RuntimeException();
    final long timestamp = System.currentTimeMillis();
    final CompletableFuture<Map<String, String>> failureLabels = CompletableFuture.completedFuture(Collections.singletonMap("key", "value"));
    FailureHandlingResult result = FailureHandlingResult.restartable(execution, error, timestamp, failureLabels, tasks, delay, false, isNewAttempt);
    assertThat(result.canRestart()).isTrue();
    assertThat(delay).isEqualTo(result.getRestartDelayMS());
    assertThat(tasks).isEqualTo(result.getVerticesToRestart());
    assertThat(result.getFailureLabels()).isEqualTo(failureLabels);
    assertThat(result.getError()).isSameAs(error);
    assertThat(result.getTimestamp()).isEqualTo(timestamp);
    assertThat(result.getFailedExecution()).isPresent();
    assertThat(result.getFailedExecution().get()).isSameAs(execution);
    assertThat(result.isRootCause()).isEqualTo(isNewAttempt);
}

/**
 * Tests FailureHandlingResult which suppresses restarts.
 */
@ParameterizedTest
@ValueSource(booleans = { true, false })
void testRestartingSuppressedFailureHandlingResultWithNoCausingExecutionVertexId(boolean isNewAttempt) {
    // create a FailureHandlingResult with error
    final Throwable error = new Exception("test error");
    final long timestamp = System.currentTimeMillis();
    final CompletableFuture<Map<String, String>> failureLabels = CompletableFuture.completedFuture(Collections.singletonMap("key", "value"));
    FailureHandlingResult result = FailureHandlingResult.unrecoverable(null, error, timestamp, failureLabels, false, isNewAttempt);
    assertThat(result.canRestart()).isFalse();
    assertThat(result.getError()).isSameAs(error);
    assertThat(result.getTimestamp()).isEqualTo(timestamp);
    assertThat(result.getFailureLabels()).isEqualTo(failureLabels);
    assertThat(result.getFailedExecution()).isNotPresent();
    assertThat(result.isRootCause()).isEqualTo(isNewAttempt);
    assertThatThrownBy(result::getVerticesToRestart).as("getVerticesToRestart is not allowed when restarting is suppressed").isInstanceOf(IllegalStateException.class);
    assertThatThrownBy(result::getRestartDelayMS).as("getRestartDelayMS is not allowed when restarting is suppressed").isInstanceOf(IllegalStateException.class);
}

