    verify(vertex, times(0)).finalizeOnMaster(any(FinalizeOnMasterContext.class));
    assertThat(eg.getRegisteredExecutions()).isEmpty();
}

@Test
void testMergeIndexRanges() {
    Collection<IndexRange> emptyList = List.of();
    List<IndexRange> emptyResult = mergeIndexRanges(emptyList);
    assertThat(emptyResult).isEmpty();
    Collection<IndexRange> singleRangeList = List.of(new IndexRange(5, 10));
    List<IndexRange> singleRangeResult = mergeIndexRanges(singleRangeList);
    assertThat(singleRangeResult).containsExactly(new IndexRange(5, 10));
    Collection<IndexRange> overlappingRangesList = List.of(new IndexRange(5, 10), new IndexRange(8, 12));
    List<IndexRange> overlappingRangesResult = mergeIndexRanges(overlappingRangesList);
    assertThat(overlappingRangesResult).containsExactly(new IndexRange(5, 12));
    Collection<IndexRange> nonOverlappingRangesList = List.of(new IndexRange(1, 5), new IndexRange(10, 15));
    List<IndexRange> nonOverlappingRangesResult = mergeIndexRanges(nonOverlappingRangesList);
    assertThat(nonOverlappingRangesResult).containsExactly(new IndexRange(1, 5), new IndexRange(10, 15));
    Collection<IndexRange> touchingRangesList = List.of(new IndexRange(1, 5), new IndexRange(6, 10));
    List<IndexRange> touchingRangesResult = mergeIndexRanges(touchingRangesList);
    assertThat(touchingRangesResult).containsExactly(new IndexRange(1, 10));
    Collection<IndexRange> mixedRangesList = List.of(new IndexRange(1, 3), new IndexRange(2, 6), new IndexRange(8, 10), new IndexRange(15, 18), new IndexRange(19, 20));
    List<IndexRange> mixedRangesResult = mergeIndexRanges(mixedRangesList);
    assertThat(mixedRangesResult).containsExactly(new IndexRange(1, 6), new IndexRange(8, 10), new IndexRange(15, 20));
}

@Test
void testPartitionDataAllProduced() throws Exception {
    IntermediateResult result = createResult(ResultPartitionType.BLOCKING, 2);
    IntermediateResultPartition partition1 = result.getPartitions()[0];
    IntermediateResultPartition partition2 = result.getPartitions()[1];
    ConsumedPartitionGroup consumedPartitionGroup = partition1.getConsumedPartitionGroups().get(0);
    // Not all data produced on init
    assertThat(partition1.hasDataAllProduced()).isFalse();
    assertThat(partition2.hasDataAllProduced()).isFalse();
    assertThat(consumedPartitionGroup.areAllPartitionsFinished()).isFalse();
    // Finished partition has produced all data
    partition1.markFinished();
    assertThat(partition1.hasDataAllProduced()).isTrue();
    assertThat(partition2.hasDataAllProduced()).isFalse();
    assertThat(consumedPartitionGroup.areAllPartitionsFinished()).isFalse();
    // Finished partition has produced all data
    partition2.markFinished();
    assertThat(partition1.hasDataAllProduced()).isTrue();
    assertThat(partition2.hasDataAllProduced()).isTrue();
    assertThat(consumedPartitionGroup.areAllPartitionsFinished()).isTrue();
    // Not all data produced if failover happens
    result.resetForNewExecution();
    assertThat(partition1.hasDataAllProduced()).isFalse();
    assertThat(partition2.hasDataAllProduced()).isFalse();
    assertThat(consumedPartitionGroup.areAllPartitionsFinished()).isFalse();
}

@Test
void testBlockingPartitionResetting() throws Exception {
    IntermediateResult result = createResult(ResultPartitionType.BLOCKING, 2);
    IntermediateResultPartition partition1 = result.getPartitions()[0];
    IntermediateResultPartition partition2 = result.getPartitions()[1];
    ConsumedPartitionGroup consumedPartitionGroup = partition1.getConsumedPartitionGroups().get(0);
    // Not all data data produced on init
    assertThat(partition1.hasDataAllProduced()).isFalse();
    assertThat(partition2.hasDataAllProduced()).isFalse();
    // Finished partition has produced all data
    partition1.markFinished();
    assertThat(consumedPartitionGroup.getNumberOfUnfinishedPartitions()).isOne();
    assertThat(partition1.hasDataAllProduced()).isTrue();
    assertThat(partition2.hasDataAllProduced()).isFalse();
    assertThat(consumedPartitionGroup.areAllPartitionsFinished()).isFalse();
    // Reset the result and mark partition2 FINISHED, partition1's hasDataAllProduced should be
    // false, partition2's hasDataAllProduced should be true
    result.resetForNewExecution();
    assertThat(consumedPartitionGroup.getNumberOfUnfinishedPartitions()).isEqualTo(2);
    partition2.markFinished();
    assertThat(consumedPartitionGroup.getNumberOfUnfinishedPartitions()).isOne();
    assertThat(partition1.hasDataAllProduced()).isFalse();
    assertThat(partition2.hasDataAllProduced()).isTrue();
    assertThat(consumedPartitionGroup.areAllPartitionsFinished()).isFalse();
    // All partition finished.
    partition1.markFinished();
    assertThat(consumedPartitionGroup.getNumberOfUnfinishedPartitions()).isZero();
    assertThat(partition1.hasDataAllProduced()).isTrue();
    assertThat(partition2.hasDataAllProduced()).isTrue();
    assertThat(consumedPartitionGroup.areAllPartitionsFinished()).isTrue();
    // Not all data produced and not all partition finished again if failover happens
    result.resetForNewExecution();
    assertThat(consumedPartitionGroup.getNumberOfUnfinishedPartitions()).isEqualTo(2);
    assertThat(partition1.hasDataAllProduced()).isFalse();
    assertThat(partition2.hasDataAllProduced()).isFalse();
    assertThat(consumedPartitionGroup.areAllPartitionsFinished()).isFalse();
}

