/**
 * Tests that regular heartbeat signal triggers the right callback functions in the {@link
 * HeartbeatListener}.
 */
@Test
public void testRegularHeartbeat() throws InterruptedException {
    final long heartbeatTimeout = 1000L;
    ResourceID ownResourceID = new ResourceID("foobar");
    ResourceID targetResourceID = new ResourceID("barfoo");
    final int outputPayload = 42;
    final ArrayBlockingQueue<String> reportedPayloads = new ArrayBlockingQueue<>(2);
    final TestingHeartbeatListener<String, Integer> heartbeatListener = new TestingHeartbeatListenerBuilder<String, Integer>().setReportPayloadConsumer((ignored, payload) -> reportedPayloads.offer(payload)).setRetrievePayloadFunction((ignored) -> outputPayload).createNewTestingHeartbeatListener();
    HeartbeatManagerImpl<String, Integer> heartbeatManager = new HeartbeatManagerImpl<>(heartbeatTimeout, FAILED_RPC_THRESHOLD, ownResourceID, heartbeatListener, new ScheduledExecutorServiceAdapter(EXECUTOR_RESOURCE.getExecutor()), LOG);
    final ArrayBlockingQueue<Integer> reportedPayloadsHeartbeatTarget = new ArrayBlockingQueue<>(2);
    final TestingHeartbeatTarget<Integer> heartbeatTarget = new TestingHeartbeatTargetBuilder<Integer>().setReceiveHeartbeatFunction((ignoredA, payload) -> {
        reportedPayloadsHeartbeatTarget.offer(payload);
        return FutureUtils.completedVoidFuture();
    }).createTestingHeartbeatTarget();
    heartbeatManager.monitorTarget(targetResourceID, heartbeatTarget);
    final String inputPayload1 = "foobar";
    heartbeatManager.requestHeartbeat(targetResourceID, inputPayload1);
    assertThat(reportedPayloads.take()).isEqualTo(inputPayload1);
    assertThat(reportedPayloadsHeartbeatTarget.take()).isEqualTo(outputPayload);
    final String inputPayload2 = "barfoo";
    heartbeatManager.receiveHeartbeat(targetResourceID, inputPayload2);
    assertThat(reportedPayloads.take()).isEqualTo(inputPayload2);
}

