/**
 * Tests that a heartbeat timeout is signaled if the heartbeat is not reported in time.
 */
@Test
public void testHeartbeatTimeout() throws Exception {
    int numHeartbeats = 6;
    final int payload = 42;
    ResourceID ownResourceID = new ResourceID("foobar");
    ResourceID targetResourceID = new ResourceID("barfoo");
    final CompletableFuture<ResourceID> timeoutFuture = new CompletableFuture<>();
    final TestingHeartbeatListener<Integer, Integer> heartbeatListener = new TestingHeartbeatListenerBuilder<Integer, Integer>().setRetrievePayloadFunction(ignored -> payload).setNotifyHeartbeatTimeoutConsumer(timeoutFuture::complete).createNewTestingHeartbeatListener();
    HeartbeatManagerImpl<Integer, Integer> heartbeatManager = new HeartbeatManagerImpl<>(HEARTBEAT_TIMEOUT, FAILED_RPC_THRESHOLD, ownResourceID, heartbeatListener, new ScheduledExecutorServiceAdapter(EXECUTOR_RESOURCE.getExecutor()), LOG);
    final HeartbeatTarget<Integer> heartbeatTarget = new TestingHeartbeatTargetBuilder<Integer>().createTestingHeartbeatTarget();
    heartbeatManager.monitorTarget(targetResourceID, heartbeatTarget);
    for (int i = 0; i < numHeartbeats; i++) {
        heartbeatManager.receiveHeartbeat(targetResourceID, payload);
        Thread.sleep(HEARTBEAT_INTERVAL);
    }
    FlinkAssertions.assertThatFuture(timeoutFuture).eventuallySucceeds();
    ResourceID timeoutResourceID = timeoutFuture.get(2 * HEARTBEAT_TIMEOUT, TimeUnit.MILLISECONDS);
    assertThat(targetResourceID).isEqualTo(timeoutResourceID);
}

/**
 * Tests the heartbeat interplay between the {@link HeartbeatManagerImpl} and the {@link
 * HeartbeatManagerSenderImpl}. The sender should regularly trigger heartbeat requests which are
 * fulfilled by the receiver. Upon stopping the receiver, the sender should notify the heartbeat
 * listener about the heartbeat timeout.
 *
 * @throws Exception
 */
@Test
public void testHeartbeatCluster() throws Exception {
    ResourceID resourceIdTarget = new ResourceID("foobar");
    ResourceID resourceIDSender = new ResourceID("barfoo");
    final int targetPayload = 42;
    final AtomicInteger numReportPayloadCallsTarget = new AtomicInteger(0);
    final TestingHeartbeatListener<String, Integer> heartbeatListenerTarget = new TestingHeartbeatListenerBuilder<String, Integer>().setRetrievePayloadFunction(ignored -> targetPayload).setReportPayloadConsumer((ignoredA, ignoredB) -> numReportPayloadCallsTarget.incrementAndGet()).createNewTestingHeartbeatListener();
    final String senderPayload = "1337";
    final CompletableFuture<ResourceID> targetHeartbeatTimeoutFuture = new CompletableFuture<>();
    final AtomicInteger numReportPayloadCallsSender = new AtomicInteger(0);
    final TestingHeartbeatListener<Integer, String> heartbeatListenerSender = new TestingHeartbeatListenerBuilder<Integer, String>().setRetrievePayloadFunction(ignored -> senderPayload).setNotifyHeartbeatTimeoutConsumer(targetHeartbeatTimeoutFuture::complete).setReportPayloadConsumer((ignoredA, ignoredB) -> numReportPayloadCallsSender.incrementAndGet()).createNewTestingHeartbeatListener();
    HeartbeatManagerImpl<String, Integer> heartbeatManagerTarget = new HeartbeatManagerImpl<>(HEARTBEAT_TIMEOUT, FAILED_RPC_THRESHOLD, resourceIdTarget, heartbeatListenerTarget, new ScheduledExecutorServiceAdapter(EXECUTOR_RESOURCE.getExecutor()), LOG);
    HeartbeatManagerSenderImpl<Integer, String> heartbeatManagerSender = new HeartbeatManagerSenderImpl<>(HEARTBEAT_INTERVAL, HEARTBEAT_TIMEOUT, FAILED_RPC_THRESHOLD, resourceIDSender, heartbeatListenerSender, new ScheduledExecutorServiceAdapter(EXECUTOR_RESOURCE.getExecutor()), LOG);
    heartbeatManagerTarget.monitorTarget(resourceIDSender, heartbeatManagerSender);
    heartbeatManagerSender.monitorTarget(resourceIdTarget, heartbeatManagerTarget);
    Thread.sleep(2 * HEARTBEAT_TIMEOUT);
    assertThat(targetHeartbeatTimeoutFuture).isNotDone();
    heartbeatManagerTarget.stop();
    ResourceID timeoutResourceID = targetHeartbeatTimeoutFuture.get(2 * HEARTBEAT_TIMEOUT, TimeUnit.MILLISECONDS);
    assertThat(timeoutResourceID).isEqualTo(resourceIdTarget);
    int numberHeartbeats = (int) (2 * HEARTBEAT_TIMEOUT / HEARTBEAT_INTERVAL);
    assertThat(numReportPayloadCallsTarget.get()).isGreaterThanOrEqualTo(numberHeartbeats / 2);
    assertThat(numReportPayloadCallsSender.get()).isGreaterThanOrEqualTo(numberHeartbeats / 2);
}

