/**
 * Tests that concurrent leadership operations (granting and revoking) leadership leave the
 * system in a sane state.
 */
@Test
public void testConcurrentLeadershipOperations() throws Exception {
    final LeaderElection leaderElection = embeddedHaServices.getDispatcherLeaderElection();
    final TestingLeaderContender leaderContender = new TestingLeaderContender();
    leaderElection.startLeaderElection(leaderContender);
    final UUID oldLeaderSessionId = leaderContender.getLeaderSessionFuture().get();
    assertThat(leaderElection.hasLeadershipAsync(oldLeaderSessionId).get(), is(true));
    embeddedHaServices.getDispatcherLeaderService().revokeLeadership().get();
    assertThat(leaderElection.hasLeadershipAsync(oldLeaderSessionId).get(), is(false));
    embeddedHaServices.getDispatcherLeaderService().grantLeadership();
    final UUID newLeaderSessionId = leaderContender.getLeaderSessionFuture().get();
    assertThat(leaderElection.hasLeadershipAsync(newLeaderSessionId).get(), is(true));
    leaderElection.confirmLeadershipAsync(oldLeaderSessionId, ADDRESS).get();
    leaderElection.confirmLeadershipAsync(newLeaderSessionId, ADDRESS).get();
    assertThat(leaderElection.hasLeadershipAsync(newLeaderSessionId).get(), is(true));
    leaderContender.tryRethrowException();
}

/**
 * Tests that the {@link EmbeddedLeaderService} can handle a concurrent grant leadership call
 * and a shutdown.
 */
@Test
public void testConcurrentGrantLeadershipAndShutdown() throws Exception {
    final ManuallyTriggeredScheduledExecutorService executorService = new ManuallyTriggeredScheduledExecutorService();
    final EmbeddedLeaderService embeddedLeaderService = new EmbeddedLeaderService(executorService);
    try {
        final TestingLeaderContender contender = new TestingLeaderContender();
        final LeaderElection leaderElection = embeddedLeaderService.createLeaderElectionService("component_id");
        leaderElection.startLeaderElection(contender);
        leaderElection.close();
        assertThat(contender.getLeaderSessionFuture()).as("The future shouldn't have completed because the grant event wasn't processed, yet.").isNotDone();
        // the election service should still be running
        assertThat(embeddedLeaderService.isShutdown()).isFalse();
    } finally {
        embeddedLeaderService.shutdown();
        // triggers the grant event processing after shutdown
        executorService.triggerAll();
    }
}

/**
 * Tests that the {@link EmbeddedLeaderService} can handle a concurrent revoke leadership call
 * and a shutdown.
 */
@Test
public void testConcurrentRevokeLeadershipAndShutdown() throws Exception {
    final ManuallyTriggeredScheduledExecutorService executorService = new ManuallyTriggeredScheduledExecutorService();
    final EmbeddedLeaderService embeddedLeaderService = new EmbeddedLeaderService(executorService);
    try {
        final TestingLeaderContender contender = new TestingLeaderContender();
