    assertThat(reader.hasReachedEndOfSuperstep()).isFalse();
    assertThatThrownBy(reader::startNextSuperstep).withFailMessage("Did not throw expected exception when starting next superstep with non-iterative reader.").isInstanceOf(IllegalStateException.class);
    assertThatThrownBy(() -> reader.handleEvent(EndOfSuperstepEvent.INSTANCE)).withFailMessage("Did not throw expected exception when handling end of superstep event with non-iterative reader.").hasCauseInstanceOf(IllegalStateException.class).isInstanceOf(IOException.class);
