    assertThat(buffer.readerIndex()).isZero();
    assertThat(buffer.writerIndex()).isEqualTo(buffer.capacity());
    assertThat(buffer.isWritable()).isFalse();
    random.setSeed(seed);
    for (int i = 0; i < buffer.capacity(); i++) {
