@Test
void testCompareTo() {
    assertThatThrownBy(() -> buffer.compareTo(null)).isInstanceOf(NullPointerException.class);
    // Fill the random stuff
    byte[] value = new byte[32];
    random.nextBytes(value);
    // Prevent overflow / underflow
    if (value[0] == 0) {
        value[0]++;
    } else if (value[0] == -1) {
        value[0]--;
    }
    buffer.setIndex(0, value.length);
    buffer.setBytes(0, value);
    assertThat(buffer).isEqualTo(wrappedBuffer(value)).isEqualTo(wrappedBuffer(value).order(LITTLE_ENDIAN));
    value[0]++;
    assertThat(buffer).isLessThan(wrappedBuffer(value)).isLessThan(wrappedBuffer(value).order(LITTLE_ENDIAN));
    value[0] -= 2;
    assertThat(buffer).isGreaterThan(wrappedBuffer(value)).isGreaterThan(wrappedBuffer(value).order(LITTLE_ENDIAN));
    value[0]++;
    assertThat(buffer).isGreaterThan(wrappedBuffer(value, 0, 31)).isGreaterThan(wrappedBuffer(value, 0, 31).order(LITTLE_ENDIAN));
    assertThat(buffer.slice(0, 31)).isLessThan(wrappedBuffer(value)).isLessThan(wrappedBuffer(value).order(LITTLE_ENDIAN));
    ByteBuf retainedSlice = buffer.retainedSlice(0, 31);
    assertThat(retainedSlice).isLessThan(wrappedBuffer(value));
    retainedSlice.release();
    retainedSlice = buffer.retainedSlice(0, 31);
    assertThat(retainedSlice).isLessThan(wrappedBuffer(value).order(LITTLE_ENDIAN));
    retainedSlice.release();
}

