@Test
void testAccumulateWithoutCopy() {
    int sourceLength = 128;
    int sourceReaderIndex = 32;
    int expectedAccumulationSize = 16;
    ByteBuf src = createSourceBuffer(sourceLength, sourceReaderIndex, expectedAccumulationSize);
    ByteBuf target = Unpooled.buffer(expectedAccumulationSize);
    // If src has enough data and no data has been copied yet, src will be returned without
    // modification.
    ByteBuf accumulated = ByteBufUtils.accumulate(target, src, expectedAccumulationSize, target.readableBytes());
    assertThat(accumulated).isSameAs(src);
    assertThat(src.readerIndex()).isEqualTo(sourceReaderIndex);
    verifyBufferContent(src, sourceReaderIndex, expectedAccumulationSize);
}

@Test
void testAccumulateWithCopy() {
    int sourceLength = 128;
    int firstSourceReaderIndex = 32;
    int secondSourceReaderIndex = 0;
    int expectedAccumulationSize = 128;
    int firstAccumulationSize = sourceLength - firstSourceReaderIndex;
    int secondAccumulationSize = expectedAccumulationSize - firstAccumulationSize;
    ByteBuf firstSource = createSourceBuffer(sourceLength, firstSourceReaderIndex, firstAccumulationSize);
    ByteBuf secondSource = createSourceBuffer(sourceLength, secondSourceReaderIndex, secondAccumulationSize);
    ByteBuf target = Unpooled.buffer(expectedAccumulationSize);
    // If src does not have enough data, src will be copied into target and null will be
    // returned.
    ByteBuf accumulated = ByteBufUtils.accumulate(target, firstSource, expectedAccumulationSize, target.readableBytes());
    assertThat(accumulated).isNull();
    assertThat(firstSource.readerIndex()).isEqualTo(sourceLength);
    assertThat(target.readableBytes()).isEqualTo(firstAccumulationSize);
    // The remaining data will be copied from the second buffer, and the target buffer will be
    // returned
    // after all data is accumulated.
    accumulated = ByteBufUtils.accumulate(target, secondSource, expectedAccumulationSize, target.readableBytes());
    assertThat(accumulated).isSameAs(target);
    assertThat(secondSource.readerIndex()).isEqualTo(secondSourceReaderIndex + secondAccumulationSize);
    assertThat(target.readableBytes()).isEqualTo(expectedAccumulationSize);
    verifyBufferContent(accumulated, 0, expectedAccumulationSize);
}

/**
 * Verifies that requests for non-existing (failed/cancelled) input channels are properly
 * cancelled. The receiver receives data, but there is no input channel to receive the data.
 * This should cancel the request.
 */
@Test
void testCancelPartitionRequest() throws Exception {
    NettyServerAndClient serverAndClient = null;
    try {
        TestPooledBufferProvider outboundBuffers = new TestPooledBufferProvider(16);
        ResultPartitionManager partitions = mock(ResultPartitionManager.class);
        ResultPartitionID pid = new ResultPartitionID();
        CountDownLatch sync = new CountDownLatch(1);
        final ResultSubpartitionView view = spy(new InfiniteSubpartitionView(outboundBuffers, sync));
        // Return infinite subpartition
        when(partitions.createSubpartitionViewOrRegisterListener(eq(pid), any(ResultSubpartitionIndexSet.class), any(BufferAvailabilityListener.class), any(PartitionRequestListener.class))).thenAnswer((Answer<Optional<ResultSubpartitionView>>) invocationOnMock -> Optional.of(view));
        NettyProtocol protocol = new NettyProtocol(partitions, mock(TaskEventDispatcher.class));
        serverAndClient = initServerAndClient(protocol);
        Channel ch = connect(serverAndClient);
        // Request for non-existing input channel => results in cancel request
        ch.writeAndFlush(new PartitionRequest(pid, new ResultSubpartitionIndexSet(0), new InputChannelID(), Integer.MAX_VALUE)).await();
        // Wait for the notification
        assertThat(sync.await(TestingUtils.TESTING_DURATION.toMillis(), TimeUnit.MILLISECONDS)).withFailMessage("Timed out after waiting for " + TestingUtils.TESTING_DURATION.toMillis() + " ms to be notified about cancelled partition.").isTrue();
        verify(view, times(1)).releaseAllResources();
    } finally {
        shutdown(serverAndClient);
    }
}

