            ((ChannelStateHolder) channel).setChannelStateWriter(ChannelStateWriter.NO_OP);
        }
    }
    for (int i = 0; i < 3; i++) {
        assertThat(getInputChannelsInPartition(gate, partitionIds[i]).stream().map(InputChannel::getConsumedSubpartitionIndexSet).collect(Collectors.toList())).containsExactly(new ResultSubpartitionIndexSet(new IndexRange(0, 1)));
