    assertChannelsType(gate, LocalInputChannel.class, partitionIds[0]);
    assertChannelsType(gate, RemoteInputChannel.class, partitionIds[1]);
    assertChannelsType(gate, LocalInputChannel.class, partitionIds[2]);
