/**
 * Tests basic correctness of buffer-or-event interleaving and correct <code>null</code> return
 * value after receiving all end-of-partition events.
 *
 * <p>For buffer-or-event instances, it is important to verify that they have been set off to
 * the correct logical index.
 */
@Test
@Timeout(value = 120)
void testBasicGetNextLogic() throws Exception {
    // Setup
    final SingleInputGate ig1 = createInputGate(3);
    final SingleInputGate ig2 = createInputGate(5);
    final UnionInputGate union = new UnionInputGate(new SingleInputGate[] { ig1, ig2 });
    assertThat(union.getNumberOfInputChannels()).isEqualTo(ig1.getNumberOfInputChannels() + ig2.getNumberOfInputChannels());
    final TestInputChannel[][] inputChannels = new TestInputChannel[][] { TestInputChannel.createInputChannels(ig1, 3), TestInputChannel.createInputChannels(ig2, 5) };
    // 0 => 0
    inputChannels[0][0].readBuffer();
    // 0 => 0
    inputChannels[0][0].readEndOfData();
    // 0 => 0
    inputChannels[0][0].readEndOfPartitionEvent();
    // 2 => 5
    inputChannels[1][2].readBuffer();
    // 2 => 5
    inputChannels[1][2].readEndOfData();
    // 2 => 5
    inputChannels[1][2].readEndOfPartitionEvent();
    // 0 => 3
    inputChannels[1][0].readBuffer();
    // 1 => 4
    inputChannels[1][1].readBuffer();
    // 1 => 1
    inputChannels[0][1].readBuffer();
    // 3 => 6
    inputChannels[1][3].readBuffer();
    // 1 => 1
    inputChannels[0][1].readEndOfData();
    // 3 => 6
    inputChannels[1][3].readEndOfData();
    // 1 => 1
    inputChannels[0][1].readEndOfPartitionEvent();
    // 3 => 6
    inputChannels[1][3].readEndOfPartitionEvent();
    // 1 => 2
    inputChannels[0][2].readBuffer();
    // 1 => 2
    inputChannels[0][2].readEndOfData();
    // 1 => 2
    inputChannels[0][2].readEndOfPartitionEvent();
    // 4 => 7
    inputChannels[1][4].readBuffer();
    // 4 => 7
    inputChannels[1][4].readEndOfData();
    // 0 => 3
    inputChannels[1][1].readEndOfData();
    // 0 => 3
    inputChannels[1][0].readEndOfData();
    // 4 => 7
    inputChannels[1][4].readEndOfPartitionEvent();
    // 0 => 3
    inputChannels[1][1].readEndOfPartitionEvent();
    // 0 => 3
    inputChannels[1][0].readEndOfPartitionEvent();
    ig1.notifyChannelNonEmpty(inputChannels[0][0]);
    ig1.notifyChannelNonEmpty(inputChannels[0][1]);
    ig1.notifyChannelNonEmpty(inputChannels[0][2]);
    ig2.notifyChannelNonEmpty(inputChannels[1][0]);
    ig2.notifyChannelNonEmpty(inputChannels[1][1]);
    ig2.notifyChannelNonEmpty(inputChannels[1][2]);
    ig2.notifyChannelNonEmpty(inputChannels[1][3]);
    ig2.notifyChannelNonEmpty(inputChannels[1][4]);
    // gate 1, channel 0
    verifyBufferOrEvent(union, true, 0, true);
    // gate 2, channel 0
    verifyBufferOrEvent(union, true, 3, true);
    // gate 1, channel 1
    verifyBufferOrEvent(union, true, 1, true);
    // gate 2, channel 1
    verifyBufferOrEvent(union, true, 4, true);
    // gate 1, channel 2
    verifyBufferOrEvent(union, true, 2, true);
    // gate 2, channel 1
    verifyBufferOrEvent(union, true, 5, true);
    // gate 1, channel 0
    verifyBufferOrEvent(union, false, 0, true);
    // gate 2, channel 1
    verifyBufferOrEvent(union, true, 6, true);
    // gate 1, channel 1
    verifyBufferOrEvent(union, false, 1, true);
    // gate 2, channel 1
    verifyBufferOrEvent(union, true, 7, true);
    // gate 1, channel 2
    verifyBufferOrEvent(union, false, 2, true);
    // gate 2, channel 0
    verifyBufferOrEvent(union, false, 3, true);
    // gate 1, channel 0
    verifyBufferOrEvent(union, false, 0, true);
    // gate 1, channel 1
    verifyBufferOrEvent(union, false, 4, true);
    // gate 1, channel 1
    verifyBufferOrEvent(union, false, 1, true);
    assertThat(union.hasReceivedEndOfData()).isEqualTo(PullingAsyncDataInput.EndOfDataStatus.NOT_END_OF_DATA);
    // gate 2, channel 2
    verifyBufferOrEvent(union, false, 5, true);
    // gate 1, channel 2
    verifyBufferOrEvent(union, false, 2, true);
    // gate 2, channel 3
    verifyBufferOrEvent(union, false, 6, true);
    // gate 2, channel 4
    verifyBufferOrEvent(union, false, 7, true);
    assertThat(union.hasReceivedEndOfData()).isEqualTo(PullingAsyncDataInput.EndOfDataStatus.DRAINED);
    assertThat(union.isFinished()).isFalse();
    // gate 2, channel 0
    verifyBufferOrEvent(union, false, 3, true);
    // gate 2, channel 1
    verifyBufferOrEvent(union, false, 4, true);
    // gate 2, channel 2
    verifyBufferOrEvent(union, false, 5, true);
    // gate 2, channel 3
    verifyBufferOrEvent(union, false, 6, true);
    // gate 2, channel 4
    verifyBufferOrEvent(union, false, 7, false);
    // Return null when the input gate has received all end-of-partition events
    assertThat(union.isFinished()).isTrue();
    assertThat(union.getNext()).isNotPresent();
}

@Test
void testDrainFlagComputation() throws Exception {
    // Setup
    final SingleInputGate inputGate1 = createInputGate();
    final SingleInputGate inputGate2 = createInputGate();
    final TestInputChannel[] inputChannels1 = new TestInputChannel[] { new TestInputChannel(inputGate1, 0), new TestInputChannel(inputGate1, 1) };
    inputGate1.setInputChannels(inputChannels1);
    final TestInputChannel[] inputChannels2 = new TestInputChannel[] { new TestInputChannel(inputGate2, 0), new TestInputChannel(inputGate2, 1) };
    inputGate2.setInputChannels(inputChannels2);
    // Test
    inputChannels1[1].readEndOfData(StopMode.DRAIN);
    inputChannels1[0].readEndOfData(StopMode.NO_DRAIN);
    inputChannels2[1].readEndOfData(StopMode.DRAIN);
    inputChannels2[0].readEndOfData(StopMode.DRAIN);
    final UnionInputGate unionInputGate = new UnionInputGate(inputGate1, inputGate2);
    inputGate1.notifyChannelNonEmpty(inputChannels1[0]);
    inputGate1.notifyChannelNonEmpty(inputChannels1[1]);
    inputGate2.notifyChannelNonEmpty(inputChannels2[0]);
    inputGate2.notifyChannelNonEmpty(inputChannels2[1]);
    verifyBufferOrEvent(unionInputGate, false, 0, true);
    verifyBufferOrEvent(unionInputGate, false, 2, true);
    // we have received EndOfData on a single input only
    assertThat(unionInputGate.hasReceivedEndOfData()).isEqualTo(PullingAsyncDataInput.EndOfDataStatus.NOT_END_OF_DATA);
    verifyBufferOrEvent(unionInputGate, false, 1, true);
    verifyBufferOrEvent(unionInputGate, false, 3, true);
    // both channels received EndOfData, one channel said we should not drain
    assertThat(unionInputGate.hasReceivedEndOfData()).isEqualTo(PullingAsyncDataInput.EndOfDataStatus.STOPPED);
}

