@Test
void testReuseRecycledBuffersWhenFlushDataBuffer() throws IOException {
    int numBuffers = 10;
    int numSubpartitions = 10;
    AtomicInteger numRequestedBuffers = new AtomicInteger(0);
    TestingTieredStorageMemoryManager memoryManager = new TestingTieredStorageMemoryManager.Builder().setRequestBufferBlockingFunction(owner -> {
        numRequestedBuffers.incrementAndGet();
        MemorySegment memorySegment = globalPool.requestPooledMemorySegment();
        // When flushing data from the data buffer, the buffers should
        // not be requested from here anymore because the freeSegments
        // can be reused before released.
        assertThat(numRequestedBuffers.get() <= numBuffers).isTrue();
        return new BufferBuilder(memorySegment, segment -> globalPool.requestPooledMemorySegment());
    }).build();
    SortBufferAccumulator bufferAccumulator = new SortBufferAccumulator(numSubpartitions, numBuffers, BUFFER_SIZE_BYTES, memoryManager, true);
    bufferAccumulator.setup(((subpartition, buffer, numRemainingBuffers) -> buffer.recycleBuffer()));
    for (int i = 0; i < numSubpartitions; i++) {
        bufferAccumulator.receive(generateRandomData(10, new Random()), new TieredStorageSubpartitionId(i % numSubpartitions), Buffer.DataType.DATA_BUFFER, false);
    }
    // Trigger flushing buffers from data buffer.
    bufferAccumulator.close();
}

