    assertThat(partitionTracker.getAllTrackedPartitions().stream().map(desc -> desc.getShuffleDescriptor().getResultPartitionID()).collect(Collectors.toList())).containsExactlyInAnyOrder(resultPartitionId1, resultPartitionId2);
