@Test
void testReleaseJobPartitionPromoteClusterPartition() {
    final TestingShuffleMaster shuffleMaster = new TestingShuffleMaster();
    final Queue<ReleaseCall> taskExecutorReleaseCalls = new ArrayBlockingQueue<>(4);
    final Queue<PromoteCall> taskExecutorPromoteCalls = new ArrayBlockingQueue<>(4);
    final JobMasterPartitionTracker partitionTracker = new JobMasterPartitionTrackerImpl(new JobID(), shuffleMaster, resourceId -> Optional.of(createTaskExecutorGateway(resourceId, taskExecutorReleaseCalls, taskExecutorPromoteCalls)));
    final ResourceID taskExecutorId1 = ResourceID.generate();
    final ResultPartitionID jobPartitionId0 = new ResultPartitionID();
    final ResultPartitionID jobPartitionId1 = new ResultPartitionID();
    final ResultPartitionID clusterPartitionId0 = new ResultPartitionID();
    final ResultPartitionID clusterPartitionId1 = new ResultPartitionID();
    // Any partition type that is not BLOCKING_PERSISTENT denotes a job partition;
    // A local job partition (occupies tm local resource)
    final ResultPartitionDeploymentDescriptor jobPartition0 = AbstractPartitionTrackerTest.createResultPartitionDeploymentDescriptor(jobPartitionId0, ResultPartitionType.BLOCKING, true);
    partitionTracker.startTrackingPartition(taskExecutorId1, jobPartition0);
    // An external job partition (accommodated by external shuffle service)
    final ResultPartitionDeploymentDescriptor jobPartition1 = AbstractPartitionTrackerTest.createResultPartitionDeploymentDescriptor(jobPartitionId1, ResultPartitionType.BLOCKING, false);
    partitionTracker.startTrackingPartition(taskExecutorId1, jobPartition1);
    // BLOCKING_PERSISTENT denotes a cluster partition
    // An local cluster partition
    final ResultPartitionDeploymentDescriptor clusterPartition0 = AbstractPartitionTrackerTest.createResultPartitionDeploymentDescriptor(clusterPartitionId0, ResultPartitionType.BLOCKING_PERSISTENT, true);
    partitionTracker.startTrackingPartition(taskExecutorId1, clusterPartition0);
    // An external cluster partition
    final ResultPartitionDeploymentDescriptor clusterPartition1 = AbstractPartitionTrackerTest.createResultPartitionDeploymentDescriptor(clusterPartitionId1, ResultPartitionType.BLOCKING_PERSISTENT, false);
    partitionTracker.startTrackingPartition(taskExecutorId1, clusterPartition1);
    partitionTracker.stopTrackingAndReleasePartitions(Arrays.asList(jobPartitionId0, jobPartitionId1));
    partitionTracker.stopTrackingAndPromotePartitions(Arrays.asList(clusterPartitionId0, clusterPartitionId1));
    // Exactly one call should have been made to the hosting task executor
    assertThat(taskExecutorReleaseCalls).hasSize(1);
    assertThat(taskExecutorPromoteCalls).hasSize(1);
    final ReleaseCall releaseCall = taskExecutorReleaseCalls.remove();
    final PromoteCall promoteCall = taskExecutorPromoteCalls.remove();
    // One local partition released and one local partition promoted.
    assertThat(Iterables.getOnlyElement(releaseCall.getReleasedPartitions())).isEqualTo(jobPartitionId0);
    assertThat(Iterables.getOnlyElement(promoteCall.getPromotedPartitions())).isEqualTo(clusterPartitionId0);
    // Both internal and external partitions will be fed into shuffle-master for releasing.
    Collection<ResultPartitionID> externallyReleasedPartitions = new ArrayList<>(shuffleMaster.externallyReleasedPartitions);
    assertThat(externallyReleasedPartitions).containsExactlyInAnyOrder(jobPartitionId0, jobPartitionId1);
}

/**
 * Tests a fix for FLINK-1930.
 *
 * <p>When consuming a pipelined result only partially, is is possible that local channels
 * release the buffer pool, which is associated with the result partition, too early. If the
 * producer is still producing data when this happens, it runs into an IllegalStateException,
 * because of the destroyed buffer pool.
 *
 * @see <a href="https://issues.apache.org/jira/browse/FLINK-1930">FLINK-1930</a>
 */
@Test
void testPartialConsumePipelinedResultReceiver() throws Exception {
    final JobVertex sender = new JobVertex("Sender");
    sender.setInvokableClass(SlowBufferSender.class);
    sender.setParallelism(PARALLELISM);
    final JobVertex receiver = new JobVertex("Receiver");
    receiver.setInvokableClass(SingleBufferReceiver.class);
    receiver.setParallelism(PARALLELISM);
    // The partition needs to be pipelined, otherwise the original issue does not occur, because
    // the sender and receiver are not online at the same time.
    connectNewDataSetAsInput(receiver, sender, DistributionPattern.POINTWISE, ResultPartitionType.PIPELINED);
    final JobGraph jobGraph = JobGraphTestUtils.streamingJobGraph(sender, receiver);
    final SlotSharingGroup slotSharingGroup = new SlotSharingGroup();
    sender.setSlotSharingGroup(slotSharingGroup);
    receiver.setSlotSharingGroup(slotSharingGroup);
    MINI_CLUSTER_RESOURCE.getMiniCluster().executeJobBlocking(jobGraph);
}

