void testRemoveExpiration() {
    PartitionRequestListenerManager partitionRequestListenerManager = new PartitionRequestListenerManager();
    assertThat(partitionRequestListenerManager.isEmpty()).isTrue();
    List<PartitionRequestListener> listenerList = new ArrayList<>();
    List<PartitionRequestListener> expireListenerList = new ArrayList<>();
    NettyPartitionRequestListener listener1 = new NettyPartitionRequestListener(TestingResultPartitionProvider.newBuilder().build(), TestingSubpartitionCreatedViewReader.newBuilder().setReceiverId(new InputChannelID()).build(), new ResultSubpartitionIndexSet(0), new ResultPartitionID(), 0L);
