@Test
void testMergeForwardGroup() {
    Map<Integer, StreamNode> streamNodeRetriever = new HashMap<>();
    StreamNodeForwardGroup forwardGroup = createForwardGroupAndUpdateStreamNodeRetriever(createStreamNode(0, -1, -1), streamNodeRetriever);
    StreamNodeForwardGroup forwardGroupWithUnDecidedParallelism = createForwardGroupAndUpdateStreamNodeRetriever(createStreamNode(1, -1, -1), streamNodeRetriever);
    forwardGroup.mergeForwardGroup(forwardGroupWithUnDecidedParallelism);
    assertThat(forwardGroup.isParallelismDecided()).isFalse();
    assertThat(forwardGroup.isMaxParallelismDecided()).isFalse();
    StreamNodeForwardGroup forwardGroupWithDecidedParallelism = createForwardGroupAndUpdateStreamNodeRetriever(createStreamNode(2, 2, 4), streamNodeRetriever);
    forwardGroup.mergeForwardGroup(forwardGroupWithDecidedParallelism);
    assertThat(forwardGroup.getParallelism()).isEqualTo(2);
    assertThat(forwardGroup.getMaxParallelism()).isEqualTo(4);
    StreamNodeForwardGroup forwardGroupWithLargerMaxParallelism = createForwardGroupAndUpdateStreamNodeRetriever(createStreamNode(3, 2, 5), streamNodeRetriever);
    // The target max parallelism is larger than source.
    assertThat(forwardGroup.mergeForwardGroup(forwardGroupWithLargerMaxParallelism)).isTrue();
    assertThat(forwardGroup.getMaxParallelism()).isEqualTo(4);
    StreamNodeForwardGroup forwardGroupWithSmallerMaxParallelism = createForwardGroupAndUpdateStreamNodeRetriever(createStreamNode(4, 2, 3), streamNodeRetriever);
    assertThat(forwardGroup.mergeForwardGroup(forwardGroupWithSmallerMaxParallelism)).isTrue();
    assertThat(forwardGroup.getMaxParallelism()).isEqualTo(3);
    StreamNodeForwardGroup forwardGroupWithMaxParallelismSmallerThanSourceParallelism = createForwardGroupAndUpdateStreamNodeRetriever(createStreamNode(5, -1, 1), streamNodeRetriever);
    assertThat(forwardGroup.mergeForwardGroup(forwardGroupWithMaxParallelismSmallerThanSourceParallelism)).isFalse();
    StreamNodeForwardGroup forwardGroupWithDifferentParallelism = createForwardGroupAndUpdateStreamNodeRetriever(createStreamNode(6, 1, 3), streamNodeRetriever);
    assertThat(forwardGroup.mergeForwardGroup(forwardGroupWithDifferentParallelism)).isFalse();
    StreamNodeForwardGroup forwardGroupWithUndefinedParallelism = createForwardGroupAndUpdateStreamNodeRetriever(createStreamNode(7, -1, 2), streamNodeRetriever);
    assertThat(forwardGroup.mergeForwardGroup(forwardGroupWithUndefinedParallelism)).isTrue();
    assertThat(forwardGroup.size()).isEqualTo(6);
    assertThat(forwardGroup.getParallelism()).isEqualTo(2);
    assertThat(forwardGroup.getMaxParallelism()).isEqualTo(2);
    for (Integer nodeId : forwardGroup.getVertexIds()) {
        StreamNode node = streamNodeRetriever.get(nodeId);
        assertThat(node.getParallelism()).isEqualTo(forwardGroup.getParallelism());
        assertThat(node.getMaxParallelism()).isEqualTo(forwardGroup.getMaxParallelism());
    }
}

