@Test
public void testPutExecutionPlanWhenAlreadyExist() throws Exception {
    final CompletableFuture<Tuple3<String, IntegerResourceVersion, ExecutionPlan>> replaceFuture = new CompletableFuture<>();
    final int resourceVersion = 100;
    final AtomicBoolean alreadyExist = new AtomicBoolean(false);
    final TestingStateHandleStore<ExecutionPlan> stateHandleStore = builder.setExistsFunction(ignore -> {
        if (alreadyExist.get()) {
            return IntegerResourceVersion.valueOf(resourceVersion);
        } else {
            alreadyExist.set(true);
            return IntegerResourceVersion.notExisting();
        }
    }).setAddFunction((ignore, state) -> jobGraphStorageHelper.store(state)).setReplaceConsumer(replaceFuture::complete).build();
    final ExecutionPlanStore executionPlanStore = createAndStartExecutionPlanStore(stateHandleStore);
    executionPlanStore.putExecutionPlan(testingExecutionPlan);
    // Replace
    executionPlanStore.putExecutionPlan(testingExecutionPlan);
    final Tuple3<String, IntegerResourceVersion, ExecutionPlan> actual = replaceFuture.get(timeout, TimeUnit.MILLISECONDS);
    assertThat(actual.f0).isEqualTo(testingExecutionPlan.getJobID().toString());
    assertThat(actual.f1).isEqualTo(IntegerResourceVersion.valueOf(resourceVersion));
    assertThat(actual.f2.getJobID()).isEqualTo(testingExecutionPlan.getJobID());
}

