/**
 * Tests that we fail with an exception if the job cannot be removed from the
 * ZooKeeperExecutionPlanStore.
 *
 * <p>Tests that a close ZooKeeperExecutionPlanStore no longer holds any locks.
 */
@Test
public void testExecutionPlanRemovalFailureAndLockRelease() throws Exception {
    final ExecutionPlanStore submittedExecutionPlanStore = createZooKeeperExecutionPlanStore("/testConcurrentAddExecutionPlan");
    final ExecutionPlanStore otherSubmittedExecutionPlanStore = createZooKeeperExecutionPlanStore("/testConcurrentAddExecutionPlan");
    final TestingExecutionPlanListener listener = new TestingExecutionPlanListener();
    submittedExecutionPlanStore.start(listener);
    otherSubmittedExecutionPlanStore.start(listener);
    final ExecutionPlan executionPlan = JobGraphTestUtils.emptyJobGraph();
    submittedExecutionPlanStore.putExecutionPlan(executionPlan);
    final ExecutionPlan recoveredExecutionPlan = otherSubmittedExecutionPlanStore.recoverExecutionPlan(executionPlan.getJobID());
    assertThat(recoveredExecutionPlan).isNotNull();
    assertThatExceptionOfType(Exception.class).as("It should not be possible to remove the ExecutionPlan since the first store still has a lock on it.").isThrownBy(() -> otherSubmittedExecutionPlanStore.globalCleanupAsync(recoveredExecutionPlan.getJobID(), Executors.directExecutor()).join());
    submittedExecutionPlanStore.stop();
    // now we should be able to delete the job graph
    otherSubmittedExecutionPlanStore.globalCleanupAsync(recoveredExecutionPlan.getJobID(), Executors.directExecutor()).join();
    assertThat(otherSubmittedExecutionPlanStore.recoverExecutionPlan(recoveredExecutionPlan.getJobID())).isNull();
    otherSubmittedExecutionPlanStore.stop();
}

