@Test
void testSlotUtilizationCalculation() {
    final DefaultAllocatedSlotPool slotPool = new DefaultAllocatedSlotPool();
    final ResourceID owner = ResourceID.generate();
    final Collection<AllocatedSlot> slots = createAllocatedSlotsWithOwner(owner);
    slotPool.addSlots(slots, 0);
    FreeSlotTracker freeSlotTracker = slotPool.getFreeSlotTracker();
    assertThat(freeSlotTracker.getAvailableSlots()).allSatisfy(allocationId -> assertThat(freeSlotTracker.getTaskExecutorUtilization(freeSlotTracker.getSlotInfo(allocationId))).isCloseTo(0, offset(0.1)));
    int numAllocatedSlots = 0;
    for (AllocatedSlot slot : slots) {
        assertThat(slotPool.reserveFreeSlot(slot.getAllocationId())).isEqualTo(slot);
        freeSlotTracker.reserveSlot(slot.getAllocationId());
        numAllocatedSlots++;
        final double utilization = (double) numAllocatedSlots / slots.size();
        assertThat(freeSlotTracker.getAvailableSlots()).allSatisfy(allocationId -> assertThat(freeSlotTracker.getTaskExecutorUtilization(freeSlotTracker.getSlotInfo(allocationId))).isCloseTo(utilization, offset(0.1)));
    }
}

