/**
 * Tests that there is no information left in the ZooKeeper cluster after the ZooKeeper client
 * has terminated. In other words, checks that the ZooKeeperLeaderElection service uses
 * ephemeral nodes.
 */
@Test
void testEphemeralZooKeeperNodes() throws Exception {
    ZooKeeperLeaderElectionDriver leaderElectionDriver;
    LeaderRetrievalDriver leaderRetrievalDriver = null;
    final TestingLeaderElectionListener electionEventHandler = new TestingLeaderElectionListener();
    final TestingLeaderRetrievalEventHandler retrievalEventHandler = new TestingLeaderRetrievalEventHandler();
    CuratorFrameworkWithUnhandledErrorListener curatorFrameworkWrapper;
    CuratorFrameworkWithUnhandledErrorListener curatorFrameworkWrapper2 = null;
    CuratorCache cache = null;
    try {
        curatorFrameworkWrapper = ZooKeeperUtils.startCuratorFramework(configuration, testingFatalErrorHandlerResource.getTestingFatalErrorHandler());
        curatorFrameworkWrapper2 = ZooKeeperUtils.startCuratorFramework(configuration, testingFatalErrorHandlerResource.getTestingFatalErrorHandler());
        leaderElectionDriver = createAndInitLeaderElectionDriver(curatorFrameworkWrapper.asCuratorFramework(), electionEventHandler);
        leaderRetrievalDriver = ZooKeeperUtils.createLeaderRetrievalDriverFactory(curatorFrameworkWrapper2.asCuratorFramework(), COMPONENT_ID).createLeaderRetrievalDriver(retrievalEventHandler, retrievalEventHandler::handleError);
        cache = CuratorCache.build(curatorFrameworkWrapper2.asCuratorFramework(), ZooKeeperUtils.generateConnectionInformationPath(COMPONENT_ID));
        final ExistsCacheListener existsListener = ExistsCacheListener.createWithNodeIsMissingValidation(cache, ZooKeeperUtils.generateConnectionInformationPath(COMPONENT_ID));
        cache.listenable().addListener(existsListener);
        cache.start();
        electionEventHandler.await(LeaderElectionEvent.IsLeaderEvent.class);
        leaderElectionDriver.publishLeaderInformation(COMPONENT_ID, LeaderInformation.known(UUID.randomUUID(), LEADER_ADDRESS));
        retrievalEventHandler.waitForNewLeader();
        Future<Boolean> existsFuture = existsListener.nodeExists();
        existsFuture.get(timeout, TimeUnit.MILLISECONDS);
        final DeletedCacheListener deletedCacheListener = DeletedCacheListener.createWithNodeExistValidation(cache, ZooKeeperUtils.generateConnectionInformationPath(COMPONENT_ID));
        cache.listenable().addListener(deletedCacheListener);
        leaderElectionDriver.close();
        // now stop the underlying client
        curatorFrameworkWrapper.close();
        Future<Boolean> deletedFuture = deletedCacheListener.nodeDeleted();
        // make sure that the leader node has been deleted
        deletedFuture.get(timeout, TimeUnit.MILLISECONDS);
        retrievalEventHandler.waitForEmptyLeaderInformation();
    } finally {
        if (leaderRetrievalDriver != null) {
            leaderRetrievalDriver.close();
        }
        if (cache != null) {
            cache.close();
        }
        if (curatorFrameworkWrapper2 != null) {
            curatorFrameworkWrapper2.close();
        }
        electionEventHandler.failIfErrorEventHappened();
    }
}

