/**
 * Tests that LeaderRetrievalUtils.findConnectingAddress finds the correct connecting address in
 * case of an old leader address in ZooKeeper and a subsequent election of a new leader. The
 * findConnectingAddress should block until the new leader has been elected and his address has
 * been written to ZooKeeper.
 */
@Test
void testConnectingAddressRetrievalWithDelayedLeaderElection() throws Exception {
    Duration timeout = Duration.ofMinutes(1L);
    long sleepingTime = 1000;
    LeaderElection leaderElection = null;
    Thread thread;
    final InetAddress localHost;
    try {
        localHost = InetAddress.getLocalHost();
    } catch (UnknownHostException e) {
        // may happen if disconnected. skip test.
        System.err.println("Skipping 'testNetworkInterfaceSelection' test.");
        return;
    }
    try (ServerSocket serverSocket = new ServerSocket(0, 50, localHost)) {
        String wrongAddress = RPC_SYSTEM.getRpcUrl("1.1.1.1", 1234, "foobar", AddressResolution.NO_ADDRESS_RESOLUTION, config);
        final TestingLeaderElectionListener listener = new TestingLeaderElectionListener();
        try {
            InetSocketAddress correctInetSocketAddress = new InetSocketAddress(localHost, serverSocket.getLocalPort());
            String correctAddress = RPC_SYSTEM.getRpcUrl(localHost.getHostName(), correctInetSocketAddress.getPort(), JobMaster.JOB_MANAGER_NAME, AddressResolution.NO_ADDRESS_RESOLUTION, config);
            // create driver to simulate a separate Flink process having leadership that writes
            // its leader information to the ZooKeeper backend and gets lost afterward
            final ZooKeeperLeaderElectionDriver externalProcessDriver = new ZooKeeperLeaderElectionDriver(ZooKeeperUtils.useNamespaceAndEnsurePath(zooKeeperExtension.getZooKeeperClient(testingFatalErrorHandlerResource.getTestingFatalErrorHandler()), ZooKeeperUtils.generateLeaderLatchPath("")), listener);
            externalProcessDriver.isLeader();
            externalProcessDriver.publishLeaderInformation(HighAvailabilityServices.DEFAULT_JOB_ID.toString(), LeaderInformation.known(UUID.randomUUID(), wrongAddress));
            FindConnectingAddress findConnectingAddress = new FindConnectingAddress(timeout, highAvailabilityServices.getJobManagerLeaderRetriever(HighAvailabilityServices.DEFAULT_JOB_ID, "unused-default-address"));
            thread = new Thread(findConnectingAddress);
            thread.start();
            leaderElection = highAvailabilityServices.getJobManagerLeaderElection(HighAvailabilityServices.DEFAULT_JOB_ID);
            TestingContender correctLeaderAddressContender = new TestingContender(correctAddress, leaderElection);
            Thread.sleep(sleepingTime);
            externalProcessDriver.notLeader();
            externalProcessDriver.close();
            correctLeaderAddressContender.startLeaderElection();
            thread.join();
            InetAddress result = findConnectingAddress.getInetAddress();
            // check that we can connect to the localHost
            try (Socket socket = new Socket()) {
                // port 0 = let the OS choose the port
                SocketAddress bindP = new InetSocketAddress(result, 0);
                // machine
                socket.bind(bindP);
                socket.connect(correctInetSocketAddress, 1000);
            }
        } finally {
            if (leaderElection != null) {
                leaderElection.close();
            }
            listener.failIfErrorEventHappened();
        }
    } catch (IOException e) {
        // may happen in certain test setups, skip test.
        System.err.println("Skipping 'testNetworkInterfaceSelection' test.");
    }
}

