    config.setProperty(MetricOptions.REPORTER_INTERVAL.key(), "1 UNICORN");
    final ManuallyTriggeredScheduledExecutorService manuallyTriggeredScheduledExecutorService = new ManuallyTriggeredScheduledExecutorService();
