void testConfigurableDelimiterForReportersInGroup() throws Exception {
    String name = "C";
    MetricConfig config1 = new MetricConfig();
    config1.setProperty(MetricOptions.REPORTER_SCOPE_DELIMITER.key(), "_");
    MetricConfig config2 = new MetricConfig();
    config2.setProperty(MetricOptions.REPORTER_SCOPE_DELIMITER.key(), "-");
    MetricConfig config3 = new MetricConfig();
    config3.setProperty(MetricOptions.REPORTER_SCOPE_DELIMITER.key(), "AA");
    Configuration config = new Configuration();
    config.set(MetricOptions.SCOPE_NAMING_TM, "A.B");
    List<ReporterSetup> reporterConfigurations = Arrays.asList(ReporterSetupBuilder.METRIC_SETUP_BUILDER.forReporter("test1", config1, new CollectingMetricsReporter()), ReporterSetupBuilder.METRIC_SETUP_BUILDER.forReporter("test2", config2, new CollectingMetricsReporter()), ReporterSetupBuilder.METRIC_SETUP_BUILDER.forReporter("test3", config3, new CollectingMetricsReporter()), ReporterSetupBuilder.METRIC_SETUP_BUILDER.forReporter("test4", new CollectingMetricsReporter()));
    MetricRegistryImpl registry = new MetricRegistryImpl(MetricRegistryTestUtils.fromConfiguration(config), reporterConfigurations);
    TaskManagerMetricGroup group = TaskManagerMetricGroup.createTaskManagerMetricGroup(registry, "host", new ResourceID("id"));
    group.counter(name);
    group.close();
    registry.closeAsync().get();
    for (ReporterSetup cfg : reporterConfigurations) {
