@Test
void testObtainAnyMetrics() throws InterruptedException {
    SystemResourcesCounter systemResources = new SystemResourcesCounter(Duration.ofMillis(10));
    double initialCpuIdle = systemResources.getCpuIdle();
    systemResources.start();
    // wait for stats to update/calculate
    try {
        double cpuIdle;
        do {
            Thread.sleep(1);
            cpuIdle = systemResources.getCpuIdle();
        } while (systemResources.isAlive() && (initialCpuIdle == cpuIdle || Double.isNaN(cpuIdle) || cpuIdle == 0.0));
    } finally {
        systemResources.shutdown();
        systemResources.join();
    }
    double totalCpuUsage = systemResources.getCpuIrq() + systemResources.getCpuNice() + systemResources.getCpuSoftIrq() + systemResources.getCpuSys() + systemResources.getCpuUser() + systemResources.getIOWait() + systemResources.getCpuSteal();
    assertThat(systemResources.getProcessorsCount()).withFailMessage("There should be at least one processor").isGreaterThan(0);
    assertThat(systemResources.getNetworkInterfaceNames().length).withFailMessage("There should be at least one network interface").isGreaterThan(0);
    assertThat(totalCpuUsage + systemResources.getCpuIdle()).isCloseTo(100.0, within(EPSILON));
}

