@Test
void testFailingJobMultipleTimesNotCauseCascadingJobFailure() throws Exception {
    Function<OperatorCoordinator.Context, OperatorCoordinator> coordinatorProvider = context -> new TestingOperatorCoordinator(context) {

        @Override
        public void handleEventFromOperator(int subtask, int attemptNumber, OperatorEvent event) {
            context.failJob(new RuntimeException("Artificial Exception"));
        }
    };
    final EventReceivingTasks tasks = EventReceivingTasks.createForRunningTasks();
    final OperatorCoordinatorHolder holder = createCoordinatorHolder(tasks, coordinatorProvider);
    holder.handleEventFromOperator(0, 0, new TestOperatorEvent());
    assertThat(globalFailure).isNotNull();
    final Throwable firstGlobalFailure = globalFailure;
    holder.handleEventFromOperator(1, 0, new TestOperatorEvent());
    assertThat(firstGlobalFailure).as("The global failure should be the same instance because the context" + "should only take the first request from the coordinator to fail the job.").isEqualTo(globalFailure);
    holder.resetToCheckpoint(0L, new byte[0]);
    holder.handleEventFromOperator(1, 1, new TestOperatorEvent());
    assertThat(firstGlobalFailure).as("The new failures should be propagated after the coordinator " + "is reset.").isNotEqualTo(globalFailure);
    // Reset global failure to null to make the after method check happy.
    globalFailure = null;
}

