@Test
void testCancelDataSinkTask() throws Exception {
    super.initEnvironment(MEMORY_MANAGER_SIZE, NETWORK_BUFFER_SIZE);
    super.addInput(new InfiniteInputIterator(), 0);
    final DataSinkTask<Record> testTask = new DataSinkTask<>(this.mockEnv);
    Configuration stubParams = new Configuration();
    File tempTestFile = new File(tempFolder.toFile(), UUID.randomUUID().toString());
    super.registerFileOutputTask(MockOutputFormat.class, tempTestFile.toURI().toString(), stubParams);
    Thread taskRunner = new Thread() {

        @Override
        public void run() {
            try {
                testTask.invoke();
            } catch (Exception ie) {
                ie.printStackTrace();
                fail("Task threw exception although it was properly canceled");
            }
        }
    };
    taskRunner.start();
    // wait until the task created the file
    long deadline = System.currentTimeMillis() + 60000;
    while (!tempTestFile.exists() && System.currentTimeMillis() < deadline) {
        Thread.sleep(10);
    }
    assertThat(tempTestFile).withFailMessage("Task did not create file within 60 seconds").exists();
    // cancel the task
    Thread.sleep(500);
    testTask.cancel();
    taskRunner.interrupt();
    // wait for the canceling to complete
    taskRunner.join();
    // assert that temp file was created
    assertThat(tempTestFile).withFailMessage("Task did not create file within 60 seconds").doesNotExist();
}

