@Test
void testNoStatefulConstructor() throws Exception {
    for (Class<?> clazz : STATELESS_TASKS) {
        // check that there is a constructor for Environment only
        clazz.getConstructor(Environment.class);
        // check that there is NO constructor for Environment and Task State
        assertThatThrownBy(() -> clazz.getDeclaredConstructor(Environment.class, TaskStateSnapshot.class)).isInstanceOf(NoSuchMethodException.class);
    }
}

@Test
void testSerialBlockResettableIterator() throws Exception {
    try {
        // create the resettable Iterator
        final BlockResettableMutableObjectIterator<Record> iterator = new BlockResettableMutableObjectIterator<Record>(this.memman, this.reader, this.serializer, 1, memOwner);
        // open the iterator
        iterator.open();
        // now test walking through the iterator
        int lower = 0;
        int upper = 0;
        do {
            lower = upper;
            upper = lower;
            // find the upper bound
            Record target = new Record();
            while ((target = iterator.next(target)) != null) {
                int val = target.getField(0, IntValue.class).getValue();
                assertThat(val).isEqualTo(upper++);
            }
            // now reset the buffer a few times
            for (int i = 0; i < 5; ++i) {
                iterator.reset();
                target = new Record();
                int count = 0;
                while ((target = iterator.next(target)) != null) {
                    int val = target.getField(0, IntValue.class).getValue();
                    assertThat(val).isEqualTo(lower + (count++));
                }
                assertThat(count).isEqualTo(upper - lower);
            }
        } while (iterator.nextBlock());
        assertThat(upper).isEqualTo(NUM_VALUES);
        // close the iterator
        iterator.close();
    } catch (Exception ex) {
        fail("Test encountered an exception: " + ex.getMessage());
    }
}

