@Test
void testCombine() throws Exception {
    int noKeys = 100;
    int noKeyCnt = 10000;
    TestData.MockTuple2Reader<Tuple2<Integer, Integer>> reader = TestData.getIntIntTupleReader();
    LOG.debug("initializing sortmerger");
    TestCountCombiner comb = new TestCountCombiner();
    Sorter<Tuple2<Integer, Integer>> merger = ExternalSorter.newBuilder(this.memoryManager, this.parentTask, this.serializerFactory2.getSerializer(), this.comparator2).maxNumFileHandles(64).withCombiner(comb).enableSpilling(this.ioManager, 0.7f).memoryFraction(0.25).objectReuse(false).largeRecords(true).build(reader);
