@Test
void testBloomFilterSerDe() {
    bloomFilter.reset();
    int val1 = "val1".hashCode();
    int val2 = "val2".hashCode();
    int val3 = "val3".hashCode();
    int val4 = "val4".hashCode();
    int val5 = "val5".hashCode();
