        final Collector<Tuple2<Integer, String>> collector = new DiscardingOutputCollector<>();
        long start = System.nanoTime();
        final Sorter<Tuple2<Integer, String>> sorter1 = ExternalSorter.newBuilder(this.memoryManager, this.parentTask, this.serializer1.getSerializer(), this.comparator1.duplicate()).maxNumFileHandles(128).enableSpilling(ioManager, 0.8f).memoryFraction((double) MEMORY_FOR_SORTER / MEMORY_SIZE).objectReuse(true).largeRecords(true).build(input1);
        final Sorter<Tuple2<Integer, String>> sorter2 = ExternalSorter.newBuilder(this.memoryManager, this.parentTask, this.serializer2.getSerializer(), this.comparator2.duplicate()).maxNumFileHandles(128).enableSpilling(ioManager, 0.8f).memoryFraction((double) MEMORY_FOR_SORTER / MEMORY_SIZE).objectReuse(true).largeRecords(true).build(input2);
        final MutableObjectIterator<Tuple2<Integer, String>> sortedInput1 = sorter1.getIterator();
        final MutableObjectIterator<Tuple2<Integer, String>> sortedInput2 = sorter2.getIterator();
        // compare with iterator values
        ReusingMergeInnerJoinIterator<Tuple2<Integer, String>, Tuple2<Integer, String>, Tuple2<Integer, String>> iterator = new ReusingMergeInnerJoinIterator<>(sortedInput1, sortedInput2, this.serializer1.getSerializer(), this.comparator1, this.serializer2.getSerializer(), this.comparator2, this.pairComparator11, this.memoryManager, this.ioManager, MEMORY_PAGES_FOR_MERGE, this.parentTask);
