/**
 * Simple test registering/unregistering state and looking it up again.
 */
@Test
void testRegisterAndLookup() throws Exception {
    JobID jobId = new JobID();
    JobVertexID jobVertexId = new JobVertexID();
    int numKeyGroups = 123;
    int numRanges = 10;
    int fract = numKeyGroups / numRanges;
    int remain = numKeyGroups % numRanges;
    List<KeyGroupRange> keyGroupRanges = new ArrayList<>(numRanges);
    int start = 0;
    for (int i = 0; i < numRanges; ++i) {
        int end = start + fract - 1;
        if (remain > 0) {
            --remain;
            ++end;
        }
        KeyGroupRange range = new KeyGroupRange(start, end);
        keyGroupRanges.add(range);
        start = end + 1;
    }
    String registrationName = "asdasdasdasd";
    KvStateLocation location = new KvStateLocation(jobId, jobVertexId, numKeyGroups, registrationName);
    KvStateID[] kvStateIds = new KvStateID[numRanges];
    InetSocketAddress[] serverAddresses = new InetSocketAddress[numRanges];
    InetAddress host = InetAddress.getLocalHost();
    // Register
    int registeredCount = 0;
    for (int rangeIdx = 0; rangeIdx < numRanges; rangeIdx++) {
        kvStateIds[rangeIdx] = new KvStateID();
        serverAddresses[rangeIdx] = new InetSocketAddress(host, 1024 + rangeIdx);
        KeyGroupRange keyGroupRange = keyGroupRanges.get(rangeIdx);
        location.registerKvState(keyGroupRange, kvStateIds[rangeIdx], serverAddresses[rangeIdx]);
        registeredCount += keyGroupRange.getNumberOfKeyGroups();
        assertThat(location.getNumRegisteredKeyGroups()).isEqualTo(registeredCount);
    }
    // Lookup
    for (int rangeIdx = 0; rangeIdx < numRanges; rangeIdx++) {
        KeyGroupRange keyGroupRange = keyGroupRanges.get(rangeIdx);
        for (int keyGroup = keyGroupRange.getStartKeyGroup(); keyGroup <= keyGroupRange.getEndKeyGroup(); ++keyGroup) {
            assertThat(location.getKvStateID(keyGroup)).isEqualTo(kvStateIds[rangeIdx]);
            assertThat(location.getKvStateServerAddress(keyGroup)).isEqualTo(serverAddresses[rangeIdx]);
        }
    }
    // Overwrite
    for (int rangeIdx = 0; rangeIdx < numRanges; rangeIdx++) {
        kvStateIds[rangeIdx] = new KvStateID();
        serverAddresses[rangeIdx] = new InetSocketAddress(host, 1024 + rangeIdx);
        location.registerKvState(keyGroupRanges.get(rangeIdx), kvStateIds[rangeIdx], serverAddresses[rangeIdx]);
        assertThat(location.getNumRegisteredKeyGroups()).isEqualTo(registeredCount);
    }
    // Lookup
    for (int rangeIdx = 0; rangeIdx < numRanges; rangeIdx++) {
        KeyGroupRange keyGroupRange = keyGroupRanges.get(rangeIdx);
        for (int keyGroup = keyGroupRange.getStartKeyGroup(); keyGroup <= keyGroupRange.getEndKeyGroup(); ++keyGroup) {
            assertThat(location.getKvStateID(keyGroup)).isEqualTo(kvStateIds[rangeIdx]);
            assertThat(location.getKvStateServerAddress(keyGroup)).isEqualTo(serverAddresses[rangeIdx]);
        }
    }
    // Unregister
    for (int rangeIdx = 0; rangeIdx < numRanges; rangeIdx++) {
        KeyGroupRange keyGroupRange = keyGroupRanges.get(rangeIdx);
        location.unregisterKvState(keyGroupRange);
        registeredCount -= keyGroupRange.getNumberOfKeyGroups();
        assertThat(location.getNumRegisteredKeyGroups()).isEqualTo(registeredCount);
    }
    // Lookup
    for (int rangeIdx = 0; rangeIdx < numRanges; rangeIdx++) {
        KeyGroupRange keyGroupRange = keyGroupRanges.get(rangeIdx);
        for (int keyGroup = keyGroupRange.getStartKeyGroup(); keyGroup <= keyGroupRange.getEndKeyGroup(); ++keyGroup) {
            assertThat(location.getKvStateID(keyGroup)).isNull();
            assertThat(location.getKvStateServerAddress(keyGroup)).isNull();
        }
    }
    assertThat(location.getNumRegisteredKeyGroups()).isZero();
}

@Test
void testKvStateEntry() throws InterruptedException {
    final int threads = 10;
    final CountDownLatch latch1 = new CountDownLatch(threads);
    final CountDownLatch latch2 = new CountDownLatch(1);
    final List<KvStateInfo<?, ?, ?>> infos = Collections.synchronizedList(new ArrayList<>());
    final JobID jobID = new JobID();
    final JobVertexID jobVertexId = new JobVertexID();
    final KeyGroupRange keyGroupRange = new KeyGroupRange(0, 1);
    final String registrationName = "foobar";
    final KvStateRegistry kvStateRegistry = new KvStateRegistry();
    final KvStateID stateID = kvStateRegistry.registerKvState(jobID, jobVertexId, keyGroupRange, registrationName, new DummyKvState(), getClass().getClassLoader());
    final AtomicReference<Throwable> exceptionHolder = new AtomicReference<>();
    for (int i = 0; i < threads; i++) {
        new Thread(() -> {
            final KvStateEntry<?, ?, ?> kvState = kvStateRegistry.getKvState(stateID);
            final KvStateInfo<?, ?, ?> stateInfo = kvState.getInfoForCurrentThread();
            infos.add(stateInfo);
            latch1.countDown();
            try {
                latch2.await();
            } catch (InterruptedException e) {
                // compare and set, so that we do not overwrite an exception
                // that was (potentially) already encountered.
                exceptionHolder.compareAndSet(null, e);
            }
        }).start();
    }
    latch1.await();
    final KvStateEntry<?, ?, ?> kvState = kvStateRegistry.getKvState(stateID);
    // verify that all the threads are done correctly.
    assertThat(infos).hasSize(threads);
    assertThat(kvState.getCacheSize()).isEqualTo(threads);
    latch2.countDown();
    for (KvStateInfo<?, ?, ?> infoA : infos) {
        boolean instanceAlreadyFound = false;
        for (KvStateInfo<?, ?, ?> infoB : infos) {
            if (infoA == infoB) {
                if (instanceAlreadyFound) {
                    fail("More than one thread sharing the same serializer instance.");
                }
                instanceAlreadyFound = true;
            } else {
                assertThat(infoA).isEqualTo(infoB);
            }
        }
    }
    kvStateRegistry.unregisterKvState(jobID, jobVertexId, keyGroupRange, registrationName, stateID);
    assertThat(kvState.getCacheSize()).isZero();
    Throwable t = exceptionHolder.get();
    assertThat(t).isNull();
}

