/**
 * Test release workers if more than resources declared.
 */
@Test
void testMoreThanDeclaredResource() throws Exception {
    new Context() {

        {
            final AtomicInteger requestCount = new AtomicInteger(0);
            final List<CompletableFuture<ResourceID>> resourceIdFutures = Arrays.asList(CompletableFuture.completedFuture(ResourceID.generate()), CompletableFuture.completedFuture(ResourceID.generate()), CompletableFuture.completedFuture(ResourceID.generate()), new CompletableFuture<>());
            final AtomicInteger releaseCount = new AtomicInteger(0);
            final List<CompletableFuture<ResourceID>> releaseResourceFutures = Arrays.asList(new CompletableFuture<>(), new CompletableFuture<>(), new CompletableFuture<>());
            driverBuilder.setRequestResourceFunction(taskExecutorProcessSpec -> resourceIdFutures.get(requestCount.getAndIncrement())).setReleaseResourceConsumer(resourceID -> releaseResourceFutures.get(releaseCount.getAndIncrement()).complete(resourceID));
            runTest(() -> {
                runInMainThread(() -> {
                    for (int i = 0; i < 4; i++) {
                        getResourceManager().requestNewWorker(WORKER_RESOURCE_SPEC);
                    }
                });
                ResourceID unWantedResource = resourceIdFutures.get(0).get();
                ResourceID normalResource = resourceIdFutures.get(1).get();
                ResourceID startingResource = resourceIdFutures.get(2).get();
                CompletableFuture<ResourceID> pendingRequestFuture = resourceIdFutures.get(3);
                registerTaskExecutorAndSendSlotReport(unWantedResource, 1).get(TIMEOUT_SEC, TimeUnit.SECONDS);
                registerTaskExecutorAndSendSlotReport(normalResource, 1).get(TIMEOUT_SEC, TimeUnit.SECONDS);
                assertThat(requestCount).hasValue(4);
                assertThat(releaseCount).hasValue(0);
                Set<InstanceID> unWantedWorkers = Collections.singleton(getResourceManager().getInstanceIdByResourceId(unWantedResource).get());
                // release unwanted workers.
                runInMainThread(() -> getResourceManager().declareResourceNeeded(Collections.singleton(new ResourceDeclaration(WORKER_RESOURCE_SPEC, 3, unWantedWorkers)))).get(TIMEOUT_SEC, TimeUnit.SECONDS);
                assertThat(releaseCount).hasValue(1);
                assertThat(releaseResourceFutures.get(0)).isCompletedWithValue(unWantedResource);
                // release pending workers.
                runInMainThread(() -> getResourceManager().declareResourceNeeded(Collections.singleton(new ResourceDeclaration(WORKER_RESOURCE_SPEC, 2, Collections.emptySet())))).get(TIMEOUT_SEC, TimeUnit.SECONDS);
                assertThat(releaseCount).hasValue(1);
                assertThat(pendingRequestFuture).isCancelled();
                // release starting workers.
                runInMainThread(() -> getResourceManager().declareResourceNeeded(Collections.singleton(new ResourceDeclaration(WORKER_RESOURCE_SPEC, 1, Collections.emptySet())))).get(TIMEOUT_SEC, TimeUnit.SECONDS);
                assertThat(releaseCount).hasValue(2);
                assertThat(releaseResourceFutures.get(1)).isCompletedWithValue(startingResource);
                // release last workers.
                runInMainThread(() -> getResourceManager().declareResourceNeeded(Collections.singleton(new ResourceDeclaration(WORKER_RESOURCE_SPEC, 0, Collections.emptySet())))).get(TIMEOUT_SEC, TimeUnit.SECONDS);
                assertThat(releaseCount).hasValue(3);
                assertThat(releaseResourceFutures.get(2)).isCompletedWithValue(normalResource);
            });
        }
    };
}

