@Test
void testRedundantResourceShouldBeFulfilled() {
    final TaskManagerInfo taskManagerInUse = new TestingTaskManagerInfo(DEFAULT_SLOT_RESOURCE.multiply(5), DEFAULT_SLOT_RESOURCE.multiply(2), DEFAULT_SLOT_RESOURCE);
    final TestingTaskManagerInfo taskManagerIdle = new TestingTaskManagerInfo(DEFAULT_SLOT_RESOURCE.multiply(5), DEFAULT_SLOT_RESOURCE.multiply(5), DEFAULT_SLOT_RESOURCE);
    taskManagerIdle.setIdleSince(System.currentTimeMillis() - 10);
    final PendingTaskManager pendingTaskManagerIdle = new PendingTaskManager(DEFAULT_SLOT_RESOURCE.multiply(5), NUM_OF_SLOTS);
    final TaskManagerResourceInfoProvider taskManagerResourceInfoProvider = TestingTaskManagerResourceInfoProvider.newBuilder().setRegisteredTaskManagersSupplier(() -> Arrays.asList(taskManagerInUse, taskManagerIdle)).setPendingTaskManagersSupplier(() -> Collections.singletonList(pendingTaskManagerIdle)).build();
    DefaultResourceAllocationStrategy strategy = createStrategy(4);
    ResourceReconcileResult result = strategy.tryReconcileClusterResources(taskManagerResourceInfoProvider);
    // pending task manager should reserved for redundant
    assertThat(result.getPendingTaskManagersToRelease()).isEmpty();
    // both in use and idle task manager should be reserved for redundant
    assertThat(result.getTaskManagersToRelease()).isEmpty();
    // add two more pending task manager for redundant since total available resource equals
    // 12(2+5+5)
    assertThat(result.getPendingTaskManagersToAllocate()).hasSize(2);
}

@Test
void testRedundantResourceShouldBeReserved() {
    final TaskManagerInfo taskManagerInUse = new TestingTaskManagerInfo(DEFAULT_SLOT_RESOURCE.multiply(5), DEFAULT_SLOT_RESOURCE.multiply(2), DEFAULT_SLOT_RESOURCE);
    final TestingTaskManagerInfo taskManagerIdle = new TestingTaskManagerInfo(DEFAULT_SLOT_RESOURCE.multiply(5), DEFAULT_SLOT_RESOURCE.multiply(5), DEFAULT_SLOT_RESOURCE);
    taskManagerIdle.setIdleSince(System.currentTimeMillis() - 10);
    final PendingTaskManager pendingTaskManagerIdle = new PendingTaskManager(DEFAULT_SLOT_RESOURCE.multiply(5), NUM_OF_SLOTS);
    final TaskManagerResourceInfoProvider taskManagerResourceInfoProvider = TestingTaskManagerResourceInfoProvider.newBuilder().setRegisteredTaskManagersSupplier(() -> Arrays.asList(taskManagerInUse, taskManagerIdle)).setPendingTaskManagersSupplier(() -> Collections.singletonList(pendingTaskManagerIdle)).build();
