/**
 * Tests that un-registration of task managers will cause resource missing again in
 * ResourceTracker.
 */
@Test
void testTaskManagerUnregisterAfterResourceRequirements() throws Exception {
    final TaskExecutorGateway taskExecutorGateway = new TestingTaskExecutorGatewayBuilder().setRequestSlotFunction(tuple6 -> new CompletableFuture<>()).createTestingTaskExecutorGateway();
    final ResourceID resourceId = ResourceID.generate();
    final TaskExecutorConnection taskManagerConnection = new TaskExecutorConnection(resourceId, taskExecutorGateway);
    final SlotReport slotReport = new SlotReport(new SlotStatus(new SlotID(resourceId, 0), DEFAULT_SLOT_RESOURCE_PROFILE));
    new Context() {

        {
            slotManagerConfigurationBuilder.setRequirementCheckDelay(Duration.ZERO);
            runTest(() -> {
                final CompletableFuture<SlotManager.RegistrationResult> registerTaskManagerFuture = new CompletableFuture<>();
                final CompletableFuture<Boolean> unRegisterTaskManagerFuture = new CompletableFuture<>();
                runInMainThread(() -> registerTaskManagerFuture.complete(getSlotManager().registerTaskManager(taskManagerConnection, slotReport, DEFAULT_TOTAL_RESOURCE_PROFILE, DEFAULT_SLOT_RESOURCE_PROFILE)));
                assertThat(assertFutureCompleteAndReturn(registerTaskManagerFuture)).isEqualTo(SlotManager.RegistrationResult.SUCCESS);
                assertThat(getTaskManagerTracker().getRegisteredTaskManagers()).hasSize(1);
                assertThat(getTaskManagerTracker().getNumberFreeSlots()).isEqualTo(2);
                ResourceRequirements resourceRequirements = createResourceRequirementsForSingleSlot();
                runInMainThreadAndWait(() -> getSlotManager().processResourceRequirements(resourceRequirements));
                assertThat(getTaskManagerTracker().getFreeResource()).isEqualTo(DEFAULT_SLOT_RESOURCE_PROFILE);
                assertThat(getResourceTracker().getMissingResources()).isEmpty();
                runInMainThread(() -> unRegisterTaskManagerFuture.complete(getSlotManager().unregisterTaskManager(taskManagerConnection.getInstanceID(), TEST_EXCEPTION)));
                assertThat(assertFutureCompleteAndReturn(unRegisterTaskManagerFuture)).isTrue();
                assertThat(getTaskManagerTracker().getRegisteredTaskManagers()).isEmpty();
                assertThat(getResourceTracker().getMissingResources()).containsKey(resourceRequirements.getJobId());
            });
        }
    };
