/**
 * Tests that formerly used task managers can timeout after all of their slots have been freed.
 */
@Test
void testTimeoutForUnusedTaskManager() throws Exception {
    final Duration taskManagerTimeout = Duration.ofMillis(50L);
    final CompletableFuture<InstanceID> releaseResourceFuture = new CompletableFuture<>();
    final AllocationID allocationId = new AllocationID();
    final TaskExecutorConnection taskExecutionConnection = createTaskExecutorConnection();
    final InstanceID instanceId = taskExecutionConnection.getInstanceID();
    new Context() {

        {
            resourceAllocatorBuilder.setDeclareResourceNeededConsumer((resourceDeclarations) -> {
                assertThat(resourceDeclarations).hasSize(1);
                ResourceDeclaration resourceDeclaration = resourceDeclarations.iterator().next();
                assertThat(resourceDeclaration.getNumNeeded()).isEqualTo(0);
                assertThat(resourceDeclaration.getUnwantedWorkers()).hasSize(1);
                releaseResourceFuture.complete(resourceDeclaration.getUnwantedWorkers().iterator().next());
            });
            slotManagerConfigurationBuilder.setTaskManagerTimeout(taskManagerTimeout);
            runTest(() -> {
                final CompletableFuture<SlotManager.RegistrationResult> registerTaskManagerFuture = new CompletableFuture<>();
                runInMainThread(() -> registerTaskManagerFuture.complete(getSlotManager().registerTaskManager(taskExecutionConnection, new SlotReport(createAllocatedSlotStatus(new JobID(), allocationId, DEFAULT_SLOT_RESOURCE_PROFILE)), DEFAULT_TOTAL_RESOURCE_PROFILE, DEFAULT_SLOT_RESOURCE_PROFILE)));
                assertThat(assertFutureCompleteAndReturn(registerTaskManagerFuture)).isEqualTo(SlotManager.RegistrationResult.SUCCESS);
                assertThat(getSlotManager().getTaskManagerIdleSince(instanceId)).isEqualTo(Long.MAX_VALUE);
                final CompletableFuture<Long> idleSinceFuture = new CompletableFuture<>();
                runInMainThread(() -> {
                    getSlotManager().freeSlot(new SlotID(taskExecutionConnection.getResourceID(), 0), allocationId);
                    idleSinceFuture.complete(getSlotManager().getTaskManagerIdleSince(instanceId));
                });
                assertThat(assertFutureCompleteAndReturn(idleSinceFuture)).isNotEqualTo(Long.MAX_VALUE);
                assertThat(assertFutureCompleteAndReturn(releaseResourceFuture)).isEqualTo(instanceId);
                // A task manager timeout does not remove the slots from the
                // SlotManager. The receiver of the callback can then decide what to do
                // with the TaskManager.
                assertThat(getSlotManager().getNumberRegisteredSlots()).isEqualTo(DEFAULT_NUM_SLOTS_PER_WORKER);
                final CompletableFuture<Boolean> unregisterTaskManagerFuture = new CompletableFuture<>();
                runInMainThread(() -> unregisterTaskManagerFuture.complete(getSlotManager().unregisterTaskManager(taskExecutionConnection.getInstanceID(), TEST_EXCEPTION)));
                assertThat(assertFutureCompleteAndReturn(unregisterTaskManagerFuture)).isTrue();
                assertThat(getSlotManager().getNumberRegisteredSlots()).isEqualTo(0);
            });
        }
    };
}

