                if (getTaskManagerTracker().getPendingTaskManagers().isEmpty()) {
                    pendingTaskManager = new PendingTaskManager(DEFAULT_TOTAL_RESOURCE_PROFILE, DEFAULT_NUM_SLOTS_PER_WORKER);
                } else {
                    pendingTaskManager = getTaskManagerTracker().getPendingTaskManagers().iterator().next();
                }
                builder.addPendingTaskManagerAllocate(pendingTaskManager);
                builder.addAllocationOnPendingResource(jobID, pendingTaskManager.getPendingTaskManagerId(), DEFAULT_SLOT_RESOURCE_PROFILE);
                return builder.build();
            });
            slotManagerConfigurationBuilder.setRequirementCheckDelay(Duration.ZERO);
            runTest(() -> {
                final CompletableFuture<SlotManager.RegistrationResult> registerTaskManagerFuture1 = new CompletableFuture<>();
                final CompletableFuture<SlotManager.RegistrationResult> registerTaskManagerFuture2 = new CompletableFuture<>();
                final CompletableFuture<SlotManager.RegistrationResult> registerTaskManagerFuture3 = new CompletableFuture<>();
                runInMainThread(() -> {
                    getSlotManager().processResourceRequirements(createResourceRequirementsForSingleSlot());
                    // task manager with allocated slot cannot deduct pending
                    // task manager
                    registerTaskManagerFuture1.complete(getSlotManager().registerTaskManager(taskExecutionConnection1, slotReportWithAllocatedSlot, DEFAULT_TOTAL_RESOURCE_PROFILE, DEFAULT_SLOT_RESOURCE_PROFILE));
                });
                assertThat(assertFutureCompleteAndReturn(registerTaskManagerFuture1)).isEqualTo(SlotManager.RegistrationResult.SUCCESS);
                assertThat(getTaskManagerTracker().getPendingTaskManagers()).hasSize(1);
                // task manager with mismatched resource cannot deduct
                // pending task manager
                runInMainThread(() -> registerTaskManagerFuture2.complete(getSlotManager().registerTaskManager(taskExecutionConnection2, new SlotReport(), LARGE_TOTAL_RESOURCE_PROFILE, LARGE_SLOT_RESOURCE_PROFILE)));
                assertThat(assertFutureCompleteAndReturn(registerTaskManagerFuture2)).isEqualTo(SlotManager.RegistrationResult.SUCCESS);
                assertThat(getTaskManagerTracker().getPendingTaskManagers()).hasSize(1);
                runInMainThread(() -> registerTaskManagerFuture3.complete(getSlotManager().registerTaskManager(taskExecutionConnection3, new SlotReport(), DEFAULT_TOTAL_RESOURCE_PROFILE, DEFAULT_SLOT_RESOURCE_PROFILE)));
                assertThat(assertFutureCompleteAndReturn(registerTaskManagerFuture3)).isEqualTo(SlotManager.RegistrationResult.SUCCESS);
                assertThat(getTaskManagerTracker().getPendingTaskManagers()).isEmpty();
            });
        }
    };
}

