    // Notify free slot is now allocated
    taskManagerTracker.notifySlotStatus(allocationId2, jobId, TASK_EXECUTOR_CONNECTION.getInstanceID(), ResourceProfile.fromResources(2, 300), SlotState.ALLOCATED);
    assertThat(taskManagerTracker.getAllocatedOrPendingSlot(allocationId2)).isPresent();
    assertThat(taskManagerTracker.getRegisteredTaskManager(TASK_EXECUTOR_CONNECTION.getInstanceID())).hasValueSatisfying(taskManagerInfo -> assertThat(taskManagerInfo.getAvailableResource()).isEqualTo(ResourceProfile.fromResources(5, 500)));
}

@Test
void testFreeSlot() {
    final FineGrainedTaskManagerTracker taskManagerTracker = new FineGrainedTaskManagerTracker();
    final ResourceProfile totalResource = ResourceProfile.fromResources(10, 1000);
    final AllocationID allocationId1 = new AllocationID();
    final AllocationID allocationId2 = new AllocationID();
