    // Free allocated slot
    taskManagerTracker.notifySlotStatus(allocationId2, jobId, TASK_EXECUTOR_CONNECTION.getInstanceID(), ResourceProfile.fromResources(2, 300), SlotState.FREE);
    assertThat(taskManagerTracker.getAllocatedOrPendingSlot(allocationId2)).isNotPresent();
    assertThat(taskManagerTracker.getRegisteredTaskManager(TASK_EXECUTOR_CONNECTION.getInstanceID())).hasValueSatisfying(taskManagerInfo -> assertThat(taskManagerInfo.getAvailableResource()).isEqualTo(totalResource));
}

