@Test
void testRequirementsNotificationWithResources() {
    JobScopedResourceTracker tracker = new JobScopedResourceTracker(JobID.generate());
    ResourceRequirement[][] resourceRequirements = new ResourceRequirement[][] { new ResourceRequirement[] { ResourceRequirement.create(PROFILE_1, 4), ResourceRequirement.create(PROFILE_2, 2) }, new ResourceRequirement[] { ResourceRequirement.create(PROFILE_1, 8), ResourceRequirement.create(PROFILE_2, 2) }, new ResourceRequirement[] { ResourceRequirement.create(PROFILE_1, 4), ResourceRequirement.create(PROFILE_2, 2) } };
    int numAcquiredSlotsP1 = resourceRequirements[0][0].getNumberOfRequiredSlots() - 1;
    int numAcquiredSlotsP2 = resourceRequirements[0][1].getNumberOfRequiredSlots();
    for (int x = 0; x < numAcquiredSlotsP1; x++) {
        tracker.notifyAcquiredResource(PROFILE_1);
    }
    for (int x = 0; x < numAcquiredSlotsP2; x++) {
        tracker.notifyAcquiredResource(PROFILE_2);
    }
    for (ResourceRequirement[] resourceRequirement : resourceRequirements) {
        tracker.notifyResourceRequirements(Arrays.asList(resourceRequirement));
        assertThat(tracker.getAcquiredResources()).containsExactlyInAnyOrder(ResourceRequirement.create(PROFILE_1, numAcquiredSlotsP1), ResourceRequirement.create(PROFILE_2, numAcquiredSlotsP2));
        assertThat(tracker.getMissingResources()).containsExactlyInAnyOrder(ResourceRequirement.create(PROFILE_1, resourceRequirement[0].getNumberOfRequiredSlots() - numAcquiredSlotsP1));
    }
    tracker.notifyResourceRequirements(Collections.emptyList());
    assertThat(tracker.getAcquiredResources()).containsExactlyInAnyOrder(ResourceRequirement.create(PROFILE_1, numAcquiredSlotsP1), ResourceRequirement.create(PROFILE_2, numAcquiredSlotsP2));
    assertThat(tracker.getMissingResources()).isEmpty();
    ;
}

