    final TaskExecutorResourceSpec taskExecutorResourceSpec = new TaskExecutorResourceSpec(new CPUResource(1.0), MemorySize.parse("1m"), MemorySize.parse("2m"), MemorySize.parse("3m"), MemorySize.parse("4m"), Collections.singleton(new ExternalResource(EXTERNAL_RESOURCE_NAME, numSlots)));
    final ResourceProfile resourceProfileFromTaskExecutorResourceUtils = TaskExecutorResourceUtils.generateDefaultSlotResourceProfile(taskExecutorResourceSpec, numSlots);
    final ResourceProfile totalResourceProfile = TaskExecutorResourceUtils.generateTotalAvailableResourceProfile(taskExecutorResourceSpec);
    final WorkerResourceSpec workerResourceSpec = WorkerResourceSpec.fromTotalResourceProfile(totalResourceProfile, numSlots);
    assertThat(SlotManagerUtils.generateDefaultSlotResourceProfile(totalResourceProfile, numSlots)).isEqualTo(resourceProfileFromTaskExecutorResourceUtils);
    assertThat(SlotManagerUtils.generateDefaultSlotResourceProfile(workerResourceSpec, numSlots)).isEqualTo(resourceProfileFromTaskExecutorResourceUtils);
}

@Test
void testCalculateDefaultNumSlots() {
    final ResourceProfile defaultSlotResource = ResourceProfile.newBuilder().setCpuCores(1.0).setTaskHeapMemoryMB(1).setTaskOffHeapMemoryMB(2).setNetworkMemoryMB(3).setManagedMemoryMB(4).build();
    final ResourceProfile totalResource1 = defaultSlotResource.multiply(5);
    final ResourceProfile totalResource2 = totalResource1.merge(ResourceProfile.newBuilder().setCpuCores(0.1).build());
    assertThat(SlotManagerUtils.calculateDefaultNumSlots(totalResource1, defaultSlotResource)).isEqualTo(5);
    assertThat(SlotManagerUtils.calculateDefaultNumSlots(totalResource2, defaultSlotResource)).isEqualTo(5);
    // For ResourceProfile.ANY in test case, return the maximum integer
    assertThat(SlotManagerUtils.calculateDefaultNumSlots(ResourceProfile.ANY, defaultSlotResource)).isEqualTo(Integer.MAX_VALUE);
}

