void testRetrieveSnapshotFromCache() throws Exception {
    GatewayRetriever<RestfulGateway> leaderRetriever = () -> CompletableFuture.completedFuture(null);
    CheckpointingStatistics checkpointingStatistics = getTestCheckpointingStatistics();
    CheckpointStatsSnapshot checkpointStatsSnapshot1 = getTestCheckpointStatsSnapshot();
    // Create a passthrough cache so the latest object will always be returned
    Cache<JobID, CompletableFuture<CheckpointStatsSnapshot>> cache = CacheBuilder.newBuilder().build();
    try (RecordingCheckpointStatsHandler checkpointStatsHandler = new RecordingCheckpointStatsHandler(leaderRetriever, TIMEOUT, Collections.emptyMap(), CheckpointingStatisticsHeaders.getInstance(), cache, Executors.directExecutor(), checkpointingStatistics)) {
        RestfulGateway functioningRestfulGateway = new TestingRestfulGateway.Builder().setRequestCheckpointStatsSnapshotFunction(jobID -> CompletableFuture.completedFuture(checkpointStatsSnapshot1)).build();
        HandlerRequest<EmptyRequestBody> request = HandlerRequest.resolveParametersAndCreate(EmptyRequestBody.getInstance(), new JobMessageParameters(), Collections.singletonMap(JobIDPathParameter.KEY, JOB_ID.toString()), Collections.emptyMap(), Collections.emptyList());
        assertThat(checkpointStatsHandler.handleRequest(request, functioningRestfulGateway).get()).usingRecursiveComparison().isEqualTo(checkpointingStatistics);
        assertThat(checkpointStatsHandler.getStoredCheckpointStats()).isEqualTo(checkpointStatsSnapshot1);
        // Refresh the checkpoint stats data
        CheckpointStatsSnapshot checkpointStatsSnapshot2 = getTestCheckpointStatsSnapshot();
        RestfulGateway refreshedRestfulGateway = new TestingRestfulGateway.Builder().setRequestCheckpointStatsSnapshotFunction(jobID -> CompletableFuture.completedFuture(checkpointStatsSnapshot2)).build();
        assertThat(checkpointStatsHandler.handleRequest(request, refreshedRestfulGateway).get()).usingRecursiveComparison().isEqualTo(checkpointingStatistics);
        assertThat(checkpointStatsHandler.getStoredCheckpointStats()).isEqualTo(checkpointStatsSnapshot2);
    }
}

