@Test
void testGetBackPressureFromMultipleCurrentAttempts() throws Exception {
    MetricStore multipleAttemptsMetricStore = new MetricStore();
    for (MetricDump metricDump : getMultipleAttemptsMetricDumps()) {
        multipleAttemptsMetricStore.add(metricDump);
    }
    // Update representativeAttempts directly without JobDetails.
    Map<Integer, Integer> representativeAttempts = new HashMap<>();
    representativeAttempts.put(0, 1);
    representativeAttempts.put(1, 0);
    multipleAttemptsMetricStore.getRepresentativeAttempts().put(TEST_JOB_ID_BACK_PRESSURE_STATS_AVAILABLE.toString(), Collections.singletonMap(TEST_JOB_VERTEX_ID.toString(), representativeAttempts));
    JobVertexBackPressureHandler jobVertexBackPressureHandler = new JobVertexBackPressureHandler(() -> CompletableFuture.completedFuture(restfulGateway), Duration.ofSeconds(10), Collections.emptyMap(), JobVertexBackPressureHeaders.getInstance(), new MetricFetcher() {

        private long updateCount = 0;

        @Override
        public MetricStore getMetricStore() {
            return multipleAttemptsMetricStore;
        }

        @Override
        public void update() {
            updateCount++;
        }

        @Override
        public long getLastUpdateTime() {
            return updateCount;
        }
    });
    final Map<String, String> pathParameters = new HashMap<>();
    pathParameters.put(JobIDPathParameter.KEY, TEST_JOB_ID_BACK_PRESSURE_STATS_AVAILABLE.toString());
    pathParameters.put(JobVertexIdPathParameter.KEY, TEST_JOB_VERTEX_ID.toString());
    final HandlerRequest<EmptyRequestBody> request = HandlerRequest.resolveParametersAndCreate(EmptyRequestBody.getInstance(), new JobVertexMessageParameters(), pathParameters, Collections.emptyMap(), Collections.emptyList());
    final CompletableFuture<JobVertexBackPressureInfo> jobVertexBackPressureInfoCompletableFuture = jobVertexBackPressureHandler.handleRequest(request, restfulGateway);
    final JobVertexBackPressureInfo jobVertexBackPressureInfo = jobVertexBackPressureInfoCompletableFuture.get();
    assertThat(jobVertexBackPressureInfo.getStatus()).isEqualTo(VertexBackPressureStatus.OK);
    assertThat(jobVertexBackPressureInfo.getBackpressureLevel()).isEqualTo(LOW);
    assertThat(jobVertexBackPressureInfo.getSubtasks().stream().map(SubtaskBackPressureInfo::getAttemptNumber).collect(Collectors.toList())).containsExactly(1, 0, null);
    assertThat(jobVertexBackPressureInfo.getSubtasks().stream().map(SubtaskBackPressureInfo::getOtherConcurrentAttempts).filter(Objects::nonNull).flatMap(Collection::stream).map(SubtaskBackPressureInfo::getAttemptNumber).collect(Collectors.toList())).containsExactly(0, 1);
    assertThat(jobVertexBackPressureInfo.getSubtasks().stream().map(SubtaskBackPressureInfo::getBackPressuredRatio).collect(Collectors.toList())).containsExactly(0.2, 0.5, 0.1);
    assertThat(jobVertexBackPressureInfo.getSubtasks().stream().map(SubtaskBackPressureInfo::getOtherConcurrentAttempts).filter(Objects::nonNull).flatMap(Collection::stream).map(SubtaskBackPressureInfo::getBackPressuredRatio).collect(Collectors.toList())).containsExactly(1.0, 0.9);
    assertThat(jobVertexBackPressureInfo.getSubtasks().stream().map(SubtaskBackPressureInfo::getIdleRatio).collect(Collectors.toList())).containsExactly(0.1, 0.1, 0.2);
    assertThat(jobVertexBackPressureInfo.getSubtasks().stream().map(SubtaskBackPressureInfo::getOtherConcurrentAttempts).filter(Objects::nonNull).flatMap(Collection::stream).map(SubtaskBackPressureInfo::getIdleRatio).collect(Collectors.toList())).containsExactly(0.0, 0.0);
    assertThat(jobVertexBackPressureInfo.getSubtasks().stream().map(SubtaskBackPressureInfo::getBusyRatio).collect(Collectors.toList())).containsExactly(0.8, 0.9, 0.7);
    assertThat(jobVertexBackPressureInfo.getSubtasks().stream().map(SubtaskBackPressureInfo::getOtherConcurrentAttempts).filter(Objects::nonNull).flatMap(Collection::stream).map(SubtaskBackPressureInfo::getBusyRatio).collect(Collectors.toList())).containsExactly(0.0, 0.1);
    assertThat(jobVertexBackPressureInfo.getSubtasks().stream().map(SubtaskBackPressureInfo::getBackpressureLevel).collect(Collectors.toList())).containsExactly(LOW, LOW, OK);
    assertThat(jobVertexBackPressureInfo.getSubtasks().stream().map(SubtaskBackPressureInfo::getOtherConcurrentAttempts).filter(Objects::nonNull).flatMap(Collection::stream).map(SubtaskBackPressureInfo::getBackpressureLevel).collect(Collectors.toList())).containsExactly(HIGH, HIGH);
    assertThat(jobVertexBackPressureInfo.getSubtasks().stream().map(SubtaskBackPressureInfo::getSubtask).collect(Collectors.toList())).containsExactly(0, 1, 3);
    assertThat(jobVertexBackPressureInfo.getSubtasks().stream().map(SubtaskBackPressureInfo::getOtherConcurrentAttempts).filter(Objects::nonNull).flatMap(Collection::stream).map(SubtaskBackPressureInfo::getSubtask).collect(Collectors.toList())).containsExactly(0, 1);
}

/**
 * Some subtasks are finished, some subtasks are running.
 */
@Test
void testHandleMixedSubtasks() throws Exception {
    final ArchivedExecutionJobVertex archivedExecutionJobVertex = new ArchivedExecutionJobVertex(new ArchivedExecutionVertex[] { generateExecutionVertex(0, ExecutionState.FINISHED), generateExecutionVertex(1, ExecutionState.RUNNING) }, JOB_VERTEX_ID, "test", 2, 2, new SlotSharingGroup(), ResourceProfile.UNKNOWN, new StringifiedAccumulatorResult[0]);
    // Check the finished subtask
    HandlerRequest<EmptyRequestBody> request = generateJobVertexFlameGraphParameters(0);
    VertexFlameGraph jobVertexFlameGraph = handler.handleRequest(request, archivedExecutionJobVertex);
    assertThat(jobVertexFlameGraph.getEndTime()).isEqualTo(VertexFlameGraph.terminated().getEndTime());
    // Check the running subtask
    request = generateJobVertexFlameGraphParameters(1);
    jobVertexFlameGraph = handler.handleRequest(request, archivedExecutionJobVertex);
    assertThat(jobVertexFlameGraph.getEndTime()).isEqualTo(taskThreadInfoStatsDefaultSample.getEndTime());
    // Check the job vertex
    request = generateJobVertexFlameGraphParameters(null);
    jobVertexFlameGraph = handler.handleRequest(request, archivedExecutionJobVertex);
    assertThat(jobVertexFlameGraph.getEndTime()).isEqualTo(taskThreadInfoStatsDefaultSample.getEndTime());
}

