/**
 * Tests that cache entries are cleaned up when their TTL has expired upon calling {@link
 * DefaultExecutionGraphCache#cleanup()}.
 */
@Test
void testCacheEntryCleanup() throws Exception {
    final Duration timeout = Duration.ofMillis(100L);
    final Duration timeToLive = Duration.ofMillis(1L);
    final JobID expectedJobId2 = new JobID();
    final ExecutionGraphInfo expectedExecutionGraphInfo2 = new ExecutionGraphInfo(new ArchivedExecutionGraphBuilder().build());
    final AtomicInteger requestJobCalls = new AtomicInteger(0);
    final TestingRestfulGateway restfulGateway = new TestingRestfulGateway.Builder().setRequestExecutionGraphInfoFunction(jobId -> {
        requestJobCalls.incrementAndGet();
        if (jobId.equals(expectedJobId)) {
            return CompletableFuture.completedFuture(expectedExecutionGraphInfo);
        } else if (jobId.equals(expectedJobId2)) {
            return CompletableFuture.completedFuture(expectedExecutionGraphInfo2);
        } else {
            throw new AssertionError("Invalid job id received.");
        }
    }).build();
    try (ExecutionGraphCache executionGraphCache = new DefaultExecutionGraphCache(timeout, timeToLive)) {
        CompletableFuture<ExecutionGraphInfo> executionGraph1Future = executionGraphCache.getExecutionGraphInfo(expectedJobId, restfulGateway);
        CompletableFuture<ExecutionGraphInfo> executionGraph2Future = executionGraphCache.getExecutionGraphInfo(expectedJobId2, restfulGateway);
        assertThatFuture(executionGraph1Future).eventuallySucceeds().isEqualTo(expectedExecutionGraphInfo);
        assertThatFuture(executionGraph2Future).eventuallySucceeds().isEqualTo(expectedExecutionGraphInfo2);
        assertThat(requestJobCalls.get()).isEqualTo(2);
        Thread.sleep(timeToLive.toMillis());
        executionGraphCache.cleanup();
        assertThat(executionGraphCache.size()).isZero();
    }
}

/**
 * Tests that concurrent accesses only trigger a single AccessExecutionGraph request.
 */
@Test
void testConcurrentAccess() throws Exception {
    final Duration timeout = Duration.ofMillis(100L);
    final Duration timeToLive = Duration.ofHours(1L);
    final CountingRestfulGateway restfulGateway = createCountingRestfulGateway(expectedJobId, CompletableFuture.completedFuture(expectedExecutionGraphInfo));
    final int numConcurrentAccesses = 10;
    final ArrayList<CompletableFuture<ExecutionGraphInfo>> executionGraphFutures = new ArrayList<>(numConcurrentAccesses);
    final ExecutorService executor = java.util.concurrent.Executors.newFixedThreadPool(numConcurrentAccesses);
    try (ExecutionGraphCache executionGraphCache = new DefaultExecutionGraphCache(timeout, timeToLive)) {
        for (int i = 0; i < numConcurrentAccesses; i++) {
            CompletableFuture<ExecutionGraphInfo> executionGraphFuture = CompletableFuture.supplyAsync(() -> executionGraphCache.getExecutionGraphInfo(expectedJobId, restfulGateway), executor).thenCompose(Function.identity());
            executionGraphFutures.add(executionGraphFuture);
        }
        final CompletableFuture<Collection<ExecutionGraphInfo>> allExecutionGraphFutures = FutureUtils.combineAll(executionGraphFutures);
        Collection<ExecutionGraphInfo> allExecutionGraphs = allExecutionGraphFutures.get();
        for (ExecutionGraphInfo executionGraph : allExecutionGraphs) {
            assertThat(executionGraph).isEqualTo(expectedExecutionGraphInfo);
        }
        assertThat(restfulGateway.getNumRequestJobCalls()).isOne();
    } finally {
        ExecutorUtils.gracefulShutdown(5000L, TimeUnit.MILLISECONDS, executor);
    }
}

