@Test
void testRestAPICheckpointType() {
    // Test for aligned checkpoint
    assertThat(RestAPICheckpointType.valueOf(CheckpointType.CHECKPOINT, false)).isEqualTo(RestAPICheckpointType.CHECKPOINT);
    assertThat(RestAPICheckpointType.valueOf(CheckpointType.FULL_CHECKPOINT, false)).isEqualTo(RestAPICheckpointType.CHECKPOINT);
    // Test for unaligned checkpoint
    assertThat(RestAPICheckpointType.valueOf(CheckpointType.CHECKPOINT, true)).isEqualTo(RestAPICheckpointType.UNALIGNED_CHECKPOINT);
    assertThat(RestAPICheckpointType.valueOf(CheckpointType.FULL_CHECKPOINT, true)).isEqualTo(RestAPICheckpointType.UNALIGNED_CHECKPOINT);
    // Test for savepoint
    assertThat(RestAPICheckpointType.valueOf(SavepointType.savepoint(SavepointFormatType.NATIVE), false)).isEqualTo(RestAPICheckpointType.SAVEPOINT);
    assertThat(RestAPICheckpointType.valueOf(SavepointType.suspend(SavepointFormatType.NATIVE), false)).isEqualTo(RestAPICheckpointType.SYNC_SAVEPOINT);
    assertThat(RestAPICheckpointType.valueOf(SavepointType.terminate(SavepointFormatType.NATIVE), false)).isEqualTo(RestAPICheckpointType.SYNC_SAVEPOINT);
    assertThatThrownBy(() -> RestAPICheckpointType.valueOf(SavepointType.terminate(SavepointFormatType.NATIVE), true)).isInstanceOf(IllegalArgumentException.class);
}

