    assertThat(deserializedSerializedThrowable.getCause()).isInstanceOf(SerializedThrowable.class);
    assertThat(deserializedSerializedThrowable.getSuppressed().length).isOne();
    assertThat(deserializedSerializedThrowable.getSuppressed()[0].getMessage()).isEqualTo("java.lang.Exception: suppressed");
    assertThat(deserializedSerializedThrowable.getSuppressed()[0]).isInstanceOf(SerializedThrowable.class);
}

