/**
 * Tests that messages with the wrong fencing token are filtered out.
 */
@Test
void testFencing() throws Exception {
    final UUID fencingToken = UUID.randomUUID();
    final UUID wrongFencingToken = UUID.randomUUID();
    final String value = "barfoo";
    FencedTestingEndpoint fencedTestingEndpoint = new FencedTestingEndpoint(rpcService, value, fencingToken);
    try {
        fencedTestingEndpoint.start();
        final FencedTestingGateway properFencedGateway = rpcService.connect(fencedTestingEndpoint.getAddress(), fencingToken, FencedTestingGateway.class).get(timeout.toMillis(), TimeUnit.MILLISECONDS);
        final FencedTestingGateway wronglyFencedGateway = rpcService.connect(fencedTestingEndpoint.getAddress(), wrongFencingToken, FencedTestingGateway.class).get(timeout.toMillis(), TimeUnit.MILLISECONDS);
        assertThat(properFencedGateway.foobar(timeout).get(timeout.toMillis(), TimeUnit.MILLISECONDS)).isEqualTo(value);
        try {
            wronglyFencedGateway.foobar(timeout).get(timeout.toMillis(), TimeUnit.MILLISECONDS);
            fail("This should fail since we have the wrong fencing token.");
        } catch (ExecutionException e) {
            assertThat(ExceptionUtils.stripExecutionException(e)).isInstanceOf(FencingTokenException.class);
        }
    } finally {
        RpcUtils.terminateRpcEndpoint(fencedTestingEndpoint);
        fencedTestingEndpoint.validateResourceClosed();
    }
}

