@Test
void testResourceTimeout() throws Exception {
    final ManuallyTriggeredComponentMainThreadExecutor mainThreadExecutor = new ManuallyTriggeredComponentMainThreadExecutor(Thread.currentThread());
    final Duration resourceTimeout = Duration.ofMinutes(1234);
    final Configuration configuration = new Configuration();
    configuration.set(JobManagerOptions.SCHEDULER_SUBMISSION_RESOURCE_WAIT_TIMEOUT, resourceTimeout);
    final AdaptiveScheduler scheduler = new AdaptiveSchedulerBuilder(createJobGraph(), mainThreadExecutor, EXECUTOR_RESOURCE.getExecutor()).setJobMasterConfiguration(configuration).build();
    scheduler.startScheduling();
    // check whether some task was scheduled with the expected timeout
    // this is technically not really safe, but the chosen timeout value
    // is odd enough that it realistically won't cause issues.
    // With this approach we don't have to make assumption as to how many
    // tasks are being scheduled.
    final boolean b = mainThreadExecutor.getActiveNonPeriodicScheduledTask().stream().anyMatch(scheduledTask -> scheduledTask.getDelay(TimeUnit.MINUTES) == resourceTimeout.toMinutes());
    assertThat(b).isTrue();
}

@Test
void testNumRescalesAndStartsMetricForRescale() throws Exception {
    final CompletableFuture<Gauge<Long>> numRescalesMetricFuture = new CompletableFuture<>();
    final CompletableFuture<Gauge<Long>> numRestartsMetricFuture = new CompletableFuture<>();
    final MetricRegistry metricRegistry = TestingMetricRegistry.builder().setRegisterConsumer((metric, name, group) -> {
        if (MetricNames.NUM_RESCALES.equals(name)) {
            numRescalesMetricFuture.complete((Gauge<Long>) metric);
        } else if (MetricNames.NUM_RESTARTS.equals(name)) {
            numRestartsMetricFuture.complete((Gauge<Long>) metric);
        }
    }).build();
    final JobGraph jobGraph = createJobGraph();
    final DefaultDeclarativeSlotPool declarativeSlotPool = new DefaultDeclarativeSlotPool(jobGraph.getJobID(), new DefaultAllocatedSlotPool(), ignored -> {
    }, Duration.ofMinutes(10), Duration.ofMinutes(10), Duration.ZERO, mainThreadExecutor);
    scheduler = new AdaptiveSchedulerBuilder(jobGraph, singleThreadMainThreadExecutor, EXECUTOR_RESOURCE.getExecutor()).setJobMasterConfiguration(createConfigurationWithNoTimeouts()).setJobManagerJobMetricGroup(JobManagerMetricGroup.createJobManagerMetricGroup(metricRegistry, "localhost").addJob(new JobID(), "jobName")).setDeclarativeSlotPool(declarativeSlotPool).build();
    final Gauge<Long> numRescalesMetric = numRescalesMetricFuture.get();
    final Gauge<Long> numRestartsMetric = numRestartsMetricFuture.get();
    final SubmissionBufferingTaskManagerGateway taskManagerGateway = new SubmissionBufferingTaskManagerGateway(1 + PARALLELISM);
    taskManagerGateway.setCancelConsumer(createCancelConsumer(scheduler));
    startTestInstanceInMainThread();
    runInMainThread(() -> declarativeSlotPool.offerSlots(createSlotOffersForResourceRequirements(ResourceCounter.withResource(ResourceProfile.UNKNOWN, 1)), new LocalTaskManagerLocation(), taskManagerGateway, System.currentTimeMillis()));
    // wait for the first task submission
    taskManagerGateway.waitForSubmissions(1);
    assertThat(numRescalesMetric.getValue()).isEqualTo(0L);
    assertThat(numRestartsMetric.getValue()).isEqualTo(0L);
    // offer more slots, which will cause a restart in order to scale up
    runInMainThread(() -> offerSlots(declarativeSlotPool, createSlotOffersForResourceRequirements(ResourceCounter.withResource(ResourceProfile.UNKNOWN, PARALLELISM)), taskManagerGateway));
    // wait for the second task submissions
    taskManagerGateway.waitForSubmissions(PARALLELISM);
    assertThat(numRescalesMetric.getValue()).isEqualTo(1L);
    assertThat(numRestartsMetric.getValue()).isEqualTo(1L);
}

