@Test
void testJobStatusListenerNotifiedOfJobStatusChanges() throws Exception {
    final JobGraph jobGraph = createJobGraph();
    final DefaultDeclarativeSlotPool declarativeSlotPool = createDeclarativeSlotPool(jobGraph.getJobID(), singleThreadMainThreadExecutor);
    final Configuration configuration = new Configuration();
    configuration.set(JobManagerOptions.SCHEDULER_SUBMISSION_RESOURCE_WAIT_TIMEOUT, Duration.ofMillis(1L));
    final CompletableFuture<Void> jobCreatedNotification = new CompletableFuture<>();
    final CompletableFuture<Void> jobRunningNotification = new CompletableFuture<>();
    final CompletableFuture<Void> jobFinishedNotification = new CompletableFuture<>();
    final CompletableFuture<JobStatus> unexpectedJobStatusNotification = new CompletableFuture<>();
    scheduler = new AdaptiveSchedulerBuilder(jobGraph, singleThreadMainThreadExecutor, EXECUTOR_RESOURCE.getExecutor()).setJobMasterConfiguration(configuration).setJobStatusListener((jobId, newJobStatus, timestamp) -> {
        switch(newJobStatus) {
            case CREATED:
                jobCreatedNotification.complete(null);
                break;
            case RUNNING:
                jobRunningNotification.complete(null);
                break;
            case FINISHED:
                jobFinishedNotification.complete(null);
                break;
            default:
                unexpectedJobStatusNotification.complete(newJobStatus);
        }
    }).setDeclarativeSlotPool(declarativeSlotPool).build();
    final SubmissionBufferingTaskManagerGateway taskManagerGateway = new SubmissionBufferingTaskManagerGateway(1 + PARALLELISM);
    runInMainThread(() -> {
        scheduler.startScheduling();
        offerSlots(declarativeSlotPool, createSlotOffersForResourceRequirements(ResourceCounter.withResource(ResourceProfile.UNKNOWN, 1)), taskManagerGateway);
    });
    // wait for the task submission
    final TaskDeploymentDescriptor submittedTask = taskManagerGateway.submittedTasks.take();
    // let the job finish
    runInMainThread(() -> scheduler.updateTaskExecutionState(new TaskExecutionState(submittedTask.getExecutionAttemptId(), ExecutionState.FINISHED)));
    jobCreatedNotification.get();
    jobRunningNotification.get();
    jobFinishedNotification.get();
    assertThat(unexpectedJobStatusNotification.isDone()).isFalse();
}

@Test
void testCloseShutsDownCheckpointingComponents() throws Exception {
    final CompletableFuture<JobStatus> completedCheckpointStoreShutdownFuture = new CompletableFuture<>();
    final CompletedCheckpointStore completedCheckpointStore = TestingCompletedCheckpointStore.createStoreWithShutdownCheckAndNoCompletedCheckpoints(completedCheckpointStoreShutdownFuture);
    final CompletableFuture<JobStatus> checkpointIdCounterShutdownFuture = new CompletableFuture<>();
    final CheckpointIDCounter checkpointIdCounter = TestingCheckpointIDCounter.createStoreWithShutdownCheckAndNoStartAction(checkpointIdCounterShutdownFuture);
    final JobGraph jobGraph = createJobGraph();
    // checkpointing components are only created if checkpointing is enabled
    jobGraph.setSnapshotSettings(new JobCheckpointingSettings(CheckpointCoordinatorConfiguration.builder().build(), null));
    scheduler = new AdaptiveSchedulerBuilder(jobGraph, singleThreadMainThreadExecutor, EXECUTOR_RESOURCE.getExecutor()).setCheckpointRecoveryFactory(new TestingCheckpointRecoveryFactory(completedCheckpointStore, checkpointIdCounter)).build();
    startTestInstanceInMainThread();
    final CompletableFuture<Void> closeFuture = new CompletableFuture<>();
    runInMainThread(() -> {
        // transition into the FAILED state
        scheduler.handleGlobalFailure(new FlinkException("Test exception"));
        // we shouldn't block the closeAsync call here because it will trigger
        // additional task on the main thread internally
        FutureUtils.forward(scheduler.closeAsync(), closeFuture);
    });
    closeFuture.join();
    assertThat(completedCheckpointStoreShutdownFuture.get()).isEqualTo(JobStatus.FAILED);
    assertThat(checkpointIdCounterShutdownFuture.get()).isEqualTo(JobStatus.FAILED);
}

