@Test
void testIdleSlotsAreReleasedAfterDownScalingTriggeredByLoweredResourceRequirements() throws Exception {
    final JobGraph jobGraph = createJobGraph();
    final Duration slotIdleTimeout = Duration.ofMillis(10);
    final Configuration configuration = createConfigurationWithNoTimeouts();
    configuration.set(JobManagerOptions.SLOT_IDLE_TIMEOUT, slotIdleTimeout);
    final DeclarativeSlotPool declarativeSlotPool = createDeclarativeSlotPool(jobGraph.getJobID(), singleThreadMainThreadExecutor, slotIdleTimeout);
    scheduler = new AdaptiveSchedulerBuilder(jobGraph, singleThreadMainThreadExecutor, EXECUTOR_RESOURCE.getExecutor()).setDeclarativeSlotPool(declarativeSlotPool).setJobMasterConfiguration(configuration).build();
    final int numInitialSlots = 4;
    final int numSlotsAfterDownscaling = 2;
    final SubmissionBufferingTaskManagerGateway taskManagerGateway = new SubmissionBufferingTaskManagerGateway(numInitialSlots);
    taskManagerGateway.setCancelConsumer(createCancelConsumer(scheduler));
    singleThreadMainThreadExecutor.execute(() -> {
        scheduler.startScheduling();
        offerSlots(declarativeSlotPool, createSlotOffersForResourceRequirements(ResourceCounter.withResource(ResourceProfile.UNKNOWN, numInitialSlots)), taskManagerGateway);
    });
    // wait for all tasks to be submitted
    taskManagerGateway.waitForSubmissions(numInitialSlots);
    // lower the resource requirements
    singleThreadMainThreadExecutor.execute(() -> scheduler.updateJobResourceRequirements(JobResourceRequirements.newBuilder().setParallelismForJobVertex(JOB_VERTEX.getID(), 1, numSlotsAfterDownscaling).build()));
    // job should be resubmitted with lower parallelism
    taskManagerGateway.waitForSubmissions(numSlotsAfterDownscaling);
    // and excessive slots should be freed
    taskManagerGateway.waitForFreedSlots(numInitialSlots - numSlotsAfterDownscaling);
    final CompletableFuture<JobStatus> jobStatusFuture = new CompletableFuture<>();
    singleThreadMainThreadExecutor.execute(() -> jobStatusFuture.complete(scheduler.getState().getJobStatus()));
    assertThatFuture(jobStatusFuture).eventuallySucceeds().isEqualTo(JobStatus.RUNNING);
    // make sure we haven't freed up any more slots
    assertThat(taskManagerGateway.freedSlots).isEmpty();
}

