@Test
void testGoToWaitingForResourcesConfiguresStateTransitionManagerFactory() throws Exception {
    final OneShotLatch latch = new OneShotLatch();
    final TestingStateTransitionManagerFactory factory = new TestingStateTransitionManagerFactory(ctx -> TestingStateTransitionManager.withOnChangeEventOnly(() -> {
        if (ctx instanceof WaitingForResources) {
            latch.trigger();
        }
    }));
    final Configuration configuration = new Configuration();
    final Duration resourceStabilizationTimeout = Duration.ofMillis(10L);
    configuration.set(JobManagerOptions.SCHEDULER_SUBMISSION_RESOURCE_STABILIZATION_TIMEOUT, resourceStabilizationTimeout);
    scheduler = new AdaptiveSchedulerBuilder(createJobGraph(), singleThreadMainThreadExecutor, EXECUTOR_RESOURCE.getExecutor()).setStateTransitionManagerFactory(factory).setJobMasterConfiguration(configuration).build();
    // start scheduling to reach Executing state
    singleThreadMainThreadExecutor.execute(scheduler::startScheduling);
    // let's wait for the onChange event in Executing state.
    latch.await();
    assertThat(scheduler.getState()).isInstanceOf(WaitingForResources.class);
    assertThat(factory.cooldownTimeout).isEqualTo(Duration.ZERO);
    assertThat(factory.maximumDelayForTrigger).isEqualTo(Duration.ZERO);
    assertThat(factory.resourceStabilizationTimeout).isEqualTo(resourceStabilizationTimeout);
}

@Test
void testGoToExecutingConfiguresStateTransitionManagerFactory() throws Exception {
    final OneShotLatch latch = new OneShotLatch();
    final TestingStateTransitionManagerFactory factory = new TestingStateTransitionManagerFactory(ctx -> TestingStateTransitionManager.withOnChangeEventOnly(() -> {
        if (ctx instanceof WaitingForResources) {
            ctx.transitionToSubsequentState();
        }
        if (ctx instanceof Executing) {
            latch.trigger();
        }
    }));
    final Configuration configuration = new Configuration();
    final Duration executingCooldownTimeout = Duration.ofMillis(1L);
    final Duration executingResourceStabilizationTimeout = Duration.ofMillis(5L);
    final Duration maxDelayForTrigger = Duration.ofMillis(10L);
    configuration.set(JobManagerOptions.SCHEDULER_EXECUTING_COOLDOWN_AFTER_RESCALING, executingCooldownTimeout);
    configuration.set(JobManagerOptions.SCHEDULER_RESCALE_TRIGGER_MAX_DELAY, maxDelayForTrigger);
    configuration.set(JobManagerOptions.SCHEDULER_EXECUTING_RESOURCE_STABILIZATION_TIMEOUT, executingResourceStabilizationTimeout);
    scheduler = new AdaptiveSchedulerBuilder(createJobGraph(), singleThreadMainThreadExecutor, EXECUTOR_RESOURCE.getExecutor()).setJobMasterConfiguration(configuration).setDeclarativeSlotPool(getSlotPoolWithFreeSlots(PARALLELISM)).setStateTransitionManagerFactory(factory).build();
    // start scheduling to reach Executing state
    singleThreadMainThreadExecutor.execute(scheduler::startScheduling);
    // let's wait for the onChange event in Executing state.
    latch.await();
    assertThat(scheduler.getState()).isInstanceOf(Executing.class);
    assertThat(factory.cooldownTimeout).isEqualTo(executingCooldownTimeout);
    assertThat(factory.maximumDelayForTrigger).isEqualTo(maxDelayForTrigger);
    assertThat(factory.resourceStabilizationTimeout).isEqualTo(executingResourceStabilizationTimeout);
}

