@Test
void testReserveAvailableResources() {
    final SlotSharingSlotAllocator slotAllocator = SlotSharingSlotAllocator.createSlotSharingSlotAllocator(TEST_RESERVE_SLOT_FUNCTION, TEST_FREE_SLOT_FUNCTION, TEST_IS_SLOT_FREE_FUNCTION, DISABLE_LOCAL_RECOVERY);
    final JobInformation jobInformation = new TestJobInformation(Arrays.asList(vertex1, vertex2, vertex3));
    final JobSchedulingPlan jobSchedulingPlan = slotAllocator.determineParallelismAndCalculateAssignment(jobInformation, getSlots(50), JobAllocationsInformation.empty()).get();
    final ReservedSlots reservedSlots = slotAllocator.tryReserveResources(jobSchedulingPlan).orElseThrow(() -> new RuntimeException("Expected that reservation succeeds."));
    final Map<ExecutionVertexID, SlotInfo> expectedAssignments = new HashMap<>();
    for (JobSchedulingPlan.SlotAssignment assignment : jobSchedulingPlan.getSlotAssignments()) {
        ExecutionSlotSharingGroup target = assignment.getTargetAs(ExecutionSlotSharingGroup.class);
        for (ExecutionVertexID containedExecutionVertex : target.getContainedExecutionVertices()) {
            expectedAssignments.put(containedExecutionVertex, assignment.getSlotInfo());
        }
    }
    for (Map.Entry<ExecutionVertexID, SlotInfo> expectedAssignment : expectedAssignments.entrySet()) {
        final LogicalSlot assignedSlot = reservedSlots.getSlotFor(expectedAssignment.getKey());
        final SlotInfo backingSlot = expectedAssignment.getValue();
        assertThat(assignedSlot.getAllocationId()).isEqualTo(backingSlot.getAllocationId());
    }
}

