/**
 * Basic test to verify that allocation takes previous allocations into account to facilitate
 * Local Recovery.
 */
@Test
void testStickyAllocation() {
    Map<JobVertexID, List<VertexAllocationInformation>> locality = new HashMap<>();
    // previous allocation allocation1: v1, v2
    AllocationID allocation1 = new AllocationID();
    locality.put(vertex1.getJobVertexID(), Collections.singletonList(new VertexAllocationInformation(allocation1, vertex1.getJobVertexID(), KeyGroupRange.of(1, 100), 1)));
    locality.put(vertex2.getJobVertexID(), Collections.singletonList(new VertexAllocationInformation(allocation1, vertex2.getJobVertexID(), KeyGroupRange.of(1, 100), 1)));
    // previous allocation allocation2: v3
    AllocationID allocation2 = new AllocationID();
    locality.put(vertex3.getJobVertexID(), Collections.singletonList(new VertexAllocationInformation(allocation2, vertex3.getJobVertexID(), KeyGroupRange.of(1, 100), 1)));
    List<SlotInfo> freeSlots = new ArrayList<>();
    IntStream.range(0, 10).forEach(i -> freeSlots.add(new TestingSlot(new AllocationID())));
    freeSlots.add(new TestingSlot(allocation1));
    freeSlots.add(new TestingSlot(allocation2));
    JobSchedulingPlan schedulingPlan = SlotSharingSlotAllocator.createSlotSharingSlotAllocator((allocationId, resourceProfile) -> TestingPhysicalSlot.builder().build(), (allocationID, cause, ts) -> {
    }, id -> false, true).determineParallelismAndCalculateAssignment(new TestJobInformation(Arrays.asList(vertex1, vertex2, vertex3)), freeSlots, new JobAllocationsInformation(locality)).get();
    Map<AllocationID, Set<VertexID>> allocated = new HashMap<>();
    for (JobSchedulingPlan.SlotAssignment assignment : schedulingPlan.getSlotAssignments()) {
        ExecutionSlotSharingGroup target = assignment.getTargetAs(ExecutionSlotSharingGroup.class);
        Set<VertexID> set = allocated.computeIfAbsent(assignment.getSlotInfo().getAllocationId(), ign -> new HashSet<>());
        for (ExecutionVertexID id : target.getContainedExecutionVertices()) {
            set.add(id.getJobVertexId());
        }
    }
    assertThat(allocated.get(allocation1)).contains(vertex1.getJobVertexID());
    assertThat(allocated.get(allocation1)).contains(vertex2.getJobVertexID());
    assertThat(allocated.get(allocation2)).contains(vertex3.getJobVertexID());
}

