public void testTriggerRescaleOnFailedCheckpoint() throws Exception {
    final AtomicInteger rescaleTriggerCount = new AtomicInteger();
    final Function<StateTransitionManager.Context, StateTransitionManager> stateTransitionManagerFactory = context -> TestingStateTransitionManager.withOnTriggerEventOnly(rescaleTriggerCount::incrementAndGet);
    final int rescaleOnFailedCheckpointsCount = 3;
    try (MockExecutingContext ctx = new MockExecutingContext()) {
        final Executing testInstance = new ExecutingStateBuilder().setStateTransitionManagerFactory(stateTransitionManagerFactory).setRescaleOnFailedCheckpointCount(rescaleOnFailedCheckpointsCount).build(ctx);
        // do multiple rescale iterations to verify that subsequent failed checkpoints after a
        // rescale result in the expected behavior
        for (int rescaleIteration = 1; rescaleIteration <= 3; rescaleIteration++) {
            // trigger an initial failed checkpoint event to show that the counting only starts
            // with the subsequent change event
            testInstance.onFailedCheckpoint();
            // trigger change
            testInstance.onNewResourceRequirements();
            for (int i = 0; i < rescaleOnFailedCheckpointsCount; i++) {
                assertThat(rescaleTriggerCount).as("No rescale operation should have been triggered for iteration #%d, yet.", rescaleIteration).hasValue(rescaleIteration - 1);
                testInstance.onFailedCheckpoint();
            }
            assertThat(rescaleTriggerCount).as("The rescale operation for iteration #%d should have been properly triggered.", rescaleIteration).hasValue(rescaleIteration);
        }
    }
}

@Test
public void testOnCompletedCheckpointResetsFailedCheckpointCount() throws Exception {
    final AtomicInteger rescaleTriggeredCount = new AtomicInteger();
    final Function<StateTransitionManager.Context, StateTransitionManager> stateTransitionManagerFactory = context -> TestingStateTransitionManager.withOnTriggerEventOnly(rescaleTriggeredCount::incrementAndGet);
    final int rescaleOnFailedCheckpointsCount = 3;
    try (MockExecutingContext ctx = new MockExecutingContext()) {
        final Executing testInstance = new ExecutingStateBuilder().setStateTransitionManagerFactory(stateTransitionManagerFactory).setRescaleOnFailedCheckpointCount(rescaleOnFailedCheckpointsCount).build(ctx);
        // trigger an initial failed checkpoint event to show that the counting only starts with
        // the subsequent change event
        testInstance.onFailedCheckpoint();
        // trigger change
        testInstance.onNewResourcesAvailable();
        IntStream.range(0, rescaleOnFailedCheckpointsCount - 1).forEach(ignored -> testInstance.onFailedCheckpoint());
        assertThat(rescaleTriggeredCount).as("No rescaling should have been trigger, yet.").hasValue(0);
        testInstance.onCompletedCheckpoint();
        // trigger change
        testInstance.onNewResourceRequirements();
        assertThat(rescaleTriggeredCount).as("The completed checkpoint should have triggered a rescale.").hasValue(1);
        IntStream.range(0, rescaleOnFailedCheckpointsCount - 1).forEach(ignored -> testInstance.onFailedCheckpoint());
        assertThat(rescaleTriggeredCount).as("No additional rescaling should have been trigger by any subsequent failed checkpoint, yet.").hasValue(1);
        testInstance.onFailedCheckpoint();
        assertThat(rescaleTriggeredCount).as("The previous failed checkpoint should have triggered the rescale.").hasValue(2);
    }
}

