@ParameterizedTest
@ValueSource(booleans = { true, false })
public void testInternalParallelismChangeBehavior(boolean parallelismChanged) throws Exception {
    try (MockExecutingContext adaptiveSchedulerCtx = new MockExecutingContext()) {
        final AtomicBoolean onChangeCalled = new AtomicBoolean();
        final Function<StateTransitionManager.Context, StateTransitionManager> stateTransitionManagerFactory = transitionCtx -> TestingStateTransitionManager.withOnChangeEventOnly(() -> {
            assertThat(transitionCtx.hasDesiredResources()).isEqualTo(parallelismChanged);
            assertThat(transitionCtx.hasSufficientResources()).isEqualTo(parallelismChanged);
            onChangeCalled.set(true);
        });
        final MockExecutionJobVertex mockExecutionJobVertex = new MockExecutionJobVertex(MockExecutionVertex::new);
        final ExecutionGraph executionGraph = new MockExecutionGraph(() -> Collections.singletonList(mockExecutionJobVertex));
        adaptiveSchedulerCtx.setHasDesiredResources(() -> true);
        adaptiveSchedulerCtx.setHasSufficientResources(() -> true);
        adaptiveSchedulerCtx.setVertexParallelism(new VertexParallelism(executionGraph.getAllVertices().values().stream().collect(Collectors.toMap(AccessExecutionJobVertex::getJobVertexId, v -> parallelismChanged ? 1 + v.getParallelism() : v.getParallelism()))));
        final Executing exec = new ExecutingStateBuilder().setStateTransitionManagerFactory(stateTransitionManagerFactory).setExecutionGraph(executionGraph).build(adaptiveSchedulerCtx);
        exec.onNewResourcesAvailable();
        assertThat(onChangeCalled.get()).isTrue();
    }
}

