@Test
void testOptimizeStreamGraph() throws DynamicCodeLoadingException {
    StreamGraph streamGraph = createStreamGraph();
    StreamNode source = streamGraph.getStreamNodes().stream().filter(node -> node.getOperatorName().contains("Source")).findFirst().get();
    StreamNode map = streamGraph.getStreamNodes().stream().filter(node -> node.getOperatorName().contains("Map")).findFirst().get();
    assertThat(source.getOutEdges().get(0).getPartitioner()).isInstanceOf(ForwardPartitioner.class);
    assertThat(map.getOutEdges().get(0).getPartitioner()).isInstanceOf(RescalePartitioner.class);
    streamGraph.getJobConfiguration().set(StreamGraphOptimizationStrategy.STREAM_GRAPH_OPTIMIZATION_STRATEGY, Collections.singletonList(TestingStreamGraphOptimizerStrategy.class.getName()));
    TestingStreamGraphOptimizerStrategy.convertToReBalanceEdgeIds.add(source.getOutEdges().get(0).getEdgeId());
    TestingStreamGraphOptimizerStrategy.convertToReBalanceEdgeIds.add(map.getOutEdges().get(0).getEdgeId());
    DefaultAdaptiveExecutionHandler handler = createAdaptiveExecutionHandler((newVertices, pendingOperatorsCount) -> {
    }, streamGraph);
    JobGraph jobGraph = handler.getJobGraph();
    JobVertex sourceVertex = jobGraph.getVertices().iterator().next();
    // notify Source node is finished
    ExecutionJobVertexFinishedEvent event1 = new ExecutionJobVertexFinishedEvent(sourceVertex.getID(), Collections.emptyMap());
    handler.handleJobEvent(event1);
    // verify that the source output edge is not updated because the original edge is forward.
    assertThat(sourceVertex.getProducedDataSets().get(0).getConsumers()).hasSize(1);
    assertThat(sourceVertex.getProducedDataSets().get(0).getConsumers().get(0).getShipStrategyName()).isEqualToIgnoringCase("forward");
    // notify Map node is finished
    Iterator<JobVertex> jobVertexIterator = jobGraph.getVertices().iterator();
