    JobVertex mapVertex = jobVertexIterator.next();
    ExecutionJobVertexFinishedEvent event2 = new ExecutionJobVertexFinishedEvent(mapVertex.getID(), Collections.emptyMap());
    handler.handleJobEvent(event2);
    // verify that the map output edge is updated to reBalance.
    assertThat(mapVertex.getProducedDataSets().get(0).getConsumers()).hasSize(1);
    assertThat(mapVertex.getProducedDataSets().get(0).getConsumers().get(0).getShipStrategyName()).isEqualToIgnoringCase("rebalance");
}

