    // larger than skewed threshold but less than skewed factor
    AggregatedBlockingInputInfo aggregatedBlockingInputInfo4 = AggregatedBlockingInputInfo.createAggregatedBlockingInputInfo(100, 20, 20, inputInfos);
    assertThat(aggregatedBlockingInputInfo4.getTargetSize()).isEqualTo(160);
    List<BlockingInputInfo> inputInfosWithoutIntraCorrelation = createBlockingInputInfos(2, 10, 4, false, true, List.of(1));
    AggregatedBlockingInputInfo aggregatedBlockingInputInfo5 = AggregatedBlockingInputInfo.createAggregatedBlockingInputInfo(40, 4, 20, inputInfosWithoutIntraCorrelation);
    assertThat(aggregatedBlockingInputInfo5.getSubpartitionBytesByPartition()).containsExactlyInAnyOrderEntriesOf(Map.of(0, new long[] { 10, 100, 10 }, 1, new long[] { 10, 100, 10 }, 2, new long[] { 10, 100, 10 }, 3, new long[] { 10, 100, 10 }));
}

