@Test
void testComputeSubpartitionSliceRange() {
    Map<Integer, List<SubpartitionSlice>> subpartitionSlicesByTypeNumber = Map.of(1, createSubpartitionSlices(5, new long[] { 100, 200, 300, 200, 100 }));
    Optional<List<IndexRange>> subpartitionSliceRanges = tryComputeSubpartitionSliceRange(1, 5, 300, subpartitionSlicesByTypeNumber);
    assertThat(subpartitionSliceRanges).isNotEmpty();
    assertThat(subpartitionSliceRanges.get()).isEqualTo(List.of(new IndexRange(0, 1), new IndexRange(2, 2), new IndexRange(3, 4)));
    // test with a big max data volume per task
    subpartitionSliceRanges = tryComputeSubpartitionSliceRange(1, 5, 10000, subpartitionSlicesByTypeNumber);
    assertThat(subpartitionSliceRanges).isNotEmpty();
    assertThat(subpartitionSliceRanges.get()).isEqualTo(List.of(new IndexRange(0, 4)));
    // test with a small max data volume per task
    subpartitionSliceRanges = tryComputeSubpartitionSliceRange(1, 5, 100, subpartitionSlicesByTypeNumber);
    assertThat(subpartitionSliceRanges).isNotEmpty();
    assertThat(subpartitionSliceRanges.get()).isEqualTo(List.of(new IndexRange(0, 0), new IndexRange(1, 1), new IndexRange(2, 2), new IndexRange(3, 3), new IndexRange(4, 4)));
    // test fallback to adjust to the closest parallelism
    subpartitionSliceRanges = tryComputeSubpartitionSliceRange(5, 5, 200, subpartitionSlicesByTypeNumber);
    assertThat(subpartitionSliceRanges).isNotEmpty();
    assertThat(subpartitionSliceRanges.get()).isEqualTo(List.of(new IndexRange(0, 0), new IndexRange(1, 1), new IndexRange(2, 2), new IndexRange(3, 3), new IndexRange(4, 4)));
    // test fallback to evenly distributed subpartition slices
    subpartitionSliceRanges = tryComputeSubpartitionSliceRange(4, 4, 200, subpartitionSlicesByTypeNumber);
    assertThat(subpartitionSliceRanges).isNotEmpty();
    assertThat(subpartitionSliceRanges.get()).isEqualTo(List.of(new IndexRange(0, 0), new IndexRange(1, 1), new IndexRange(2, 2), new IndexRange(3, 4)));
    // test failed to compute slice range
    subpartitionSliceRanges = tryComputeSubpartitionSliceRange(6, 6, 200, subpartitionSlicesByTypeNumber);
    assertThat(subpartitionSliceRanges).isEmpty();
}

