@Test
void pendingSlotRequestsOfVerticesToRestartWillNotBeFulfilledByReturnedSlots() throws Exception {
    final int parallelism = 10;
    final JobGraph jobGraph = sourceSinkJobGraph(parallelism);
    testExecutionSlotAllocator.disableAutoCompletePendingRequests();
    testExecutionSlotAllocator.enableCompletePendingRequestsWithReturnedSlots();
    final DefaultScheduler scheduler = createScheduler(jobGraph, ComponentMainThreadExecutorServiceAdapter.forMainThread(), new PipelinedRegionSchedulingStrategy.Factory(), new RestartAllFailoverStrategy.Factory());
    scheduler.startScheduling();
    final ExecutionVertex ev1 = Iterables.get(scheduler.getExecutionGraph().getAllExecutionVertices(), 0);
    final Set<CompletableFuture<LogicalSlot>> pendingLogicalSlotFutures = testExecutionSlotAllocator.getPendingRequests().values().stream().map(ExecutionSlotAssignment::getLogicalSlotFuture).collect(Collectors.toSet());
    assertThat(pendingLogicalSlotFutures).hasSize(parallelism * 2);
    testExecutionSlotAllocator.completePendingRequest(ev1.getID());
    assertThat(pendingLogicalSlotFutures.stream().filter(CompletableFuture::isDone).count()).isEqualTo(1L);
    final String exceptionMessage = "expected exception";
    scheduler.updateTaskExecutionState(new TaskExecutionState(ev1.getCurrentExecutionAttempt().getAttemptId(), ExecutionState.FAILED, new RuntimeException(exceptionMessage)));
    assertThat(testExecutionSlotAllocator.getPendingRequests()).isEmpty();
    // the failed task will return its slot before triggering failover. And the slot
    // will be returned and re-assigned to another task which is waiting for a slot.
    // failover will be triggered after that and the re-assigned slot will be returned
    // once the attached task is canceled, but the slot will not be assigned to other
    // tasks which are identified to be restarted soon.
    assertThat(testExecutionSlotAllocator.getReturnedSlots()).hasSize(2);
    assertThat(pendingLogicalSlotFutures.stream().filter(CompletableFuture::isCancelled).count()).isEqualTo(parallelism * 2L - 2L);
}

