    taskRestartExecutor.triggerNonPeriodicScheduledTask();
    // initiate job failure
    testRestartBackoffTimeStrategy.setCanRestart(false);
    final ExecutionAttemptID failingAttemptId = Iterables.getOnlyElement(scheduler.requestJob().getArchivedExecutionGraph().getAllExecutionVertices()).getCurrentExecutionAttempt().getAttemptId();
    final RuntimeException failingException = new RuntimeException("failing exception");
    final long updateStateTriggeringJobFailureTimestamp = initiateFailure(scheduler, failingAttemptId, failingException);
    final Iterable<RootExceptionHistoryEntry> actualExceptionHistory = scheduler.getExceptionHistory();
    // assert restarted attempt
    assertThat(actualExceptionHistory).hasSize(2);
    Iterator<RootExceptionHistoryEntry> iterator = actualExceptionHistory.iterator();
    RootExceptionHistoryEntry entry0 = iterator.next();
    assertThat(ExceptionHistoryEntryTestingUtils.matchesFailure(entry0, restartableException, updateStateTriggeringRestartTimestamp, taskFailureExecutionVertex.getTaskNameWithSubtaskIndex(), taskFailureExecutionVertex.getCurrentAssignedResourceLocation())).isTrue();
    RootExceptionHistoryEntry entry1 = iterator.next();
    assertThat(ExceptionHistoryEntryTestingUtils.matchesGlobalFailure(entry1, failingException, updateStateTriggeringJobFailureTimestamp)).isTrue();
}

