    final ExecutionVertex rootCauseExecutionVertex = extractExecutionVertex(0);
    final long rootCauseTimestamp = triggerFailure(rootCauseExecutionVertex, null);
    final FailureHandlingResult failureHandlingResult = FailureHandlingResult.restartable(rootCauseExecutionVertex.getCurrentExecutionAttempt(), null, rootCauseTimestamp, CompletableFuture.completedFuture(Collections.singletonMap("key2", "value2")), StreamSupport.stream(executionGraph.getAllExecutionVertices().spliterator(), false).map(ExecutionVertex::getID).collect(Collectors.toSet()), 0L, false, true);
    // FailedExecution with failure labels
    assertThat(failureHandlingResult.getFailureLabels().get()).isEqualTo(Collections.singletonMap("key2", "value2"));
    final FailureHandlingResultSnapshot testInstance = FailureHandlingResultSnapshot.create(failureHandlingResult, this::getCurrentExecutions);
    final Throwable actualException = new SerializedThrowable(testInstance.getRootCause()).deserializeError(ClassLoader.getSystemClassLoader());
    assertThat(actualException).isInstanceOf(FlinkException.class);
    assertThat(actualException).hasMessageContaining(ErrorInfo.handleMissingThrowable(null).getMessage());
    assertThat(testInstance.getTimestamp()).isEqualTo(rootCauseTimestamp);
    assertThat(testInstance.getRootCauseExecution()).isPresent();
    assertThat(testInstance.getRootCauseExecution().get()).isSameAs(rootCauseExecutionVertex.getCurrentExecutionAttempt());
    assertThat(testInstance.isRootCause()).isTrue();
}

