@Test
void testGetConsumedPartitionGroupsAndProducers() throws Exception {
    final JobVertex producer1 = ExecutionGraphTestUtils.createNoOpVertex(1);
    final JobVertex producer2 = ExecutionGraphTestUtils.createNoOpVertex(1);
    final JobVertex consumer = ExecutionGraphTestUtils.createNoOpVertex(1);
    final IntermediateDataSet dataSet1 = connectNewDataSetAsInput(consumer, producer1, DistributionPattern.ALL_TO_ALL, ResultPartitionType.PIPELINED).getSource();
    final IntermediateDataSet dataSet2 = connectNewDataSetAsInput(consumer, producer2, DistributionPattern.ALL_TO_ALL, ResultPartitionType.PIPELINED).getSource();
    final ExecutionGraph eg = ExecutionGraphTestUtils.createExecutionGraph(EXECUTOR_EXTENSION.getExecutor(), producer1, producer2, consumer);
    final ExecutionGraphToInputsLocationsRetrieverAdapter inputsLocationsRetriever = new ExecutionGraphToInputsLocationsRetrieverAdapter(eg);
    ExecutionVertexID evIdOfProducer1 = new ExecutionVertexID(producer1.getID(), 0);
    ExecutionVertexID evIdOfProducer2 = new ExecutionVertexID(producer2.getID(), 0);
    ExecutionVertexID evIdOfConsumer = new ExecutionVertexID(consumer.getID(), 0);
    Collection<ConsumedPartitionGroup> consumedPartitionGroupsOfProducer1 = inputsLocationsRetriever.getConsumedPartitionGroups(evIdOfProducer1);
    Collection<ConsumedPartitionGroup> consumedPartitionGroupsOfProducer2 = inputsLocationsRetriever.getConsumedPartitionGroups(evIdOfProducer2);
    Collection<ConsumedPartitionGroup> consumedPartitionGroupsOfConsumer = inputsLocationsRetriever.getConsumedPartitionGroups(evIdOfConsumer);
    IntermediateResultPartitionID partitionId1 = new IntermediateResultPartitionID(dataSet1.getId(), 0);
    IntermediateResultPartitionID partitionId2 = new IntermediateResultPartitionID(dataSet2.getId(), 0);
    assertThat(consumedPartitionGroupsOfProducer1).isEmpty();
    assertThat(consumedPartitionGroupsOfProducer2).isEmpty();
    assertThat(consumedPartitionGroupsOfConsumer).hasSize(2);
    assertThat(consumedPartitionGroupsOfConsumer.stream().flatMap(IterableUtils::toStream).collect(Collectors.toSet())).containsExactlyInAnyOrder(partitionId1, partitionId2);
    for (ConsumedPartitionGroup consumedPartitionGroup : consumedPartitionGroupsOfConsumer) {
        if (consumedPartitionGroup.getFirst().equals(partitionId1)) {
            assertThat(inputsLocationsRetriever.getProducersOfConsumedPartitionGroup(consumedPartitionGroup)).containsExactly(evIdOfProducer1);
        } else {
            assertThat(inputsLocationsRetriever.getProducersOfConsumedPartitionGroup(consumedPartitionGroup)).containsExactly(evIdOfProducer2);
        }
    }
}

