    jobStatusMetrics.jobStatusChanges(new JobID(), JobStatus.RUNNING, clock.absoluteTimeMillis());
    clock.advanceTime(Duration.ofMillis(10));
    assertThat(metric.getTotalTime()).isEqualTo(10L);
