/**
 * Check that a {@link SharedStateRegistryFactory} used by {@link SchedulerUtils} registers
 * shared checkpoint state on restore.
 */
@Test
void testSharedStateRegistration() throws Exception {
    UUID backendId = UUID.randomUUID();
    String localPath = "k0";
    StreamStateHandle handle = new ByteStreamStateHandle("h0", new byte[] { 1, 2, 3 });
    CheckpointRecoveryFactory recoveryFactory = buildRecoveryFactory(buildCheckpoint(buildIncrementalHandle(localPath, handle, backendId)));
    CompletedCheckpointStore checkpointStore = SchedulerUtils.createCompletedCheckpointStore(new Configuration(), recoveryFactory, Executors.directExecutor(), log, new JobID(), RecoveryClaimMode.CLAIM);
    SharedStateRegistry sharedStateRegistry = checkpointStore.getSharedStateRegistry();
    IncrementalRemoteKeyedStateHandle newHandle = buildIncrementalHandle(localPath, new PlaceholderStreamStateHandle(handle.getStreamStateHandleID(), handle.getStateSize(), false), backendId);
    newHandle.registerSharedStates(sharedStateRegistry, 1L);
    assertThat(newHandle.getSharedState().stream().filter(e -> e.getLocalPath().equals(localPath)).findFirst().get().getHandle()).isEqualTo(handle);
}

