@Test
void testSortedExecutionTimeWithInputBytes() {
    // executions with unbalanced input bytes
    ExecutionTimeWithInputBytes executionTimeWithInputBytes1 = new ExecutionTimeWithInputBytes(10, 10);
    ExecutionTimeWithInputBytes executionTimeWithInputBytes2 = new ExecutionTimeWithInputBytes(10, 20);
    List<ExecutionTimeWithInputBytes> pairList = new ArrayList<>();
    pairList.add(executionTimeWithInputBytes1);
    pairList.add(executionTimeWithInputBytes2);
    List<ExecutionTimeWithInputBytes> sortedList = pairList.stream().sorted().collect(Collectors.toList());
    assertThat(sortedList.get(0)).isEqualTo(executionTimeWithInputBytes2);
    // executions with balanced input bytes
    ExecutionTimeWithInputBytes executionTimeWithInputBytes3 = new ExecutionTimeWithInputBytes(20, 10);
    ExecutionTimeWithInputBytes executionTimeWithInputBytes4 = new ExecutionTimeWithInputBytes(10, 10);
    pairList.clear();
    pairList.add(executionTimeWithInputBytes3);
    pairList.add(executionTimeWithInputBytes4);
    sortedList = pairList.stream().sorted().collect(Collectors.toList());
    assertThat(sortedList.get(0)).isEqualTo(executionTimeWithInputBytes4);
    // executions with UNKNOWN input bytes
    ExecutionTimeWithInputBytes executionTimeWithInputBytes5 = new ExecutionTimeWithInputBytes(20, -1);
    ExecutionTimeWithInputBytes executionTimeWithInputBytes6 = new ExecutionTimeWithInputBytes(10, -1);
    pairList.clear();
    pairList.add(executionTimeWithInputBytes5);
    pairList.add(executionTimeWithInputBytes6);
    sortedList = pairList.stream().sorted().collect(Collectors.toList());
    assertThat(sortedList.get(0)).isEqualTo(executionTimeWithInputBytes6);
    // executions with 0 input bytes and non-zero execution time
    ExecutionTimeWithInputBytes executionTimeWithInputBytes7 = new ExecutionTimeWithInputBytes(1, 0);
    assertThat(executionTimeWithInputBytes7).isGreaterThan(executionTimeWithInputBytes1);
    // executions with 0 input bytes and 0 execution time
    ExecutionTimeWithInputBytes executionTimeWithInputBytes8 = new ExecutionTimeWithInputBytes(0, 0);
    assertThat(executionTimeWithInputBytes8).isLessThan(executionTimeWithInputBytes1);
    // executions with assigned input bytes mixed with UNKNOWN input bytes
    ExecutionTimeWithInputBytes executionTimeWithInputBytes9 = new ExecutionTimeWithInputBytes(20, 100);
    ExecutionTimeWithInputBytes executionTimeWithInputBytes10 = new ExecutionTimeWithInputBytes(15, -1);
    assertThatThrownBy(() -> executionTimeWithInputBytes9.compareTo(executionTimeWithInputBytes10)).isInstanceOf(IllegalArgumentException.class);
}

