        assertThat(getTargetGroup(strategy, jv4Vertices, i)).isEqualTo(getTargetGroup(strategy, jv5Vertices, i));
    }
    // Check for tJv4
    assertThat(getTargetGroup(strategy, jv4Vertices, 2)).isNotEqualTo(getTargetGroup(strategy, jv1Vertices, 0)).isNotEqualTo(getTargetGroup(strategy, jv1Vertices, 1));
    assertThat(getTargetGroup(strategy, jv4Vertices, 3)).isNotEqualTo(getTargetGroup(strategy, jv1Vertices, 0)).isNotEqualTo(getTargetGroup(strategy, jv1Vertices, 1));
    // Check for tJv6
    assertThat(getTargetGroup(strategy, jv6Vertices, 0)).isEqualTo(getTargetGroup(strategy, jv0Vertices, 0));
    assertThat(getTargetGroup(strategy, jv6Vertices, 1)).isEqualTo(getTargetGroup(strategy, jv4Vertices, 3));
    assertThat(getTargetGroup(strategy, jv6Vertices, 2)).isEqualTo(getTargetGroup(strategy, jv4Vertices, 0));
}

