/**
 * This test verifies that the {@link NettyShuffleEnvironment} requires buffers as expected, so
 * that the required shuffle memory size returned by {@link
 * ShuffleMaster#computeShuffleMemorySizeForTask(TaskInputsOutputsDescriptor)} is correct.
 */
@Test
void testComputeRequiredNetworkBuffers() throws Exception {
    int numBuffersPerChannel = 5;
    int numBuffersPerGate = 8;
    Optional<Integer> maxRequiredBuffersPerGate = Optional.of(Integer.MAX_VALUE);
    int sortShuffleMinParallelism = 8;
    int numSortShuffleMinBuffers = 12;
    IntermediateDataSetID ids1 = new IntermediateDataSetID();
    IntermediateDataSetID ids2 = new IntermediateDataSetID();
    int numChannels1 = 3;
    int numChannels2 = 4;
    IntermediateDataSetID ds1 = new IntermediateDataSetID();
    IntermediateDataSetID ds2 = new IntermediateDataSetID();
    IntermediateDataSetID ds3 = new IntermediateDataSetID();
    // pipelined shuffle
    int numSubs1 = 5;
    // hash blocking shuffle
    int numSubs2 = 6;
    // sort blocking shuffle
    int numSubs3 = 10;
    Map<IntermediateDataSetID, Integer> subpartitionNums = ImmutableMap.of(ds1, numSubs1, ds2, numSubs2, ds3, numSubs3);
    Map<IntermediateDataSetID, ResultPartitionType> partitionTypes = ImmutableMap.of(ds1, PIPELINED_BOUNDED, ds2, BLOCKING, ds3, BLOCKING);
    Map<IntermediateDataSetID, Integer> numInputChannels = ImmutableMap.of(ids1, numChannels1, ids2, numChannels2);
    Map<IntermediateDataSetID, Integer> partitionReuseCount = ImmutableMap.of(ids1, 1, ids2, 1);
    Map<IntermediateDataSetID, ResultPartitionType> inputPartitionTypes = ImmutableMap.of(ids1, PIPELINED_BOUNDED, ids2, BLOCKING);
    int numTotalBuffers = NettyShuffleUtils.computeNetworkBuffersForAnnouncing(numBuffersPerChannel, numBuffersPerGate, maxRequiredBuffersPerGate, sortShuffleMinParallelism, numSortShuffleMinBuffers, numInputChannels, partitionReuseCount, subpartitionNums, inputPartitionTypes, partitionTypes);
    NettyShuffleEnvironment sEnv = new NettyShuffleEnvironmentBuilder().setNumNetworkBuffers(numTotalBuffers).setNetworkBuffersPerChannel(numBuffersPerChannel).setSortShuffleMinBuffers(numSortShuffleMinBuffers).setSortShuffleMinParallelism(sortShuffleMinParallelism).build();
    SingleInputGate inputGate1 = createInputGate(sEnv, PIPELINED_BOUNDED, numChannels1);
    inputGate1.setup();
    SingleInputGate inputGate2 = createInputGate(sEnv, BLOCKING, numChannels2);
    inputGate2.setup();
    ResultPartition resultPartition1 = createResultPartition(sEnv, PIPELINED_BOUNDED, numSubs1);
    resultPartition1.setup();
    ResultPartition resultPartition2 = createResultPartition(sEnv, BLOCKING, numSubs2);
    resultPartition2.setup();
    ResultPartition resultPartition3 = createResultPartition(sEnv, BLOCKING, numSubs3);
    resultPartition3.setup();
    int expected = calculateBuffersConsumption(inputGate1) + calculateBuffersConsumption(inputGate2) + calculateBuffersConsumption(resultPartition1) + calculateBuffersConsumption(resultPartition2) + calculateBuffersConsumption(resultPartition3);
    assertThat(numTotalBuffers).isEqualTo(expected);
    inputGate1.close();
    inputGate2.close();
    resultPartition1.close();
    resultPartition2.close();
    resultPartition3.close();
}

@Test
void testRestoreOrSnapshotShuffleMaster() throws IOException {
    String clusterId = configuration.get(HighAvailabilityOptions.HA_CLUSTER_ID);
    Path path = new Path(HighAvailabilityServicesUtils.getClusterHighAvailableStoragePath(configuration), "shuffleMaster-snapshot");
    FileSystem fileSystem = path.getFileSystem();
    assertThat(fileSystem.exists(new Path(path, clusterId))).isFalse();
    assertThat(ShuffleMasterSnapshotUtil.isShuffleMasterSnapshotExist(path, clusterId)).isFalse();
    // Take a snapshot
    ShuffleMasterSnapshotUtil.restoreOrSnapshotShuffleMaster(shuffleMaster, configuration, Executors.directExecutor());
    assertThat(fileSystem.exists(new Path(path, clusterId))).isTrue();
    assertThat(ShuffleMasterSnapshotUtil.isShuffleMasterSnapshotExist(path, clusterId)).isTrue();
    ShuffleMasterSnapshot snapshot = ShuffleMasterSnapshotUtil.readSnapshot(path, clusterId);
    assertThat(snapshot).isInstanceOf(TestingShuffleMasterSnapshot.class);
    assertThat(restoredSnapshot).isNull();
    assertThat(triggeredSnapshot).isTrue();
    // Clear state
    this.triggeredSnapshot = false;
    // Restore shuffle master
    ShuffleMasterSnapshotUtil.restoreOrSnapshotShuffleMaster(shuffleMaster, configuration, Executors.directExecutor());
    assertThat(restoredSnapshot).isInstanceOf(TestingShuffleMasterSnapshot.class);
    assertThat(triggeredSnapshot).isFalse();
}

