void testExceptionInRunnableFailsTheJob() throws InterruptedException, ExecutionException {
    ManuallyTriggeredScheduledExecutorService manualWorkerExecutor = new ManuallyTriggeredScheduledExecutorService();
    // need the factory to have the exception handler set
    final ManuallyTriggeredScheduledExecutorService coordinatorExecutorWithExceptionHandler = new ManuallyTriggeredScheduledExecutorService();
    SourceCoordinatorContext<MockSourceSplit> testingContext = new SourceCoordinatorContext<>(new JobID(), coordinatorExecutorWithExceptionHandler, manualWorkerExecutor, new SourceCoordinatorProvider.CoordinatorExecutorThreadFactory(coordinatorThreadName, operatorCoordinatorContext), operatorCoordinatorContext, new MockSourceSplitSerializer(), splitSplitAssignmentTracker, false);
    testingContext.runInCoordinatorThread(() -> {
        throw new RuntimeException();
    });
    manualWorkerExecutor.triggerAll();
    // shutdown coordinatorExecutor and blocks until tasks are finished
    testingContext.close();
    coordinatorExecutorWithExceptionHandler.triggerAll();
    // blocks until the job is failed: wait that the uncaught exception handler calls
    // operatorCoordinatorContext#failJob() which completes the future
    operatorCoordinatorContext.getJobFailedFuture().get();
    assertThat(operatorCoordinatorContext.isJobFailed()).isTrue();
}

