@Test
void testReadWritten() throws Exception {
    byte[] inputChannelInfoData = randomBytes(1024);
    byte[] resultSubpartitionInfoData = randomBytes(1024);
    byte[] resultSubpartitionInfoFutureData = randomBytes(1024);
    int partitionIndex = 0;
    SequentialChannelStateReader reader = new SequentialChannelStateReaderImpl(toTaskStateSnapshot(write(1L, singletonMap(new InputChannelInfo(0, 0), inputChannelInfoData), singletonMap(new ResultSubpartitionInfo(partitionIndex, 0), resultSubpartitionInfoData), singletonMap(new ResultSubpartitionInfo(partitionIndex, 1), resultSubpartitionInfoFutureData))));
    NetworkBufferPool networkBufferPool = new NetworkBufferPool(6, 1024);
    try {
        int numChannels = 1;
        InputGate gate = buildGate(networkBufferPool, numChannels);
        reader.readInputData(new InputGate[] { gate });
        assertThat(collectBytes(gate::pollNext, BufferOrEvent::getBuffer)).isEqualTo(inputChannelInfoData);
        int subpartitions = 2;
        BufferWritingResultPartition resultPartition = buildResultPartition(networkBufferPool, ResultPartitionType.PIPELINED, partitionIndex, subpartitions);
        reader.readOutputData(new BufferWritingResultPartition[] { resultPartition }, false);
        ResultSubpartitionView view = resultPartition.createSubpartitionView(new ResultSubpartitionIndexSet(0), new NoOpBufferAvailablityListener());
        assertThat(collectBytes(() -> Optional.ofNullable(view.getNextBuffer()), BufferAndBacklog::buffer)).isEqualTo(resultSubpartitionInfoData);
        ResultSubpartitionView futureView = resultPartition.createSubpartitionView(new ResultSubpartitionIndexSet(1), new NoOpBufferAvailablityListener());
        assertThat(collectBytes(() -> Optional.ofNullable(futureView.getNextBuffer()), BufferAndBacklog::buffer)).isEqualTo(resultSubpartitionInfoFutureData);
    } finally {
        networkBufferPool.destroy();
    }
}

