@ParameterizedTest
@MethodSource("testSeekParameters")
void testSeek(StreamCompressionDecorator streamCompressionDecorator) throws IOException {
    final List<String> records = Arrays.asList("first", "second", "third", "fourth", "fifth");
    final Map<String, Long> positions = new HashMap<>();
    byte[] compressedBytes;
    try (final TestingOutputStream outputStream = new TestingOutputStream();
        final CompressibleFSDataOutputStream compressibleOutputStream = new CompressibleFSDataOutputStream(outputStream, streamCompressionDecorator)) {
        for (String record : records) {
            positions.put(record, compressibleOutputStream.getPos());
            compressibleOutputStream.write(record.getBytes(StandardCharsets.UTF_8));
        }
        compressibleOutputStream.flush();
        compressedBytes = outputStream.toByteArray();
    }
    try (final FSDataInputStream inputStream = new InputStreamFSInputWrapper(new ByteArrayInputStream(compressedBytes));
        final FSDataInputStream compressibleInputStream = new CompressibleFSDataInputStream(inputStream, streamCompressionDecorator)) {
        verifyRecord(compressibleInputStream, positions, "first");
        verifyRecord(compressibleInputStream, positions, "third");
        verifyRecord(compressibleInputStream, positions, "fifth");
    }
    // Verify read of partial records. This ensures that we skip any unread data in the
    // underlying buffers.
    try (final FSDataInputStream inputStream = new InputStreamFSInputWrapper(new ByteArrayInputStream(compressedBytes));
        final FSDataInputStream compressibleInputStream = new CompressibleFSDataInputStream(inputStream, streamCompressionDecorator)) {
        verifyRecordPrefix(compressibleInputStream, positions, "first", "fir");
        verifyRecordPrefix(compressibleInputStream, positions, "third", "thi");
        verifyRecord(compressibleInputStream, positions, "fifth");
    }
}

/**
 * Test that all writes are duplicated to both streams and that the state reflects what was
 * written.
 */
@Test
void testDuplicatedWrite() throws Exception {
    int streamCapacity = 1024 * 1024;
    TestMemoryCheckpointOutputStream primaryStream = new TestMemoryCheckpointOutputStream(streamCapacity);
    TestMemoryCheckpointOutputStream secondaryStream = new TestMemoryCheckpointOutputStream(streamCapacity);
    TestMemoryCheckpointOutputStream referenceStream = new TestMemoryCheckpointOutputStream(streamCapacity);
    DuplicatingCheckpointOutputStream duplicatingStream = new DuplicatingCheckpointOutputStream(primaryStream, secondaryStream, 64);
    Random random = new Random(42);
    for (int i = 0; i < 500; ++i) {
        int choice = random.nextInt(3);
        if (choice == 0) {
            int val = random.nextInt();
            referenceStream.write(val);
            duplicatingStream.write(val);
        } else {
            byte[] bytes = new byte[random.nextInt(128)];
            random.nextBytes(bytes);
            if (choice == 1) {
                referenceStream.write(bytes);
                duplicatingStream.write(bytes);
            } else {
                int off = bytes.length > 0 ? random.nextInt(bytes.length) : 0;
                int len = bytes.length > 0 ? random.nextInt(bytes.length - off) : 0;
                referenceStream.write(bytes, off, len);
                duplicatingStream.write(bytes, off, len);
            }
        }
        assertThat(duplicatingStream.getPos()).isEqualTo(referenceStream.getPos());
    }
    StreamStateHandle refStateHandle = referenceStream.closeAndGetHandle();
    StreamStateHandle primaryStateHandle = duplicatingStream.closeAndGetPrimaryHandle();
    StreamStateHandle secondaryStateHandle = duplicatingStream.closeAndGetSecondaryHandle();
    assertThat(CommonTestUtils.isStreamContentEqual(refStateHandle.openInputStream(), primaryStateHandle.openInputStream())).isTrue();
    assertThat(CommonTestUtils.isStreamContentEqual(refStateHandle.openInputStream(), secondaryStateHandle.openInputStream())).isTrue();
    refStateHandle.discardState();
    primaryStateHandle.discardState();
    secondaryStateHandle.discardState();
}

