void testDisposeDoesNotDeleteParentDirectory() throws Exception {
    final Path p = resolve("path", "with", "parent");
    final List<Path> pathsToDelete = new ArrayList<>();
    initializeFileSystem(MockedLocalFileSystem.newBuilder().setDeleteFunction((path, ignoredRecursionMarker) -> {
        pathsToDelete.add(path);
        return true;
    }).build());
    final FileStateHandle handle = new FileStateHandle(p, 42);
    handle.discardState();
    assertThat(pathsToDelete).as("Only one delete call should have happened on the actual path but not the parent.").singleElement().isEqualTo(p);
}

