@Test
public void testReadFromFileSegments() throws IOException {
    Path dirPath = new Path(tmp.getRoot().getPath());
    Path filePath = new Path(dirPath, UUID.randomUUID().toString());
    byte[] fileContent = prepareFileToRead(filePath, 512);
    int startPos, segmentSize;
    // 1. whole file as one segment
    startPos = 0;
    segmentSize = 512;
    FsSegmentDataInputStream inputStream = openSegment(filePath, startPos, segmentSize);
    closeableRegistry.registerCloseable(inputStream);
    byte[] readResult = new byte[segmentSize];
    int readLen = inputStream.read(readResult);
    assertThat(readLen).isEqualTo(segmentSize);
    assertBytesContentEqual(fileContent, startPos, segmentSize, readResult);
    assertThat(inputStream.read()).isEqualTo(-1);
    // 2. read with a file segment
    startPos = 26;
    segmentSize = 483;
    inputStream = openSegment(filePath, startPos, segmentSize);
    readResult = new byte[segmentSize];
    readLen = inputStream.read(readResult);
    assertThat(readLen).isEqualTo(segmentSize);
    assertBytesContentEqual(fileContent, startPos, segmentSize, readResult);
    assertThat(inputStream.read()).isEqualTo(-1);
    // 3. seek to a relative position
    startPos = 56;
    segmentSize = 123;
    inputStream = openSegment(filePath, startPos, segmentSize);
    int readBufferSize = 32;
    readResult = new byte[readBufferSize];
    int seekPos = 74;
    inputStream.seek(seekPos);
    assertThat(inputStream.getPos()).isEqualTo(seekPos);
    readLen = inputStream.read(readResult);
    assertThat(readLen).isEqualTo(readBufferSize);
    assertBytesContentEqual(fileContent, startPos + seekPos, readLen, readResult);
    assertThat(inputStream.getPos()).isEqualTo(seekPos + readBufferSize);
    // current relative position is (74 + 32 = 106)
    // reading another 32 bytes will cross the segment boundary
    assertThat(inputStream.read(readResult)).isEqualTo(segmentSize - seekPos - readBufferSize);
    assertThat(inputStream.read()).isEqualTo(-1);
    assertThat(inputStream.read(new byte[10])).isEqualTo(-1);
    assertThat(inputStream.read(new byte[10], 0, 1)).isEqualTo(-1);
}

@Test
void testEntropyInjection() throws Exception {
    final int fileSizeThreshold = 1024;
    final FileSystem fs = new TestEntropyAwareFs();
    final Path checkpointDir = new Path(Path.fromLocalFile(TempDirUtils.newFolder(tmp)), ENTROPY_MARKER + "/checkpoints");
    final String checkpointDirStr = checkpointDir.toString();
    final FsCheckpointStorageAccess storage = new FsCheckpointStorageAccess(fs, checkpointDir, null, true, new JobID(), fileSizeThreshold, 4096);
    storage.initializeBaseLocationsForCheckpoint();
    final FsCheckpointStorageLocation location = (FsCheckpointStorageLocation) storage.initializeLocationForCheckpoint(96562);
    assertThat(location.getCheckpointDirectory().toString()).startsWith(checkpointDirStr);
    assertThat(location.getSharedStateDirectory().toString()).startsWith(checkpointDirStr);
    assertThat(location.getTaskOwnedStateDirectory().toString()).startsWith(checkpointDirStr);
    assertThat(location.getMetadataFilePath().toString()).doesNotContain(ENTROPY_MARKER);
    // check entropy in task-owned state
    try (CheckpointStateOutputStream stream = storage.createTaskOwnedStateStream()) {
        stream.write(new byte[fileSizeThreshold + 1], 0, fileSizeThreshold + 1);
        FileStateHandle handle = (FileStateHandle) stream.closeAndGetHandle();
        assertThat(handle).isNotNull();
        assertThat(handle.getFilePath().toString()).doesNotContain(ENTROPY_MARKER);
        assertThat(handle.getFilePath().toString()).contains(RESOLVED_MARKER);
    }
    // check entropy in the exclusive/shared state
    try (CheckpointStateOutputStream stream = location.createCheckpointStateOutputStream(CheckpointedStateScope.EXCLUSIVE)) {
        stream.write(new byte[fileSizeThreshold + 1], 0, fileSizeThreshold + 1);
        FileStateHandle handle = (FileStateHandle) stream.closeAndGetHandle();
        assertThat(handle).isNotNull();
        assertThat(handle.getFilePath().toString()).doesNotContain(ENTROPY_MARKER);
        assertThat(handle.getFilePath().toString()).contains(RESOLVED_MARKER);
    }
    // check that there is no entropy in the metadata
    // check entropy in the exclusive/shared state
    try (CheckpointMetadataOutputStream stream = location.createMetadataOutputStream()) {
        stream.flush();
        FsCompletedCheckpointStorageLocation handle = (FsCompletedCheckpointStorageLocation) stream.closeAndFinalizeCheckpoint();
        assertThat(handle).isNotNull();
        // metadata files have no entropy
        assertThat(handle.getMetadataHandle().getFilePath().toString()).doesNotContain(ENTROPY_MARKER);
        assertThat(handle.getMetadataHandle().getFilePath().toString()).doesNotContain(ENTROPY_MARKER);
        // external location is the same as metadata, without the file name
        assertThat(handle.getExternalPointer()).isEqualTo(handle.getMetadataHandle().getFilePath().getParent().toString());
    }
}

