@Test
void testBulkReadINdexOutOfBounds() throws IOException {
    final ByteStreamStateHandle handle = new ByteStreamStateHandle("name", new byte[10]);
    // check negative offset
    assertThatThrownBy(() -> handle.openInputStream().read(new byte[10], -1, 5)).isInstanceOf(IndexOutOfBoundsException.class);
    // check offset overflow
    assertThatThrownBy(() -> handle.openInputStream().read(new byte[10], 10, 5)).isInstanceOf(IndexOutOfBoundsException.class);
    // check negative length
    assertThatThrownBy(() -> handle.openInputStream().read(new byte[10], 0, -2)).isInstanceOf(IndexOutOfBoundsException.class);
    // check length too large
    assertThatThrownBy(() -> handle.openInputStream().read(new byte[10], 5, 6)).isInstanceOf(IndexOutOfBoundsException.class);
    // check length integer overflow
    assertThatThrownBy(() -> handle.openInputStream().read(new byte[10], 5, Integer.MAX_VALUE)).isInstanceOf(IndexOutOfBoundsException.class);
}

