    FileMergingSnapshotManager manager1 = taskExecutorFileMergingManager.fileMergingSnapshotManagerForTask(job1, tmResourceId1, executionID1, clusterConfig, jobConfig, new UnregisteredMetricGroups.UnregisteredTaskManagerJobMetricGroup());
    manager1.initFileSystem(checkpointDir1.getFileSystem(), checkpointDir1, new Path(checkpointDir1, "shared"), new Path(checkpointDir1, "taskowned"), writeBufferSize);
    ExecutionAttemptID executionID2 = ExecutionAttemptID.randomId();
    FileMergingSnapshotManager manager2 = taskExecutorFileMergingManager.fileMergingSnapshotManagerForTask(job1, tmResourceId2, executionID2, clusterConfig, jobConfig, new UnregisteredMetricGroups.UnregisteredTaskManagerJobMetricGroup());
    manager2.initFileSystem(checkpointDir1.getFileSystem(), checkpointDir1, new Path(checkpointDir1, "shared"), new Path(checkpointDir1, "taskowned"), writeBufferSize);
    ExecutionAttemptID executionID3 = ExecutionAttemptID.randomId();
    FileMergingSnapshotManager manager3 = taskExecutorFileMergingManager.fileMergingSnapshotManagerForTask(job2, tmResourceId3, executionID3, clusterConfig, jobConfig, new UnregisteredMetricGroups.UnregisteredTaskManagerJobMetricGroup());
    manager3.initFileSystem(checkpointDir2.getFileSystem(), checkpointDir2, new Path(checkpointDir2, "shared"), new Path(checkpointDir2, "taskowned"), writeBufferSize);
    assertThat(manager1).isEqualTo(manager2);
    assertThat(manager1).isNotEqualTo(manager3);
    // tasks of same job should have same private dir.
    assertThat(manager1.getManagedDir(key1, CheckpointedStateScope.EXCLUSIVE)).isEqualTo(manager2.getManagedDir(key2, CheckpointedStateScope.EXCLUSIVE));
    // tasks of different jobs should have different private dirs.
    assertThat(manager1.getManagedDir(key1, CheckpointedStateScope.EXCLUSIVE)).isNotEqualTo(manager3.getManagedDir(key2, CheckpointedStateScope.EXCLUSIVE));
    manager1.registerSubtaskForSharedStates(key1);
    manager1.registerSubtaskForSharedStates(key2);
    manager3.registerSubtaskForSharedStates(key1);
    manager3.registerSubtaskForSharedStates(key2);
    // tasks of same job should have different shared dirs for different subtasks.
    assertThat(manager1.getManagedDir(key1, CheckpointedStateScope.SHARED)).isNotEqualTo(manager1.getManagedDir(key2, CheckpointedStateScope.SHARED));
    // tasks with same SubtaskKey of different jobs should have different shared dirs.
    assertThat(manager1.getManagedDir(key1, CheckpointedStateScope.SHARED)).isNotEqualTo(manager3.getManagedDir(key1, CheckpointedStateScope.SHARED));
    taskExecutorFileMergingManager.releaseMergingSnapshotManagerForTask(job1, executionID1);
    taskExecutorFileMergingManager.releaseMergingSnapshotManagerForTask(job1, executionID2);
    taskExecutorFileMergingManager.releaseMergingSnapshotManagerForTask(job2, executionID3);
    ExecutionAttemptID executionID4 = ExecutionAttemptID.randomId();
    FileMergingSnapshotManager manager4 = taskExecutorFileMergingManager.fileMergingSnapshotManagerForTask(job1, tmResourceId4, executionID4, clusterConfig, jobConfig, new UnregisteredMetricGroups.UnregisteredTaskManagerJobMetricGroup());
    assertThat(manager4).isNotEqualTo(manager1);
}

/**
 * This tests that the creation of {@link TaskManagerServices} correctly creates the local state
