@Test
void testRegisteredKeyValueStateBackendMetaInfoV2SerializationRoundtrip() throws Exception {
    TypeSerializer<?> keySerializer = IntSerializer.INSTANCE;
    TypeSerializer<?> namespaceSerializer = LongSerializer.INSTANCE;
    TypeSerializer<?> stateSerializer = DoubleSerializer.INSTANCE;
    TypeSerializer<?> userKeySerializer = StringSerializer.INSTANCE;
    List<StateMetaInfoSnapshot> stateMetaInfoList = new ArrayList<>();
    stateMetaInfoList.add(new org.apache.flink.runtime.state.v2.RegisteredKeyValueStateBackendMetaInfo<>("a", org.apache.flink.api.common.state.v2.StateDescriptor.Type.VALUE, namespaceSerializer, stateSerializer).snapshot());
    stateMetaInfoList.add(new org.apache.flink.runtime.state.v2.RegisteredKeyAndUserKeyValueStateBackendMetaInfo<>("b", org.apache.flink.api.common.state.v2.StateDescriptor.Type.MAP, namespaceSerializer, stateSerializer, userKeySerializer).snapshot());
    stateMetaInfoList.add(new org.apache.flink.runtime.state.v2.RegisteredKeyValueStateBackendMetaInfo<>("c", org.apache.flink.api.common.state.v2.StateDescriptor.Type.VALUE, namespaceSerializer, stateSerializer).snapshot());
    KeyedBackendSerializationProxy<?> serializationProxy = new KeyedBackendSerializationProxy<>(keySerializer, stateMetaInfoList, true);
    byte[] serialized;
    try (ByteArrayOutputStreamWithPos out = new ByteArrayOutputStreamWithPos()) {
        serializationProxy.write(new DataOutputViewStreamWrapper(out));
        serialized = out.toByteArray();
    }
    serializationProxy = new KeyedBackendSerializationProxy<>(Thread.currentThread().getContextClassLoader());
    try (ByteArrayInputStreamWithPos in = new ByteArrayInputStreamWithPos(serialized)) {
        serializationProxy.read(new DataInputViewStreamWrapper(in));
    }
    assertThat(serializationProxy.isUsingKeyGroupCompression()).isTrue();
    assertThat(serializationProxy.getKeySerializerSnapshot()).isInstanceOf(IntSerializer.IntSerializerSnapshot.class);
    assertEqualStateMetaInfoSnapshotsLists(stateMetaInfoList, serializationProxy.getStateMetaInfoSnapshots());
}

@Test
void testMapKeyedStateMetaInfoSerialization() throws Exception {
    TypeSerializer<?> keySerializer = IntSerializer.INSTANCE;
    TypeSerializer<?> namespaceSerializer = LongSerializer.INSTANCE;
    TypeSerializer<?> stateSerializer = DoubleSerializer.INSTANCE;
    TypeSerializer<?> userKeySerializer = StringSerializer.INSTANCE;
    List<StateMetaInfoSnapshot> stateMetaInfoList = new ArrayList<>();
    // create StateMetaInfoSnapshot without userKeySerializer
    StateMetaInfoSnapshot oldStateMeta = new org.apache.flink.runtime.state.v2.RegisteredKeyValueStateBackendMetaInfo<>("test1", org.apache.flink.api.common.state.v2.StateDescriptor.Type.MAP, namespaceSerializer, stateSerializer).snapshot();
    StateMetaInfoSnapshot oldStateMetaWithUserKey = new org.apache.flink.runtime.state.v2.RegisteredKeyAndUserKeyValueStateBackendMetaInfo<>("test2", org.apache.flink.api.common.state.v2.StateDescriptor.Type.MAP, namespaceSerializer, stateSerializer, userKeySerializer).snapshot();
    stateMetaInfoList.add(oldStateMeta);
    stateMetaInfoList.add(oldStateMetaWithUserKey);
    assertThat(oldStateMeta.getBackendStateType()).isEqualTo(StateMetaInfoSnapshot.BackendStateType.KEY_VALUE_V2);
    assertThat(oldStateMetaWithUserKey.getBackendStateType()).isEqualTo(StateMetaInfoSnapshot.BackendStateType.KEY_VALUE_V2);
    assertThat(oldStateMeta.getTypeSerializerSnapshot(StateMetaInfoSnapshot.CommonSerializerKeys.USER_KEY_SERIALIZER)).isNull();
    assertThat(oldStateMetaWithUserKey.getTypeSerializerSnapshot(StateMetaInfoSnapshot.CommonSerializerKeys.USER_KEY_SERIALIZER).restoreSerializer()).isEqualTo(userKeySerializer);
    KeyedBackendSerializationProxy<?> serializationProxy = new KeyedBackendSerializationProxy<>(keySerializer, stateMetaInfoList, true);
    byte[] serialized;
    try (ByteArrayOutputStreamWithPos out = new ByteArrayOutputStreamWithPos()) {
        serializationProxy.write(new DataOutputViewStreamWrapper(out));
        serialized = out.toByteArray();
    }
    serializationProxy = new KeyedBackendSerializationProxy<>(Thread.currentThread().getContextClassLoader());
    try (ByteArrayInputStreamWithPos in = new ByteArrayInputStreamWithPos(serialized)) {
        serializationProxy.read(new DataInputViewStreamWrapper(in));
    }
    List<StateMetaInfoSnapshot> stateMetaInfoSnapshots = serializationProxy.getStateMetaInfoSnapshots();
    org.apache.flink.runtime.state.v2.RegisteredKeyValueStateBackendMetaInfo restoredMetaInfo = (RegisteredKeyValueStateBackendMetaInfo) RegisteredStateMetaInfoBase.fromMetaInfoSnapshot(stateMetaInfoSnapshots.get(0));
    assertThat(restoredMetaInfo.getClass()).isEqualTo(org.apache.flink.runtime.state.v2.RegisteredKeyAndUserKeyValueStateBackendMetaInfo.class);
    assertThat(restoredMetaInfo.getName()).isEqualTo("test1");
    assertThat(((RegisteredKeyAndUserKeyValueStateBackendMetaInfo) restoredMetaInfo).getUserKeySerializer()).isNull();
    assertThat(restoredMetaInfo.getStateSerializer()).isEqualTo(DoubleSerializer.INSTANCE);
    assertThat(restoredMetaInfo.getNamespaceSerializer()).isEqualTo(LongSerializer.INSTANCE);
    org.apache.flink.runtime.state.v2.RegisteredKeyValueStateBackendMetaInfo restoredMetaInfo1 = (RegisteredKeyValueStateBackendMetaInfo) RegisteredStateMetaInfoBase.fromMetaInfoSnapshot(stateMetaInfoSnapshots.get(1));
    assertThat(restoredMetaInfo1.getClass()).isEqualTo(org.apache.flink.runtime.state.v2.RegisteredKeyAndUserKeyValueStateBackendMetaInfo.class);
    assertThat(restoredMetaInfo1.getName()).isEqualTo("test2");
    assertThat(((RegisteredKeyAndUserKeyValueStateBackendMetaInfo) restoredMetaInfo1).getUserKeySerializer()).isEqualTo(StringSerializer.INSTANCE);
    assertThat(restoredMetaInfo1.getStateSerializer()).isEqualTo(DoubleSerializer.INSTANCE);
    assertThat(restoredMetaInfo1.getNamespaceSerializer()).isEqualTo(LongSerializer.INSTANCE);
}

/**
 * Tests that we can concurrently modify the JobLeaderService and complete the leader retrieval
 * operation. See FLINK-16373.
 */
@Test
void handlesConcurrentJobAdditionsAndLeaderChanges() throws Exception {
    final JobLeaderService jobLeaderService = new DefaultJobLeaderService(new LocalUnresolvedTaskManagerLocation(), RetryingRegistrationConfiguration.defaultConfiguration());
    final TestingJobLeaderListener jobLeaderListener = new TestingJobLeaderListener();
    final int numberOperations = 20;
    final BlockingQueue<SettableLeaderRetrievalService> instantiatedLeaderRetrievalServices = new ArrayBlockingQueue<>(numberOperations);
    final HighAvailabilityServices haServices = new TestingHighAvailabilityServicesBuilder().setJobMasterLeaderRetrieverFunction(leaderForJobId -> {
        final SettableLeaderRetrievalService leaderRetrievalService = new SettableLeaderRetrievalService();
        instantiatedLeaderRetrievalServices.offer(leaderRetrievalService);
        return leaderRetrievalService;
    }).build();
    jobLeaderService.start("foobar", rpcServiceExtension.getTestingRpcService(), haServices, jobLeaderListener);
    final CheckedThread addJobAction = new CheckedThread() {

        @Override
        public void go() throws Exception {
            for (int i = 0; i < numberOperations; i++) {
                final JobID jobId = JobID.generate();
                jobLeaderService.addJob(jobId, "foobar");
                Thread.yield();
                jobLeaderService.removeJob(jobId);
            }
        }
    };
    addJobAction.start();
    for (int i = 0; i < numberOperations; i++) {
        final SettableLeaderRetrievalService leaderRetrievalService = instantiatedLeaderRetrievalServices.take();
        leaderRetrievalService.notifyListener("foobar", UUID.randomUUID());
    }
    addJobAction.sync();
}

/**
 * Tests that the JobLeaderService won't try to reconnect to JobMaster after it has lost the
 * leadership. See FLINK-16836.
 */
@Test
void doesNotReconnectAfterTargetLostLeadership() throws Exception {
    final JobID jobId = new JobID();
    final SettableLeaderRetrievalService leaderRetrievalService = new SettableLeaderRetrievalService();
    final TestingHighAvailabilityServices haServices = new TestingHighAvailabilityServicesBuilder().setJobMasterLeaderRetrieverFunction(ignored -> leaderRetrievalService).build();
    final TestingJobMasterGateway jobMasterGateway = registerJobMaster();
    final OneShotLatch jobManagerGainedLeadership = new OneShotLatch();
    final TestingJobLeaderListener testingJobLeaderListener = new TestingJobLeaderListener(ignored -> jobManagerGainedLeadership.trigger());
    final JobLeaderService jobLeaderService = createAndStartJobLeaderService(haServices, testingJobLeaderListener);
    try {
        jobLeaderService.addJob(jobId, jobMasterGateway.getAddress());
        leaderRetrievalService.notifyListener(jobMasterGateway.getAddress(), UUID.randomUUID());
        jobManagerGainedLeadership.await();
        // revoke the leadership
        leaderRetrievalService.notifyListener(null, null);
        testingJobLeaderListener.waitUntilJobManagerLostLeadership();
        jobLeaderService.reconnect(jobId);
    } finally {
        jobLeaderService.stop();
    }
}

/**
 * Tests that the JobLeaderService can reconnect to an old leader which seemed to have lost the
 * leadership in between. See FLINK-14316.
 */
@Test
void canReconnectToOldLeaderWithSameLeaderAddress() throws Exception {
    final JobID jobId = new JobID();
    final SettableLeaderRetrievalService leaderRetrievalService = new SettableLeaderRetrievalService();
    final TestingHighAvailabilityServices haServices = new TestingHighAvailabilityServicesBuilder().setJobMasterLeaderRetrieverFunction(ignored -> leaderRetrievalService).build();
    final TestingJobMasterGateway jobMasterGateway = registerJobMaster();
    final BlockingQueue<JobID> leadershipQueue = new ArrayBlockingQueue<>(1);
    final TestingJobLeaderListener testingJobLeaderListener = new TestingJobLeaderListener(leadershipQueue::offer);
    final JobLeaderService jobLeaderService = createAndStartJobLeaderService(haServices, testingJobLeaderListener);
    try {
        jobLeaderService.addJob(jobId, jobMasterGateway.getAddress());
        final UUID leaderSessionId = UUID.randomUUID();
        leaderRetrievalService.notifyListener(jobMasterGateway.getAddress(), leaderSessionId);
        // wait for the first leadership
        assertThat(leadershipQueue.take()).isEqualTo(jobId);
        // revoke the leadership
        leaderRetrievalService.notifyListener(null, null);
        testingJobLeaderListener.waitUntilJobManagerLostLeadership();
        leaderRetrievalService.notifyListener(jobMasterGateway.getAddress(), leaderSessionId);
        // check that we obtain the leadership a second time
        assertThat(leadershipQueue.take()).isEqualTo(jobId);
    } finally {
        jobLeaderService.stop();
    }
}

