/**
 * Tests that inconsistent static slot allocation with the same AllocationID to a different slot
 * is rejected.
 */
@Test
void testInconsistentStaticSlotAllocation() throws Exception {
    runInMainThread(2, taskSlotTable -> {
        final JobID jobId = new JobID();
        final AllocationID allocationId1 = new AllocationID();
        final AllocationID allocationId2 = new AllocationID();
        assertThatNoException().isThrownBy(() -> taskSlotTable.allocateSlot(0, jobId, allocationId1, SLOT_TIMEOUT));
        assertThatThrownBy(() -> taskSlotTable.allocateSlot(1, jobId, allocationId1, SLOT_TIMEOUT)).isInstanceOf(SlotAllocationException.class);
        assertThatThrownBy(() -> taskSlotTable.allocateSlot(0, jobId, allocationId2, SLOT_TIMEOUT)).isInstanceOf(SlotAllocationException.class);
        assertThat(taskSlotTable.isAllocated(0, jobId, allocationId1)).isTrue();
        assertThat(taskSlotTable.isSlotFree(1)).isTrue();
        Iterator<TaskSlot<TaskSlotPayload>> allocatedSlots = taskSlotTable.getAllocatedSlots(jobId);
        assertThat(allocatedSlots.next().getIndex()).isZero();
        assertThat(allocatedSlots.hasNext()).isFalse();
    });
}

