@Test
void testGenerateSlotReport() throws Exception {
    runInMainThread(3, taskSlotTable -> {
        final JobID jobId = new JobID();
        final AllocationID allocationId1 = new AllocationID();
        final AllocationID allocationId2 = new AllocationID();
        final AllocationID allocationId3 = new AllocationID();
        assertThatNoException().as("Slot with allocation ID %s should have been allocated successfully.", allocationId1).isThrownBy(() -> taskSlotTable.allocateSlot(0, jobId, allocationId1, SLOT_TIMEOUT));
        assertThatNoException().as("Slot with allocation ID %s should have been allocated successfully.", allocationId2).isThrownBy(() -> taskSlotTable.allocateSlot(-1, jobId, allocationId2, // index 3
        SLOT_TIMEOUT));
        assertThatNoException().as("Slot with allocation ID %s should have been allocated successfully.", allocationId3).isThrownBy(() -> taskSlotTable.allocateSlot(-1, jobId, allocationId3, SLOT_TIMEOUT));
        assertThat(taskSlotTable.freeSlot(allocationId2)).isEqualTo(3);
        ResourceID resourceId = ResourceID.generate();
        SlotReport slotReport = taskSlotTable.createSlotReport(resourceId);
        List<SlotStatus> slotStatuses = new ArrayList<>();
        slotReport.iterator().forEachRemaining(slotStatuses::add);
        assertThat(slotStatuses).hasSize(4);
        assertThat(slotStatuses).containsExactlyInAnyOrder(new SlotStatus(new SlotID(resourceId, 0), TaskSlotUtils.DEFAULT_RESOURCE_PROFILE, jobId, allocationId1), new SlotStatus(new SlotID(resourceId, 1), TaskSlotUtils.DEFAULT_RESOURCE_PROFILE, null, null), new SlotStatus(new SlotID(resourceId, 2), TaskSlotUtils.DEFAULT_RESOURCE_PROFILE, null, null), new SlotStatus(new SlotID(resourceId, 4), TaskSlotUtils.DEFAULT_RESOURCE_PROFILE, jobId, allocationId3));
    });
}

