/**
 * Tests that the TaskExecutor syncs its slots view with the JobMaster's view via the
 * AllocatedSlotReport reported by the heartbeat (See FLINK-11059).
 */
@Test
void testSyncSlotsWithJobMasterByHeartbeat() throws Exception {
    final CountDownLatch activeSlots = new CountDownLatch(2);
    final TaskSlotTable<Task> taskSlotTable = new ActivateSlotNotifyingTaskSlotTable(2, activeSlots);
    final TaskManagerServices taskManagerServices = new TaskManagerServicesBuilder().setTaskSlotTable(taskSlotTable).build();
    final TaskExecutor taskExecutor = createTaskExecutor(taskManagerServices);
    final TestingResourceManagerGateway testingResourceManagerGateway = new TestingResourceManagerGateway();
    final BlockingQueue<AllocationID> allocationsNotifiedFree = new ArrayBlockingQueue<>(2);
    OneShotLatch initialSlotReporting = new OneShotLatch();
    testingResourceManagerGateway.setSendSlotReportFunction(resourceIDInstanceIDSlotReportTuple3 -> {
        initialSlotReporting.trigger();
        return CompletableFuture.completedFuture(Acknowledge.get());
    });
    testingResourceManagerGateway.setNotifySlotAvailableConsumer(instanceIDSlotIDAllocationIDTuple3 -> allocationsNotifiedFree.offer(instanceIDSlotIDAllocationIDTuple3.f2));
    rpc.registerGateway(testingResourceManagerGateway.getAddress(), testingResourceManagerGateway);
    resourceManagerLeaderRetriever.notifyListener(testingResourceManagerGateway.getAddress(), testingResourceManagerGateway.getFencingToken().toUUID());
    final BlockingQueue<AllocationID> failedSlotFutures = new ArrayBlockingQueue<>(2);
    final ResourceID jobManagerResourceId = ResourceID.generate();
    final TestingJobMasterGateway jobMasterGateway = new TestingJobMasterGatewayBuilder().setFailSlotConsumer((resourceID, allocationID, throwable) -> failedSlotFutures.offer(allocationID)).setOfferSlotsFunction((resourceID, slotOffers) -> CompletableFuture.completedFuture(new ArrayList<>(slotOffers))).setRegisterTaskManagerFunction((ignoredJobId, ignoredTaskManagerRegistrationInformation) -> CompletableFuture.completedFuture(new JMTMRegistrationSuccess(jobManagerResourceId))).build();
    final String jobManagerAddress = jobMasterGateway.getAddress();
    rpc.registerGateway(jobManagerAddress, jobMasterGateway);
    jobManagerLeaderRetriever.notifyListener(jobManagerAddress, jobMasterGateway.getFencingToken().toUUID());
    taskExecutor.start();
    try {
        final TaskExecutorGateway taskExecutorGateway = taskExecutor.getSelfGateway(TaskExecutorGateway.class);
        initialSlotReporting.await();
        final AllocationID allocationIdInBoth = new AllocationID();
        final AllocationID allocationIdOnlyInJM = new AllocationID();
        final AllocationID allocationIdOnlyInTM = new AllocationID();
        taskExecutorGateway.requestSlot(new SlotID(taskExecutor.getResourceID(), 0), jobId, allocationIdInBoth, ResourceProfile.ZERO, "foobar", testingResourceManagerGateway.getFencingToken(), timeout);
        taskExecutorGateway.requestSlot(new SlotID(taskExecutor.getResourceID(), 1), jobId, allocationIdOnlyInTM, ResourceProfile.ZERO, "foobar", testingResourceManagerGateway.getFencingToken(), timeout);
        activeSlots.await();
        List<AllocatedSlotInfo> allocatedSlotInfos = Arrays.asList(new AllocatedSlotInfo(0, allocationIdInBoth), new AllocatedSlotInfo(1, allocationIdOnlyInJM));
        AllocatedSlotReport allocatedSlotReport = new AllocatedSlotReport(jobId, allocatedSlotInfos);
        taskExecutorGateway.heartbeatFromJobManager(jobManagerResourceId, allocatedSlotReport);
        assertThat(failedSlotFutures.take()).isEqualTo(allocationIdOnlyInJM);
        assertThat(allocationsNotifiedFree.take()).isEqualTo(allocationIdOnlyInTM);
        assertThat(failedSlotFutures.poll(5L, TimeUnit.MILLISECONDS)).isNull();
        assertThat(allocationsNotifiedFree.poll(5L, TimeUnit.MILLISECONDS)).isNull();
    } finally {
        RpcUtils.terminateRpcEndpoint(taskExecutor);
    }
}

/**
 * Tests that the {@link SlotReport} sent to the RM does not contain out dated/stale information
 * as slots are being requested from the TM.
 *
 * <p>This is a probabilistic test case and needs to be executed several times to produce a
 * failure without the fix for FLINK-12865.
 */
@Test
void testSlotReportDoesNotContainStaleInformation() throws Exception {
    final OneShotLatch receivedSlotRequest = new OneShotLatch();
    final CompletableFuture<Void> verifySlotReportFuture = new CompletableFuture<>();
    final OneShotLatch terminateSlotReportVerification = new OneShotLatch();
    final TestingResourceManagerGateway testingResourceManagerGateway = new TestingResourceManagerGateway();
    // Assertions for this test
    testingResourceManagerGateway.setTaskExecutorHeartbeatFunction((ignored, heartbeatPayload) -> {
        try {
            final ArrayList<SlotStatus> slots = Lists.newArrayList(heartbeatPayload.getSlotReport());
            assertThat(slots).hasSize(1);
            final SlotStatus slotStatus = slots.get(0);
            LOGGER.info("Received SlotStatus: {}", slotStatus);
            if (receivedSlotRequest.isTriggered()) {
                assertThat(slotStatus.getAllocationID()).isNotNull();
            } else {
                assertThat(slotStatus.getAllocationID()).isNull();
            }
        } catch (AssertionError e) {
            verifySlotReportFuture.completeExceptionally(e);
        }
        if (terminateSlotReportVerification.isTriggered()) {
            verifySlotReportFuture.complete(null);
        }
        return FutureUtils.completedVoidFuture();
    });
    final CompletableFuture<ResourceID> taskExecutorRegistrationFuture = new CompletableFuture<>();
    testingResourceManagerGateway.setSendSlotReportFunction(ignored -> {
        taskExecutorRegistrationFuture.complete(null);
        return CompletableFuture.completedFuture(Acknowledge.get());
    });
    rpc.registerGateway(testingResourceManagerGateway.getAddress(), testingResourceManagerGateway);
    resourceManagerLeaderRetriever.notifyListener(testingResourceManagerGateway.getAddress(), testingResourceManagerGateway.getFencingToken().toUUID());
    final TaskManagerServices taskManagerServices = new TaskManagerServicesBuilder().setTaskSlotTable(new AllocateSlotNotifyingTaskSlotTable(receivedSlotRequest)).build();
    final TaskExecutor taskExecutor = createTaskExecutor(taskManagerServices);
    final ResourceID taskExecutorResourceId = taskManagerServices.getUnresolvedTaskManagerLocation().getResourceID();
    taskExecutor.start();
    final TaskExecutorGateway taskExecutorGateway = taskExecutor.getSelfGateway(TaskExecutorGateway.class);
    final ScheduledExecutorService heartbeatExecutor = java.util.concurrent.Executors.newSingleThreadScheduledExecutor();
    try {
        taskExecutorRegistrationFuture.get();
        final OneShotLatch scheduleFirstHeartbeat = new OneShotLatch();
        final ResourceID resourceManagerResourceId = testingResourceManagerGateway.getOwnResourceId();
        final long heartbeatInterval = 5L;
        heartbeatExecutor.scheduleWithFixedDelay(() -> {
            scheduleFirstHeartbeat.trigger();
            taskExecutorGateway.heartbeatFromResourceManager(resourceManagerResourceId);
        }, 0L, heartbeatInterval, TimeUnit.MILLISECONDS);
        scheduleFirstHeartbeat.await();
        taskExecutorGateway.requestSlot(new SlotID(taskExecutorResourceId, 0), jobId, new AllocationID(), ResourceProfile.ZERO, "foobar", testingResourceManagerGateway.getFencingToken(), timeout).get();
        terminateSlotReportVerification.trigger();
        verifySlotReportFuture.get();
    } finally {
        ExecutorUtils.gracefulShutdown(timeout.toMillis(), TimeUnit.MILLISECONDS, heartbeatExecutor);
        RpcUtils.terminateRpcEndpoint(taskExecutor);
    }
}

