void testMigrateLegacyConfigToStandardYaml() throws Exception {
    File file = new File(confDir.toFile(), ConfigurationFileMigrationUtils.LEGACY_FLINK_CONF_FILENAME);
    try (FileWriter fw = new FileWriter(file)) {
        fw.write(TEST_CONFIG_KEY + ": " + TEST_CONFIG_VALUE + "\n");
        fw.write("pipeline.cached-files" + ": " + "name:file1,path:'file:///tmp/file1';name:file2,path:'hdfs:///tmp/file2'" + "\n");
    }
    Map<String, String> configuration = ConfigurationFileMigrationUtils.loadLegacyYAMLResource(file);
    File newConfigFolder = TempDirUtils.newFolder(confDir);
    try (FileWriter fw = new FileWriter(TempDirUtils.newFile(newConfigFolder.toPath(), GlobalConfiguration.FLINK_CONF_FILENAME))) {
        String[] args = { "-c", confDir.toFile().getAbsolutePath() };
        for (String line : FlinkConfigLoader.migrateLegacyConfigurationToStandardYaml(args)) {
            fw.write(line + "\n");
        }
    }
    Configuration standardYamlConfig = GlobalConfiguration.loadConfiguration(newConfigFolder.toString());
    assertThat(configuration.getOrDefault(TEST_CONFIG_KEY, null)).isEqualTo(standardYamlConfig.getString(TEST_CONFIG_KEY, null));
    List<String> cachedFiles = ConfigurationUtils.convertToList(configuration.get(PipelineOptions.CACHED_FILES.key()), String.class);
    assertThat(DistributedCache.parseCachedFilesFromString(cachedFiles)).isEqualTo(DistributedCache.parseCachedFilesFromString(standardYamlConfig.get(PipelineOptions.CACHED_FILES)));
}

@Test
void testProcessShutdownBlocking() throws Exception {
    // this test works only on linux
    assumeThat(OperatingSystem.isLinux()).isTrue();
    final File markerFile = new File(EnvironmentInformation.getTemporaryFileDirectory(), UUID.randomUUID() + ".marker");
    final BlockingShutdownProcess blockingProcess = new BlockingShutdownProcess(markerFile.getAbsolutePath(), 0, false);
    try {
        blockingProcess.startProcess();
        long pid = blockingProcess.getProcessId();
        assertThat(pid).withFailMessage("Cannot determine process ID").isNotEqualTo(-1);
        // wait for the marker file to appear, which means the process is up properly
        TestJvmProcess.waitForMarkerFile(markerFile, 30000);
        TestJvmProcess.killProcessWithSigTerm(pid);
        // minimal delay until the Java process object notices that the process is gone
        // this will not let the test fail predictably if the process is actually in fact going
        // away,
        // but it would create frequent failures. Not ideal, but the best we can do without
        // severely prolonging the test
        Thread.sleep(50);
        // the process should not go away by itself
        assertThat(blockingProcess.isAlive()).withFailMessage("Test broken, process shutdown blocking does not work").isTrue();
    } finally {
        blockingProcess.destroy();
        //noinspection ResultOfMethodCallIgnored
        markerFile.delete();
    }
}

@Test
void testProcessExitsDespiteBlockingShutdownHook() throws Exception {
    // this test works only on linux
    assumeThat(OperatingSystem.isLinux()).isTrue();
    final File markerFile = new File(EnvironmentInformation.getTemporaryFileDirectory(), UUID.randomUUID() + ".marker");
    final BlockingShutdownProcess blockingProcess = new BlockingShutdownProcess(markerFile.getAbsolutePath(), 100, true);
    try {
        blockingProcess.startProcess();
        long pid = blockingProcess.getProcessId();
        assertThat(pid).withFailMessage("Cannot determine process ID").isNotEqualTo(-1);
        // wait for the marker file to appear, which means the process is up properly
        TestJvmProcess.waitForMarkerFile(markerFile, 30000);
        TestJvmProcess.killProcessWithSigTerm(pid);
        // the process should eventually go away
        // 30 secs in nanos
        final long deadline = System.nanoTime() + 30_000_000_000L;
        while (blockingProcess.isAlive() && System.nanoTime() < deadline) {
            Thread.sleep(50);
        }
        assertThat(blockingProcess.isAlive()).withFailMessage("shutdown blocking process does not properly terminate itself").isFalse();
    } finally {
        blockingProcess.destroy();
        //noinspection ResultOfMethodCallIgnored
        markerFile.delete();
    }
}

