        assertThat(this.psi.nextKey()).withFailMessage("KeyGroupedIterator must have another key.").isTrue();
        assertThat(this.psi.getComparatorWithCurrentReference().equalToReference(new Record(new IntValue(1)))).withFailMessage("KeyGroupedIterator returned a wrong key.").isTrue();
        assertThat(this.psi.getCurrent().getField(0, IntValue.class).getValue()).withFailMessage("KeyGroupedIterator returned a wrong key.").isOne();
        assertThat(this.psi.nextKey()).withFailMessage("KeyGroupedIterator must have another key.").isTrue();
        assertThat(this.psi.getComparatorWithCurrentReference().equalToReference(new Record(new IntValue(2)))).withFailMessage("KeyGroupedIterator returned a wrong key.").isTrue();
        assertThat(this.psi.getCurrent().getField(0, IntValue.class).getValue()).withFailMessage("KeyGroupedIterator returned a wrong key.").isEqualTo(2);
        assertThat(this.psi.nextKey()).withFailMessage("KeyGroupedIterator must have another key.").isTrue();
        assertThat(this.psi.getComparatorWithCurrentReference().equalToReference(new Record(new IntValue(3)))).withFailMessage("KeyGroupedIterator returned a wrong key.").isTrue();
        assertThat(this.psi.getCurrent().getField(0, IntValue.class).getValue()).withFailMessage("KeyGroupedIterator returned a wrong key.").isEqualTo(3);
        assertThat(this.psi.nextKey()).withFailMessage("KeyGroupedIterator must have another key.").isTrue();
        assertThat(this.psi.getComparatorWithCurrentReference().equalToReference(new Record(new IntValue(4)))).withFailMessage("KeyGroupedIterator returned a wrong key.").isTrue();
        assertThat(this.psi.getCurrent().getField(0, IntValue.class).getValue()).withFailMessage("KeyGroupedIterator returned a wrong key.").isEqualTo(4);
        assertThat(this.psi.nextKey()).withFailMessage("KeyGroupedIterator must have another key.").isTrue();
        assertThat(this.psi.getComparatorWithCurrentReference().equalToReference(new Record(new IntValue(5)))).withFailMessage("KeyGroupedIterator returned a wrong key.").isTrue();
        assertThat(this.psi.getCurrent().getField(0, IntValue.class).getValue()).withFailMessage("KeyGroupedIterator returned a wrong key.").isEqualTo(5);
