        assertThat(this.psi.getValues().next().getField(1, StringValue.class).getValue()).withFailMessage("KeyGroupedIterator returned a wrong value.").isEqualTo("C");
        assertThat(this.psi.getValues().hasNext()).withFailMessage("KeyGroupedIterator must have another value.").isTrue();
        assertThat(this.psi.getCurrent().getField(0, IntValue.class).getValue()).withFailMessage("KeyGroupedIterator returned a wrong key.").isEqualTo(3);
        assertThat(this.psi.getCurrent().getField(0, IntValue.class).getValue()).withFailMessage("KeyGroupedIterator returned a wrong key.").isEqualTo(3);
        // Progression first via next() only, then hasNext() only Key 4, Values E, F, G
        assertThat(this.psi.nextKey()).withFailMessage("KeyGroupedIterator must have another key.").isTrue();
        assertThat(this.psi.getValues().next().getField(1, StringValue.class).getValue()).withFailMessage("KeyGroupedIterator returned a wrong value.").isEqualTo("E");
        assertThat(this.psi.getValues().hasNext()).withFailMessage("KeyGroupedIterator must have another value.").isTrue();
        // Key 5, Values H, I, J, K, L
        assertThat(this.psi.nextKey()).withFailMessage("KeyGroupedIterator must have another key.").isTrue();
        assertThat(this.psi.getValues().next().getField(1, StringValue.class).getValue()).withFailMessage("KeyGroupedIterator returned a wrong value.").isEqualTo("H");
