        assertThat(this.psi.getCurrent().getField(0, IntValue.class).getValue()).withFailMessage("KeyGroupedIterator returned a wrong key.").isEqualTo(5);
        assertThat(this.psi.getCurrent().getField(0, IntValue.class).getValue()).withFailMessage("KeyGroupedIterator returned a wrong key.").isEqualTo(5);
        assertThat(this.psi.getValues().next().getField(1, StringValue.class).getValue()).withFailMessage("KeyGroupedIterator returned a wrong value.").isEqualTo("I");
        assertThat(this.psi.getValues().hasNext()).withFailMessage("KeyGroupedIterator must have another value.").isTrue();
        // end
        assertThat(this.psi.nextKey()).withFailMessage("KeyGroupedIterator must not have another key.").isFalse();
        assertThat(this.psi.nextKey()).withFailMessage("KeyGroupedIterator must not have another key.").isFalse();
    } catch (Exception e) {
        e.printStackTrace();
        fail("The test encountered an unexpected exception.");
    }
}

