@Test
void testExecutorService_uncaughtExceptionHandler() throws InterruptedException {
    final CountDownLatch handlerCalled = new CountDownLatch(1);
    final ThreadFactory threadFactory = new ThreadFactoryBuilder().setDaemon(true).setUncaughtExceptionHandler((t, e) -> handlerCalled.countDown()).build();
    final ExecutorService executorService = Executors.newSingleThreadExecutor(threadFactory);
    try {
        executorService.execute(() -> {
            throw new RuntimeException("foo");
        });
        // expect handler to be called
        handlerCalled.await();
    } finally {
        executorService.shutdown();
    }
}

@Test
void testScheduledExecutorService_uncaughtExceptionHandler() throws InterruptedException {
    final CountDownLatch handlerCalled = new CountDownLatch(1);
    final ThreadFactory threadFactory = new ThreadFactoryBuilder().setDaemon(true).setUncaughtExceptionHandler((t, e) -> handlerCalled.countDown()).build();
    final ScheduledExecutorService scheduledExecutorService = Executors.newSingleThreadScheduledExecutor(threadFactory);
    scheduledExecutorService.execute(() -> {
        throw new RuntimeException("foo");
    });
    assertThat(handlerCalled.await(TIMEOUT_MS, TimeUnit.MILLISECONDS)).withFailMessage("Expected handler not to be called.").isFalse();
}

