/**
 * Tests that shutdown fails all pending requests and future request triggers.
 */
@Test
void testShutDown() throws Exception {
    Map<ImmutableSet<ExecutionAttemptID>, CompletableFuture<TaskExecutorThreadInfoGateway>> executionWithGateways = createMockSubtaskWithGateways(// request future will only be completed after all gateways
    // successfully return thread infos.
    CompletionType.SUCCESSFULLY, CompletionType.NEVER_COMPLETE);
    List<CompletableFuture<VertexThreadInfoStats>> requestFutures = new ArrayList<>();
    CompletableFuture<VertexThreadInfoStats> requestFuture1 = coordinator.triggerThreadInfoRequest(executionWithGateways, DEFAULT_NUMBER_OF_SAMPLES, DEFAULT_DELAY_BETWEEN_SAMPLES, DEFAULT_MAX_STACK_TRACE_DEPTH);
    CompletableFuture<VertexThreadInfoStats> requestFuture2 = coordinator.triggerThreadInfoRequest(executionWithGateways, DEFAULT_NUMBER_OF_SAMPLES, DEFAULT_DELAY_BETWEEN_SAMPLES, DEFAULT_MAX_STACK_TRACE_DEPTH);
    // trigger request
    requestFutures.add(requestFuture1);
    requestFutures.add(requestFuture2);
    for (CompletableFuture<VertexThreadInfoStats> future : requestFutures) {
        assertThat(future).isNotDone();
    }
    // shut down
    coordinator.shutDown();
    // verify all completed
    for (CompletableFuture<VertexThreadInfoStats> future : requestFutures) {
        assertThat(future).isCompletedExceptionally();
    }
    // verify new trigger returns failed future
    CompletableFuture<VertexThreadInfoStats> future = coordinator.triggerThreadInfoRequest(executionWithGateways, DEFAULT_NUMBER_OF_SAMPLES, DEFAULT_DELAY_BETWEEN_SAMPLES, DEFAULT_MAX_STACK_TRACE_DEPTH);
