    final ZooKeeperStateHandleStore<TestingLongStateHandleHelper.LongStateHandle> storeForCreation = new ZooKeeperStateHandleStore<>(client, storage);
    final ZooKeeperStateHandleStore<TestingLongStateHandleHelper.LongStateHandle> storeForDeletion = new ZooKeeperStateHandleStore<>(client, storage);
    final String pathInZooKeeper = "/testRepeatableCleanupWithLock";
    final long actualValue = 12345L;
    final RuntimeException expectedException = new RuntimeException("RuntimeException for testing the failing discardState call.");
    final TestingLongStateHandleHelper.LongStateHandle stateHandle = new TestingLongStateHandleHelper.LongStateHandle(actualValue, throwExceptionOnce(expectedException));
    final RetrievableStateHandle<TestingLongStateHandleHelper.LongStateHandle> handleForCreation = storeForCreation.addAndLock(pathInZooKeeper, stateHandle);
    final RetrievableStateHandle<TestingLongStateHandleHelper.LongStateHandle> handleForDeletion = storeForDeletion.getAndLock(pathInZooKeeper);
    assertThat(actualValue).isEqualTo(handleForCreation.retrieveState().getValue());
    assertThat(actualValue).isEqualTo(handleForDeletion.retrieveState().getValue());
    assertThat(storeForCreation.releaseAndTryRemove(pathInZooKeeper)).as("Deletion by the first StateHandleStore shouldn't be successful because there's still a lock from StateHandleStore #1.").isFalse();
    assertThat(client.checkExists().forPath(ZooKeeperStateHandleStore.getRootLockPath(pathInZooKeeper))).as("StateHandle should not be marked for deletion, yet.").isNotNull();
    assertThat(client.checkExists().forPath(storeForCreation.getInstanceLockPath(pathInZooKeeper))).as("The lock for storeForCreation should have been removed").isNull();
    assertThat(stateHandle.getNumberOfDiscardCalls()).as("discardState shouldn't have been called, yet.").isZero();
    assertThatThrownBy(() -> storeForDeletion.releaseAndTryRemove(pathInZooKeeper)).as("Exception should have been thrown.").hasCause(expectedException);
    assertThat(client.checkExists().forPath(ZooKeeperStateHandleStore.getRootLockPath(pathInZooKeeper))).as("StateHandle should be marked for deletion.").isNull();
    assertThat(client.checkExists().forPath(pathInZooKeeper)).as("StateHandle should not be deleted, yet.").isNotNull();
    assertThat(stateHandle.isDiscarded()).as("The StateHandle should not be discarded, yet.").isFalse();
    assertThat(storeForDeletion.releaseAndTryRemove(pathInZooKeeper)).isTrue();
    assertThat(client.checkExists().forPath(pathInZooKeeper)).as("The StateHandle node should have been removed").isNull();
    assertThat(stateHandle.isDiscarded()).as("The StateHandle should have been discarded.").isTrue();
}

