@Test
void testGetAllAndLockOnConcurrentDelete() throws Exception {
    final TestingLongStateHandleHelper stateHandleProvider = new TestingLongStateHandleHelper();
    final CuratorFramework client = ZooKeeperUtils.useNamespaceAndEnsurePath(getZooKeeperClient(), "/testGetAllAndLockOnConcurrentDelete");
    // this store simulates the ZooKeeper connection for maintaining the lifecycle (i.e.
    // creating and deleting the nodes) of the StateHandles
    final ZooKeeperStateHandleStore<TestingLongStateHandleHelper.LongStateHandle> storeForCreationAndDeletion = new ZooKeeperStateHandleStore<>(client, stateHandleProvider);
    // this store simulates a concurrent access to ZooKeeper
    final ZooKeeperStateHandleStore<TestingLongStateHandleHelper.LongStateHandle> storeForRetrieval = new ZooKeeperStateHandleStore<>(client, stateHandleProvider);
    final String pathInZooKeeperPrefix = "/node";
    final long stateForDeletion = 42L;
    final String handlePathForDeletion = pathInZooKeeperPrefix + "-for-deletion";
    storeForCreationAndDeletion.addAndLock(handlePathForDeletion, new TestingLongStateHandleHelper.LongStateHandle(stateForDeletion));
    final long stateToKeep = stateForDeletion + 2;
    storeForCreationAndDeletion.addAndLock(pathInZooKeeperPrefix + "-keep", new TestingLongStateHandleHelper.LongStateHandle(stateToKeep));
    final List<Tuple2<RetrievableStateHandle<TestingLongStateHandleHelper.LongStateHandle>, String>> actuallyLockedHandles = storeForRetrieval.getAllAndLock(parentPath -> {
        final List<String> childNodes = client.getChildren().forPath(parentPath);
        // the following block simulates the concurrent deletion of the
        // child node after the node names are delivered to the
        // storeForRetrieval causing a retry
        if (storeForCreationAndDeletion.exists(handlePathForDeletion).isExisting()) {
            storeForCreationAndDeletion.releaseAndTryRemove(handlePathForDeletion);
        }
        return childNodes;
    });
    assertThat(Iterables.getOnlyElement(actuallyLockedHandles).f0.retrieveState().getValue()).as("Only the StateHandle that was expected to be kept should be returned.").isEqualTo(stateToKeep);
}

