    assertThat(vertices.get(1).getSlotSharingGroup()).isNotEqualTo(vertices.get(4).getSlotSharingGroup());
    // second pipeline
    assertThat(vertices.get(2).getSlotSharingGroup()).isEqualTo(vertices.get(3).getSlotSharingGroup()).isEqualTo(vertices.get(5).getSlotSharingGroup());
