/**
 * This test verifies that all ListState implementations are consistent in not allowing adding
 * {@code null}.
 */
@Test
void testListStateAddNull() throws Exception {
    CheckpointableKeyedStateBackend<String> keyedBackend = createKeyedBackend(StringSerializer.INSTANCE);
    final ListStateDescriptor<Long> stateDescr = new ListStateDescriptor<>("my-state", Long.class);
    try {
        ListState<Long> state = keyedBackend.getPartitionedState(VoidNamespace.INSTANCE, VoidNamespaceSerializer.INSTANCE, stateDescr);
        keyedBackend.setCurrentKey("abc");
        assertThat(state.get()).isNull();
        assertThatThrownBy(() -> state.add(null)).isInstanceOf(NullPointerException.class);
    } finally {
        keyedBackend.close();
        keyedBackend.dispose();
    }
}

