void testListStateAPIs() throws Exception {
    final ListStateDescriptor<Long> stateDescr = new ListStateDescriptor<>("my-state", Long.class);
    try (CheckpointableKeyedStateBackend<String> keyedBackend = createKeyedBackend(StringSerializer.INSTANCE)) {
        ListState<Long> state = keyedBackend.getPartitionedState(VoidNamespace.INSTANCE, VoidNamespaceSerializer.INSTANCE, stateDescr);
        keyedBackend.setCurrentKey("g");
