/**
 * Verify iterator of {@link MapState} supporting arbitrary access, see [FLINK-10267] to know
 * more details.
 */
@Test
void testMapStateIteratorArbitraryAccess() throws Exception {
    MapStateDescriptor<Integer, Long> kvId = new MapStateDescriptor<>("id", Integer.class, Long.class);
    CheckpointableKeyedStateBackend<Integer> backend = createKeyedBackend(IntSerializer.INSTANCE);
    try {
        MapState<Integer, Long> state = backend.getPartitionedState(VoidNamespace.INSTANCE, VoidNamespaceSerializer.INSTANCE, kvId);
        backend.setCurrentKey(1);
        int stateSize = 4096;
        for (int i = 0; i < stateSize; i++) {
            state.put(i, i * 2L);
        }
        Iterator<Map.Entry<Integer, Long>> iterator = state.iterator();
        int iteratorCount = 0;
        while (iterator.hasNext()) {
            Map.Entry<Integer, Long> entry = iterator.next();
            assertThat(entry.getKey()).isEqualTo(iteratorCount);
            switch(ThreadLocalRandom.current().nextInt() % 3) {
                case // remove twice
                0:
                    iterator.remove();
                    assertThatThrownBy(iterator::remove).isInstanceOf(IllegalStateException.class);
                    break;
                case // hasNext -> remove
                1:
                    iterator.hasNext();
                    iterator.remove();
                    break;
                case // nothing to do
                2:
                    break;
            }
            iteratorCount++;
        }
        assertThat(iteratorCount).isEqualTo(stateSize);
    } finally {
        backend.dispose();
    }
}

