@Test
void testMainAndPerSplitWatermarkIdleness() throws Exception {
    final WatermarkStrategy<Integer> watermarkStrategy = WatermarkStrategy.forGenerator((ctx) -> new OnEventTestWatermarkGenerator<>());
    InterpretingSourceReader reader = new InterpretingSourceReader(// Emit from main output
    output -> output.collect(0, 100L), // Mark main output as idle
    // This should not generate IDLE event as per-split output is active
    ReaderOutput::markIdle, // Emit from per-split output
    output -> output.createOutputForSplit("1").collect(0, 150L), output -> output.createOutputForSplit("2").collect(0, 200L), // Mark output of split 1 as idle
    // This should not generate IDLE event as output of split 2 is active
    output -> output.createOutputForSplit("1").markIdle(), // Mark output of split 2 as idle
    // Expect to have an IDLE event as all outputs (main, split 1 and split 2)
    // are idle
    output -> output.createOutputForSplit("2").markIdle(), // Emit from main output
    // Expect to have an ACTIVE event
    output -> output.collect(0, 250L), // Mark output 1 and 2 as idle again
    // This should not generate IDLE event as main output is active
    output -> output.createOutputForSplit("1").markIdle(), output -> output.createOutputForSplit("2").markIdle(), // Mark main output as idle again to test active from per-split output
    // Expect to have an IDLE event
    ReaderOutput::markIdle, // Emit from per-split output
    // Expect to have an ACTIVE event
    output -> output.createOutputForSplit("1").collect(0, 300L));
    SourceOperator<Integer, MockSourceSplit> sourceOperator = createTestOperator(reader, watermarkStrategy, true);
    List<Object> events = testSequenceOfEvents(sourceOperator);
    assertThat(events).containsExactly(// Record and watermark from main output
    new StreamRecord<>(0, 100L), new Watermark(100L), new WatermarkStatus(WatermarkStatus.IDLE_STATUS), // Record and watermark from split 1
    new StreamRecord<>(0, 150L), new WatermarkStatus(WatermarkStatus.ACTIVE_STATUS), new Watermark(150L), // Record and watermark from split 2
    new StreamRecord<>(0, 200L), new Watermark(200L), // IDLE event as output of main, split 1 and split 2 are idle
    new WatermarkStatus(WatermarkStatus.IDLE_STATUS), // Record and watermark from main output, together with an ACTIVE event
    new StreamRecord<>(0, 250L), new WatermarkStatus(WatermarkStatus.ACTIVE_STATUS), new Watermark(250L), // IDLE event as output of main, split 1 and split 2 are idle
    new WatermarkStatus(WatermarkStatus.IDLE_STATUS), // Record and watermark from split 1, together with an ACTIVE event
    new StreamRecord<>(0, 300L), new WatermarkStatus(WatermarkStatus.ACTIVE_STATUS), new Watermark(300));
}

