    assertThat(metrics.getDurationMetrics()).hasSize(2).containsEntry(MetricNames.RESTORED_STATE_SIZE + "." + StateObject.StateObjectLocation.LOCAL_MEMORY.name(), expectedSumLocalMemory).containsEntry(MetricNames.RESTORED_STATE_SIZE + "." + StateObject.StateObjectLocation.UNKNOWN.name(), expectedSumUnknown);
