@Test
void periodicWatermarksEmitOnPeriodicEmitStreamMode() throws Exception {
    OneInputStreamOperatorTestHarness<Long, Long> testHarness = createTestHarness(WatermarkStrategy.forGenerator((ctx) -> new PeriodicWatermarkGenerator()).withTimestampAssigner((ctx) -> new LongExtractor()));
    testHarness.processElement(new StreamRecord<>(2L, 1));
