@Test
void watermarksWithIdlenessUnderBackpressure() throws Exception {
    long idleTimeout = 100;
    TimestampsAndWatermarksOperatorFactory<Tuple2<Boolean, Long>> operator = new TimestampsAndWatermarksOperatorFactory<>(WatermarkStrategy.forGenerator((ctx) -> new PunctuatedWatermarkGenerator()).withTimestampAssigner((ctx) -> new TupleExtractor()).withIdleness(Duration.ofMillis(idleTimeout)), true);
    OneInputStreamOperatorTestHarness<Tuple2<Boolean, Long>, Tuple2<Boolean, Long>> testHarness = new OneInputStreamOperatorTestHarness<>(operator);
    testHarness.open();
    TaskIOMetricGroup taskIOMetricGroup = testHarness.getEnvironment().getMetricGroup().getIOMetricGroup();
    taskIOMetricGroup.getHardBackPressuredTimePerSecond().markStart();
    for (int i = 0; i < 10; i++) {
        testHarness.advanceTime(idleTimeout);
    }
    assertThat(testHarness.getOutput()).isEmpty();
    taskIOMetricGroup.getHardBackPressuredTimePerSecond().markEnd();
    taskIOMetricGroup.getSoftBackPressuredTimePerSecond().markStart();
    for (int i = 10; i < 20; i++) {
        testHarness.advanceTime(idleTimeout);
    }
    assertThat(testHarness.getOutput()).isEmpty();
    taskIOMetricGroup.getSoftBackPressuredTimePerSecond().markEnd();
    for (int i = 20; i < 30; i++) {
        testHarness.advanceTime(idleTimeout);
    }
    assertThat(testHarness.getOutput()).containsExactly(WatermarkStatus.IDLE);
}

/**
 * Verify that state of separate windows does not leak into other windows.
 */
@Test
void testWindowSeparationAndFiring() throws Exception {
    TriggerTestHarness<Object, TimeWindow> testHarness = new TriggerTestHarness<>(CountTrigger.of(3), new TimeWindow.Serializer());
    assertThat(testHarness.processElement(new StreamRecord<>(1), new TimeWindow(0, 2))).isEqualTo(TriggerResult.CONTINUE);
    assertThat(testHarness.processElement(new StreamRecord<>(1), new TimeWindow(2, 4))).isEqualTo(TriggerResult.CONTINUE);
    // shouldn't have any timers
    assertThat(testHarness.numProcessingTimeTimers()).isZero();
    assertThat(testHarness.numEventTimeTimers()).isZero();
    assertThat(testHarness.numStateEntries()).isEqualTo(2);
    assertThat(testHarness.numStateEntries(new TimeWindow(0, 2))).isOne();
    assertThat(testHarness.numStateEntries(new TimeWindow(2, 4))).isOne();
    assertThat(testHarness.processElement(new StreamRecord<>(1), new TimeWindow(0, 2))).isEqualTo(TriggerResult.CONTINUE);
    assertThat(testHarness.processElement(new StreamRecord<>(1), new TimeWindow(0, 2))).isEqualTo(TriggerResult.FIRE);
    assertThat(testHarness.processElement(new StreamRecord<>(1), new TimeWindow(2, 4))).isEqualTo(TriggerResult.CONTINUE);
    // right now, CountTrigger will clear it's state in onElement when firing
    // ideally, this should be moved to onFire()
    assertThat(testHarness.numStateEntries()).isOne();
    assertThat(testHarness.numStateEntries(new TimeWindow(0, 2))).isZero();
    assertThat(testHarness.numStateEntries(new TimeWindow(2, 4))).isOne();
    assertThat(testHarness.processElement(new StreamRecord<>(1), new TimeWindow(2, 4))).isEqualTo(TriggerResult.FIRE);
    // now all state should be gone
    assertThat(testHarness.numStateEntries()).isZero();
}

