            context.registerEventTimeTimer(2);
            context.registerEventTimeTimer(3);
            context.registerEventTimeTimer(4);
            return TriggerResult.CONTINUE;
        }
    }).when(mockTrigger).onElement(ArgumentMatchers.any(), anyLong(), anyTimeWindow(), anyTriggerContext());
    // set up our timers
    testHarness.processElement(new StreamRecord<>(1), new TimeWindow(0, 2));
    assertThat(testHarness.numEventTimeTimers(new TimeWindow(0, 2))).isEqualTo(4);
    when(mockTrigger.onEventTime(anyLong(), anyTimeWindow(), anyTriggerContext())).thenReturn(TriggerResult.CONTINUE);
    assertThat(testHarness.advanceWatermark(1, new TimeWindow(0, 2))).isEqualTo(TriggerResult.CONTINUE);
    when(mockTrigger.onEventTime(anyLong(), anyTimeWindow(), anyTriggerContext())).thenReturn(TriggerResult.FIRE);
    assertThat(testHarness.advanceWatermark(2, new TimeWindow(0, 2))).isEqualTo(TriggerResult.FIRE_AND_PURGE);
    when(mockTrigger.onEventTime(anyLong(), anyTimeWindow(), anyTriggerContext())).thenReturn(TriggerResult.FIRE_AND_PURGE);
    assertThat(testHarness.advanceWatermark(3, new TimeWindow(0, 2))).isEqualTo(TriggerResult.FIRE_AND_PURGE);
    when(mockTrigger.onEventTime(anyLong(), anyTimeWindow(), anyTriggerContext())).thenReturn(TriggerResult.PURGE);
    assertThat(testHarness.advanceWatermark(4, new TimeWindow(0, 2))).isEqualTo(TriggerResult.PURGE);
    doAnswer(new Answer<TriggerResult>() {

        @Override
        public TriggerResult answer(InvocationOnMock invocation) throws Exception {
            Trigger.TriggerContext context = (Trigger.TriggerContext) invocation.getArguments()[3];
            // register some timers that we can step through to call onEventTime
            // several
            // times in a row
            context.registerProcessingTimeTimer(1);
            context.registerProcessingTimeTimer(2);
            context.registerProcessingTimeTimer(3);
            context.registerProcessingTimeTimer(4);
            return TriggerResult.CONTINUE;
        }
    }).when(mockTrigger).onElement(ArgumentMatchers.any(), anyLong(), anyTimeWindow(), anyTriggerContext());
    // set up our timers
    testHarness.processElement(new StreamRecord<>(1), new TimeWindow(0, 2));
    assertThat(testHarness.numProcessingTimeTimers(new TimeWindow(0, 2))).isEqualTo(4);
    assertThat(testHarness.numEventTimeTimers(new TimeWindow(0, 2))).isZero();
