    when(mockAssigner.assignWindows(anyInt(), anyLong(), anyAssignerContext())).thenReturn(Collections.singletonList(new TimeWindow(0, 2)));
    testHarness.processElement(new StreamRecord<>(0, 0L));
    when(mockAssigner.assignWindows(anyInt(), anyLong(), anyAssignerContext())).thenReturn(Collections.singletonList(new TimeWindow(0, 1)));
    testHarness.processElement(new StreamRecord<>(1, 0L));
    // no output so far
    assertThat(testHarness.extractOutputStreamRecords()).isEmpty();
    // state for two windows
    assertThat(testHarness.numKeyedStateEntries()).isEqualTo(2);
    assertThat(testHarness.numEventTimeTimers()).isEqualTo(2);
    // now we fire
    shouldFireOnElement(mockTrigger);
    when(mockAssigner.assignWindows(anyInt(), anyLong(), anyAssignerContext())).thenReturn(Collections.singletonList(new TimeWindow(0, 1)));
    testHarness.processElement(new StreamRecord<>(1, 0L));
    when(mockAssigner.assignWindows(anyInt(), anyLong(), anyAssignerContext())).thenReturn(Collections.singletonList(new TimeWindow(0, 2)));
    testHarness.processElement(new StreamRecord<>(0, 0L));
    verify(mockWindowFunction, times(2)).process(anyInt(), anyTimeWindow(), anyInternalWindowContext(), anyIntIterable(), WindowOperatorContractTest.anyCollector());
    verify(mockWindowFunction, times(1)).process(eq(0), eq(new TimeWindow(0, 2)), anyInternalWindowContext(), intIterable(0, 0), WindowOperatorContractTest.anyCollector());
    verify(mockWindowFunction, times(1)).process(eq(1), eq(new TimeWindow(0, 1)), anyInternalWindowContext(), intIterable(1, 1), WindowOperatorContractTest.anyCollector());
}

