        assertThatThrownBy(() -> timer.scheduleAtFixedRate(timestamp -> fail("should not be called"), 0L, 100L)).isInstanceOf(IllegalStateException.class);
        // check that the task eventually responded to interruption
        assertThat(errorFuture.get(30L, TimeUnit.SECONDS)).isInstanceOf(InterruptedException.class);
