    FieldAccessor<Tuple2<String, Tuple3<Integer, Long, Double>>, Tuple3<Integer, Long, Double>> f1 = FieldAccessorFactory.getAccessor(tpeInfo, "f1", null);
    assertThat(f1.getFieldType().getTypeClass()).isEqualTo(Tuple3.class);
