    // we don't set the content-encoding header
    assertThat(taskManagerConnection.getContentEncoding()).isNull();
    assertThat(taskManagerConnection.getContentType()).isEqualTo("application/json; charset=UTF-8");
    // check headers in case of an error
    URL notFoundJobUrl = new URL("http://localhost:" + restAddress.getPort() + "/jobs/dontexist");
    HttpURLConnection notFoundJobConnection = (HttpURLConnection) notFoundJobUrl.openConnection();
    notFoundJobConnection.setConnectTimeout(100000);
    notFoundJobConnection.connect();
    assertThat(notFoundJobConnection).satisfies(c -> assertThat(c.getResponseCode()).isGreaterThanOrEqualTo(400)).// we don't set the content-encoding header
