@Test
void testTransferredSstCanBeCleanedUp() throws Exception {
    SpecifiedException expectedException = new SpecifiedException("throw exception while multi thread transfer states.");
    File checkpointPrivateFolder = TempDirUtils.newFolder(temporaryFolder, "private");
    Path checkpointPrivateDirectory = Path.fromLocalFile(checkpointPrivateFolder);
    File checkpointSharedFolder = TempDirUtils.newFolder(temporaryFolder, "shared");
    Path checkpointSharedDirectory = Path.fromLocalFile(checkpointSharedFolder);
    FileSystem fileSystem = checkpointPrivateDirectory.getFileSystem();
    int sstFileCount = 6;
    int fileStateSizeThreshold = 1024;
    int writeBufferSize = 4096;
    CheckpointStreamFactory checkpointStreamFactory = new FsCheckpointStreamFactory(fileSystem, checkpointPrivateDirectory, checkpointSharedDirectory, fileStateSizeThreshold, writeBufferSize);
    String localFolder = "local";
    TempDirUtils.newFolder(temporaryFolder, localFolder);
    List<Path> filePaths = generateRandomSstFiles(localFolder, sstFileCount, fileStateSizeThreshold);
    CloseableRegistry tmpResourcesRegistry = new CloseableRegistry();
    try (ForStStateDataTransfer stateTransfer = new ForStStateDataTransfer(1)) {
        stateTransfer.transferFilesToCheckpointFs(SnapshotType.SharingFilesStrategy.FORWARD_BACKWARD, filePaths, checkpointStreamFactory, CheckpointedStateScope.SHARED, new CloseableRegistry(), tmpResourcesRegistry, false);
        assertThatThrownBy(() -> stateTransfer.transferFilesToCheckpointFs(SnapshotType.SharingFilesStrategy.FORWARD_BACKWARD, filePaths, new LastFailingCheckpointStateOutputStreamFactory(checkpointStreamFactory, sstFileCount, expectedException), CheckpointedStateScope.SHARED, new CloseableRegistry(), tmpResourcesRegistry, false)).isEqualTo(expectedException);
        assertThat(checkpointPrivateFolder.list()).isEmpty();
        assertThat(checkpointSharedFolder.list()).isNotEmpty();
        tmpResourcesRegistry.close();
        // Check whether the temporary file before the exception can be cleaned up
        assertThat(checkpointPrivateFolder.list()).isEmpty();
        assertThat(checkpointSharedFolder.list()).isEmpty();
        Path first = filePaths.stream().findFirst().get();
        assertThatThrownBy(() -> stateTransfer.transferFilesToCheckpointFs(SnapshotType.SharingFilesStrategy.FORWARD_BACKWARD, Collections.singletonList(first), checkpointStreamFactory, CheckpointedStateScope.SHARED, new CloseableRegistry(), tmpResourcesRegistry, false)).as("Cannot register Closeable, registry is already closed. Closing argument.").isInstanceOf(IOException.class);
        // Check whether the temporary file after the exception can be cleaned up.
        assertThat(checkpointPrivateFolder.list()).isEmpty();
        assertThat(checkpointSharedFolder.list()).isEmpty();
    }
}

