        validHarnessResult(harness2[1], 2, records[5], records[6], records[7], records[8], records[9]);
        snapshot2 = AbstractStreamOperatorTestHarness.repackageState(harness2[0].snapshot(0, 0), harness2[1].snapshot(0, 0));
    } finally {
