@Test
void testKryoRestoreResilienceWithDifferentRegistrationOrder(@TempDir File newTmpDir) throws Exception {
    // register A first then B
    ((SerializerConfigImpl) env.getExecutionConfig().getSerializerConfig()).registerKryoType(StateBackendTestBase.TestNestedPojoClassA.class);
    ((SerializerConfigImpl) env.getExecutionConfig().getSerializerConfig()).registerKryoType(StateBackendTestBase.TestNestedPojoClassB.class);
    TypeInformation<StateBackendTestBase.TestPojo> pojoType = new GenericTypeInfo<>(StateBackendTestBase.TestPojo.class);
    // make sure that we are in fact using the KryoSerializer
    assertThat(pojoType.createSerializer(env.getExecutionConfig().getSerializerConfig())).isInstanceOf(KryoSerializer.class);
    ValueStateDescriptor<StateBackendTestBase.TestPojo> stateDescriptor = new ValueStateDescriptor<>("id", pojoType);
    ValueState<StateBackendTestBase.TestPojo> state = keyedBackend.getOrCreateKeyedState(1, IntSerializer.INSTANCE, stateDescriptor);
    // access the internal state representation to retrieve the original Kryo registration
    // ids;
    // these will be later used to check that on restore, the new Kryo serializer has
    // reconfigured itself to
    // have identical mappings
    AbstractKeyedState abstractKeyedState = (AbstractKeyedState) state;
    KryoSerializer<StateBackendTestBase.TestPojo> kryoSerializer = (KryoSerializer<StateBackendTestBase.TestPojo>) abstractKeyedState.getValueSerializer();
    int mainPojoClassRegistrationId = kryoSerializer.getKryo().getRegistration(StateBackendTestBase.TestPojo.class).getId();
    int nestedPojoClassARegistrationId = kryoSerializer.getKryo().getRegistration(StateBackendTestBase.TestNestedPojoClassA.class).getId();
    int nestedPojoClassBRegistrationId = kryoSerializer.getKryo().getRegistration(StateBackendTestBase.TestNestedPojoClassB.class).getId();
    // ============== create snapshot of current configuration ==============
    // make some more modifications
    setCurrentContext("test", "test");
    state.asyncUpdate(new StateBackendTestBase.TestPojo("u1", 1, new StateBackendTestBase.TestNestedPojoClassA(1.0, 2), new StateBackendTestBase.TestNestedPojoClassB(2.3, "foo")));
    drain();
    RunnableFuture<SnapshotResult<KeyedStateHandle>> snapshot = keyedBackend.snapshot(1L, System.currentTimeMillis(), env.getCheckpointStorageAccess().resolveCheckpointStorageLocation(1L, CheckpointStorageLocationReference.getDefault()), CheckpointOptions.forCheckpointWithDefaultLocation());
    if (!snapshot.isDone()) {
        snapshot.run();
    }
    SnapshotResult<KeyedStateHandle> snapshotResult = snapshot.get();
    KeyedStateHandle stateHandle = snapshotResult.getJobManagerOwnedSnapshot();
    IOUtils.closeQuietly(keyedBackend);
    keyedBackend.dispose();
    env = getMockEnvironment(newTmpDir);
    ((SerializerConfigImpl) env.getExecutionConfig().getSerializerConfig()).registerKryoType(StateBackendTestBase.TestNestedPojoClassB.class);
    // this time register B first
    ((SerializerConfigImpl) env.getExecutionConfig().getSerializerConfig()).registerKryoType(StateBackendTestBase.TestNestedPojoClassA.class);
    FileSystem.initialize(new Configuration(), null);
    Configuration configuration = new Configuration();
    ForStStateBackend forStStateBackend = new ForStStateBackend().configure(configuration, null);
    ForStKeyedStateBackend<String> restoredKeyedStateBackend = createKeyedStateBackend(forStStateBackend, env, StringSerializer.INSTANCE, Collections.singletonList(stateHandle));
    restoredKeyedStateBackend.setup(aec);
    // re-initialize to ensure that we create the KryoSerializer from scratch, otherwise
    // initializeSerializerUnlessSet would not pick up our new config
    stateDescriptor = new ValueStateDescriptor<>("id", pojoType);
    state = restoredKeyedStateBackend.getOrCreateKeyedState(1, IntSerializer.INSTANCE, stateDescriptor);
    // verify that on restore, the serializer that the state handle uses has reconfigured
    // itself to have
    // identical Kryo registration ids compared to the previous execution
    abstractKeyedState = (AbstractKeyedState) state;
    kryoSerializer = (KryoSerializer<StateBackendTestBase.TestPojo>) abstractKeyedState.getValueSerializer();
    assertThat(kryoSerializer.getKryo().getRegistration(StateBackendTestBase.TestPojo.class).getId()).isEqualTo(mainPojoClassRegistrationId);
    assertThat(kryoSerializer.getKryo().getRegistration(StateBackendTestBase.TestNestedPojoClassA.class).getId()).isEqualTo(nestedPojoClassARegistrationId);
    assertThat(kryoSerializer.getKryo().getRegistration(StateBackendTestBase.TestNestedPojoClassB.class).getId()).isEqualTo(nestedPojoClassBRegistrationId);
    setCurrentContext("test", "test");
    // update to test state backends that eagerly serialize, such as RocksDB
    state.asyncUpdate(new StateBackendTestBase.TestPojo("u1", 11, new StateBackendTestBase.TestNestedPojoClassA(22.1, 12), new StateBackendTestBase.TestNestedPojoClassB(1.23, "foobar")));
    RunnableFuture<SnapshotResult<KeyedStateHandle>> snapshot1 = restoredKeyedStateBackend.snapshot(1L, System.currentTimeMillis(), env.getCheckpointStorageAccess().resolveCheckpointStorageLocation(1L, CheckpointStorageLocationReference.getDefault()), CheckpointOptions.forCheckpointWithDefaultLocation());
    if (!snapshot1.isDone()) {
        snapshot1.run();
    }
    snapshot1.get().discardState();
}

