 */
@Test
void testReleaseSnapshot() {
    int expectedSnapshotVersion = 0;
    int round = 10;
    for (int i = 0; i < round; i++) {
        assertThat(stateMap.getStateMapVersion()).isEqualTo(expectedSnapshotVersion);
        assertThat(stateMap.getHighestFinishedSnapshotVersion()).isEqualTo(expectedSnapshotVersion);
        CopyOnWriteSkipListStateMapSnapshot<Integer, Long, String> snapshot = stateMap.stateSnapshot();
