// Verify the next checkpoint is still incremental after a savepoint completed.
@Test
void testCheckpointIsIncremental() throws Exception {
    try (CloseableRegistry closeableRegistry = new CloseableRegistry();
        RocksIncrementalSnapshotStrategy<?> checkpointSnapshotStrategy = createSnapshotStrategy()) {
        FsCheckpointStreamFactory checkpointStreamFactory = createFsCheckpointStreamFactory();
        // make and notify checkpoint with id 1
        snapshot(1L, checkpointSnapshotStrategy, checkpointStreamFactory, closeableRegistry);
        checkpointSnapshotStrategy.notifyCheckpointComplete(1L);
        // notify savepoint with id 2
        checkpointSnapshotStrategy.notifyCheckpointComplete(2L);
        // make checkpoint with id 3
        IncrementalRemoteKeyedStateHandle incrementalRemoteKeyedStateHandle3 = snapshot(3L, checkpointSnapshotStrategy, checkpointStreamFactory, closeableRegistry);
        // If 3rd checkpoint's full size > checkpointed size, it means 3rd checkpoint is
        // incremental.
        assertThat(incrementalRemoteKeyedStateHandle3.getStateSize()).isGreaterThan(incrementalRemoteKeyedStateHandle3.getCheckpointedSize());
    }
}

@Test
void testClose() throws InterruptedException {
    RocksDBManualCompactionConfig config = RocksDBManualCompactionConfig.getDefault();
    ManuallyTriggeredScheduledExecutorService scheduledExecutor = new ManuallyTriggeredScheduledExecutorService();
    ManuallyTriggeredScheduledExecutorService ioExecutor = new ManuallyTriggeredScheduledExecutorService();
    CompactionScheduler compactionScheduler = new CompactionScheduler(config, ioExecutor, new CompactionTaskProducer(Collections::emptyList, config, new ColumnFamilyLookup()), new Compactor(Compactor.CompactionTarget.NO_OP, 1L), new CompactionTracker(config, ign -> 0L), scheduledExecutor);
    compactionScheduler.start();
    scheduledExecutor.triggerScheduledTasks();
    compactionScheduler.stop();
    // should not fail e.g. because compactionScheduler was stopped
    ioExecutor.triggerAll();
    ioExecutor.shutdown();
}

