    ResourceSpec preferredResource6 = ResourceSpec.newBuilder(2.0, 700).build();
    ResourceSpec minResource7 = ResourceSpec.newBuilder(1.0, 700).build();
    ResourceSpec preferredResource7 = ResourceSpec.newBuilder(2.0, 800).build();
    Method opMethod = SingleOutputStreamOperator.class.getDeclaredMethod("setResources", ResourceSpec.class, ResourceSpec.class);
    opMethod.setAccessible(true);
    Method sinkMethod = DataStreamSink.class.getDeclaredMethod("setResources", ResourceSpec.class, ResourceSpec.class);
    sinkMethod.setAccessible(true);
    DataStream<Long> source1 = env.fromSequence(0, 0);
    opMethod.invoke(source1, minResource1, preferredResource1);
    DataStream<Long> map1 = source1.map(new MapFunction<Long, Long>() {

        @Override
        public Long map(Long value) throws Exception {
            return null;
        }
    });
    opMethod.invoke(map1, minResource2, preferredResource2);
    DataStream<Long> source2 = env.fromSequence(0, 0);
    opMethod.invoke(source2, minResource3, preferredResource3);
    DataStream<Long> map2 = source2.map(new MapFunction<Long, Long>() {

        @Override
        public Long map(Long value) throws Exception {
            return null;
        }
    });
    opMethod.invoke(map2, minResource4, preferredResource4);
    DataStream<Long> connected = map1.connect(map2).flatMap(new CoFlatMapFunction<Long, Long, Long>() {

        @Override
        public void flatMap1(Long value, Collector<Long> out) throws Exception {
        }

        @Override
        public void flatMap2(Long value, Collector<Long> out) throws Exception {
        }
    });
    opMethod.invoke(connected, minResource5, preferredResource5);
    DataStream<Long> windowed = connected.windowAll(GlobalWindows.create()).trigger(PurgingTrigger.of(CountTrigger.of(10))).reduce(new ReduceFunction<Long>() {

        private static final long serialVersionUID = 1L;

        @Override
        public Long reduce(Long value1, Long value2) throws Exception {
            return null;
        }
    });
    opMethod.invoke(windowed, minResource6, preferredResource6);
    DataStreamSink<Long> sink = windowed.print();
    sinkMethod.invoke(sink, minResource7, preferredResource7);
    assertThat(getStreamGraph(env).getStreamNode(source1.getId()).getMinResources()).isEqualTo(minResource1);
    assertThat(getStreamGraph(env).getStreamNode(source1.getId()).getPreferredResources()).isEqualTo(preferredResource1);
    assertThat(getStreamGraph(env).getStreamNode(map1.getId()).getMinResources()).isEqualTo(minResource2);
    assertThat(getStreamGraph(env).getStreamNode(map1.getId()).getPreferredResources()).isEqualTo(preferredResource2);
    assertThat(getStreamGraph(env).getStreamNode(source2.getId()).getMinResources()).isEqualTo(minResource3);
    assertThat(getStreamGraph(env).getStreamNode(source2.getId()).getPreferredResources()).isEqualTo(preferredResource3);
    assertThat(getStreamGraph(env).getStreamNode(map2.getId()).getMinResources()).isEqualTo(minResource4);
    assertThat(getStreamGraph(env).getStreamNode(map2.getId()).getPreferredResources()).isEqualTo(preferredResource4);
    assertThat(getStreamGraph(env).getStreamNode(connected.getId()).getMinResources()).isEqualTo(minResource5);
    assertThat(getStreamGraph(env).getStreamNode(connected.getId()).getPreferredResources()).isEqualTo(preferredResource5);
    assertThat(getStreamGraph(env).getStreamNode(windowed.getId()).getMinResources()).isEqualTo(minResource6);
    assertThat(getStreamGraph(env).getStreamNode(windowed.getId()).getPreferredResources()).isEqualTo(preferredResource6);
    assertThat(getStreamGraph(env).getStreamNode(sink.getTransformation().getId()).getMinResources()).isEqualTo(minResource7);
    assertThat(getStreamGraph(env).getStreamNode(sink.getTransformation().getId()).getPreferredResources()).isEqualTo(preferredResource7);
