@Test
void testConcurrentSetContext() throws Exception {
    int numThreads = 20;
    final CountDownLatch waitingThreadCount = new CountDownLatch(numThreads);
    final OneShotLatch latch = new OneShotLatch();
    final List<CheckedThread> threads = new ArrayList<>();
    for (int x = 0; x < numThreads; x++) {
        final CheckedThread thread = new CheckedThread() {

            @Override
            public void go() {
                final StreamExecutionEnvironment preparedEnvironment = new StreamExecutionEnvironment();
                StreamExecutionEnvironment.initializeContextEnvironment(configuration -> preparedEnvironment);
                try {
                    waitingThreadCount.countDown();
                    latch.awaitQuietly();
                    assertThat(StreamExecutionEnvironment.getExecutionEnvironment()).isSameAs(preparedEnvironment);
                } finally {
                    StreamExecutionEnvironment.resetContextEnvironment();
                }
            }
        };
        thread.start();
        threads.add(thread);
    }
    // wait for all threads to be ready and trigger the job submissions at the same time
    waitingThreadCount.await();
    latch.trigger();
    for (CheckedThread thread : threads) {
        thread.sync();
    }
}

