        testHarness.notifyOfCompletedCheckpoint(// all the pending for checkpoint 2 and 3 are committed
        3L);
        TestUtils.checkLocalFs(outDir, 0, 4);
        fileCounter = 0;
        for (Map.Entry<File, String> fileContents : TestUtils.getFileContentByPath(outDir).entrySet()) {
            if (fileContents.getKey().getName().equals("part-0-0")) {
                fileCounter++;
                assertThat(fileContents.getValue()).isEqualTo("test1@1\ntest1@2\n");
