@Test
void testCreateJobVertexLazily() {
    final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
    env.setParallelism(1);
    DataStream<Tuple2<String, String>> input = env.fromData("a", "b", "c", "d", "e", "f").map(new MapFunction<String, Tuple2<String, String>>() {

        @Override
        public Tuple2<String, String> map(String value) {
            return new Tuple2<>(value, value);
        }
    });
    DataStream<Tuple2<String, String>> result = input.keyBy(x -> x.f0).map(new MapFunction<Tuple2<String, String>, Tuple2<String, String>>() {

        @Override
        public Tuple2<String, String> map(Tuple2<String, String> value) {
            return value;
        }
    });
    result.sinkTo(new DiscardingSink<>());
    StreamGraph streamGraph = env.getStreamGraph();
    streamGraph.setDynamic(true);
    AdaptiveGraphManager adaptiveGraphManager = new AdaptiveGraphManager(Thread.currentThread().getContextClassLoader(), streamGraph, Runnable::run);
    JobGraph jobGraph = adaptiveGraphManager.getJobGraph();
    List<JobVertex> jobVertices = jobGraph.getVerticesSortedTopologicallyFromSources();
    assertThat(jobVertices.size()).isEqualTo(1);
    while (!jobVertices.isEmpty()) {
        List<JobVertex> newJobVertices = new ArrayList<>();
        for (JobVertex jobVertex : jobVertices) {
            newJobVertices.addAll(adaptiveGraphManager.onJobVertexFinished(jobVertex.getID()));
        }
        jobVertices = newJobVertices;
    }
    jobVertices = jobGraph.getVerticesSortedTopologicallyFromSources();
    List<StreamNode> streamNodes = streamGraph.getStreamNodes().stream().sorted(Comparator.comparingInt(StreamNode::getId)).collect(Collectors.toList());
    assertThat(jobVertices.size()).isEqualTo(2);
    assertThat(adaptiveGraphManager.getPendingOperatorsCount()).isEqualTo(0);
    assertThat(adaptiveGraphManager.getStreamNodeIdsByJobVertexId(jobVertices.get(0).getID())).isEqualTo(List.of(streamNodes.get(1).getId(), streamNodes.get(0).getId()));
    assertThat(adaptiveGraphManager.getStreamNodeIdsByJobVertexId(jobVertices.get(1).getID())).isEqualTo(List.of(streamNodes.get(3).getId(), streamNodes.get(2).getId()));
    assertThat(adaptiveGraphManager.getProducerStreamNodeId(jobVertices.get(0).getProducedDataSets().get(0).getId())).isEqualTo(streamNodes.get(1).getId());
    assertThat(adaptiveGraphManager.getOutputStreamEdges(jobVertices.get(0).getProducedDataSets().get(0).getId())).isEqualTo(streamNodes.get(1).getOutEdges());
    Set<Integer> forwardGroup = adaptiveGraphManager.getStreamNodeForwardGroupByVertexId(jobVertices.get(0).getID()).getVertexIds();
    assertThat(forwardGroup.size()).isEqualTo(2);
    assertThat(forwardGroup.contains(streamNodes.get(0).getId())).isTrue();
    assertThat(forwardGroup.contains(streamNodes.get(1).getId())).isTrue();
}

