@Test
void testModifyStreamEdge() {
    StreamGraph streamGraph = createStreamGraphForModifyStreamEdgeTest();
    Map<Integer, StreamNodeForwardGroup> forwardGroupsByEndpointNodeIdCache = new HashMap<>();
    Map<Integer, Integer> frozenNodeToStartNodeMap = new HashMap<>();
    Map<Integer, Map<StreamEdge, NonChainedOutput>> opIntermediateOutputsCaches = new HashMap<>();
    StreamGraphContext streamGraphContext = new DefaultStreamGraphContext(streamGraph, forwardGroupsByEndpointNodeIdCache, frozenNodeToStartNodeMap, opIntermediateOutputsCaches, new HashMap<>(), new HashSet<>(), Thread.currentThread().getContextClassLoader());
    StreamNode sourceNode = streamGraph.getStreamNode(streamGraph.getSourceIDs().iterator().next());
    StreamNode targetNode = streamGraph.getStreamNode(sourceNode.getOutEdges().get(0).getTargetId());
    targetNode.setParallelism(1);
    StreamEdge targetEdge = sourceNode.getOutEdges().get(0);
    StreamNodeForwardGroup forwardGroup1 = new StreamNodeForwardGroup(Collections.singleton(sourceNode));
    StreamNodeForwardGroup forwardGroup2 = new StreamNodeForwardGroup(Collections.singleton(targetNode));
    forwardGroupsByEndpointNodeIdCache.put(sourceNode.getId(), forwardGroup1);
    forwardGroupsByEndpointNodeIdCache.put(targetNode.getId(), forwardGroup2);
    StreamEdgeUpdateRequestInfo streamEdgeUpdateRequestInfo = new StreamEdgeUpdateRequestInfo(targetEdge.getEdgeId(), targetEdge.getSourceId(), targetEdge.getTargetId()).withOutputPartitioner(new ForwardForUnspecifiedPartitioner<>());
    assertThat(streamGraphContext.modifyStreamEdge(Collections.singletonList(streamEdgeUpdateRequestInfo))).isTrue();
    assertThat(targetEdge.getPartitioner() instanceof ForwardPartitioner).isTrue();
    // We cannot modify when partitioner is forward partitioner.
    assertThat(streamGraphContext.modifyStreamEdge(Collections.singletonList(streamEdgeUpdateRequestInfo))).isEqualTo(false);
    // We cannot modify when target node job vertex is created.
    frozenNodeToStartNodeMap.put(targetEdge.getTargetId(), targetEdge.getTargetId());
    assertThat(streamGraphContext.modifyStreamEdge(Collections.singletonList(streamEdgeUpdateRequestInfo))).isEqualTo(false);
    NonChainedOutput nonChainedOutput = new NonChainedOutput(targetEdge.supportsUnalignedCheckpoints(), targetEdge.getSourceId(), targetNode.getParallelism(), targetNode.getMaxParallelism(), targetEdge.getBufferTimeout(), false, new IntermediateDataSetID(), targetEdge.getOutputTag(), targetEdge.getPartitioner(), ResultPartitionType.BLOCKING);
    opIntermediateOutputsCaches.put(targetEdge.getSourceId(), Map.of(targetEdge, nonChainedOutput, targetNode.getOutEdges().get(0), nonChainedOutput));
    // We cannot modify when target edge is consumed by multi edges.
    frozenNodeToStartNodeMap.put(targetEdge.getTargetId(), targetEdge.getTargetId());
    assertThat(streamGraphContext.modifyStreamEdge(Collections.singletonList(streamEdgeUpdateRequestInfo))).isEqualTo(false);
}

