@Test
void testSlotSharingResourceConfiguration() {
    final String slotSharingGroup1 = "slot-a";
    final String slotSharingGroup2 = "slot-b";
    final ResourceProfile resourceProfile1 = ResourceProfile.fromResources(1, 10);
    final ResourceProfile resourceProfile2 = ResourceProfile.fromResources(2, 20);
    final ResourceProfile resourceProfile3 = ResourceProfile.fromResources(3, 30);
    final Map<String, ResourceProfile> slotSharingGroupResource = new HashMap<>();
    slotSharingGroupResource.put(slotSharingGroup1, resourceProfile1);
    slotSharingGroupResource.put(slotSharingGroup2, resourceProfile2);
    slotSharingGroupResource.put(StreamGraphGenerator.DEFAULT_SLOT_SHARING_GROUP, resourceProfile3);
    final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
    env.fromData(1, 2, 3).name(slotSharingGroup1).slotSharingGroup(slotSharingGroup1).map(x -> x + 1).name(slotSharingGroup2).slotSharingGroup(slotSharingGroup2).map(x -> x * x).name(StreamGraphGenerator.DEFAULT_SLOT_SHARING_GROUP).slotSharingGroup(StreamGraphGenerator.DEFAULT_SLOT_SHARING_GROUP);
    final StreamGraph streamGraph = env.getStreamGraph();
    streamGraph.setSlotSharingGroupResource(slotSharingGroupResource);
    final JobGraph jobGraph = createJobGraph(streamGraph);
    int numVertex = 0;
    for (JobVertex jobVertex : jobGraph.getVertices()) {
        numVertex += 1;
        if (jobVertex.getName().contains(slotSharingGroup1)) {
            assertThat(jobVertex.getSlotSharingGroup().getResourceProfile()).isEqualTo(resourceProfile1);
        } else if (jobVertex.getName().contains(slotSharingGroup2)) {
            assertThat(jobVertex.getSlotSharingGroup().getResourceProfile()).isEqualTo(resourceProfile2);
        } else if (jobVertex.getName().contains(StreamGraphGenerator.DEFAULT_SLOT_SHARING_GROUP)) {
            assertThat(jobVertex.getSlotSharingGroup().getResourceProfile()).isEqualTo(resourceProfile3);
        } else {
            Assertions.fail("");
        }
    }
    assertThat(numVertex).isEqualTo(3);
}

