// Manual hash assignment
// ------------------------------------------------------------------------
/**
 * Tests that manual hash assignments are mapped to the same operator ID.
 *
 * <pre>
 *                     /-> [ (map) ] -> [ (sink)@sink0 ]
 * [ (src@source ) ] -+
 *                     \-> [ (map) ] -> [ (sink)@sink1 ]
 * </pre>
 *
 * <pre>
 *                    /-> [ (map) ] -> [ (reduce) ] -> [ (sink)@sink0 ]
 * [ (src)@source ] -+
 *                   \-> [ (map) ] -> [ (reduce) ] -> [ (sink)@sink1 ]
 * </pre>
 */
@Test
void testManualHashAssignment() {
    StreamExecutionEnvironment env = StreamExecutionEnvironment.createLocalEnvironment();
    env.setParallelism(4);
    env.disableOperatorChaining();
    DataStream<String> src = env.addSource(new NoOpSourceFunction()).name("source").uid("source");
    src.map(new NoOpMapFunction()).sinkTo(new org.apache.flink.streaming.api.functions.sink.v2.DiscardingSink<>()).name("sink0").uid("sink0");
    src.map(new NoOpMapFunction()).sinkTo(new org.apache.flink.streaming.api.functions.sink.v2.DiscardingSink<>()).name("sink1").uid("sink1");
    JobGraph jobGraph = env.getStreamGraph().getJobGraph();
    Set<JobVertexID> ids = new HashSet<>();
    for (JobVertex vertex : jobGraph.getVertices()) {
        assertThat(ids.add(vertex.getID())).isTrue();
    }
    // Resubmit a slightly different program
    env = StreamExecutionEnvironment.createLocalEnvironment();
    env.setParallelism(4);
    env.disableOperatorChaining();
    src = env.addSource(new NoOpSourceFunction()).// New map function, should be mapped to the source state
    map(new NoOpMapFunction()).name("source").uid("source");
    src.map(new NoOpMapFunction()).keyBy(new NoOpKeySelector()).reduce(new NoOpReduceFunction()).sinkTo(new org.apache.flink.streaming.api.functions.sink.v2.DiscardingSink<>()).name("sink0").uid("sink0");
    src.map(new NoOpMapFunction()).keyBy(new NoOpKeySelector()).reduce(new NoOpReduceFunction()).sinkTo(new org.apache.flink.streaming.api.functions.sink.v2.DiscardingSink<>()).name("sink1").uid("sink1");
    JobGraph newJobGraph = env.getStreamGraph().getJobGraph();
    assertThat(newJobGraph.getJobID()).isNotEqualTo(jobGraph.getJobID());
    for (JobVertex vertex : newJobGraph.getVertices()) {
        // Verify that the expected IDs are the same
        if (vertex.getName().endsWith("source") || vertex.getName().endsWith("sink0") || vertex.getName().endsWith("sink1")) {
            assertThat(vertex.getID()).isIn(ids);
        }
    }
}

