    testHarness.processElement(new StreamRecord<>(second));
    final OperatorSubtaskState snapshot = testHarness.snapshot(checkpointId, 2L);
    assertThat(testHarness.getOutput()).isEmpty();
    testHarness.close();
    // create new testHarness but with different parallelism level and subtaskId that original
    // one.
    // we will make sure that new subtaskId was used during committable recovery.
    SinkAndCounters restored = sinkWithPostCommit();
    final OneInputStreamOperatorTestHarness<CommittableMessage<String>, CommittableMessage<String>> restoredHarness = createTestHarness(restored.sink, false, true, 10, 10, subtaskIdAfterRecovery);
    restoredHarness.initializeState(snapshot);
    restoredHarness.open();
    // Previous committables are immediately committed if possible
    assertThat(restored.commitCounter.getAsInt()).isEqualTo(2);
    ListAssert<CommittableMessage<String>> records = assertThat(restoredHarness.extractOutputValues()).hasSize(3);
    CommittableSummaryAssert<Object> objectCommittableSummaryAssert = records.element(0, as(committableSummary())).hasCheckpointId(checkpointId).hasFailedCommittables(0).hasSubtaskId(subtaskIdAfterRecovery);
    objectCommittableSummaryAssert.hasOverallCommittables(2);
    // Expect the same checkpointId that the original snapshot was made with.
    records.element(1, as(committableWithLineage())).hasCheckpointId(checkpointId).hasSubtaskId(subtaskIdAfterRecovery).hasCommittable(first.getCommittable());
    records.element(2, as(committableWithLineage())).hasCheckpointId(checkpointId).hasSubtaskId(subtaskIdAfterRecovery).hasCommittable(second.getCommittable());
    restoredHarness.close();
}

