/**
 * Verify that clear() does not leak across windows.
 */
@Test
void testClear() throws Exception {
    TriggerTestHarness<Object, TimeWindow> testHarness = new TriggerTestHarness<>(ContinuousEventTimeTrigger.<TimeWindow>of(Duration.ofHours(1)), new TimeWindow.Serializer());
    assertThat(testHarness.processElement(new StreamRecord<>(1), new TimeWindow(0, 2))).isEqualTo(TriggerResult.CONTINUE);
    assertThat(testHarness.processElement(new StreamRecord<>(1), new TimeWindow(2, 4))).isEqualTo(TriggerResult.CONTINUE);
    assertThat(testHarness.numStateEntries()).isEqualTo(2);
    assertThat(testHarness.numProcessingTimeTimers()).isZero();
    assertThat(testHarness.numEventTimeTimers()).isEqualTo(4);
    assertThat(testHarness.numEventTimeTimers(new TimeWindow(0, 2))).isEqualTo(2);
    assertThat(testHarness.numEventTimeTimers(new TimeWindow(2, 4))).isEqualTo(2);
    testHarness.clearTriggerState(new TimeWindow(2, 4));
    assertThat(testHarness.numStateEntries()).isOne();
    assertThat(testHarness.numProcessingTimeTimers()).isZero();
    assertThat(testHarness.numEventTimeTimers()).isEqualTo(3);
    assertThat(testHarness.numEventTimeTimers(new TimeWindow(0, 2))).isEqualTo(2);
    assertThat(testHarness.numEventTimeTimers(new TimeWindow(2, 4))).isOne();
    testHarness.clearTriggerState(new TimeWindow(0, 2));
    assertThat(testHarness.numStateEntries()).isZero();
    assertThat(testHarness.numProcessingTimeTimers()).isZero();
    // doesn't clean up timers
    assertThat(testHarness.numEventTimeTimers()).isEqualTo(2);
}

@Test
void testMergingWindows() throws Exception {
    TriggerTestHarness<Object, TimeWindow> testHarness = new TriggerTestHarness<>(ContinuousEventTimeTrigger.<TimeWindow>of(Duration.ofHours(1)), new TimeWindow.Serializer());
    assertThat(ContinuousEventTimeTrigger.<TimeWindow>of(Duration.ofHours(1)).canMerge()).isTrue();
    assertThat(testHarness.processElement(new StreamRecord<>(1), new TimeWindow(0, 2))).isEqualTo(TriggerResult.CONTINUE);
    assertThat(testHarness.processElement(new StreamRecord<>(1), new TimeWindow(2, 4))).isEqualTo(TriggerResult.CONTINUE);
    assertThat(testHarness.numStateEntries()).isEqualTo(2);
    assertThat(testHarness.numProcessingTimeTimers()).isZero();
    assertThat(testHarness.numEventTimeTimers()).isEqualTo(4);
    assertThat(testHarness.numEventTimeTimers(new TimeWindow(0, 2))).isEqualTo(2);
    assertThat(testHarness.numEventTimeTimers(new TimeWindow(2, 4))).isEqualTo(2);
    testHarness.mergeWindows(new TimeWindow(0, 4), Lists.newArrayList(new TimeWindow(0, 2), new TimeWindow(2, 4)));
    assertThat(testHarness.numStateEntries()).isOne();
    assertThat(testHarness.numProcessingTimeTimers()).isZero();
    assertThat(testHarness.numEventTimeTimers()).isEqualTo(// on merging, timers are not cleaned up
    5);
    assertThat(testHarness.numEventTimeTimers(new TimeWindow(0, 2))).isEqualTo(2);
    assertThat(testHarness.numEventTimeTimers(new TimeWindow(2, 4))).isEqualTo(2);
    assertThat(testHarness.numEventTimeTimers(new TimeWindow(0, 4))).isOne();
    Collection<Tuple2<TimeWindow, TriggerResult>> triggerResults = testHarness.advanceWatermark(4);
    boolean sawFiring = false;
    for (Tuple2<TimeWindow, TriggerResult> r : triggerResults) {
        if (r.f0.equals(new TimeWindow(0, 4))) {
            sawFiring = true;
            assertThat(r.f1).isEqualTo(TriggerResult.FIRE);
        }
    }
    assertThat(sawFiring).isTrue();
    assertThat(testHarness.numStateEntries()).isOne();
    assertThat(testHarness.numProcessingTimeTimers()).isZero();
    assertThat(testHarness.numEventTimeTimers()).isOne();
}

/**
 * Verify ContinuousProcessingTimeTrigger fire.
 */
@Test
void testProcessingTimeWindowFiring() throws Exception {
    ContinuousProcessingTimeTrigger<TimeWindow> trigger = ContinuousProcessingTimeTrigger.of(Duration.ofMillis(5));
    assertThat(trigger.canMerge()).isTrue();
    ListStateDescriptor<Integer> stateDesc = new ListStateDescriptor<>("window-contents", BasicTypeInfo.INT_TYPE_INFO.createSerializer(new SerializerConfigImpl()));
    WindowOperatorFactory<Byte, Integer, Iterable<Integer>, WindowedInteger, TimeWindow> operator = new WindowOperatorFactory<>(TumblingProcessingTimeWindows.of(Duration.ofMillis(10)), new TimeWindow.Serializer(), new NullByteKeySelector<>(), BasicTypeInfo.BYTE_TYPE_INFO.createSerializer(new SerializerConfigImpl()), stateDesc, new InternalIterableWindowFunction<>(new IntegerSumWindowFunction()), trigger, 0, null);
    KeyedOneInputStreamOperatorTestHarness<Byte, Integer, WindowedInteger> testHarness = new KeyedOneInputStreamOperatorTestHarness<>(operator, operator.getKeySelector(), BasicTypeInfo.BYTE_TYPE_INFO);
    ArrayDeque<Object> expectedOutput = new ArrayDeque<>();
    testHarness.open();
    // window [0, 10)
    testHarness.getProcessingTimeService().setCurrentTime(0);
    testHarness.processElement(1, NO_TIMESTAMP);
    // window [0, 10)
    testHarness.getProcessingTimeService().setCurrentTime(2);
    testHarness.processElement(2, NO_TIMESTAMP);
    // Fire window [0, 10), value is 1+2=3.
    testHarness.getProcessingTimeService().setCurrentTime(5);
    expectedOutput.add(new StreamRecord<>(new WindowedInteger(new TimeWindow(0, 10), 3), 9));
    TestHarnessUtil.assertOutputEquals("Output mismatch", expectedOutput, testHarness.getOutput());
    // window [0, 10)
    testHarness.getProcessingTimeService().setCurrentTime(7);
    testHarness.processElement(3, NO_TIMESTAMP);
    // Fire window [0, 10), value is 3+3=6.
    testHarness.getProcessingTimeService().setCurrentTime(9);
    expectedOutput.add(new StreamRecord<>(new WindowedInteger(new TimeWindow(0, 10), 6), 9));
    TestHarnessUtil.assertOutputEquals("Output mismatch", expectedOutput, testHarness.getOutput());
    // window [10, 20)
    testHarness.getProcessingTimeService().setCurrentTime(10);
    testHarness.processElement(3, NO_TIMESTAMP);
    // Fire window [10, 20), value is 3.
    testHarness.getProcessingTimeService().setCurrentTime(15);
    expectedOutput.add(new StreamRecord<>(new WindowedInteger(new TimeWindow(10, 20), 3), 19));
    TestHarnessUtil.assertOutputEquals("Output mismatch", expectedOutput, testHarness.getOutput());
    // window [10, 20)
    testHarness.getProcessingTimeService().setCurrentTime(18);
    testHarness.processElement(3, NO_TIMESTAMP);
    // Fire window [10, 20), value is 3+3=6.
    testHarness.getProcessingTimeService().setCurrentTime(20);
    expectedOutput.add(new StreamRecord<>(new WindowedInteger(new TimeWindow(10, 20), 6), 19));
    TestHarnessUtil.assertOutputEquals("Output mismatch", expectedOutput, testHarness.getOutput());
}

