@Test
void testIncrementalMerging() throws Exception {
    @SuppressWarnings("unchecked")
    ListState<Tuple2<TimeWindow, TimeWindow>> mockState = mock(ListState.class);
    MergingWindowSet<TimeWindow> windowSet = new MergingWindowSet<>(EventTimeSessionWindows.withGap(Duration.ofMillis(3)), mockState);
    TestingMergeFunction mergeFunction = new TestingMergeFunction();
    // add initial window
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(0, 4), mergeFunction)).isEqualTo(new TimeWindow(0, 4));
    assertThat(mergeFunction.hasMerged()).isFalse();
    assertThat(windowSet.getStateWindow(new TimeWindow(0, 4))).isEqualTo(new TimeWindow(0, 4));
    // add some more windows
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(0, 4), mergeFunction)).isEqualTo(new TimeWindow(0, 4));
    assertThat(mergeFunction.hasMerged()).isFalse();
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(3, 5), mergeFunction)).isEqualTo(new TimeWindow(0, 5));
    assertThat(mergeFunction.hasMerged()).isTrue();
    assertThat(mergeFunction.mergeTarget()).isEqualTo(new TimeWindow(0, 5));
    assertThat(mergeFunction.stateWindow()).isEqualTo(new TimeWindow(0, 4));
    assertThat(mergeFunction.mergeSources()).containsExactly(new TimeWindow(0, 4));
    assertThat(mergeFunction.mergedStateWindows()).isEmpty();
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(4, 6), mergeFunction)).isEqualTo(new TimeWindow(0, 6));
    assertThat(mergeFunction.hasMerged()).isTrue();
    assertThat(mergeFunction.mergeTarget()).isEqualTo(new TimeWindow(0, 6));
    assertThat(mergeFunction.stateWindow()).isEqualTo(new TimeWindow(0, 4));
    assertThat(mergeFunction.mergeSources()).containsExactly(new TimeWindow(0, 5));
    assertThat(mergeFunction.mergedStateWindows()).isEmpty();
    assertThat(windowSet.getStateWindow(new TimeWindow(0, 6))).isEqualTo(new TimeWindow(0, 4));
    // add some windows that falls into the already merged region
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(1, 4), mergeFunction)).isEqualTo(new TimeWindow(0, 6));
    assertThat(mergeFunction.hasMerged()).isFalse();
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(0, 4), mergeFunction)).isEqualTo(new TimeWindow(0, 6));
    assertThat(mergeFunction.hasMerged()).isFalse();
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(3, 5), mergeFunction)).isEqualTo(new TimeWindow(0, 6));
    assertThat(mergeFunction.hasMerged()).isFalse();
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(4, 6), mergeFunction)).isEqualTo(new TimeWindow(0, 6));
    assertThat(mergeFunction.hasMerged()).isFalse();
    assertThat(windowSet.getStateWindow(new TimeWindow(0, 6))).isEqualTo(new TimeWindow(0, 4));
    // add some more windows that don't merge with the first bunch
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(11, 14), mergeFunction)).isEqualTo(new TimeWindow(11, 14));
    assertThat(mergeFunction.hasMerged()).isFalse();
    assertThat(windowSet.getStateWindow(new TimeWindow(0, 6))).isEqualTo(new TimeWindow(0, 4));
    assertThat(windowSet.getStateWindow(new TimeWindow(11, 14))).isEqualTo(new TimeWindow(11, 14));
    // add some more windows that merge with the second bunch
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(10, 13), mergeFunction)).isEqualTo(new TimeWindow(10, 14));
    assertThat(mergeFunction.hasMerged()).isTrue();
    assertThat(mergeFunction.mergeTarget()).isEqualTo(new TimeWindow(10, 14));
    assertThat(mergeFunction.stateWindow()).isEqualTo(new TimeWindow(11, 14));
    assertThat(mergeFunction.mergeSources()).containsExactly(new TimeWindow(11, 14));
    assertThat(mergeFunction.mergedStateWindows()).isEmpty();
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(12, 15), mergeFunction)).isEqualTo(new TimeWindow(10, 15));
    assertThat(mergeFunction.hasMerged()).isTrue();
    assertThat(mergeFunction.mergeTarget()).isEqualTo(new TimeWindow(10, 15));
    assertThat(mergeFunction.stateWindow()).isEqualTo(new TimeWindow(11, 14));
    assertThat(mergeFunction.mergeSources()).containsExactly(new TimeWindow(10, 14));
    assertThat(mergeFunction.mergedStateWindows()).isEmpty();
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(11, 14), mergeFunction)).isEqualTo(new TimeWindow(10, 15));
    assertThat(mergeFunction.hasMerged()).isFalse();
    assertThat(windowSet.getStateWindow(new TimeWindow(0, 6))).isEqualTo(new TimeWindow(0, 4));
    assertThat(windowSet.getStateWindow(new TimeWindow(10, 15))).isEqualTo(new TimeWindow(11, 14));
    // retire the first batch of windows
    windowSet.retireWindow(new TimeWindow(0, 6));
    assertThat(windowSet.getStateWindow(new TimeWindow(0, 6))).isNull();
    assertThat(windowSet.getStateWindow(new TimeWindow(10, 15))).isEqualTo(new TimeWindow(11, 14));
}

@Test
void testLateMerging() throws Exception {
    @SuppressWarnings("unchecked")
    ListState<Tuple2<TimeWindow, TimeWindow>> mockState = mock(ListState.class);
    MergingWindowSet<TimeWindow> windowSet = new MergingWindowSet<>(EventTimeSessionWindows.withGap(Duration.ofMillis(3)), mockState);
    TestingMergeFunction mergeFunction = new TestingMergeFunction();
    // add several non-overlapping initial windows
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(0, 3), mergeFunction)).isEqualTo(new TimeWindow(0, 3));
    assertThat(mergeFunction.hasMerged()).isFalse();
    assertThat(windowSet.getStateWindow(new TimeWindow(0, 3))).isEqualTo(new TimeWindow(0, 3));
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(5, 8), mergeFunction)).isEqualTo(new TimeWindow(5, 8));
    assertThat(mergeFunction.hasMerged()).isFalse();
    assertThat(windowSet.getStateWindow(new TimeWindow(5, 8))).isEqualTo(new TimeWindow(5, 8));
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(10, 13), mergeFunction)).isEqualTo(new TimeWindow(10, 13));
    assertThat(mergeFunction.hasMerged()).isFalse();
    assertThat(windowSet.getStateWindow(new TimeWindow(10, 13))).isEqualTo(new TimeWindow(10, 13));
    // add a window that merges the later two windows
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(8, 10), mergeFunction)).isEqualTo(new TimeWindow(5, 13));
    assertThat(mergeFunction.hasMerged()).isTrue();
    assertThat(mergeFunction.mergeTarget()).isEqualTo(new TimeWindow(5, 13));
    assertThat(mergeFunction.stateWindow()).satisfiesAnyOf(w -> assertThat(w).isEqualTo(new TimeWindow(5, 8)), w -> assertThat(w).isEqualTo(new TimeWindow(10, 13)));
    assertThat(mergeFunction.mergeSources()).containsExactlyInAnyOrder(new TimeWindow(5, 8), new TimeWindow(10, 13));
    assertThat(mergeFunction.mergedStateWindows()).containsAnyOf(new TimeWindow(5, 8), new TimeWindow(10, 13));
    assertThat(mergeFunction.mergedStateWindows().toArray()).satisfiesAnyOf(o -> assertThat(o).containsExactly(new TimeWindow(10, 13)), o -> assertThat(o).containsExactly(new TimeWindow(5, 8)));
    assertThat(mergeFunction.mergedStateWindows()).doesNotContain(mergeFunction.mergeTarget());
    assertThat(windowSet.getStateWindow(new TimeWindow(0, 3))).isEqualTo(new TimeWindow(0, 3));
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(5, 8), mergeFunction)).isEqualTo(new TimeWindow(5, 13));
    assertThat(mergeFunction.hasMerged()).isFalse();
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(8, 10), mergeFunction)).isEqualTo(new TimeWindow(5, 13));
    assertThat(mergeFunction.hasMerged()).isFalse();
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(10, 13), mergeFunction)).isEqualTo(new TimeWindow(5, 13));
    assertThat(mergeFunction.hasMerged()).isFalse();
    assertThat(windowSet.getStateWindow(new TimeWindow(5, 13))).isIn(new TimeWindow(5, 8), new TimeWindow(10, 13));
    // add a window that merges all of them together
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(3, 5), mergeFunction)).isEqualTo(new TimeWindow(0, 13));
    assertThat(mergeFunction.hasMerged()).isTrue();
    assertThat(mergeFunction.mergeTarget()).isEqualTo(new TimeWindow(0, 13));
    assertThat(mergeFunction.stateWindow()).isIn(new TimeWindow(0, 3), new TimeWindow(5, 8), new TimeWindow(10, 13));
    assertThat(mergeFunction.mergeSources()).containsExactlyInAnyOrder(new TimeWindow(0, 3), new TimeWindow(5, 13));
    assertThat(mergeFunction.mergedStateWindows().toArray()).satisfiesAnyOf(o -> assertThat(o).containsExactly(new TimeWindow(0, 3)), o -> assertThat(o).containsExactly(new TimeWindow(5, 8)), o -> assertThat(o).containsExactly(new TimeWindow(10, 13)));
    assertThat(mergeFunction.mergedStateWindows()).doesNotContain(mergeFunction.mergeTarget());
    assertThat(windowSet.getStateWindow(new TimeWindow(0, 13))).isIn(new TimeWindow(0, 3), new TimeWindow(5, 8), new TimeWindow(10, 13));
}

