/**
 * Test merging of a large new window that covers multiple existing windows.
 */
@Test
void testMergeLargeWindowCoveringMultipleWindows() throws Exception {
    @SuppressWarnings("unchecked")
    ListState<Tuple2<TimeWindow, TimeWindow>> mockState = mock(ListState.class);
    MergingWindowSet<TimeWindow> windowSet = new MergingWindowSet<>(EventTimeSessionWindows.withGap(Duration.ofMillis(3)), mockState);
    TestingMergeFunction mergeFunction = new TestingMergeFunction();
    // add several non-overlapping initial windows
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(1, 3), mergeFunction)).isEqualTo(new TimeWindow(1, 3));
    assertThat(mergeFunction.hasMerged()).isFalse();
    assertThat(windowSet.getStateWindow(new TimeWindow(1, 3))).isEqualTo(new TimeWindow(1, 3));
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(5, 8), mergeFunction)).isEqualTo(new TimeWindow(5, 8));
    assertThat(mergeFunction.hasMerged()).isFalse();
    assertThat(windowSet.getStateWindow(new TimeWindow(5, 8))).isEqualTo(new TimeWindow(5, 8));
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(10, 13), mergeFunction)).isEqualTo(new TimeWindow(10, 13));
    assertThat(mergeFunction.hasMerged()).isFalse();
    assertThat(windowSet.getStateWindow(new TimeWindow(10, 13))).isEqualTo(new TimeWindow(10, 13));
    // add a new window that completely covers the existing windows
    mergeFunction.reset();
    assertThat(windowSet.addWindow(new TimeWindow(0, 13), mergeFunction)).isEqualTo(new TimeWindow(0, 13));
    assertThat(mergeFunction.hasMerged()).isTrue();
    assertThat(mergeFunction.mergedStateWindows().toArray()).satisfiesAnyOf(o -> assertThat(o).containsExactlyInAnyOrder(new TimeWindow(0, 3), new TimeWindow(5, 8)), o -> assertThat(o).containsExactlyInAnyOrder(new TimeWindow(0, 3), new TimeWindow(10, 13)), o -> assertThat(o).containsExactlyInAnyOrder(new TimeWindow(5, 8), new TimeWindow(10, 13)));
    assertThat(windowSet.getStateWindow(new TimeWindow(0, 13))).isIn(new TimeWindow(1, 3), new TimeWindow(5, 8), new TimeWindow(10, 13));
}

