@Test
void testWindowFireWithoutResetTimer() throws Exception {
    TriggerTestHarness<Object, TimeWindow> testHarness = new TriggerTestHarness<>(ProcessingTimeoutTrigger.of(CountTrigger.of(3), Duration.ofMillis(50), false, true), new TimeWindow.Serializer());
    assertThat(testHarness.processElement(new StreamRecord<>(1), new TimeWindow(0, 2))).isEqualTo(TriggerResult.CONTINUE);
    assertThat(testHarness.processElement(new StreamRecord<>(1), new TimeWindow(0, 2))).isEqualTo(TriggerResult.CONTINUE);
    // Should be two states, one for ProcessingTimeoutTrigger and one for CountTrigger.
    assertThat(testHarness.numStateEntries()).isEqualTo(2);
    assertThat(testHarness.numProcessingTimeTimers()).isOne();
    assertThat(testHarness.numEventTimeTimers()).isZero();
    // Should not fire before interval time.
    assertThrows("Must have exactly one timer firing. Fired timers: []", IllegalStateException.class, () -> testHarness.advanceProcessingTime(Long.MIN_VALUE + 40, new TimeWindow(0, 2)));
    assertThat(testHarness.advanceProcessingTime(Long.MIN_VALUE + 50, new TimeWindow(0, 2))).isEqualTo(TriggerResult.FIRE);
    // After firing states should be clear.
    assertThat(testHarness.numStateEntries()).isZero();
    assertThat(testHarness.numProcessingTimeTimers()).isZero();
    assertThat(testHarness.numEventTimeTimers()).isZero();
    // Check inner trigger is working as well
    assertThat(testHarness.processElement(new StreamRecord<>(1), new TimeWindow(0, 2))).isEqualTo(TriggerResult.CONTINUE);
    assertThat(testHarness.processElement(new StreamRecord<>(1), new TimeWindow(0, 2))).isEqualTo(TriggerResult.CONTINUE);
    assertThat(testHarness.processElement(new StreamRecord<>(1), new TimeWindow(0, 2))).isEqualTo(TriggerResult.FIRE);
}

@Test
