    TriggerTestHarness<Object, TimeWindow> testHarness = new TriggerTestHarness<>(ProcessingTimeoutTrigger.of(CountTrigger.of(3), Duration.ofMillis(50), true, true), new TimeWindow.Serializer());
    assertThrows("Must have exactly one timer firing. Fired timers: []", IllegalStateException.class, () -> testHarness.advanceProcessingTime(0, new TimeWindow(0, 2)));
    assertThat(testHarness.processElement(new StreamRecord<>(1), new TimeWindow(0, 2))).isEqualTo(TriggerResult.CONTINUE);
    assertThrows("Must have exactly one timer firing. Fired timers: []", IllegalStateException.class, () -> testHarness.advanceProcessingTime(10, new TimeWindow(0, 2)));
