    // Check inner trigger is working as well
    assertThat(testHarness.processElement(new StreamRecord<>(1, 0), new TimeWindow(0, 2))).isEqualTo(TriggerResult.CONTINUE);
    assertThat(testHarness.processElement(new StreamRecord<>(1, 10), new TimeWindow(0, 2))).isEqualTo(TriggerResult.CONTINUE);
