    // same as ProcessingTimeTrigger timer for maxWindowTime.
    assertThat(testHarness.numStateEntries()).isOne();
    assertThat(testHarness.numProcessingTimeTimers()).isOne();
    assertThat(testHarness.numEventTimeTimers()).isZero();
}

