@ParameterizedTest(name = "Enable async state = {0}")
@ValueSource(booleans = { false, true })
void testLateness(boolean enableAsyncState) throws Exception {
    final int windowSize = 2;
    final long lateness = 500;
    ReducingStateDescriptor<Tuple2<String, Integer>> stateDesc = new ReducingStateDescriptor<>("window-contents", new SumReducer(), STRING_INT_TUPLE.createSerializer(new SerializerConfigImpl()));
    WindowOperatorFactory<String, Tuple2<String, Integer>, Tuple2<String, Integer>, Tuple2<String, Integer>, TimeWindow> operator = new WindowOperatorFactory<>(TumblingEventTimeWindows.of(Duration.ofSeconds(windowSize)), new TimeWindow.Serializer(), new TupleKeySelector(), BasicTypeInfo.STRING_TYPE_INFO.createSerializer(new SerializerConfigImpl()), stateDesc, new InternalSingleValueWindowFunction<>(new PassThroughWindowFunction<String, TimeWindow, Tuple2<String, Integer>>()), PurgingTrigger.of(EventTimeTrigger.create()), lateness, lateOutputTag);
    WindowOperatorBuilder<Tuple2<String, Integer>, String, TimeWindow> builder = new WindowOperatorBuilder<>(TumblingEventTimeWindows.of(Duration.ofSeconds(windowSize)), PurgingTrigger.of(EventTimeTrigger.create()), new ExecutionConfig(), STRING_INT_TUPLE, new TupleKeySelector(), TypeInformation.of(String.class));
    builder.allowedLateness(Duration.ofMillis(lateness));
    builder.sideOutputLateData(lateOutputTag);
    OneInputStreamOperatorTestHarness<Tuple2<String, Integer>, Tuple2<String, Integer>> testHarness = enableAsyncState ? createAsyncTestHarness(builder.asyncReduce(new SumReducer(), new PassThroughWindowFunction<>())) : createTestHarness(operator);
    testHarness.open();
    ConcurrentLinkedQueue<Object> expected = new ConcurrentLinkedQueue<>();
    ConcurrentLinkedQueue<Object> lateExpected = new ConcurrentLinkedQueue<>();
    testHarness.processElement(new StreamRecord<>(new Tuple2<>("key2", 1), 500));
    testHarness.processWatermark(new Watermark(1500));
    expected.add(new Watermark(1500));
    testHarness.processElement(new StreamRecord<>(new Tuple2<>("key2", 1), 1300));
    testHarness.processWatermark(new Watermark(2300));
    expected.add(new StreamRecord<>(new Tuple2<>("key2", 2), 1999));
    expected.add(new Watermark(2300));
    // this will not be sideoutput because window.maxTimestamp() + allowedLateness >
    // currentWatermark
    testHarness.processElement(new StreamRecord<>(new Tuple2<>("key2", 1), 1997));
    testHarness.processWatermark(new Watermark(6000));
    // this is 1 and not 3 because the trigger fires and purges
    expected.add(new StreamRecord<>(new Tuple2<>("key2", 1), 1999));
    expected.add(new Watermark(6000));
    // this will be side output because window.maxTimestamp() + allowedLateness <
    // currentWatermark
    testHarness.processElement(new StreamRecord<>(new Tuple2<>("key2", 1), 1998));
    testHarness.processWatermark(new Watermark(7000));
    lateExpected.add(new StreamRecord<>(new Tuple2<>("key2", 1), 1998));
    expected.add(new Watermark(7000));
    TestHarnessUtil.assertOutputEqualsSorted("Output was not correct.", expected, testHarness.getOutput(), new Tuple2ResultSortComparator());
    TestHarnessUtil.assertOutputEqualsSorted("SideOutput was not correct.", lateExpected, (Iterable) testHarness.getSideOutput(lateOutputTag), new Tuple2ResultSortComparator());
    testHarness.close();
}

@ParameterizedTest(name = "Enable async state = {0}")
@ValueSource(booleans = { false, true })
void testCleanupTimeOverflow(boolean enableAsyncState) throws Exception {
    final int windowSize = 1000;
    final long lateness = 2000;
    ReducingStateDescriptor<Tuple2<String, Integer>> stateDesc = new ReducingStateDescriptor<>("window-contents", new SumReducer(), STRING_INT_TUPLE.createSerializer(new SerializerConfigImpl()));
    TumblingEventTimeWindows windowAssigner = TumblingEventTimeWindows.of(Duration.ofMillis(windowSize));
    final WindowOperatorFactory<String, Tuple2<String, Integer>, Tuple2<String, Integer>, Tuple2<String, Integer>, TimeWindow> operator = new WindowOperatorFactory<>(windowAssigner, new TimeWindow.Serializer(), new TupleKeySelector(), BasicTypeInfo.STRING_TYPE_INFO.createSerializer(new SerializerConfigImpl()), stateDesc, new InternalSingleValueWindowFunction<>(new PassThroughWindowFunction<String, TimeWindow, Tuple2<String, Integer>>()), EventTimeTrigger.create(), lateness, null);
    WindowOperatorBuilder<Tuple2<String, Integer>, String, TimeWindow> builder = new WindowOperatorBuilder<>(windowAssigner, EventTimeTrigger.create(), new ExecutionConfig(), STRING_INT_TUPLE, new TupleKeySelector(), TypeInformation.of(String.class));
    builder.allowedLateness(Duration.ofMillis(lateness));
    OneInputStreamOperatorTestHarness<Tuple2<String, Integer>, Tuple2<String, Integer>> testHarness = enableAsyncState ? createAsyncTestHarness(builder.asyncReduce(new SumReducer(), new PassThroughWindowFunction<>())) : createTestHarness(operator);
    testHarness.open();
    ConcurrentLinkedQueue<Object> expected = new ConcurrentLinkedQueue<>();
    long timestamp = Long.MAX_VALUE - 1750;
    Collection<TimeWindow> windows = windowAssigner.assignWindows(new Tuple2<>("key2", 1), timestamp, new WindowAssigner.WindowAssignerContext() {

        @Override
        public long getCurrentProcessingTime() {
            return enableAsyncState ? ((AsyncWindowOperator<?, ?, ?, ?, ?>) testHarness.getOperator()).getWindowAssignerContext().getCurrentProcessingTime() : ((WindowOperator<?, ?, ?, ?, ?>) testHarness.getOperator()).windowAssignerContext.getCurrentProcessingTime();
        }
    });
    TimeWindow window = Iterables.getOnlyElement(windows);
    testHarness.processElement(new StreamRecord<>(new Tuple2<>("key2", 1), timestamp));
    // the garbage collection timer would wrap-around
    assertThat(window.maxTimestamp() + lateness).isLessThan(window.maxTimestamp());
    // and it would prematurely fire with watermark (Long.MAX_VALUE - 1500)
    assertThat(window.maxTimestamp() + lateness).isLessThan(Long.MAX_VALUE - 1500);
    // if we don't correctly prevent wrap-around in the garbage collection
    // timers this watermark will clean our window state for the just-added
    // element/window
    testHarness.processWatermark(new Watermark(Long.MAX_VALUE - 1500));
    // this watermark is before the end timestamp of our only window
    assertThat(window.maxTimestamp()).isStrictlyBetween(Long.MAX_VALUE - 1500, Long.MAX_VALUE);
    // push in a watermark that will trigger computation of our window
    testHarness.processWatermark(new Watermark(window.maxTimestamp()));
    expected.add(new Watermark(Long.MAX_VALUE - 1500));
    expected.add(new StreamRecord<>(new Tuple2<>("key2", 1), window.maxTimestamp()));
    expected.add(new Watermark(window.maxTimestamp()));
    TestHarnessUtil.assertOutputEqualsSorted("Output was not correct.", expected, testHarness.getOutput(), new Tuple2ResultSortComparator());
    testHarness.close();
}

