void testSideOutputDueToLatenessSliding(boolean enableAsyncState) throws Exception {
    final int windowSize = 3;
    final int windowSlide = 1;
    final long lateness = 0;
    ReducingStateDescriptor<Tuple2<String, Integer>> stateDesc = new ReducingStateDescriptor<>("window-contents", new SumReducer(), STRING_INT_TUPLE.createSerializer(new SerializerConfigImpl()));
