    WindowOperatorBuilder<Tuple2<String, Integer>, String, TimeWindow> builder = new WindowOperatorBuilder<>(SlidingEventTimeWindows.of(Duration.ofSeconds(windowSize), Duration.ofSeconds(windowSlide)), EventTimeTrigger.create(), new ExecutionConfig(), STRING_INT_TUPLE, new TupleKeySelector(), TypeInformation.of(String.class));
