@Test
void testScalingDown() throws Exception {
    S sink1 = createSink();
    OneInputStreamOperatorTestHarness<IN, IN> testHarness1 = new OneInputStreamOperatorTestHarness<>(sink1, maxParallelism, 2, 0);
    testHarness1.open();
    S sink2 = createSink();
    OneInputStreamOperatorTestHarness<IN, IN> testHarness2 = new OneInputStreamOperatorTestHarness<>(sink2, maxParallelism, 2, 1);
    testHarness2.open();
    int elementCounter = 1;
    int snapshotCount = 0;
    for (int x = 0; x < 10; x++) {
        testHarness1.processElement(new StreamRecord<>(generateValue(elementCounter, 0)));
        elementCounter++;
    }
    for (int x = 0; x < 11; x++) {
        testHarness2.processElement(new StreamRecord<>(generateValue(elementCounter, 0)));
        elementCounter++;
    }
    // snapshot at checkpoint 0 for testHarness1 and testHarness 2
    OperatorSubtaskState snapshot1 = testHarness1.snapshot(snapshotCount, 0);
    OperatorSubtaskState snapshot2 = testHarness2.snapshot(snapshotCount, 0);
    // merge the two partial states
    OperatorSubtaskState mergedSnapshot = AbstractStreamOperatorTestHarness.repackageState(snapshot1, snapshot2);
    testHarness1.close();
    testHarness2.close();
    // and create a third instance that operates alone but
    // has the merged state of the previous 2 instances
    OperatorSubtaskState initState = AbstractStreamOperatorTestHarness.repartitionOperatorState(mergedSnapshot, maxParallelism, 2, 1, 0);
    S sink3 = createSink();
    OneInputStreamOperatorTestHarness<IN, IN> mergedTestHarness = new OneInputStreamOperatorTestHarness<>(sink3, maxParallelism, 1, 0);
    mergedTestHarness.setup();
    mergedTestHarness.initializeState(initState);
    mergedTestHarness.open();
    for (int x = 0; x < 12; x++) {
        mergedTestHarness.processElement(new StreamRecord<>(generateValue(elementCounter, 0)));
        elementCounter++;
    }
    snapshotCount++;
    mergedTestHarness.snapshot(snapshotCount, 1);
    mergedTestHarness.notifyOfCompletedCheckpoint(snapshotCount);
    verifyResultsWhenReScaling(sink3, 1, 33);
    mergedTestHarness.close();
}

@Test
void testScalingUp() throws Exception {
    S sink1 = createSink();
    OneInputStreamOperatorTestHarness<IN, IN> testHarness1 = new OneInputStreamOperatorTestHarness<>(sink1, maxParallelism, 1, 0);
    int elementCounter = 1;
    int snapshotCount = 0;
    testHarness1.open();
    // put two more checkpoints as pending
    for (int x = 0; x < 10; x++) {
        testHarness1.processElement(new StreamRecord<>(generateValue(elementCounter, 0)));
        elementCounter++;
    }
    testHarness1.snapshot(++snapshotCount, 0);
    for (int x = 0; x < 11; x++) {
        testHarness1.processElement(new StreamRecord<>(generateValue(elementCounter, 0)));
        elementCounter++;
    }
    // this will be the state that will be split between the two new operators
    OperatorSubtaskState snapshot = testHarness1.snapshot(++snapshotCount, 0);
    testHarness1.close();
    // verify no elements are in the sink
    verifyResultsWhenReScaling(sink1, 0, -1);
    // we will create two operator instances, testHarness2 and testHarness3,
    // that will share the state of testHarness1
    OperatorSubtaskState initState1 = AbstractStreamOperatorTestHarness.repartitionOperatorState(snapshot, maxParallelism, 1, 2, 0);
    OperatorSubtaskState initState2 = AbstractStreamOperatorTestHarness.repartitionOperatorState(snapshot, maxParallelism, 1, 2, 1);
    ++snapshotCount;
    S sink2 = createSink();
    OneInputStreamOperatorTestHarness<IN, IN> testHarness2 = new OneInputStreamOperatorTestHarness<>(sink2, maxParallelism, 2, 0);
    testHarness2.setup();
    testHarness2.initializeState(initState1);
    testHarness2.open();
    testHarness2.notifyOfCompletedCheckpoint(snapshotCount);
    verifyResultsWhenReScaling(sink2, 1, 10);
    S sink3 = createSink();
    OneInputStreamOperatorTestHarness<IN, IN> testHarness3 = new OneInputStreamOperatorTestHarness<>(sink3, maxParallelism, 2, 1);
    testHarness3.setup();
    testHarness3.initializeState(initState2);
    testHarness3.open();
    // add some more elements to verify that everything functions normally from now on...
    for (int x = 0; x < 10; x++) {
        testHarness3.processElement(new StreamRecord<>(generateValue(elementCounter, 0)));
        elementCounter++;
    }
    testHarness3.snapshot(snapshotCount, 1);
    testHarness3.notifyOfCompletedCheckpoint(snapshotCount);
    verifyResultsWhenReScaling(sink3, 11, 31);
    testHarness2.close();
    testHarness3.close();
}

