void testTaskSideOutputStatistics() throws Exception {
    TaskMetricGroup taskMetricGroup = UnregisteredMetricGroups.createUnregisteredTaskMetricGroup();
    ResultPartitionWriter[] partitionWriters = new ResultPartitionWriter[3];
    for (int i = 0; i < partitionWriters.length; ++i) {
        partitionWriters[i] = new RecordOrEventCollectingResultPartitionWriter<>(new ArrayDeque<>(), new StreamElementSerializer<>(BasicTypeInfo.INT_TYPE_INFO.createSerializer(new SerializerConfigImpl())));
        partitionWriters[i].setup();
