    try (StreamTaskMailboxTestHarness<Integer> testHarness = new StreamTaskMailboxTestHarnessBuilder<>(OneInputStreamTask::new, BasicTypeInfo.INT_TYPE_INFO).addInput(BasicTypeInfo.INT_TYPE_INFO).addAdditionalOutput(partitionWriters).setupOperatorChain(new OperatorID(), new PassThroughOperator<>()).chain(BasicTypeInfo.INT_TYPE_INFO.createSerializer(new SerializerConfigImpl())).setOperatorFactory(SimpleOperatorFactory.of(new OddEvenOperator())).addNonChainedOutputsCount(new OutputTag<>("odd", BasicTypeInfo.INT_TYPE_INFO), 2).addNonChainedOutputsCount(1).build().chain(BasicTypeInfo.INT_TYPE_INFO.createSerializer(new SerializerConfigImpl())).setOperatorFactory(SimpleOperatorFactory.of(new DuplicatingOperator())).addNonChainedOutputsCount(1).build().finish().setTaskMetricGroup(taskMetricGroup).build()) {
        Counter numRecordsInCounter = taskMetricGroup.getIOMetricGroup().getNumRecordsInCounter();
        Counter numRecordsOutCounter = taskMetricGroup.getIOMetricGroup().getNumRecordsOutCounter();
        final int numEvenRecords = 5;
