@ParameterizedTest
@MethodSource("provideExternallyInducedParameters")
void testExternallyInducedSource(CheckpointOptions checkpointOptions, boolean rpcFirst) throws Exception {
    final int numEventsBeforeCheckpoint = 10;
    final int totalNumEvents = 20;
    TestingExternallyInducedSourceReader testingReader = new TestingExternallyInducedSourceReader(numEventsBeforeCheckpoint, totalNumEvents);
    try (StreamTaskMailboxTestHarness<Integer> testHarness = createTestHarness(new TestingExternallyInducedSource(testingReader), 0, null)) {
        TestingExternallyInducedSourceReader runtimeTestingReader = (TestingExternallyInducedSourceReader) ((SourceOperator) testHarness.getStreamTask().mainOperator).getSourceReader();
        CheckpointMetaData checkpointMetaData = new CheckpointMetaData(TestingExternallyInducedSourceReader.CHECKPOINT_ID, 2);
        if (rpcFirst) {
            testHarness.streamTask.triggerCheckpointAsync(checkpointMetaData, checkpointOptions);
            testHarness.processAll();
        } else {
            do {
                testHarness.processSingleStep();
            } while (!runtimeTestingReader.shouldTriggerCheckpoint().isPresent());
            // stream task should block when trigger received but no RPC
            assertThat(testHarness.streamTask.inputProcessor.isAvailable()).isFalse();
            CompletableFuture<Boolean> triggerCheckpointAsync = testHarness.streamTask.triggerCheckpointAsync(checkpointMetaData, checkpointOptions);
            // process mails until checkpoint has been processed
            while (!triggerCheckpointAsync.isDone()) {
                testHarness.processSingleStep();
            }
            // stream task should be unblocked now
            assertThat(testHarness.streamTask.inputProcessor.isAvailable()).isTrue();
            testHarness.processAll();
        }
        int expectedEvents = checkpointOptions.getCheckpointType().isSavepoint() && ((SavepointType) checkpointOptions.getCheckpointType()).isSynchronous() ? numEventsBeforeCheckpoint : totalNumEvents;
        assertThat(runtimeTestingReader.numEmittedEvents).isEqualTo(expectedEvents);
        assertThat(runtimeTestingReader.checkpointed).isTrue();
        assertThat(runtimeTestingReader.checkpointedId).isEqualTo(TestingExternallyInducedSourceReader.CHECKPOINT_ID);
        assertThat(runtimeTestingReader.checkpointedAt).isEqualTo(numEventsBeforeCheckpoint);
        Assertions.assertThat(testHarness.getOutput()).contains(new CheckpointBarrier(checkpointMetaData.getCheckpointId(), checkpointMetaData.getTimestamp(), checkpointOptions));
    }
}

