@Test
void testBufferDebloatingMultiGates() throws Exception {
    // debloat period doesn't matter, we will schedule debloating manually
    Configuration config = new Configuration().set(BUFFER_DEBLOAT_PERIOD, Duration.ofHours(10)).set(BUFFER_DEBLOAT_TARGET, Duration.ofSeconds(1)).set(BUFFER_DEBLOAT_ENABLED, true).set(BUFFER_DEBLOAT_THRESHOLD_PERCENTAGES, // disable the threshold to achieve exact buffer sizes
    0);
    final long throughputGate1 = 1024L;
    final long throughputGate2 = 60 * 1024L;
    final int inputChannelsGate1 = 1;
    final int inputChannelsGate2 = 4;
    final ThroughputCalculator throughputCalculator = new ThroughputCalculator(SystemClock.getInstance()) {

        /* parameters are ignored */
        private int callCount = 0;

        @Override
        public long calculateThroughput() {
            if (callCount++ % 2 == 0) {
                return throughputGate1;
            } else {
                return throughputGate2;
            }
        }
    };
    try (StreamTaskMailboxTestHarness<String> harness = new StreamTaskMailboxTestHarnessBuilder<>(OneInputStreamTask::new, STRING_TYPE_INFO).setTaskManagerRuntimeInfo(new TestingTaskManagerRuntimeInfo(config)).addInput(STRING_TYPE_INFO, inputChannelsGate1).addInput(STRING_TYPE_INFO, inputChannelsGate2).modifyGateBuilder(gateBuilder -> gateBuilder.setThroughputCalculator(bufferDebloatConfiguration -> throughputCalculator)).setupOutputForSingletonOperatorChain(new TestBoundedOneInputStreamOperator()).build()) {
        final IndexedInputGate[] inputGates = harness.streamTask.getEnvironment().getAllInputGates();
        harness.processAll();
        // call debloating until the EMA reaches the target buffer size
        while (getCurrentBufferSize(inputGates[0]) == 0 || getCurrentBufferSize(inputGates[0]) > throughputGate1) {
            harness.streamTask.debloat();
        }
        assertThat(getCurrentBufferSize(inputGates[0])).isEqualTo(throughputGate1);
        assertThat(getCurrentBufferSize(inputGates[1])).isEqualTo(throughputGate2 / inputChannelsGate2);
    }
}

/**
 * Tests mailbox metrics latency and queue size and verifies that (1) latency measurement is
 * executed once initially and at least once triggered by timer and (2) mailbox size is greater
 * than zero for some time and eventually equals to zero.
 *
 * @throws Exception on {@link MockEnvironmentBuilder#build()} failure.
 */
@Test
void testMailboxMetricsScheduling() throws Exception {
    try (MockEnvironment mockEnvironment = new MockEnvironmentBuilder().build()) {
        Gauge<Integer> mailboxSizeMetric = mockEnvironment.getMetricGroup().getIOMetricGroup().getMailboxSize();
        Histogram mailboxLatencyMetric = mockEnvironment.getMetricGroup().getIOMetricGroup().getMailboxLatency();
        AtomicInteger maxMailboxSize = new AtomicInteger(-1);
        final int minMeasurements = 2;
        SupplierWithException<StreamTask, Exception> task = () -> new StreamTask<Object, StreamOperator<Object>>(mockEnvironment) {

            @Override
            protected void init() {
                this.mailboxProcessor.getMailboxMetricsControl().setLatencyMeasurementInterval(2);
            }

            @Override
            protected void processInput(MailboxDefaultAction.Controller controller) throws Exception {
                if (mailboxLatencyMetric.getCount() < minMeasurements) {
                    mailboxProcessor.getMainMailboxExecutor().execute(() -> {
                    }, "mail");
                    Thread.sleep(1);
                } else {
                    controller.suspendDefaultAction();
                    mailboxProcessor.suspend();
                }
                maxMailboxSize.set(Math.max(maxMailboxSize.get(), mailboxSizeMetric.getValue()));
            }
        };
        runTask(task).waitForTaskCompletion(false);
        assertThat(mailboxLatencyMetric.getCount()).isGreaterThanOrEqualTo(minMeasurements);
        assertThat(maxMailboxSize).hasValueGreaterThan(0);
        assertThat(mailboxSizeMetric.getValue()).isZero();
    }
}

