    TaskMetricGroup taskMetricGroup = UnregisteredMetricGroups.createUnregisteredTaskMetricGroup();
    ResultPartitionWriter[] partitionWriters = new ResultPartitionWriter[3];
    for (int i = 0; i < partitionWriters.length; ++i) {
        partitionWriters[i] = new RecordOrEventCollectingResultPartitionWriter<>(new ArrayDeque<>(), new StreamElementSerializer<>(BasicTypeInfo.INT_TYPE_INFO.createSerializer(new SerializerConfigImpl())));
        partitionWriters[i].setup();
    }
    try (StreamTaskMailboxTestHarness<Integer> testHarness = new StreamTaskMailboxTestHarnessBuilder<>(TwoInputStreamTask::new, BasicTypeInfo.INT_TYPE_INFO).addInput(BasicTypeInfo.INT_TYPE_INFO).addInput(BasicTypeInfo.INT_TYPE_INFO).addAdditionalOutput(partitionWriters).setupOperatorChain(new OperatorID(), new PassThroughOperator<>()).chain(BasicTypeInfo.INT_TYPE_INFO.createSerializer(new SerializerConfigImpl())).setOperatorFactory(SimpleOperatorFactory.of(new OneInputStreamTaskTest.OddEvenOperator())).addNonChainedOutputsCount(new OutputTag<>("odd", BasicTypeInfo.INT_TYPE_INFO), 2).addNonChainedOutputsCount(1).build().chain(BasicTypeInfo.INT_TYPE_INFO.createSerializer(new SerializerConfigImpl())).setOperatorFactory(SimpleOperatorFactory.of(new OneInputStreamTaskTest.DuplicatingOperator())).addNonChainedOutputsCount(1).build().finish().setTaskMetricGroup(taskMetricGroup).build()) {
        Counter numRecordsInCounter = taskMetricGroup.getIOMetricGroup().getNumRecordsInCounter();
        Counter numRecordsOutCounter = taskMetricGroup.getIOMetricGroup().getNumRecordsOutCounter();
        final int numEvenRecords = 5;
        final int numOddRecords = 3;
        for (int x = 0; x < numEvenRecords; x++) {
            testHarness.processElement(new StreamRecord<>(2 * x));
        }
        for (int x = 0; x < numOddRecords; x++) {
            testHarness.processElement(new StreamRecord<>(2 * x + 1));
        }
        final int oddEvenOperatorOutputsWithOddTag = numOddRecords;
        final int oddEvenOperatorOutputsWithoutTag = numOddRecords + numEvenRecords;
        final int duplicatingOperatorOutput = (numOddRecords + numEvenRecords) * 2;
        assertThat(numRecordsInCounter.getCount()).isEqualTo(numOddRecords + numEvenRecords);
        assertThat(numRecordsOutCounter.getCount()).isEqualTo(oddEvenOperatorOutputsWithOddTag + oddEvenOperatorOutputsWithoutTag + duplicatingOperatorOutput);
        testHarness.waitForTaskCompletion();
    } finally {
        for (ResultPartitionWriter partitionWriter : partitionWriters) {
            partitionWriter.close();
        }
    }
}

@Test
void testExponentialBackoffDelayRetryStrategy() {
    int maxAttempts = 10;
    long initialDelay = 100L;
    long maxRetryDelay = 2000L;
    double multiplier = 2;
    AsyncRetryStrategy<Void> exponentialBackoffDelayRetryStrategy = new AsyncRetryStrategies.ExponentialBackoffDelayRetryStrategyBuilder<Void>(maxAttempts, initialDelay, maxRetryDelay, multiplier).build();
    assertThat(exponentialBackoffDelayRetryStrategy.canRetry(maxAttempts)).isTrue();
    assertThat(exponentialBackoffDelayRetryStrategy.canRetry(maxAttempts + 1)).isFalse();
    // test if this strategy can be reused.
    for (int j = 1; j <= 5; j++) {
        long currentDelay = initialDelay;
        for (int i = 1; i <= maxAttempts; i++) {
            assertThat(exponentialBackoffDelayRetryStrategy.getBackoffTimeMillis(i)).isEqualTo(currentDelay);
            currentDelay = Math.min((long) (currentDelay * multiplier), maxRetryDelay);
        }
    }
}

