@Test
void testRetrieveChanges() throws Exception {
    int totalCount = ChangelogCollectResult.CHANGE_RECORD_BUFFER_SIZE * 2;
    CloseableIterator<RowData> data = CloseableIterator.adapterForIterator(IntStream.range(0, totalCount).mapToObj(i -> (RowData) GenericRowData.of(i)).iterator());
    ChangelogCollectResult changelogResult = new ChangelogCollectResult(new StatementResult(ResolvedSchema.of(Column.physical("id", DataTypes.INT())), data, true, ResultKind.SUCCESS_WITH_CONTENT, JobID.generate()));
    int count = 0;
    boolean running = true;
    while (running) {
        final TypedResult<List<RowData>> result = changelogResult.retrieveChanges();
        // slow the processing down
        Thread.sleep(100);
        switch(result.getType()) {
            case EMPTY:
                // do nothing
                break;
            case EOS:
                running = false;
                break;
            case PAYLOAD:
                count += result.getPayload().size();
                break;
            default:
                throw new SqlExecutionException("Unknown result type: " + result.getType());
        }
    }
    assertThat(count).isEqualTo(totalCount);
}

