/**
 * Test that {@link SqlGatewayMessageHeaders} can identify the version correctly.
 */
@Test
void testSqlGatewayMessageHeaders() throws Exception {
    // The header can't support V0, but sends request by V0
    assertThatThrownBy(() -> restClient.sendRequest(serverAddress.getHostName(), serverAddress.getPort(), headerNot0, EmptyMessageParameters.getInstance(), EmptyRequestBody.getInstance(), Collections.emptyList(), SqlGatewayRestAPIVersion.V0)).satisfies(FlinkAssertions.anyCauseMatches(IllegalArgumentException.class, String.format("The requested version V0 is not supported by the request (method=%s URL=%s). Supported versions are: %s.", headerNot0.getHttpMethod(), headerNot0.getTargetRestEndpointURL(), headerNot0.getSupportedAPIVersions().stream().map(RestAPIVersion::getURLVersionPrefix).collect(Collectors.joining(",")))));
    // The header only supports V0, sends request by V0
    CompletableFuture<TestResponse> specifiedVersionResponse = restClient.sendRequest(serverAddress.getHostName(), serverAddress.getPort(), header0, EmptyMessageParameters.getInstance(), EmptyRequestBody.getInstance(), Collections.emptyList(), SqlGatewayRestAPIVersion.V0);
    TestResponse testResponse0 = specifiedVersionResponse.get(timeout.toMillis(), TimeUnit.MILLISECONDS);
    assertThat(testResponse0.getStatus()).isEqualTo("V0");
    // The header only supports V0, lets the client get the version
    CompletableFuture<TestResponse> unspecifiedVersionResponse0 = restClient.sendRequest(serverAddress.getHostName(), serverAddress.getPort(), header0, EmptyMessageParameters.getInstance(), EmptyRequestBody.getInstance(), Collections.emptyList());
    TestResponse testResponse1 = unspecifiedVersionResponse0.get(timeout.toMillis(), TimeUnit.MILLISECONDS);
    assertThat(testResponse1.getStatus()).isEqualTo("V0");
    // The header supports multiple versions, lets the client get the latest version as default
    CompletableFuture<TestResponse> unspecifiedVersionResponse1 = restClient.sendRequest(serverAddress.getHostName(), serverAddress.getPort(), headerNot0, EmptyMessageParameters.getInstance(), EmptyRequestBody.getInstance(), Collections.emptyList());
    TestResponse testResponse2 = unspecifiedVersionResponse1.get(timeout.toMillis(), TimeUnit.MILLISECONDS);
    assertThat(testResponse2.getStatus()).isEqualTo(RestAPIVersion.getLatestVersion(headerNot0.getSupportedAPIVersions()).name());
}

