@Test
void testCreateMaterializedTableInContinuousMode() throws Exception {
    String materializedTableDDL = "CREATE MATERIALIZED TABLE users_shops" + " PARTITIONED BY (ds)\n" + " WITH(\n" + "   'format' = 'debezium-json'\n" + " )\n" + " FRESHNESS = INTERVAL '30' SECOND\n" + " AS SELECT \n" + "  user_id,\n" + "  shop_id,\n" + "  ds,\n" + "  SUM (payment_amount_cents) AS payed_buy_fee_sum,\n" + "  SUM (1) AS pv\n" + " FROM (\n" + "    SELECT user_id, shop_id, DATE_FORMAT(order_created_at, 'yyyy-MM-dd') AS ds, payment_amount_cents FROM datagenSource" + " ) AS tmp\n" + " GROUP BY (user_id, shop_id, ds)";
    OperationHandle materializedTableHandle = service.executeStatement(sessionHandle, materializedTableDDL, -1, new Configuration());
    awaitOperationTermination(service, sessionHandle, materializedTableHandle);
    // validate materialized table: schema, refresh mode, refresh status, refresh handler,
    // doesn't check the data because it generates randomly.
    ResolvedCatalogMaterializedTable actualMaterializedTable = (ResolvedCatalogMaterializedTable) service.getTable(sessionHandle, ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "users_shops"));
    // Expected schema
    ResolvedSchema expectedSchema = ResolvedSchema.of(Arrays.asList(Column.physical("user_id", DataTypes.BIGINT()), Column.physical("shop_id", DataTypes.BIGINT()), Column.physical("ds", DataTypes.STRING()), Column.physical("payed_buy_fee_sum", DataTypes.BIGINT()), Column.physical("pv", DataTypes.INT().notNull())));
    assertThat(actualMaterializedTable.getResolvedSchema()).isEqualTo(expectedSchema);
    assertThat(actualMaterializedTable.getFreshness()).isEqualTo(Duration.ofSeconds(30));
    assertThat(actualMaterializedTable.getLogicalRefreshMode()).isEqualTo(CatalogMaterializedTable.LogicalRefreshMode.AUTOMATIC);
    assertThat(actualMaterializedTable.getRefreshMode()).isEqualTo(CatalogMaterializedTable.RefreshMode.CONTINUOUS);
    assertThat(actualMaterializedTable.getRefreshStatus()).isEqualTo(CatalogMaterializedTable.RefreshStatus.ACTIVATED);
    assertThat(actualMaterializedTable.getRefreshHandlerDescription()).isNotEmpty();
    assertThat(actualMaterializedTable.getSerializedRefreshHandler()).isNotEmpty();
    ContinuousRefreshHandler activeRefreshHandler = ContinuousRefreshHandlerSerializer.INSTANCE.deserialize(actualMaterializedTable.getSerializedRefreshHandler(), getClass().getClassLoader());
    waitUntilAllTasksAreRunning(restClusterClient, JobID.fromHexString(activeRefreshHandler.getJobId()));
    // verify the background job is running
    String describeJobDDL = String.format("DESCRIBE JOB '%s'", activeRefreshHandler.getJobId());
    OperationHandle describeJobHandle = service.executeStatement(sessionHandle, describeJobDDL, -1, new Configuration());
    awaitOperationTermination(service, sessionHandle, describeJobHandle);
    List<RowData> jobResults = fetchAllResults(service, sessionHandle, describeJobHandle);
    assertThat(jobResults.get(0).getString(2).toString()).isEqualTo("RUNNING");
    // get checkpoint interval
    long checkpointInterval = getCheckpointIntervalConfig(restClusterClient, activeRefreshHandler.getJobId());
    assertThat(checkpointInterval).isEqualTo(30 * 1000);
    // drop the materialized table
    dropMaterializedTable(ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "users_shops"));
}

