    String sourceDdl = String.format("CREATE TABLE IF NOT EXISTS my_source (\n" + "  order_id BIGINT,\n" + "  user_id BIGINT,\n" + "  shop_id BIGINT,\n" + "  order_created_at STRING\n" + ")\n" + "WITH (\n" + "  'connector' = 'values',\n" + "  'bounded' = 'true',\n" + "  'data-id' = '%s'\n" + ")", dataId);
