@Test
void testAlterMaterializedTableSuspendAndResumeInContinuousMode(@TempDir Path temporaryPath) throws Exception {
    String materializedTableDDL = "CREATE MATERIALIZED TABLE users_shops" + " PARTITIONED BY (ds)\n" + " WITH(\n" + "   'format' = 'debezium-json'\n" + " )\n" + " FRESHNESS = INTERVAL '30' SECOND\n" + " AS SELECT \n" + "  user_id,\n" + "  shop_id,\n" + "  ds,\n" + "  SUM (payment_amount_cents) AS payed_buy_fee_sum,\n" + "  SUM (1) AS pv\n" + " FROM (\n" + "    SELECT user_id, shop_id, DATE_FORMAT(order_created_at, 'yyyy-MM-dd') AS ds, payment_amount_cents FROM datagenSource" + " ) AS tmp\n" + " GROUP BY (user_id, shop_id, ds)";
    OperationHandle materializedTableHandle = service.executeStatement(sessionHandle, materializedTableDDL, -1, new Configuration());
    awaitOperationTermination(service, sessionHandle, materializedTableHandle);
    ResolvedCatalogMaterializedTable activeMaterializedTable = (ResolvedCatalogMaterializedTable) service.getTable(sessionHandle, ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "users_shops"));
    assertThat(activeMaterializedTable.getRefreshStatus()).isEqualTo(CatalogMaterializedTable.RefreshStatus.ACTIVATED);
    ContinuousRefreshHandler activeRefreshHandler = ContinuousRefreshHandlerSerializer.INSTANCE.deserialize(activeMaterializedTable.getSerializedRefreshHandler(), getClass().getClassLoader());
    waitUntilAllTasksAreRunning(restClusterClient, JobID.fromHexString(activeRefreshHandler.getJobId()));
    // set up savepoint dir
    String savepointDir = temporaryPath.toString();
    String alterJobSavepointDDL = String.format("SET 'execution.checkpointing.savepoint-dir' = 'file://%s'", savepointDir);
    OperationHandle alterMaterializedTableSavepointHandle = service.executeStatement(sessionHandle, alterJobSavepointDDL, -1, new Configuration());
    awaitOperationTermination(service, sessionHandle, alterMaterializedTableSavepointHandle);
    // suspend materialized table
    String alterMaterializedTableSuspendDDL = "ALTER MATERIALIZED TABLE users_shops SUSPEND";
    OperationHandle alterMaterializedTableSuspendHandle = service.executeStatement(sessionHandle, alterMaterializedTableSuspendDDL, -1, new Configuration());
    awaitOperationTermination(service, sessionHandle, alterMaterializedTableSuspendHandle);
    ResolvedCatalogMaterializedTable suspendMaterializedTable = (ResolvedCatalogMaterializedTable) service.getTable(sessionHandle, ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "users_shops"));
    assertThat(suspendMaterializedTable.getRefreshStatus()).isEqualTo(CatalogMaterializedTable.RefreshStatus.SUSPENDED);
    // verify background job is stopped
    byte[] refreshHandler = suspendMaterializedTable.getSerializedRefreshHandler();
    ContinuousRefreshHandler suspendRefreshHandler = ContinuousRefreshHandlerSerializer.INSTANCE.deserialize(refreshHandler, getClass().getClassLoader());
    String suspendJobId = suspendRefreshHandler.getJobId();
    String describeJobDDL = String.format("DESCRIBE JOB '%s'", suspendJobId);
    OperationHandle describeJobHandle = service.executeStatement(sessionHandle, describeJobDDL, -1, new Configuration());
    awaitOperationTermination(service, sessionHandle, alterMaterializedTableSuspendHandle);
    List<RowData> jobResults = fetchAllResults(service, sessionHandle, describeJobHandle);
    assertThat(jobResults.get(0).getString(2).toString()).isEqualTo("FINISHED");
    // verify savepoint is created
    assertThat(suspendRefreshHandler.getRestorePath()).isNotEmpty();
    String actualSavepointPath = suspendRefreshHandler.getRestorePath().get();
    // resume materialized table
    String alterMaterializedTableResumeDDL = "ALTER MATERIALIZED TABLE users_shops RESUME WITH ('debezium-json.ignore-parse-errors' = 'true')";
    OperationHandle alterMaterializedTableResumeHandle = service.executeStatement(sessionHandle, alterMaterializedTableResumeDDL, -1, new Configuration());
    awaitOperationTermination(service, sessionHandle, alterMaterializedTableResumeHandle);
    ResolvedCatalogMaterializedTable resumedCatalogMaterializedTable = (ResolvedCatalogMaterializedTable) service.getTable(sessionHandle, ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "users_shops"));
    assertThat(resumedCatalogMaterializedTable.getOptions()).doesNotContainKey("debezium-json.ignore-parse-errors");
    assertThat(resumedCatalogMaterializedTable.getRefreshStatus()).isEqualTo(CatalogMaterializedTable.RefreshStatus.ACTIVATED);
    waitUntilAllTasksAreRunning(restClusterClient, JobID.fromHexString(ContinuousRefreshHandlerSerializer.INSTANCE.deserialize(resumedCatalogMaterializedTable.getSerializedRefreshHandler(), getClass().getClassLoader()).getJobId()));
    // verify background job is running
    refreshHandler = resumedCatalogMaterializedTable.getSerializedRefreshHandler();
    ContinuousRefreshHandler resumeRefreshHandler = ContinuousRefreshHandlerSerializer.INSTANCE.deserialize(refreshHandler, getClass().getClassLoader());
    String resumeJobId = resumeRefreshHandler.getJobId();
    String describeResumeJobDDL = String.format("DESCRIBE JOB '%s'", resumeJobId);
    OperationHandle describeResumeJobHandle = service.executeStatement(sessionHandle, describeResumeJobDDL, -1, new Configuration());
    awaitOperationTermination(service, sessionHandle, describeResumeJobHandle);
    jobResults = fetchAllResults(service, sessionHandle, describeResumeJobHandle);
    assertThat(jobResults.get(0).getString(2).toString()).isEqualTo("RUNNING");
    // verify resumed job is restored from savepoint
    Optional<String> actualRestorePath = getJobRestoreSavepointPath(restClusterClient, resumeJobId);
    assertThat(actualRestorePath).isNotEmpty();
    assertThat(actualRestorePath.get()).isEqualTo(actualSavepointPath);
    // drop the materialized table
    dropMaterializedTable(ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "users_shops"));
}

