@Test
void testAlterMaterializedTableSuspendAndResumeInFullMode() throws Exception {
    createAndVerifyCreateMaterializedTableWithData("users_shops", Collections.emptyList(), Collections.emptyMap(), RefreshMode.FULL);
    ResolvedCatalogMaterializedTable activeMaterializedTable = (ResolvedCatalogMaterializedTable) service.getTable(sessionHandle, ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "users_shops"));
    assertThat(activeMaterializedTable.getRefreshStatus()).isEqualTo(CatalogMaterializedTable.RefreshStatus.ACTIVATED);
    // suspend materialized table
    String alterMaterializedTableSuspendDDL = "ALTER MATERIALIZED TABLE users_shops SUSPEND";
    OperationHandle alterMaterializedTableSuspendHandle = service.executeStatement(sessionHandle, alterMaterializedTableSuspendDDL, -1, new Configuration());
    awaitOperationTermination(service, sessionHandle, alterMaterializedTableSuspendHandle);
    ResolvedCatalogMaterializedTable suspendMaterializedTable = (ResolvedCatalogMaterializedTable) service.getTable(sessionHandle, ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "users_shops"));
    assertThat(suspendMaterializedTable.getRefreshStatus()).isEqualTo(CatalogMaterializedTable.RefreshStatus.SUSPENDED);
    // verify workflow is suspended
    byte[] refreshHandler = suspendMaterializedTable.getSerializedRefreshHandler();
    EmbeddedRefreshHandler suspendRefreshHandler = EmbeddedRefreshHandlerSerializer.INSTANCE.deserialize(refreshHandler, getClass().getClassLoader());
    String workflowName = suspendRefreshHandler.getWorkflowName();
    String workflowGroup = suspendRefreshHandler.getWorkflowGroup();
    EmbeddedQuartzScheduler embeddedWorkflowScheduler = SQL_GATEWAY_REST_ENDPOINT_EXTENSION.getSqlGatewayRestEndpoint().getQuartzScheduler();
    JobKey jobKey = JobKey.jobKey(workflowName, workflowGroup);
    Trigger.TriggerState suspendTriggerState = embeddedWorkflowScheduler.getQuartzScheduler().getTriggerState(TriggerKey.triggerKey(workflowName, workflowGroup));
    assertThat(suspendTriggerState).isEqualTo(Trigger.TriggerState.PAUSED);
    // resume materialized table
    String alterMaterializedTableResumeDDL = "ALTER MATERIALIZED TABLE users_shops RESUME WITH ('debezium-json.ignore-parse-errors' = 'true')";
    OperationHandle alterMaterializedTableResumeHandle = service.executeStatement(sessionHandle, alterMaterializedTableResumeDDL, -1, new Configuration());
    awaitOperationTermination(service, sessionHandle, alterMaterializedTableResumeHandle);
    ResolvedCatalogMaterializedTable resumedCatalogMaterializedTable = (ResolvedCatalogMaterializedTable) service.getTable(sessionHandle, ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "users_shops"));
    assertThat(resumedCatalogMaterializedTable.getRefreshStatus()).isEqualTo(CatalogMaterializedTable.RefreshStatus.ACTIVATED);
    // verify workflow is resumed
    refreshHandler = resumedCatalogMaterializedTable.getSerializedRefreshHandler();
    EmbeddedRefreshHandler resumeRefreshHandler = EmbeddedRefreshHandlerSerializer.INSTANCE.deserialize(refreshHandler, getClass().getClassLoader());
    assertThat(resumeRefreshHandler.getWorkflowName()).isEqualTo(workflowName);
    assertThat(resumeRefreshHandler.getWorkflowGroup()).isEqualTo(workflowGroup);
    JobDetail jobDetail = embeddedWorkflowScheduler.getQuartzScheduler().getJobDetail(jobKey);
    Trigger.TriggerState resumedTriggerState = embeddedWorkflowScheduler.getQuartzScheduler().getTriggerState(TriggerKey.triggerKey(workflowName, workflowGroup));
    assertThat(resumedTriggerState).isEqualTo(Trigger.TriggerState.NORMAL);
    WorkflowInfo workflowInfo = fromJson((String) jobDetail.getJobDataMap().get(WORKFLOW_INFO), WorkflowInfo.class);
    assertThat(workflowInfo.getDynamicOptions()).containsEntry("debezium-json.ignore-parse-errors", "true");
    // drop the materialized table
    dropMaterializedTable(ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "users_shops"));
}

