@Test
void testAlterMaterializedTableAsQueryInFullMode() throws Exception {
    createAndVerifyCreateMaterializedTableWithData("users_shops", Collections.emptyList(), Collections.emptyMap(), RefreshMode.FULL);
    ResolvedCatalogMaterializedTable oldTable = (ResolvedCatalogMaterializedTable) service.getTable(sessionHandle, ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "users_shops"));
    // Alter materialized table as query in full mode
    String alterMaterializedTableAsQueryDDL = "ALTER MATERIALIZED TABLE users_shops" + " AS SELECT \n" + "  user_id,\n" + "  shop_id,\n" + "  ds,\n" + "  COUNT(order_id) AS order_cnt,\n" + "  SUM(order_amount) AS order_amount_sum\n" + " FROM (\n" + "    SELECT user_id, shop_id, order_created_at AS ds, order_id, 1 as order_amount FROM my_source" + " ) AS tmp\n" + " GROUP BY (user_id, shop_id, ds)";
    OperationHandle alterMaterializedTableAsQueryHandle = service.executeStatement(sessionHandle, alterMaterializedTableAsQueryDDL, -1, new Configuration());
    awaitOperationTermination(service, sessionHandle, alterMaterializedTableAsQueryHandle);
    // verify the altered materialized table
    ResolvedCatalogMaterializedTable newTable = (ResolvedCatalogMaterializedTable) service.getTable(sessionHandle, ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "users_shops"));
    assertThat(getAddedColumns(newTable.getResolvedSchema(), oldTable.getResolvedSchema())).isEqualTo(Collections.singletonList(Column.physical("order_amount_sum", DataTypes.INT())));
    assertThat(newTable.getDefinitionQuery()).isEqualTo(String.format("SELECT `tmp`.`user_id`, `tmp`.`shop_id`, `tmp`.`ds`, COUNT(`tmp`.`order_id`) AS `order_cnt`, SUM(`tmp`.`order_amount`) AS `order_amount_sum`\n" + "FROM (SELECT `my_source`.`user_id`, `my_source`.`shop_id`, `my_source`.`order_created_at` AS `ds`, `my_source`.`order_id`, 1 AS `order_amount`\n" + "FROM `%s`.`test_db`.`my_source`) AS `tmp`\n" + "GROUP BY ROW(`tmp`.`user_id`, `tmp`.`shop_id`, `tmp`.`ds`)", fileSystemCatalogName));
    // the refresh handler in full mode should be the same as the old one
    assertThat(oldTable.getSerializedRefreshHandler()).isEqualTo(newTable.getSerializedRefreshHandler());
    assertThat(oldTable.getDefinitionFreshness()).isEqualTo(newTable.getDefinitionFreshness());
}

