@Test
void testAlterMaterializedTableAsQueryInContinuousMode(@TempDir Path temporaryPath) throws Exception {
    String materializedTableDDL = "CREATE MATERIALIZED TABLE users_shops (" + " PRIMARY KEY (ds, user_id) not enforced)" + " PARTITIONED BY (ds)\n" + " WITH(\n" + "   'format' = 'debezium-json'\n" + " )\n" + " FRESHNESS = INTERVAL '30' SECOND\n" + " AS SELECT \n" + "  coalesce(user_id, 0) as user_id,\n" + "  shop_id,\n" + "  coalesce(ds, '') as ds,\n" + "  SUM (payment_amount_cents) AS payed_buy_fee_sum\n" + " FROM (\n" + "    SELECT user_id, shop_id, DATE_FORMAT(order_created_at, 'yyyy-MM-dd') AS ds, payment_amount_cents FROM datagenSource" + " ) AS tmp\n" + " GROUP BY (user_id, shop_id, ds)";
    OperationHandle materializedTableHandle = service.executeStatement(sessionHandle, materializedTableDDL, -1, new Configuration());
    awaitOperationTermination(service, sessionHandle, materializedTableHandle);
    ResolvedCatalogMaterializedTable oldTable = (ResolvedCatalogMaterializedTable) service.getTable(sessionHandle, ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "users_shops"));
    // verify background job is running
    ContinuousRefreshHandler activeRefreshHandler = ContinuousRefreshHandlerSerializer.INSTANCE.deserialize(oldTable.getSerializedRefreshHandler(), getClass().getClassLoader());
    waitUntilAllTasksAreRunning(restClusterClient, JobID.fromHexString(activeRefreshHandler.getJobId()));
    // setup savepoint dir
    String savepointDir = "file://" + temporaryPath.toAbsolutePath();
    String setupSavepointDDL = "SET 'execution.checkpointing.savepoint-dir' = '" + savepointDir + "'";
    OperationHandle setupSavepointHandle = service.executeStatement(sessionHandle, setupSavepointDDL, -1, new Configuration());
    awaitOperationTermination(service, sessionHandle, setupSavepointHandle);
    String alterTableDDL = "ALTER MATERIALIZED TABLE users_shops" + " AS SELECT \n" + "  coalesce(user_id, 0) as user_id,\n" + "  shop_id,\n" + "  coalesce(ds, '') as ds,\n" + "  SUM (payment_amount_cents) AS payed_buy_fee_sum,\n" + "  SUM (1) AS pv\n" + " FROM (\n" + "    SELECT user_id, shop_id, DATE_FORMAT(order_created_at, 'yyyy-MM-dd') AS ds, payment_amount_cents FROM datagenSource" + " ) AS tmp\n" + " GROUP BY (user_id, shop_id, ds)";
    OperationHandle alterTableHandle = service.executeStatement(sessionHandle, alterTableDDL, -1, new Configuration());
    awaitOperationTermination(service, sessionHandle, alterTableHandle);
    ResolvedCatalogMaterializedTable newTable = (ResolvedCatalogMaterializedTable) service.getTable(sessionHandle, ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "users_shops"));
    assertThat(getAddedColumns(newTable.getResolvedSchema(), oldTable.getResolvedSchema())).isEqualTo(Collections.singletonList(Column.physical("pv", DataTypes.INT())));
    assertThat(newTable.getResolvedSchema().getPrimaryKey()).isEqualTo(oldTable.getResolvedSchema().getPrimaryKey());
    assertThat(newTable.getResolvedSchema().getWatermarkSpecs()).isEqualTo(oldTable.getResolvedSchema().getWatermarkSpecs());
    assertThat(newTable.getDefinitionQuery()).isEqualTo(String.format("SELECT COALESCE(`tmp`.`user_id`, 0) AS `user_id`, `tmp`.`shop_id`, COALESCE(`tmp`.`ds`, '') AS `ds`, SUM(`tmp`.`payment_amount_cents`) AS `payed_buy_fee_sum`, SUM(1) AS `pv`\n" + "FROM (SELECT `datagenSource`.`user_id`, `datagenSource`.`shop_id`, `DATE_FORMAT`(`datagenSource`.`order_created_at`, 'yyyy-MM-dd') AS `ds`, `datagenSource`.`payment_amount_cents`\n" + "FROM `%s`.`test_db`.`datagenSource`) AS `tmp`\n" + "GROUP BY ROW(`tmp`.`user_id`, `tmp`.`shop_id`, `tmp`.`ds`)", fileSystemCatalogName));
    assertThat(oldTable.getSerializedRefreshHandler()).isNotEqualTo(newTable.getSerializedRefreshHandler());
    // verify the new continuous job is start without savepoint
    ContinuousRefreshHandler newContinuousRefreshHandler = ContinuousRefreshHandlerSerializer.INSTANCE.deserialize(newTable.getSerializedRefreshHandler(), Thread.currentThread().getContextClassLoader());
    Optional<String> restorePath = getJobRestoreSavepointPath(restClusterClient, newContinuousRefreshHandler.getJobId());
    assertThat(restorePath).isEmpty();
    // drop the materialized table
    dropMaterializedTable(ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "users_shops"));
}

