void testAlterMaterializedTableAsQueryInContinuousModeWithSuspendStatus(@TempDir Path temporaryPath) throws Exception {
    String materializedTableDDL = "CREATE MATERIALIZED TABLE users_shops" + " PARTITIONED BY (ds)\n" + " WITH(\n" + "   'format' = 'debezium-json'\n" + " )\n" + " FRESHNESS = INTERVAL '30' SECOND\n" + " AS SELECT \n" + "  user_id,\n" + "  shop_id,\n" + "  ds,\n" + "  SUM (payment_amount_cents) AS payed_buy_fee_sum\n" + " FROM (\n" + "    SELECT user_id, shop_id, DATE_FORMAT(order_created_at, 'yyyy-MM-dd') AS ds, payment_amount_cents FROM datagenSource" + " ) AS tmp\n" + " GROUP BY (user_id, shop_id, ds)";
    OperationHandle materializedTableHandle = service.executeStatement(sessionHandle, materializedTableDDL, -1, new Configuration());
    awaitOperationTermination(service, sessionHandle, materializedTableHandle);
    ResolvedCatalogMaterializedTable oldTable = (ResolvedCatalogMaterializedTable) service.getTable(sessionHandle, ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "users_shops"));
    // verify background job is running
    ContinuousRefreshHandler activeRefreshHandler = ContinuousRefreshHandlerSerializer.INSTANCE.deserialize(oldTable.getSerializedRefreshHandler(), getClass().getClassLoader());
    waitUntilAllTasksAreRunning(restClusterClient, JobID.fromHexString(activeRefreshHandler.getJobId()));
    // setup savepoint dir
    String savepointDir = "file://" + temporaryPath.toAbsolutePath();
    String setupSavepointDDL = "SET 'execution.checkpointing.savepoint-dir' = '" + savepointDir + "'";
    OperationHandle setupSavepointHandle = service.executeStatement(sessionHandle, setupSavepointDDL, -1, new Configuration());
    awaitOperationTermination(service, sessionHandle, setupSavepointHandle);
    // suspend materialized table
    String suspendTableDDL = "ALTER MATERIALIZED TABLE users_shops SUSPEND";
    OperationHandle suspendTableHandle = service.executeStatement(sessionHandle, suspendTableDDL, -1, new Configuration());
    awaitOperationTermination(service, sessionHandle, suspendTableHandle);
    String alterTableDDL = "ALTER MATERIALIZED TABLE users_shops" + " AS SELECT \n" + "  user_id,\n" + "  shop_id,\n" + "  ds,\n" + "  SUM (payment_amount_cents) AS payed_buy_fee_sum,\n" + "  SUM (1) AS pv\n" + " FROM (\n" + "    SELECT user_id, shop_id, DATE_FORMAT(order_created_at, 'yyyy-MM-dd') AS ds, payment_amount_cents FROM datagenSource" + " ) AS tmp\n" + " GROUP BY (user_id, shop_id, ds)";
    OperationHandle alterTableHandle = service.executeStatement(sessionHandle, alterTableDDL, -1, new Configuration());
    awaitOperationTermination(service, sessionHandle, alterTableHandle);
    ResolvedCatalogMaterializedTable newTable = (ResolvedCatalogMaterializedTable) service.getTable(sessionHandle, ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "users_shops"));
    assertThat(getAddedColumns(newTable.getResolvedSchema(), oldTable.getResolvedSchema())).isEqualTo(Collections.singletonList(Column.physical("pv", DataTypes.INT())));
    assertThat(newTable.getDefinitionQuery()).isEqualTo(String.format("SELECT `tmp`.`user_id`, `tmp`.`shop_id`, `tmp`.`ds`, SUM(`tmp`.`payment_amount_cents`) AS `payed_buy_fee_sum`, SUM(1) AS `pv`\n" + "FROM (SELECT `datagenSource`.`user_id`, `datagenSource`.`shop_id`, `DATE_FORMAT`(`datagenSource`.`order_created_at`, 'yyyy-MM-dd') AS `ds`, `datagenSource`.`payment_amount_cents`\n" + "FROM `%s`.`test_db`.`datagenSource`) AS `tmp`\n" + "GROUP BY ROW(`tmp`.`user_id`, `tmp`.`shop_id`, `tmp`.`ds`)", fileSystemCatalogName));
    assertThat(oldTable.getSerializedRefreshHandler()).isEqualTo(newTable.getSerializedRefreshHandler());
    assertThat(oldTable.getDefinitionFreshness()).isEqualTo(newTable.getDefinitionFreshness());
    // verify the restore path is empty
    ContinuousRefreshHandler newContinuousRefreshHandler = ContinuousRefreshHandlerSerializer.INSTANCE.deserialize(newTable.getSerializedRefreshHandler(), Thread.currentThread().getContextClassLoader());
    assertThat(newContinuousRefreshHandler.getRestorePath()).isEmpty();
    // drop the materialized table
    dropMaterializedTable(ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "users_shops"));
}

@Test
void testDropMaterializedTableInContinuousMode() throws Exception {
    String materializedTableDDL = "CREATE MATERIALIZED TABLE users_shops" + " PARTITIONED BY (ds)\n" + " WITH(\n" + "   'format' = 'debezium-json'\n" + " )\n" + " FRESHNESS = INTERVAL '30' SECOND\n" + " AS SELECT \n" + "  user_id,\n" + "  shop_id,\n" + "  ds,\n" + "  SUM (payment_amount_cents) AS payed_buy_fee_sum,\n" + "  SUM (1) AS pv\n" + " FROM (\n" + "    SELECT user_id, shop_id, DATE_FORMAT(order_created_at, 'yyyy-MM-dd') AS ds, payment_amount_cents FROM datagenSource" + " ) AS tmp\n" + " GROUP BY (user_id, shop_id, ds)";
    OperationHandle materializedTableHandle = service.executeStatement(sessionHandle, materializedTableDDL, -1, new Configuration());
    awaitOperationTermination(service, sessionHandle, materializedTableHandle);
    // verify materialized table exists
    ResolvedCatalogBaseTable<?> activeMaterializedTable = service.getTable(sessionHandle, ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "users_shops"));
    assertThat(activeMaterializedTable).isInstanceOf(ResolvedCatalogMaterializedTable.class);
    waitUntilAllTasksAreRunning(restClusterClient, JobID.fromHexString(ContinuousRefreshHandlerSerializer.INSTANCE.deserialize(((ResolvedCatalogMaterializedTable) activeMaterializedTable).getSerializedRefreshHandler(), getClass().getClassLoader()).getJobId()));
    // verify background job is running
    ContinuousRefreshHandler activeRefreshHandler = ContinuousRefreshHandlerSerializer.INSTANCE.deserialize(((ResolvedCatalogMaterializedTable) activeMaterializedTable).getSerializedRefreshHandler(), getClass().getClassLoader());
    String describeJobDDL = String.format("DESCRIBE JOB '%s'", activeRefreshHandler.getJobId());
    OperationHandle describeJobHandle = service.executeStatement(sessionHandle, describeJobDDL, -1, new Configuration());
    awaitOperationTermination(service, sessionHandle, describeJobHandle);
    List<RowData> jobResults = fetchAllResults(service, sessionHandle, describeJobHandle);
    assertThat(jobResults.get(0).getString(2).toString()).isEqualTo("RUNNING");
    // Drop materialized table using drop table statement
    String dropTableUsingMaterializedTableDDL = "DROP TABLE users_shops";
    OperationHandle dropTableUsingMaterializedTableHandle = service.executeStatement(sessionHandle, dropTableUsingMaterializedTableDDL, -1, new Configuration());
    assertThatThrownBy(() -> awaitOperationTermination(service, sessionHandle, dropTableUsingMaterializedTableHandle)).rootCause().isInstanceOf(ValidationException.class).hasMessage(String.format("Table with identifier '%s' does not exist.", ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "users_shops").asSummaryString()));
    // drop materialized table
    String dropMaterializedTableDDL = "DROP MATERIALIZED TABLE IF EXISTS users_shops";
    OperationHandle dropMaterializedTableHandle = service.executeStatement(sessionHandle, dropMaterializedTableDDL, -1, new Configuration());
    awaitOperationTermination(service, sessionHandle, dropMaterializedTableHandle);
    // verify materialized table metadata is removed
    assertThatThrownBy(() -> service.getTable(sessionHandle, ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "users_shops"))).isInstanceOf(SqlGatewayException.class).hasMessageContaining("Failed to getTable.");
    // verify background job is canceled
    waitUntilJobCanceled(JobID.fromHexString(activeRefreshHandler.getJobId()), restClusterClient);
    String describeJobAfterDropDDL = String.format("DESCRIBE JOB '%s'", activeRefreshHandler.getJobId());
    OperationHandle describeJobAfterDropHandle = service.executeStatement(sessionHandle, describeJobAfterDropDDL, -1, new Configuration());
    awaitOperationTermination(service, sessionHandle, describeJobAfterDropHandle);
    List<RowData> jobResultsAfterDrop = fetchAllResults(service, sessionHandle, describeJobAfterDropHandle);
    assertThat(jobResultsAfterDrop.get(0).getString(2).toString()).isEqualTo("CANCELED");
    // verify drop materialized table that doesn't exist
    String dropNonExistMaterializedTableDDL = "DROP MATERIALIZED TABLE users_shops";
    OperationHandle dropNonExistTableHandle = service.executeStatement(sessionHandle, dropNonExistMaterializedTableDDL, -1, new Configuration());
    assertThatThrownBy(() -> awaitOperationTermination(service, sessionHandle, dropNonExistTableHandle)).rootCause().isInstanceOf(ValidationException.class).hasMessage(String.format("Materialized table with identifier %s does not exist.", ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "users_shops").asSerializableString()));
    String dropNonExistMaterializedTableDDL2 = "DROP MATERIALIZED TABLE IF EXISTS users_shops";
    OperationHandle dropNonExistMaterializedTableHandle2 = service.executeStatement(sessionHandle, dropNonExistMaterializedTableDDL2, -1, new Configuration());
    awaitOperationTermination(service, sessionHandle, dropNonExistMaterializedTableHandle2);
    // Drop a table using drop materialized table statement
    dropMaterializedTableDDL = "DROP MATERIALIZED TABLE IF EXISTS datagenSource";
    OperationHandle dropTableHandle = service.executeStatement(sessionHandle, dropMaterializedTableDDL, -1, new Configuration());
    assertThatThrownBy(() -> awaitOperationTermination(service, sessionHandle, dropTableHandle)).rootCause().isInstanceOf(ValidationException.class).hasMessage(String.format("Table %s is not a materialized table, does not support materialized table related operation.", ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "datagenSource").asSerializableString()));
}

