@Test
void testRefreshMaterializedTableWithStaticPartitionInContinuousMode() throws Exception {
    List<Row> data = new ArrayList<>();
    data.add(Row.of(1L, 1L, 1L, "2024-01-01"));
    data.add(Row.of(2L, 2L, 2L, "2024-01-02"));
    createAndVerifyCreateMaterializedTableWithData("my_materialized_table", data, Collections.singletonMap("ds", "yyyy-MM-dd"), RefreshMode.CONTINUOUS);
    ObjectIdentifier objectIdentifier = ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "my_materialized_table");
    // add more data to all data list
    data.add(Row.of(3L, 3L, 3L, "2024-01-01"));
    data.add(Row.of(4L, 4L, 4L, "2024-01-02"));
    // refresh the materialized table with static partition
    long startTime = System.currentTimeMillis();
    Map<String, String> staticPartitions = new HashMap<>();
    staticPartitions.put("ds", "2024-01-02");
    OperationHandle refreshTableHandle = service.refreshMaterializedTable(sessionHandle, objectIdentifier.asSerializableString(), false, null, Collections.emptyMap(), staticPartitions, Collections.emptyMap());
    awaitOperationTermination(service, sessionHandle, refreshTableHandle);
    List<RowData> result = fetchAllResults(service, sessionHandle, refreshTableHandle);
    assertThat(result.size()).isEqualTo(1);
    String jobId = result.get(0).getString(0).toString();
    // 1. verify fresh job created
    verifyRefreshJobCreated(restClusterClient, jobId, startTime);
    // 2. verify the new job overwrite the data
    assertThat(fetchTableData(sessionHandle, "SELECT * FROM my_materialized_table where ds = '2024-01-02'").size()).isEqualTo(getPartitionSize(data, "2024-01-02"));
    // 3. verify the data of partition '2024-01-01' is not changed
    assertThat(fetchTableData(sessionHandle, "SELECT * FROM my_materialized_table where ds = '2024-01-01'").size()).isNotEqualTo(getPartitionSize(data, "2024-01-01"));
    // drop the materialized table
    dropMaterializedTable(ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "my_materialized_table"));
}

