@Test
void testPeriodicRefreshMaterializedTableWithPartitionOptions() throws Exception {
    List<Row> data = new ArrayList<>();
    // create materialized table with partition formatter
    createAndVerifyCreateMaterializedTableWithData("my_materialized_table", data, Collections.singletonMap("ds", "yyyy-MM-dd"), RefreshMode.FULL);
    ObjectIdentifier materializedTableIdentifier = ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "my_materialized_table");
    // add more data to all data list
    data.add(Row.of(1L, 1L, 1L, "2024-01-01"));
    data.add(Row.of(2L, 2L, 2L, "2024-01-02"));
    data.add(Row.of(4L, 4L, 4L, "2024-01-02"));
    // refresh the materialized table with period schedule
    long startTime = System.currentTimeMillis();
    OperationHandle periodRefreshTableHandle = service.refreshMaterializedTable(sessionHandle, materializedTableIdentifier.asSerializableString(), true, "2024-01-03 00:00:00", Collections.emptyMap(), Collections.emptyMap(), Collections.emptyMap());
    awaitOperationTermination(service, sessionHandle, periodRefreshTableHandle);
    List<RowData> periodRefreshResult = fetchAllResults(service, sessionHandle, periodRefreshTableHandle);
    assertThat(periodRefreshResult.size()).isEqualTo(1);
    String periodJobId = periodRefreshResult.get(0).getString(0).toString();
    // 1. verify fresh job created
    verifyRefreshJobCreated(restClusterClient, periodJobId, startTime);
    // 2. verify the new job overwrite the data
    // for partition with formatter, only the data of partition '2024-01-02' is changed and the
    // data of partition '2024-01-01' is not changed
    assertThat(fetchTableData(sessionHandle, "SELECT * FROM my_materialized_table where ds = '2024-01-02'")).size().isEqualTo(getPartitionSize(data, "2024-01-02"));
    assertThat(fetchTableData(sessionHandle, "SELECT * FROM my_materialized_table where ds = '2024-01-01'").size()).isNotEqualTo(getPartitionSize(data, "2024-01-01"));
    // drop the materialized table
    dropMaterializedTable(ObjectIdentifier.of(fileSystemCatalogName, TEST_DEFAULT_DATABASE, "my_materialized_table"));
}

