@Test
void testCancelUninterruptedOperation() throws Exception {
    AtomicReference<Boolean> isRunning = new AtomicReference<>(false);
    OperationHandle operationHandle = operationManager.submitOperation(() -> {
        // mock cpu busy task that doesn't interrupt system call
        while (true) {
            isRunning.compareAndSet(false, true);
        }
    });
    CommonTestUtils.waitUtil(isRunning::get, Duration.ofSeconds(10), "Failed to start up the task.");
    assertThatThrownBy(() -> operationManager.cancelOperation(operationHandle)).satisfies(FlinkAssertions.anyCauseMatches(SqlCancelException.class, String.format("Operation '%s' did not react to \"Future.cancel(true)\" and " + "is stuck for %s seconds in method.\n", operationHandle, 5)));
    assertThat(operationManager.getOperationInfo(operationHandle).getStatus()).isEqualTo(OperationStatus.CANCELED);
}

@Test
void testCloseUninterruptedOperation() throws Exception {
    AtomicReference<Boolean> isRunning = new AtomicReference<>(false);
    for (int i = 0; i < 10; i++) {
        EXECUTOR_EXTENSION.getExecutor().submit(() -> {
            operationManager.submitOperation(() -> {
                // mock cpu busy task that doesn't interrupt system call
                while (true) {
                    isRunning.compareAndSet(false, true);
                }
            });
        });
    }
    CommonTestUtils.waitUtil(isRunning::get, Duration.ofSeconds(10), "Failed to start up the task.");
    assertThatThrownBy(() -> operationManager.close()).satisfies(FlinkAssertions.anyCauseMatches(SqlCancelException.class));
    assertThat(operationManager.getOperationCount()).isEqualTo(0);
}

