@Test
void testAlterTable() {
    sql("alter table t1 rename to t2").ok("ALTER TABLE `T1` RENAME TO `T2`");
    sql("alter table if exists t1 rename to t2").ok("ALTER TABLE IF EXISTS `T1` RENAME TO `T2`");
    sql("alter table c1.d1.t1 rename to t2").ok("ALTER TABLE `C1`.`D1`.`T1` RENAME TO `T2`");
    sql("alter table if exists c1.d1.t1 rename to t2").ok("ALTER TABLE IF EXISTS `C1`.`D1`.`T1` RENAME TO `T2`");
    sql("alter table t1 set ('key1'='value1')").ok("ALTER TABLE `T1` SET (\n" + "  'key1' = 'value1'\n" + ")");
    sql("alter table if exists t1 set ('key1'='value1')").ok("ALTER TABLE IF EXISTS `T1` SET (\n" + "  'key1' = 'value1'\n" + ")");
    sql("alter table t1 add constraint ct1 primary key(a, b)").ok("ALTER TABLE `T1` ADD (\n" + "  CONSTRAINT `CT1` PRIMARY KEY (`A`, `B`)\n" + ")").node(new ValidationMatcher().fails("Flink doesn't support ENFORCED mode for PRIMARY KEY constraint. " + "ENFORCED/NOT ENFORCED controls if the constraint checks are performed on the incoming/outgoing data. " + "Flink does not own the data therefore the only supported mode is the NOT ENFORCED mode"));
    sql("alter table t1 add constraint ct1 primary key(a, b) not enforced").ok("ALTER TABLE `T1` ADD (\n" + "  CONSTRAINT `CT1` PRIMARY KEY (`A`, `B`) NOT ENFORCED\n" + ")");
    sql("alter table if exists t1 add constraint ct1 primary key(a, b) not enforced").ok("ALTER TABLE IF EXISTS `T1` ADD (\n" + "  CONSTRAINT `CT1` PRIMARY KEY (`A`, `B`) NOT ENFORCED\n" + ")");
    sql("alter table t1 " + "add unique(a, b)").ok("ALTER TABLE `T1` ADD (\n" + "  UNIQUE (`A`, `B`)\n" + ")").node(new ValidationMatcher().fails("UNIQUE constraint is not supported yet"));
    sql("alter table if exists t1 " + "add unique(a, b)").ok("ALTER TABLE IF EXISTS `T1` ADD (\n" + "  UNIQUE (`A`, `B`)\n" + ")");
    sql("alter table t1 drop constraint ct1").ok("ALTER TABLE `T1` DROP CONSTRAINT `CT1`");
    sql("alter table if exists t1 drop constraint ct1").ok("ALTER TABLE IF EXISTS `T1` DROP CONSTRAINT `CT1`");
    sql("alter table t1 rename a to b").ok("ALTER TABLE `T1` RENAME `A` TO `B`");
    sql("alter table if exists t1 rename a to b").ok("ALTER TABLE IF EXISTS `T1` RENAME `A` TO `B`");
    sql("alter table if exists t1 rename a.x to a.y").ok("ALTER TABLE IF EXISTS `T1` RENAME `A`.`X` TO `A`.`Y`");
}

