@Test
void testUnnest() {
    sql("select*from unnest(x)").ok("SELECT *\n" + "FROM UNNEST(`X`)");
    sql("select*from unnest(x) AS T").ok("SELECT *\n" + "FROM UNNEST(`X`) AS `T`");
    // UNNEST cannot be first word in query
    sql("^unnest^(x)").fails("(?s)Encountered \"unnest\" at.*");
    // UNNEST with more than one argument
    final String sql = "select * from dept,\n" + "unnest(dept.employees, dept.managers)";
    final String expected = "SELECT *\n" + "FROM `DEPT`,\n" + "UNNEST(`DEPT`.`EMPLOYEES`, `DEPT`.`MANAGERS`)";
    sql(sql).ok(expected);
    // LATERAL UNNEST is the same as UNNEST
    // (LATERAL is implicit for UNNEST, so the parser just ignores it)
    sql("select * from dept, lateral unnest(dept.employees)").ok("SELECT *\n" + "FROM `DEPT`,\n" + "UNNEST(`DEPT`.`EMPLOYEES`)");
    sql("select * from dept, unnest(dept.employees)").ok("SELECT *\n" + "FROM `DEPT`,\n" + "UNNEST(`DEPT`.`EMPLOYEES`)");
    // Does not generate extra parentheses around UNNEST because UNNEST is
    // a table expression.
    final String sql1 = "" + "SELECT\n" + "  item.name,\n" + "  relations.*\n" + "FROM dfs.tmp item\n" + "JOIN (\n" + "  SELECT * FROM UNNEST(item.related) i(rels)\n" + ") relations\n" + "ON TRUE";
    final String expected1 = "SELECT `ITEM`.`NAME`, `RELATIONS`.*\n" + "FROM `DFS`.`TMP` AS `ITEM`\n" + "INNER JOIN (SELECT *\n" + "FROM UNNEST(`ITEM`.`RELATED`) AS `I` (`RELS`)) AS `RELATIONS` ON TRUE";
    sql(sql1).ok(expected1);
}

