    assertThat(resolvedTable.getResolvedSchema()).isEqualTo(RESOLVED_TABLE_SCHEMA);
    // test materialized table de/serialization
    final CatalogMaterializedTable catalogMaterializedTable = CatalogPropertiesUtil.deserializeCatalogMaterializedTable(catalogMaterializedTableAsProperties());
    final ResolvedCatalogMaterializedTable resolvedCatalogMaterializedTable = resolveCatalogBaseTable(ResolvedCatalogMaterializedTable.class, catalogMaterializedTable);
    assertThat(CatalogPropertiesUtil.serializeCatalogMaterializedTable(resolvedCatalogMaterializedTable, DefaultSqlFactory.INSTANCE)).isEqualTo(catalogMaterializedTableAsProperties());
    assertThat(resolvedCatalogMaterializedTable.getResolvedSchema()).isEqualTo(RESOLVED_MATERIALIZED_TABLE_SCHEMA);
    assertThat(resolvedCatalogMaterializedTable.getDefinitionFreshness()).isEqualTo(IntervalFreshness.ofSecond("30"));
    assertThat(resolvedCatalogMaterializedTable.getDefinitionQuery()).isEqualTo(DEFINITION_QUERY);
    assertThat(resolvedCatalogMaterializedTable.getLogicalRefreshMode()).isEqualTo(CatalogMaterializedTable.LogicalRefreshMode.CONTINUOUS);
    assertThat(resolvedCatalogMaterializedTable.getRefreshMode()).isEqualTo(CatalogMaterializedTable.RefreshMode.CONTINUOUS);
    assertThat(resolvedCatalogMaterializedTable.getRefreshStatus()).isEqualTo(CatalogMaterializedTable.RefreshStatus.INITIALIZING);
    byte[] expectedBytes = ContinuousRefreshHandlerSerializer.INSTANCE.serialize(CONTINUOUS_REFRESH_HANDLER);
    assertThat(resolvedCatalogMaterializedTable.getSerializedRefreshHandler()).isEqualTo(expectedBytes);
}

