@Test
void testDatabaseModificationEvent() throws Exception {
    CompletableFuture<CreateDatabaseEvent> createFuture = new CompletableFuture<>();
    CompletableFuture<AlterDatabaseEvent> alterFuture = new CompletableFuture<>();
    CompletableFuture<DropDatabaseEvent> dropFuture = new CompletableFuture<>();
    CatalogManager catalogManager = createCatalogManager(new TestingDatabaseModificationListener(createFuture, alterFuture, dropFuture));
    // Validate create a database
    catalogManager.createDatabase(catalogManager.getCurrentCatalog(), "database1", new CatalogDatabaseImpl(Collections.singletonMap("key1", "val1"), "database1 comment"), true);
    CreateDatabaseEvent createDatabaseEvent = createFuture.get(10, TimeUnit.SECONDS);
    assertThat(createDatabaseEvent.context().getCatalogName()).isEqualTo(catalogManager.getCurrentCatalog());
    assertThat(createDatabaseEvent.ignoreIfExists()).isTrue();
    assertThat(createDatabaseEvent.databaseName()).isEqualTo("database1");
    assertThat(createDatabaseEvent.database().getComment()).isEqualTo("database1 comment");
    assertThat(createDatabaseEvent.database().getProperties()).isEqualTo(Collections.singletonMap("key1", "val1"));
    assertThat(alterFuture.isDone()).isFalse();
    assertThat(dropFuture.isDone()).isFalse();
    // Validate alter a database
    catalogManager.alterDatabase(catalogManager.getCurrentCatalog(), "database1", new CatalogDatabaseImpl(Collections.singletonMap("key1", "val_val1"), "database1 comment modified"), false);
    AlterDatabaseEvent alterDatabaseEvent = alterFuture.get(10, TimeUnit.SECONDS);
    assertThat(alterDatabaseEvent.context().getCatalogName()).isEqualTo(catalogManager.getCurrentCatalog());
    assertThat(alterDatabaseEvent.ignoreIfNotExists()).isFalse();
    assertThat(alterDatabaseEvent.databaseName()).isEqualTo("database1");
    assertThatThrownBy(alterDatabaseEvent::database).hasMessage("There is no database in AlterDatabaseEvent, use database name instead.");
    assertThat(alterDatabaseEvent.newDatabase().getComment()).isEqualTo("database1 comment modified");
    assertThat(alterDatabaseEvent.newDatabase().getProperties()).isEqualTo(Collections.singletonMap("key1", "val_val1"));
    // Validate drop a database
    catalogManager.dropDatabase(catalogManager.getCurrentCatalog(), "database1", true, true);
    DropDatabaseEvent dropDatabaseEvent = dropFuture.get(10, TimeUnit.SECONDS);
    assertThat(dropDatabaseEvent.context().getCatalogName()).isEqualTo(catalogManager.getCurrentCatalog());
    assertThat(dropDatabaseEvent.ignoreIfNotExists()).isTrue();
    assertThat(dropDatabaseEvent.databaseName()).isEqualTo("database1");
    assertThatThrownBy(dropDatabaseEvent::database).hasMessage("There is no database in DropDatabaseEvent, use database name instead.");
    assertThat(dropDatabaseEvent.cascade()).isTrue();
}

@Test
void testTableModificationListener() throws Exception {
    CompletableFuture<CreateTableEvent> createFuture = new CompletableFuture<>();
    CompletableFuture<CreateTableEvent> createTemporaryFuture = new CompletableFuture<>();
    CompletableFuture<AlterTableEvent> alterFuture = new CompletableFuture<>();
    CompletableFuture<DropTableEvent> dropFuture = new CompletableFuture<>();
    CompletableFuture<DropTableEvent> dropTemporaryFuture = new CompletableFuture<>();
    CatalogManager catalogManager = createCatalogManager(new TestingTableModificationListener(createFuture, createTemporaryFuture, alterFuture, dropFuture, dropTemporaryFuture));
    catalogManager.initSchemaResolver(true, ExpressionResolverMocks.dummyResolver(), new ParserMock());
    // Create a view
    catalogManager.createTable(CatalogView.of(Schema.newBuilder().build(), null, "", "", Collections.emptyMap()), ObjectIdentifier.of(catalogManager.getCurrentCatalog(), catalogManager.getCurrentDatabase(), "view1"), true);
    assertThat(createFuture.isDone()).isFalse();
    // Create a table
    catalogManager.createTable(CatalogTable.newBuilder().schema(Schema.newBuilder().build()).build(), ObjectIdentifier.of(catalogManager.getCurrentCatalog(), catalogManager.getCurrentDatabase(), "table1"), true);
    CreateTableEvent createEvent = createFuture.get(10, TimeUnit.SECONDS);
    assertThat(createEvent.isTemporary()).isFalse();
    assertThat(createEvent.identifier().getObjectName()).isEqualTo("table1");
    assertThat(createEvent.ignoreIfExists()).isTrue();
    // Create a temporary table
    catalogManager.createTemporaryTable(CatalogTable.newBuilder().schema(Schema.newBuilder().build()).build(), ObjectIdentifier.of(catalogManager.getCurrentCatalog(), catalogManager.getCurrentDatabase(), "table2"), false);
    CreateTableEvent createTemporaryEvent = createTemporaryFuture.get(10, TimeUnit.SECONDS);
    assertThat(createTemporaryEvent.isTemporary()).isTrue();
    assertThat(createTemporaryEvent.identifier().getObjectName()).isEqualTo("table2");
    assertThat(createTemporaryEvent.ignoreIfExists()).isFalse();
    // Alter a table
    catalogManager.alterTable(CatalogTable.newBuilder().schema(Schema.newBuilder().build()).comment("table1 comment").build(), ObjectIdentifier.of(catalogManager.getCurrentCatalog(), catalogManager.getCurrentDatabase(), "table1"), false);
    AlterTableEvent alterEvent = alterFuture.get(10, TimeUnit.SECONDS);
    assertThat(alterEvent.isTemporary()).isFalse();
    assertThat(alterEvent.identifier().getObjectName()).isEqualTo("table1");
    assertThat(alterEvent.newTable().getComment()).isEqualTo("table1 comment");
    assertThat(alterEvent.ignoreIfNotExists()).isFalse();
    // Drop a view
    catalogManager.dropView(ObjectIdentifier.of(catalogManager.getCurrentCatalog(), catalogManager.getCurrentDatabase(), "table1"), true);
    assertThat(dropFuture.isDone()).isFalse();
    // Drop a table
    catalogManager.dropTable(ObjectIdentifier.of(catalogManager.getCurrentCatalog(), catalogManager.getCurrentDatabase(), "table1"), true);
    DropTableEvent dropEvent = dropFuture.get(10, TimeUnit.SECONDS);
    assertThat(dropEvent.isTemporary()).isFalse();
    assertThat(dropEvent.ignoreIfNotExists()).isTrue();
    assertThat(dropEvent.identifier().getObjectName()).isEqualTo("table1");
    // Create a temporary view with the same table name `table2`
    catalogManager.createTemporaryTable(CatalogView.of(Schema.newBuilder().build(), null, "", "", Collections.emptyMap()), ObjectIdentifier.of(catalogManager.getCurrentCatalog(), catalogManager.getCurrentDatabase(), "view2"), false);
    // Drop a temporary view
    catalogManager.dropTemporaryView(ObjectIdentifier.of(catalogManager.getCurrentCatalog(), catalogManager.getCurrentDatabase(), "view2"), true);
    assertThat(dropTemporaryFuture.isDone()).isFalse();
    // Drop a temporary table
    catalogManager.dropTemporaryTable(ObjectIdentifier.of(catalogManager.getCurrentCatalog(), catalogManager.getCurrentDatabase(), "table2"), false);
    DropTableEvent dropTemporaryEvent = dropTemporaryFuture.get(10, TimeUnit.SECONDS);
    assertThat(dropTemporaryEvent.isTemporary()).isTrue();
    assertThat(dropTemporaryEvent.ignoreIfNotExists()).isFalse();
    assertThat(dropTemporaryEvent.identifier().getObjectName()).isEqualTo("table2");
}

