@Test
void testCatalogStore() throws Exception {
    CatalogStore catalogStore = new GenericInMemoryCatalogStore();
    Configuration configuration = new Configuration();
    configuration.setString("type", "generic_in_memory");
    assertThatThrownBy(() -> catalogStore.storeCatalog("cat1", CatalogDescriptor.of("cat1", configuration))).isInstanceOf(IllegalStateException.class).hasMessageContaining("CatalogStore is not opened yet.");
    CatalogManager catalogManager = CatalogManagerMocks.createCatalogManager(catalogStore);
    catalogStore.storeCatalog("exist_cat", CatalogDescriptor.of("exist_cat", configuration));
    catalogManager.createCatalog("cat1", CatalogDescriptor.of("cat1", configuration));
    catalogManager.createCatalog("cat2", CatalogDescriptor.of("cat2", configuration));
    catalogManager.createCatalog("cat3", CatalogDescriptor.of("cat3", configuration));
    catalogManager.createCatalog("cat_comment", CatalogDescriptor.of("cat_comment", configuration.clone(), "comment for catalog"));
    catalogManager.createCatalog("cat_comment", CatalogDescriptor.of("cat_comment", configuration.clone(), "second comment for catalog"), true);
    assertThatThrownBy(() -> catalogManager.createCatalog("cat_comment", CatalogDescriptor.of("cat_comment", configuration.clone(), "third comment for catalog"), false)).isInstanceOf(CatalogException.class).hasMessage("Catalog cat_comment already exists.");
    assertThatThrownBy(() -> catalogManager.createCatalog("cat_no_type", CatalogDescriptor.of("cat_no_type", new Configuration(), "catalog without type"), false)).isInstanceOf(ValidationException.class).hasMessageContaining("Unable to create catalog 'cat_no_type'.");
    assertFalse(catalogManager.listCatalogs().contains("cat_no_type"));
    assertTrue(catalogManager.getCatalog("cat1").isPresent());
    assertTrue(catalogManager.getCatalog("cat2").isPresent());
    assertTrue(catalogManager.getCatalog("cat3").isPresent());
    assertTrue(catalogManager.getCatalog("cat_comment").isPresent());
    assertTrue(catalogManager.getCatalogDescriptor("cat_comment").isPresent());
    assertEquals("comment for catalog", catalogManager.getCatalogDescriptor("cat_comment").get().getComment().get());
    assertThat(catalogManager.getCatalog("cat_comment")).isPresent();
    assertThat(catalogManager.getCatalogDescriptor("cat_comment")).isPresent().hasValueSatisfying(descriptor -> assertThat(descriptor.getComment()).isPresent().hasValueSatisfying(comment -> assertEquals("comment for catalog", comment)));
    catalogManager.alterCatalog("cat_comment", new CatalogChange.CatalogConfigurationChange(conf -> conf.setString("default-database", "db")));
    catalogManager.alterCatalog("cat_comment", new CatalogChange.CatalogCommentChange("new comment"));
    assertThat(catalogManager.getCatalogDescriptor("cat_comment")).isPresent().hasValueSatisfying(descriptor -> {
        assertThat(descriptor.getConfiguration().toMap()).containsEntry("default-database", "db");
        assertThat(descriptor.getComment()).isPresent().hasValueSatisfying(comment -> assertEquals("new comment", comment));
    });
    assertTrue(catalogManager.listCatalogs().contains("cat1"));
    assertTrue(catalogManager.listCatalogs().contains("cat2"));
    assertTrue(catalogManager.listCatalogs().contains("cat3"));
    assertTrue(catalogManager.listCatalogs().contains("cat_comment"));
    catalogManager.registerCatalog("cat4", new GenericInMemoryCatalog("cat4"));
    assertThatThrownBy(() -> catalogManager.createCatalog("cat1", CatalogDescriptor.of("cat1", configuration))).isInstanceOf(CatalogException.class).hasMessageContaining("Catalog cat1 already exists.");
    assertThatThrownBy(() -> catalogManager.createCatalog("cat4", CatalogDescriptor.of("cat4", configuration))).isInstanceOf(CatalogException.class).hasMessageContaining("Catalog cat4 already exists.");
    catalogManager.createDatabase("exist_cat", "cat_db", new CatalogDatabaseImpl(Collections.emptyMap(), "database for exist_cat"), false);
    catalogManager.createTable(CatalogTable.newBuilder().schema(Schema.newBuilder().build()).build(), ObjectIdentifier.of("exist_cat", "cat_db", "test_table"), false);
    catalogManager.createModel(CatalogModel.of(Schema.derived(), Schema.derived(), Collections.emptyMap(), null), ObjectIdentifier.of("exist_cat", "cat_db", "test_model"), false);
    assertThat(catalogManager.listSchemas("exist_cat")).isEqualTo(new HashSet<>(Arrays.asList("default", "cat_db")));
    assertThat(catalogManager.listTables("exist_cat", "cat_db")).isEqualTo(Collections.singleton("test_table"));
    assertThat(catalogManager.listModels("exist_cat", "cat_db")).isEqualTo(Collections.singleton("test_model"));
    catalogManager.setCurrentCatalog("exist_cat");
    assertThat(catalogManager.listSchemas()).isEqualTo(new HashSet<>(Arrays.asList("cat1", "cat2", "cat3", "cat4", "default_catalog", "exist_cat", "cat_comment")));
    catalogManager.setCurrentDatabase("cat_db");
    assertThat(catalogManager.listTables()).isEqualTo(Collections.singleton("test_table"));
    catalogManager.unregisterCatalog("cat1", false);
    catalogManager.unregisterCatalog("cat2", false);
    catalogManager.unregisterCatalog("cat3", false);
    assertFalse(catalogManager.listCatalogs().contains("cat1"));
    assertFalse(catalogManager.listCatalogs().contains("cat2"));
    assertFalse(catalogManager.listCatalogs().contains("cat3"));
    catalogManager.close();
    assertThatThrownBy(() -> catalogManager.listCatalogs()).isInstanceOf(IllegalStateException.class).hasMessageContaining("CatalogStore is not opened yet.");
}

