@Test
void testTemporarySystemFunction() {
    // register first time
    functionCatalog.registerTemporarySystemFunction(NAME, FUNCTION_1, false);
    assertThat(functionCatalog.lookupFunction(PARTIAL_UNRESOLVED_IDENTIFIER)).hasValue(ContextResolvedFunction.temporary(FunctionIdentifier.of(NAME), FUNCTION_1));
    // register second time lenient
    functionCatalog.registerTemporarySystemFunction(NAME, FUNCTION_2, true);
    assertThat(functionCatalog.lookupFunction(PARTIAL_UNRESOLVED_IDENTIFIER)).hasValue(ContextResolvedFunction.temporary(FunctionIdentifier.of(NAME), FUNCTION_1));
    // register second time not lenient
    assertThatThrownBy(() -> functionCatalog.registerTemporarySystemFunction(NAME, FUNCTION_2, false)).satisfies(anyCauseMatches(ValidationException.class, "A function named '" + NAME + "' does already exist."));
    // drop first time
    assertThat(functionCatalog.dropTemporarySystemFunction(NAME, false)).isTrue();
    assertThat(functionCatalog.lookupFunction(PARTIAL_UNRESOLVED_IDENTIFIER)).isEmpty();
