@Test
void testStoreAndGet() {
    CatalogStore catalogStore = new GenericInMemoryCatalogStore();
    catalogStore.open();
    catalogStore.storeCatalog("catalog1", CatalogDescriptor.of("catalog1", new Configuration()));
    assertThat(catalogStore.getCatalog("catalog1").isPresent()).isTrue();
    assertThat(catalogStore.contains("catalog1")).isTrue();
    catalogStore.removeCatalog("catalog1", true);
    assertThat(catalogStore.contains("catalog1")).isFalse();
    assertThatThrownBy(() -> catalogStore.removeCatalog("catalog1", false)).isInstanceOf(CatalogException.class).hasMessageContaining("Catalog catalog1 does not exist in the catalog store.");
    catalogStore.close();
    assertThatThrownBy(() -> catalogStore.storeCatalog("catalog1", CatalogDescriptor.of("catalog1", new Configuration()))).isInstanceOf(IllegalStateException.class).hasMessageContaining("CatalogStore is not opened yet.");
    assertThatThrownBy(() -> catalogStore.removeCatalog("catalog1", false)).isInstanceOf(IllegalStateException.class).hasMessageContaining("CatalogStore is not opened yet.");
    assertThatThrownBy(() -> catalogStore.contains("catalog1")).isInstanceOf(IllegalStateException.class).hasMessageContaining("CatalogStore is not opened yet.");
    assertThatThrownBy(() -> catalogStore.listCatalogs()).isInstanceOf(IllegalStateException.class).hasMessageContaining("CatalogStore is not opened yet.");
}

