@Test
void testSchemaResolutionErrors() {
    // columns
    testError(Schema.newBuilder().fromSchema(SCHEMA).column("id", DataTypes.STRING()).build(), "Schema must not contain duplicate column names.");
    testError(Schema.newBuilder().columnByExpression("invalid", callSql("INVALID")).build(), "Invalid expression for computed column 'invalid'.");
    // metadata columns
    testError(Schema.newBuilder().columnByMetadata("metadata", DataTypes.INT()).columnByMetadata("from_metadata", DataTypes.BIGINT(), "metadata", false).build(), "The column `metadata` and `from_metadata` in the table are both from the same metadata key 'metadata'. " + "Please specify one of the columns as the metadata column and use the " + "computed column syntax to specify the others.");
    testError(Schema.newBuilder().columnByMetadata("from_metadata", DataTypes.BIGINT(), "metadata", false).columnByMetadata("from_metadata2", DataTypes.STRING(), "metadata", true).build(), "The column `from_metadata` and `from_metadata2` in the table are both from the same metadata key 'metadata'. " + "Please specify one of the columns as the metadata column and use the " + "computed column syntax to specify the others.");
    // time attributes and watermarks
    testError(Schema.newBuilder().column("ts", DataTypes.BOOLEAN()).watermark("ts", callSql(WATERMARK_SQL)).build(), "Invalid data type of time field for watermark definition." + " The field must be of type TIMESTAMP(p) or TIMESTAMP_LTZ(p), the supported precision 'p' is from 0 to 3, but the time field type is BOOLEAN");
    testError(Schema.newBuilder().column("ts", DataTypes.TIMESTAMP(3)).watermark("ts", callSql("INVALID")).build(), "Invalid expression for watermark 'WATERMARK FOR `ts` AS [INVALID]'.");
    testError(Schema.newBuilder().column("ts", DataTypes.TIMESTAMP(3)).watermark("ts", callSql(INVALID_WATERMARK_SQL)).build(), "The watermark declaration's output data type 'TIMESTAMP_LTZ(3)' is " + "different from the time field's data type 'TIMESTAMP(3)'.");
    testError(Schema.newBuilder().column("ts", DataTypes.TIMESTAMP(3)).watermark("other_ts", callSql(WATERMARK_SQL)).build(), "Invalid column name 'other_ts' for rowtime attribute in watermark declaration. Available columns are: [ts]");
    testError(Schema.newBuilder().fromSchema(SCHEMA).watermark("orig_ts", WATERMARK_SQL).build(), "Multiple watermark definitions are not supported yet.");
    testError(Schema.newBuilder().columnByExpression("ts", PROCTIME_SQL).watermark("ts", WATERMARK_SQL).build(), "A watermark can not be defined for a processing-time attribute.");
    // primary keys
    testError(Schema.newBuilder().column("id", DataTypes.INT()).primaryKey("INVALID").build(), "Column 'INVALID' does not exist.");
    testError(Schema.newBuilder().column("nullable_col", DataTypes.INT()).primaryKey("nullable_col").build(), "Column 'nullable_col' is nullable.");
    testError(Schema.newBuilder().column("orig_ts", DataTypes.TIMESTAMP(3)).columnByExpression("ts", COMPUTED_SQL).primaryKey("ts").build(), "Column 'ts' is not a physical column.");
    testError(Schema.newBuilder().column("id", DataTypes.INT()).primaryKey("id", "id").build(), "Invalid primary key 'PK_id_id'. A primary key must not contain duplicate columns. Found: [id]");
}

