@Test
void testGenerateDecimalValues() {
    for (int precision = 1; precision <= 38; precision++) {
        for (int scale = 0; scale <= precision; scale++) {
            DecimalDataRandomGenerator gen = new DecimalDataRandomGenerator(precision, scale, Double.MIN_VALUE, Double.MAX_VALUE, 0f);
            DecimalData value = gen.next();
            assertThat(value).as("Null value for DECIMAL(" + precision + "," + scale + ")").isNotNull();
            String strRepr = String.valueOf(value);
            if (strRepr.charAt(0) == '-') {
                // drop the negative sign
                strRepr = strRepr.substring(1);
            }
            if (scale != precision) {
                // need to account for decimal . and potential leading zeros
                assertThat(strRepr).as("Wrong length for DECIMAL(" + precision + "," + scale + ") = " + strRepr).hasSizeLessThanOrEqualTo(precision + 1);
            } else {
                // need to account for decimal . and potential leading zeros
                assertThat(strRepr).as("Wrong length for DECIMAL(" + precision + "," + scale + ") = " + strRepr).hasSizeLessThanOrEqualTo(precision + 2);
            }
            if (scale != 0) {
                String decimalPart = strRepr.split("\\.")[1];
                assertThat(decimalPart).as("Wrong length for DECIMAL(" + precision + "," + scale + ") = " + strRepr).hasSize(scale);
            }
        }
    }
}

@Test
void testMinMax() {
    for (int precision = 1; precision <= 38; precision++) {
        for (int scale = 0; scale <= precision; scale++) {
            BigDecimal min = BigDecimal.valueOf(-10.0);
            BigDecimal max = BigDecimal.valueOf(10.0);
            DecimalDataRandomGenerator gen = new DecimalDataRandomGenerator(precision, scale, min.doubleValue(), max.doubleValue(), 0f);
            DecimalData result = gen.next();
            assertThat(result).as("Null value for DECIMAL(" + precision + "," + scale + ")").isNotNull();
            assertThat(result.toBigDecimal()).as("value must be greater than or equal to min").isGreaterThanOrEqualTo(min).as("value must be less than or equal to max").isLessThanOrEqualTo(max);
        }
    }
}

