    descriptor.putString(DataGenConnectorOptionsUtil.FIELDS + ".f0." + DataGenConnectorOptionsUtil.KIND, DataGenConnectorOptionsUtil.RANDOM);
    descriptor.putLong(DataGenConnectorOptionsUtil.FIELDS + ".f0." + DataGenConnectorOptionsUtil.LENGTH, 20);
    descriptor.putString(DataGenConnectorOptionsUtil.FIELDS + ".f1." + DataGenConnectorOptionsUtil.KIND, DataGenConnectorOptionsUtil.RANDOM);
    descriptor.putLong(DataGenConnectorOptionsUtil.FIELDS + ".f1." + DataGenConnectorOptionsUtil.MIN, 10);
    descriptor.putLong(DataGenConnectorOptionsUtil.FIELDS + ".f1." + DataGenConnectorOptionsUtil.MAX, 100);
    descriptor.putString(DataGenConnectorOptionsUtil.FIELDS + ".f2." + DataGenConnectorOptionsUtil.KIND, DataGenConnectorOptionsUtil.SEQUENCE);
    descriptor.putLong(DataGenConnectorOptionsUtil.FIELDS + ".f2." + DataGenConnectorOptionsUtil.START, 50);
    descriptor.putLong(DataGenConnectorOptionsUtil.FIELDS + ".f2." + DataGenConnectorOptionsUtil.END, 60);
    descriptor.putString(DataGenConnectorOptionsUtil.FIELDS + ".f3." + DataGenConnectorOptionsUtil.KIND, DataGenConnectorOptionsUtil.RANDOM);
    descriptor.putString(DataGenConnectorOptionsUtil.FIELDS + ".f3." + DataGenConnectorOptionsUtil.MAX_PAST, "5s");
    descriptor.putString(DataGenConnectorOptionsUtil.FIELDS + ".f5." + DataGenConnectorOptionsUtil.KIND, DataGenConnectorOptionsUtil.SEQUENCE);
    descriptor.putLong(DataGenConnectorOptionsUtil.FIELDS + ".f5." + DataGenConnectorOptionsUtil.START, 1);
    descriptor.putLong(DataGenConnectorOptionsUtil.FIELDS + ".f5." + DataGenConnectorOptionsUtil.END, 11);
    descriptor.putString(DataGenConnectorOptionsUtil.FIELDS + ".f6.key." + DataGenConnectorOptionsUtil.NULL_RATE, "1");
    descriptor.putString(DataGenConnectorOptionsUtil.FIELDS + ".f7." + DataGenConnectorOptionsUtil.NULL_RATE, "1");
    final long begin = System.currentTimeMillis();
    List<RowData> results = runGenerator(SCHEMA, descriptor);
    final long end = System.currentTimeMillis();
    assertThat(results).hasSize(11);
    for (int i = 0; i < results.size(); i++) {
        RowData row = results.get(i);
        assertThat(row.getString(0).toString()).hasSize(20);
        assertThat(row.getLong(1)).isBetween(10L, 100L);
        assertThat(row.getLong(2)).isEqualTo(i + 50);
        assertThat(row.getTimestamp(3, 3).getMillisecond()).isBetween(begin - 5000, end);
        assertThat(row.getBinary(4)).hasSize(2);
        // f5 is sequence bytes produced in sequence long [1, 11]
        assertThat(row.getBinary(5)).hasSize(8);
        assertThat(row.getBinary(5)[row.getBinary(5).length - 1]).isEqualTo((byte) (i + 1));
        assertThat(row.getMap(6).keyArray().isNullAt(0)).isTrue();
        assertThat(row.getString(7)).isNull();
    }
}

@Test
void testVariableLengthDataGeneration() throws Exception {
    DescriptorProperties descriptor = new DescriptorProperties();
    final int rowsNumber = 999;
    descriptor.putString(FactoryUtil.CONNECTOR.key(), "datagen");
    descriptor.putLong(DataGenConnectorOptions.NUMBER_OF_ROWS.key(), rowsNumber);
    ResolvedSchema schema = ResolvedSchema.of(Column.physical("f0", DataTypes.STRING()), Column.physical("f1", DataTypes.VARCHAR(20)), Column.physical("f2", DataTypes.BYTES()), Column.physical("f3", DataTypes.VARBINARY(4)), Column.physical("f4", DataTypes.BINARY(2)));
    List<RowData> results = runGenerator(schema, descriptor);
    assertThat(results).hasSize(rowsNumber);
    for (RowData row : results) {
        assertThat(row.getString(0).toString()).hasSize(RandomGeneratorVisitor.RANDOM_STRING_LENGTH_DEFAULT);
        assertThat(row.getString(1).toString()).hasSize(20);
        assertThat(row.getBinary(2)).hasSize(RandomGeneratorVisitor.RANDOM_BYTES_LENGTH_DEFAULT);
        assertThat(row.getBinary(3)).hasSize(4);
    }
    descriptor.putBoolean(DataGenConnectorOptionsUtil.FIELDS + ".f0." + DataGenConnectorOptionsUtil.VAR_LEN, true);
    descriptor.putBoolean(DataGenConnectorOptionsUtil.FIELDS + ".f1." + DataGenConnectorOptionsUtil.VAR_LEN, true);
    descriptor.putBoolean(DataGenConnectorOptionsUtil.FIELDS + ".f2." + DataGenConnectorOptionsUtil.VAR_LEN, true);
    descriptor.putBoolean(DataGenConnectorOptionsUtil.FIELDS + ".f3." + DataGenConnectorOptionsUtil.VAR_LEN, true);
    results = runGenerator(schema, descriptor);
    Set<Integer> sizeString = new HashSet<>();
    Set<Integer> sizeVarChar = new HashSet<>();
    Set<Integer> sizeBytes = new HashSet<>();
    Set<Integer> sizeVarBinary = new HashSet<>();
    for (RowData row : results) {
        assertThat(row.getString(0).toString()).hasSizeBetween(1, RandomGeneratorVisitor.RANDOM_STRING_LENGTH_DEFAULT);
        assertThat(row.getString(1).toString()).hasSizeBetween(1, RandomGeneratorVisitor.RANDOM_STRING_LENGTH_DEFAULT);
        assertThat(row.getBinary(2)).hasSizeBetween(1, RandomGeneratorVisitor.RANDOM_BYTES_LENGTH_DEFAULT);
        assertThat(row.getBinary(3)).hasSizeBetween(1, RandomGeneratorVisitor.RANDOM_BYTES_LENGTH_DEFAULT);
        sizeString.add(row.getString(0).toString().length());
        sizeVarChar.add(row.getString(1).toString().length());
        sizeBytes.add(row.getBinary(2).length);
        sizeVarBinary.add(row.getBinary(3).length);
    }
    assertThat(sizeString.size()).isGreaterThan(1);
    assertThat(sizeBytes.size()).isGreaterThan(1);
    assertThat(sizeVarBinary.size()).isGreaterThan(1);
    assertThat(sizeVarChar.size()).isGreaterThan(1);
