@Test
public void testCatalogModelSerde() {
    final Map<String, String> options = new HashMap<>();
    options.put("endpoint", "someendpoint");
    options.put("api_key", "fake_key");
    final CatalogModel catalogModel = CatalogModel.of(Schema.newBuilder().column("f1", DataTypes.INT().getLogicalType().asSerializableString()).column("f2", DataTypes.STRING().getLogicalType().asSerializableString()).build(), Schema.newBuilder().column("label", DataTypes.STRING().getLogicalType().asSerializableString()).build(), options, "some comment");
    final Column f1 = Column.physical("f1", DataTypes.INT());
    final Column f2 = Column.physical("f2", DataTypes.STRING());
    final Column label = Column.physical("label", DataTypes.STRING());
    final ResolvedSchema inputSchema = ResolvedSchema.of(f1, f2);
    final ResolvedSchema outputSchema = ResolvedSchema.of(label);
    final ResolvedCatalogModel testModel = ResolvedCatalogModel.of(catalogModel, inputSchema, outputSchema);
    final Map<String, String> serializedMap = CatalogPropertiesUtil.serializeResolvedCatalogModel(testModel, DefaultSqlFactory.INSTANCE);
    final CatalogModel deserializedModel = CatalogPropertiesUtil.deserializeCatalogModel(serializedMap);
    assertThat(deserializedModel.getInputSchema().toString()).isEqualTo(catalogModel.getInputSchema().toString());
    assertThat(deserializedModel.getOutputSchema().toString()).isEqualTo(catalogModel.getOutputSchema().toString());
    assertThat(deserializedModel.getOptions()).isEqualTo(catalogModel.getOptions());
    assertThat(deserializedModel.getComment()).isEqualTo(catalogModel.getComment());
}

@Test
public void testCatalogTableSerde() {
    final Map<String, String> options = new HashMap<>();
    final CatalogTable catalogTable = CatalogTable.newBuilder().schema(Schema.newBuilder().column("f1", DataTypes.INT().getLogicalType().asSerializableString()).column("f2", DataTypes.STRING().getLogicalType().asSerializableString()).primaryKey("f1").build()).comment("some comment").options(options).build();
    final Column f1 = Column.physical("f1", DataTypes.INT());
    final Column f2 = Column.physical("f2", DataTypes.STRING());
    List<Column> columns = Arrays.asList(f1, f2);
    final UniqueConstraint primaryKey = UniqueConstraint.primaryKey("PK_f1", Collections.singletonList("f1"));
    final ResolvedSchema schema = new ResolvedSchema(columns, Collections.emptyList(), primaryKey);
    final ResolvedCatalogTable testTable = new ResolvedCatalogTable(catalogTable, schema);
    final Map<String, String> serializedMap = CatalogPropertiesUtil.serializeCatalogTable(testTable, DefaultSqlFactory.INSTANCE);
    final CatalogTable deserializedTable = CatalogPropertiesUtil.deserializeCatalogTable(serializedMap);
    assertThat(deserializedTable.getUnresolvedSchema().toString()).isEqualTo(catalogTable.getUnresolvedSchema().toString());
}

