@Test
void testConcurrentAccess() throws Exception {
    int concurrency = 4;
    ExecutorService executor = Executors.newFixedThreadPool(concurrency * 2);
    InterceptingCacheMetricGroup metricGroup = new InterceptingCacheMetricGroup();
    try (DefaultLookupCache cache = createCache(DefaultLookupCache.newBuilder().maximumSize(Long.MAX_VALUE))) {
        List<CompletableFuture<?>> futures = new ArrayList<>();
        // Concurrently put entries into the cache
        for (int i = 0; i < concurrency; i++) {
            String key = "key-" + i;
            String value = "value-" + i;
            CompletableFuture<Void> future = runAsync(() -> {
                cache.open(metricGroup);
                cache.put(GenericRowData.of(key), Collections.singleton(GenericRowData.of(value)));
            }, executor);
            futures.add(future);
        }
        FutureUtils.waitForAll(futures).get();
        futures.clear();
        // Concurrently get entries from the cache
        for (int i = 0; i < concurrency; i++) {
            String key = "key-" + i;
            String value = "value-" + i;
            // cache hit
            CompletableFuture<Void> hitFuture = runAsync(() -> {
                cache.open(metricGroup);
                assertThat(cache.getIfPresent(GenericRowData.of(key))).isEqualTo(Collections.singleton(GenericRowData.of(value)));
            }, executor);
            futures.add(hitFuture);
            // Cache miss
            CompletableFuture<Void> missFuture = runAsync(() -> {
                cache.open(metricGroup);
                assertThat(cache.getIfPresent(NON_EXIST_KEY)).isNull();
            }, executor);
            futures.add(missFuture);
        }
        FutureUtils.waitForAll(futures).get();
        // Validate metrics after concurrent accesses
        assertThat(metricGroup.hitCounter.getCount()).isEqualTo(concurrency);
        assertThat(metricGroup.missCounter.getCount()).isEqualTo(concurrency);
        assertThat(metricGroup.numCachedRecordsGauge.getValue()).isEqualTo(concurrency);
    } finally {
        executor.shutdownNow();
    }
}

@Test
void testBuildFromConfig() {
    // Happy path
    Configuration config = new Configuration();
    config.set(LookupOptions.CACHE_TYPE, LookupOptions.LookupCacheType.PARTIAL);
    config.set(LookupOptions.PARTIAL_CACHE_MAX_ROWS, 15213L);
    config.set(LookupOptions.PARTIAL_CACHE_EXPIRE_AFTER_WRITE, Duration.ofMillis(18213L));
    config.set(LookupOptions.PARTIAL_CACHE_EXPIRE_AFTER_ACCESS, Duration.ofMillis(15513L));
    config.set(LookupOptions.PARTIAL_CACHE_CACHE_MISSING_KEY, false);
    DefaultLookupCache cache = DefaultLookupCache.fromConfig(config);
    assertThat(cache.getMaximumSize()).isEqualTo(15213L);
    assertThat(cache.getExpireAfterWriteDuration()).isEqualTo(Duration.ofMillis(18213L));
    assertThat(cache.getExpireAfterAccessDuration()).isEqualTo(Duration.ofMillis(15513L));
    assertThat(cache.isCacheMissingKey()).isFalse();
    // Illegal configurations
    Configuration configWithIllegalCacheType = new Configuration();
    configWithIllegalCacheType.set(LookupOptions.CACHE_TYPE, LookupOptions.LookupCacheType.NONE);
    assertThatThrownBy(() -> DefaultLookupCache.fromConfig(configWithIllegalCacheType)).isInstanceOf(IllegalArgumentException.class).hasMessage("'lookup.cache' should be 'PARTIAL' in order to build a default lookup cache");
    Configuration configWithoutEviction = new Configuration();
    configWithoutEviction.set(LookupOptions.CACHE_TYPE, LookupOptions.LookupCacheType.PARTIAL);
    assertThatThrownBy(() -> DefaultLookupCache.fromConfig(configWithoutEviction)).isInstanceOf(IllegalArgumentException.class).hasMessage("Missing 'lookup.partial-cache.expire-after-access', " + "'lookup.partial-cache.expire-after-write' " + "or 'lookup.partial-cache.max-rows' in the configuration. " + "The cache will not have evictions under this configuration " + "and could lead to potential memory issues " + "as the cache size may grow indefinitely.");
}

@Test
void testBuilder() {
    // Happy path
    DefaultLookupCache cache = DefaultLookupCache.newBuilder().cacheMissingKey(true).maximumSize(15213L).expireAfterWrite(Duration.ofMillis(18213L)).expireAfterAccess(Duration.ofMillis(15513L)).build();
    assertThat(cache.isCacheMissingKey()).isEqualTo(true);
    assertThat(cache.getMaximumSize()).isEqualTo(15213L);
    assertThat(cache.getExpireAfterWriteDuration()).isEqualTo(Duration.ofMillis(18213L));
    assertThat(cache.getExpireAfterAccessDuration()).isEqualTo(Duration.ofMillis(15513L));
    // Test illegal usage without eviction policy
    assertThatThrownBy(() -> DefaultLookupCache.newBuilder().build()).isInstanceOf(IllegalArgumentException.class).hasMessage("Expiration duration and maximum size are not set for the cache. " + "The cache will not have any eviction and could lead to " + "potential memory issues as the cache size may grow infinitely.");
}

