    try (TimedCacheReloadTrigger trigger = new TimedCacheReloadTrigger(reloadTime, RELOAD_INTERVAL_IN_DAYS, scheduledExecutor, CONSTANT_CLOCK)) {
        trigger.open(context);
        assertThat(scheduledExecutor.numQueuedRunnables()).isEqualTo(1);
        assertThat(scheduledExecutor.getNumPeriodicTasksWithFixedDelay()).isEqualTo(0);
        assertThat(scheduledExecutor.getNumPeriodicTasksWithFixedRate()).isEqualTo(1);
        ScheduledTask<?> scheduledLoadTask = (ScheduledTask<?>) scheduledExecutor.getAllPeriodicScheduledTask().iterator().next();
        assertThat(scheduledLoadTask.getDelay(TimeUnit.MILLISECONDS)).isEqualTo(Duration.ofDays(1).minus(MILLIS_DIFF, ChronoUnit.MILLIS).toMillis());
        assertThat(scheduledLoadTask.getPeriod()).isEqualTo(Duration.ofDays(RELOAD_INTERVAL_IN_DAYS).toMillis());
        scheduledExecutor.trigger();
        assertThat(context.getReloadTask().getNumLoads()).isEqualTo(1);
        scheduledExecutor.triggerPeriodicScheduledTasks();
        assertThat(context.getReloadTask().getNumLoads()).isEqualTo(2);
    }
    assertThat(scheduledExecutor.isTerminated()).isTrue();
}

