@Test
void testValueLiteralString() {
    assertThat(new ValueLiteralExpression(new Integer[][] { null, null, { 1, 2, 3 } }).toString()).isEqualTo("[null, null, [1, 2, 3]]");
    assertThat(new ValueLiteralExpression(new String[][] { null, null, { "1", "2", "3", "Dog's" } }, DataTypes.ARRAY(DataTypes.ARRAY(DataTypes.STRING())).notNull()).toString()).isEqualTo("[null, null, ['1', '2', '3', 'Dog''s']]");
    final Map<String, Integer> map = new LinkedHashMap<>();
    map.put("key1", 1);
    map.put("key2", 2);
    map.put("key3", 3);
    assertThat(new ValueLiteralExpression(map, DataTypes.MAP(DataTypes.STRING(), DataTypes.INT()).notNull()).toString()).isEqualTo("{key1=1, key2=2, key3=3}");
    assertThat(new ValueLiteralExpression(map, DataTypes.MULTISET(DataTypes.STRING()).notNull()).toString()).isEqualTo("{key1=1, key2=2, key3=3}");
}

