@Test
void testLocalDateTimeValueLiteralExtraction() {
    final Timestamp sqlTimestamp = Timestamp.valueOf("2006-11-03 00:00:00.123456789");
    final LocalDateTime localDateTime = LocalDateTime.of(2006, 11, 3, 0, 0, 0, 123456789);
    assertThat(new ValueLiteralExpression(sqlTimestamp).getValueAs(LocalDateTime.class).orElseThrow(AssertionError::new)).isEqualTo(localDateTime);
}

@Test
void testLocalTimeValueLiteralExtraction() {
    final LocalTime localTime = LocalTime.of(12, 12, 12, 123456789);
    final long nanos = localTime.toNanoOfDay();
    final int millis = localTime.get(ChronoField.MILLI_OF_DAY);
    final Time sqlTime = Time.valueOf("12:12:12");
    assertThat(new ValueLiteralExpression(sqlTime).getValueAs(LocalTime.class).orElseThrow(AssertionError::new)).isEqualTo(localTime.withNano(0));
    assertThat(new ValueLiteralExpression(nanos).getValueAs(LocalTime.class).orElseThrow(AssertionError::new)).isEqualTo(localTime);
    assertThat(new ValueLiteralExpression(millis).getValueAs(LocalTime.class).orElseThrow(AssertionError::new)).isEqualTo(localTime.minusNanos(456789));
}

@Test
void testLocalDateValueLiteralExtraction() {
    final LocalDate localDate = LocalDate.of(2012, 12, 12);
    final int daysSinceEpoch = (int) localDate.toEpochDay();
    final Date sqlDate = Date.valueOf("2012-12-12");
    assertThat(new ValueLiteralExpression(sqlDate).getValueAs(LocalDate.class).orElseThrow(AssertionError::new)).isEqualTo(localDate);
    assertThat(new ValueLiteralExpression(daysSinceEpoch).getValueAs(LocalDate.class).orElseThrow(AssertionError::new)).isEqualTo(localDate);
}

@Test
void testInstantValueLiteralExtraction() {
    final Instant instant = Instant.ofEpochMilli(100);
    final long millis = instant.toEpochMilli();
    final int seconds = (int) instant.toEpochMilli() / 1_000;
    assertThat(new ValueLiteralExpression(millis).getValueAs(Instant.class).orElseThrow(AssertionError::new)).isEqualTo(instant);
    assertThat(new ValueLiteralExpression(seconds).getValueAs(Instant.class).orElseThrow(AssertionError::new)).isEqualTo(instant.minusMillis(100));
}

@Test
void testOffsetDateTimeValueLiteralExtraction() {
    final OffsetDateTime offsetDateTime = OffsetDateTime.of(LocalDateTime.parse("2012-12-12T12:12:12"), // Europe/Berlin equals GMT+1 on 2012-12-12
    ZoneOffset.ofHours(1));
    final ZonedDateTime zonedDateTime = ZonedDateTime.of(LocalDateTime.parse("2012-12-12T12:12:12"), ZoneId.of("Europe/Berlin"));
    assertThat(new ValueLiteralExpression(zonedDateTime).getValueAs(OffsetDateTime.class).orElseThrow(AssertionError::new)).isEqualTo(offsetDateTime);
}

