@Test
void testMergeColumnStatsUnknown() {
    ColumnStats columnStats0 = new ColumnStats(4L, 5L, 2D, 3, 15, 2);
    ColumnStats columnStats1 = new ColumnStats(4L, null, 2D, 3, 15, 2);
    ColumnStats columnStats2 = new ColumnStats(4L, 5L, 2D, null, 15, 2);
    ColumnStats columnStats3 = new ColumnStats(null, 5L, 2D, 3, 15, 2);
    ColumnStats columnStats4 = new ColumnStats(4L, 5L, 2D, 3, null, 2);
    ColumnStats columnStats5 = new ColumnStats(4L, 5L, 2D, 3, 15, null);
    ColumnStats columnStats6 = new ColumnStats(4L, 5L, null, 3, 15, 2);
    assertThat(columnStats0.merge(columnStats1, false)).isEqualTo(new ColumnStats(4L, null, 2D, 3, 15, 2));
    assertThat(columnStats0.merge(columnStats2, false)).isEqualTo(new ColumnStats(4L, 10L, 2D, null, 15, 2));
    assertThat(columnStats0.merge(columnStats3, false)).isEqualTo(new ColumnStats(null, 10L, 2D, 3, 15, 2));
    assertThat(columnStats0.merge(columnStats4, false)).isEqualTo(new ColumnStats(4L, 10L, 2D, 3, null, 2));
    assertThat(columnStats0.merge(columnStats5, false)).isEqualTo(new ColumnStats(4L, 10L, 2D, 3, 15, null));
    assertThat(columnStats0.merge(columnStats6, false)).isEqualTo(new ColumnStats(4L, 10L, null, 3, 15, 2));
    assertThat(columnStats6.merge(columnStats6, false)).isEqualTo(new ColumnStats(4L, 10L, null, 3, 15, 2));
    // tet column stats merge while partition key is true.
    assertThat(columnStats0.merge(columnStats1, true)).isEqualTo(new ColumnStats(8L, null, 2D, 3, 15, 2));
    assertThat(columnStats0.merge(columnStats3, true)).isEqualTo(new ColumnStats(null, 10L, 2D, 3, 15, 2));
}

/**
 * Checks that {@link ProjectableTableSource#projectFields(int[])} returns a table source with a
 * different {@link TableSource#explainSource()} even when filtering out all fields.
 *
 * <p>Required by {@code PushProjectIntoTableSourceScanRule}.
 */
@Test
void testEmptyProjection() {
    TableSource<?> source = createTableSource(TableSchema.builder().field("f0", DataTypes.INT()).build());
    assumeThat(source).isInstanceOf(ProjectableTableSource.class);
    ProjectableTableSource<?> projectableTableSource = (ProjectableTableSource<?>) source;
    TableSource<?> newTableSource = projectableTableSource.projectFields(new int[0]);
    assertThat(newTableSource.explainSource()).isNotEqualTo(source.explainSource());
}

/**
 * Checks that {@link ProjectableTableSource#projectFields(int[])} returns a table source with a
 * different {@link TableSource#explainSource()}, but same schema.
 *
 * <p>Required by {@code PushProjectIntoTableSourceScanRule}.
 */
@Test
void testProjectionReturnsDifferentSource() {
    TableSource<?> source = createTableSource(TableSchema.builder().field("f0", DataTypes.INT()).field("f1", DataTypes.STRING()).field("f2", DataTypes.BIGINT()).build());
    assumeThat(source).isInstanceOf(ProjectableTableSource.class);
    ProjectableTableSource<?> projectableTableSource = (ProjectableTableSource<?>) source;
    TableSource<?> newTableSource = projectableTableSource.projectFields(new int[] { 0, 2 });
    assertThat(newTableSource.explainSource()).isNotEqualTo(source.explainSource());
    assertThat(newTableSource.getTableSchema()).isEqualTo(source.getTableSchema());
}

