@Test
void testResolveParameters() {
    List<Method> methods = ExtractionUtils.collectMethods(LongClass.class, "method");
    Method method = methods.get(0);
    Type longType = ExtractionUtils.resolveVariableWithClassContext(LongClass.class, method.getGenericParameterTypes()[0]);
    Type futureType = ExtractionUtils.resolveVariableWithClassContext(LongClass.class, method.getGenericParameterTypes()[1]);
    Type listOfFutures = ExtractionUtils.resolveVariableWithClassContext(LongClass.class, method.getGenericParameterTypes()[2]);
    Type arrayType = ExtractionUtils.resolveVariableWithClassContext(LongClass.class, method.getGenericParameterTypes()[3]);
    assertThat(longType).isEqualTo(Long.class);
    assertThat(futureType).isInstanceOf(ParameterizedType.class);
    assertThat(((ParameterizedType) futureType).getRawType()).isEqualTo(CompletableFuture.class);
    assertThat(((ParameterizedType) futureType).getActualTypeArguments()[0]).isEqualTo(Long.class);
    assertThat(listOfFutures).isInstanceOf(ParameterizedType.class);
    assertThat(((ParameterizedType) listOfFutures).getRawType()).isEqualTo(List.class);
    assertThat(((ParameterizedType) listOfFutures).getActualTypeArguments()[0]).isInstanceOf(ParameterizedType.class);
    ParameterizedType innerFuture = ((ParameterizedType) ((ParameterizedType) listOfFutures).getActualTypeArguments()[0]);
    assertThat(innerFuture.getRawType()).isEqualTo(CompletableFuture.class);
    assertThat(innerFuture.getActualTypeArguments()[0]).isEqualTo(Long.class);
    assertThat(arrayType).isInstanceOf(GenericArrayType.class);
    assertThat(((GenericArrayType) arrayType).getGenericComponentType()).isEqualTo(Long.class);
}

