    tEnv.getCatalog(tEnv.getCurrentCatalog()).orElseThrow(Exception::new).alterPartitionStatistics(new ObjectPath(tEnv.getCurrentDatabase(), "PartTable"), new CatalogPartitionSpec(Collections.singletonMap("b", "3")), new CatalogTableStatistics(3L, 1, 100L, 100L), false);
    tEnv.getCatalog(tEnv.getCurrentCatalog()).orElseThrow(Exception::new).alterPartitionColumnStatistics(new ObjectPath(tEnv.getCurrentDatabase(), "PartTable"), new CatalogPartitionSpec(Collections.singletonMap("b", "1")), createSinglePartitionColumnStats(), false);
