@Test
void testPersistedConfigOption() throws Exception {
    List<String> data = Stream.concat(DATA.stream(), Stream.of("4,2,This string is long", "5,3,This is an even longer string")).collect(Collectors.toList());
    String[] sinkColumnDefinitions = new String[] { "a bigint", "b int", "c varchar(11)" };
    createTestCsvSourceTable("src", data, COLUMNS_DEFINITION);
    File sinkPath = createTestCsvSinkTable("sink", sinkColumnDefinitions);
    // Set config option to trim the strings, so it's persisted in the json plan
    tableEnv.getConfig().getConfiguration().set(ExecutionConfigOptions.TABLE_EXEC_SINK_TYPE_LENGTH_ENFORCER, ExecutionConfigOptions.TypeLengthEnforcer.TRIM_PAD);
    CompiledPlan plan = tableEnv.compilePlanSql("INSERT INTO sink SELECT * FROM src");
    // Set config option to trim the strings to IGNORE, to validate that the persisted config
    // is overriding the environment setting.
    tableEnv.getConfig().getConfiguration().set(ExecutionConfigOptions.TABLE_EXEC_SINK_TYPE_LENGTH_ENFORCER, ExecutionConfigOptions.TypeLengthEnforcer.IGNORE);
    plan.execute().await();
    List<String> expected = Stream.concat(DATA.stream(), Stream.of("4,2,This string", "5,3,This is an ")).collect(Collectors.toList());
    assertResult(expected, sinkPath);
}

