@Test
void testCanonizeType() {
    FlinkTypeFactory typeFactory = new FlinkTypeFactory(Thread.currentThread().getContextClassLoader(), FlinkTypeSystem.INSTANCE);
    TypeInformation<?> genericTypeInfo = Types.GENERIC(TestClass.class);
    TypeInformation<?> genericTypeInfo2 = Types.GENERIC(TestClass2.class);
    RelDataType genericRelType = typeFactory.createFieldTypeFromLogicalType(new TypeInformationRawType(genericTypeInfo));
    RelDataType genericRelType2 = typeFactory.createFieldTypeFromLogicalType(new TypeInformationRawType(genericTypeInfo));
    RelDataType genericRelType3 = typeFactory.createFieldTypeFromLogicalType(new TypeInformationRawType(genericTypeInfo2));
    assertThat(genericRelType).as("The type expect to be canonized").isEqualTo(genericRelType2);
    assertThat(genericRelType).as("The type expect to be not canonized").isNotEqualTo(genericRelType3);
    assertThat(typeFactory.builder().add("f0", genericRelType).build()).as("The type expect to be not canonized").isNotEqualTo(typeFactory.builder().add("f0", genericRelType3).build());
}

