@Test
void testJobName() {
    final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
    final Executor executor = new DefaultExecutor(env);
    final List<Transformation<?>> dummyTransformations = Collections.singletonList(env.fromData(1, 2, 3).sinkTo(new DiscardingSink<>()).getTransformation());
    final Configuration configuration = new Configuration();
    configuration.set(PipelineOptions.NAME, "Custom Name");
    // default
    testJobName(executor.createPipeline(dummyTransformations, new Configuration(), "Default Name"), "Default Name");
    // Table API specific
    testJobName(executor.createPipeline(dummyTransformations, configuration, "Default Name"), "Custom Name");
    // DataStream API specific
    env.configure(configuration);
    testJobName(executor.createPipeline(dummyTransformations, new Configuration(), "Default Name"), "Custom Name");
}

@Test
void testDefaultBatchProperties() {
    final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
    final Executor executor = new DefaultExecutor(env);
    final List<Transformation<?>> dummyTransformations = Collections.singletonList(env.fromData(1, 2, 3).sinkTo(new DiscardingSink<>()).getTransformation());
    final Configuration configuration = new Configuration();
    configuration.set(ExecutionOptions.RUNTIME_MODE, RuntimeExecutionMode.BATCH);
    final StreamGraph streamGraph = (StreamGraph) executor.createPipeline(dummyTransformations, configuration, "Default Name");
    assertThat(streamGraph.getExecutionConfig().isObjectReuseEnabled()).isTrue();
    assertThat(streamGraph.getExecutionConfig().getLatencyTrackingInterval()).isEqualTo(0);
    assertThat(streamGraph.isChainingEnabled()).isTrue();
    assertThat(streamGraph.isAllVerticesInSameSlotSharingGroupByDefault()).isFalse();
    assertThat(streamGraph.getCheckpointConfig().isCheckpointingEnabled()).isFalse();
    assertThat(streamGraph.getGlobalStreamExchangeMode()).isEqualTo(GlobalStreamExchangeMode.ALL_EDGES_BLOCKING);
}

