" + "TIME '12:12:12.333',
" + "TIMESTAMP '2024-02-03 12:12:12.333',
" + "TO_TIMESTAMP_LTZ(1234567, 3),
" + "INTERVAL '99 00:00:34.999' DAY TO SECOND(3),
" + "INTERVAL '39-2' YEAR TO MONTH");
    final TableResult tableResult = env.sqlQuery(String.format("SELECT %s", exprStr)).execute();
