@Test
void testClearCaseInsensitiveLookupHint() {
    // SELECT /*+ lookUp('table'='lookup', 'retry-predicate'='lookup_miss',
    // 'retry-strategy'='fixed_delay', 'fixed-delay'='155 ms', 'max-attempts'='10',
    // 'async'='true', 'output-mode'='allow_unordered','capacity'='1000', 'time-out'='300 s')
    // */ s.a
    // FROM src s
    // JOIN lookup FOR SYSTEM_TIME AS OF s.pts AS d
    // ON s.a=d.a
    CorrelationId cid = builder.getCluster().createCorrel();
    RelDataType aType = builder.getTypeFactory().createStructType(Collections.singletonList(builder.getTypeFactory().createSqlType(SqlTypeName.BIGINT)), Collections.singletonList("a"));
    RelDataType ptsType = builder.getTypeFactory().createStructType(Collections.singletonList(builder.getTypeFactory().createProctimeIndicatorType(false)), Collections.singletonList("pts"));
    RelNode root = FlinkHints.capitalizeQueryHints(builder.scan("src").scan("lookup").snapshot(builder.getRexBuilder().makeCall(FlinkSqlOperatorTable.PROCTIME)).filter(builder.equals(builder.field(builder.getRexBuilder().makeCorrel(aType, cid), "a"), builder.getRexBuilder().makeInputRef(aType, 0))).correlate(JoinRelType.INNER, cid, builder.getRexBuilder().makeInputRef(aType, 0), builder.getRexBuilder().makeInputRef(ptsType, 1)).project(builder.field(1, 0, "a")).hints(RelHint.builder(FlinkHints.HINT_ALIAS).hintOption("t1").build()).hints(RelHint.builder("lookUp").hintOptions(LookupJoinHintTestUtil.getLookupJoinHintOptions("d", true, false)).build()).build());
    verifyRelPlan(root);
}

