@Test
void includingAllOverwriteOptionsMergeStrategyExpansion() {
    List<SqlTableLikeOption> inputOptions = Arrays.asList(new SqlTableLikeOption(MergingStrategy.EXCLUDING, FeatureOption.ALL), new SqlTableLikeOption(MergingStrategy.INCLUDING, FeatureOption.CONSTRAINTS));
    Map<FeatureOption, MergingStrategy> mergingStrategies = util.computeMergingStrategies(inputOptions);
    assertThat(mergingStrategies.get(FeatureOption.OPTIONS)).isEqualTo(MergingStrategy.EXCLUDING);
    assertThat(mergingStrategies.get(FeatureOption.PARTITIONS)).isEqualTo(MergingStrategy.EXCLUDING);
    assertThat(mergingStrategies.get(FeatureOption.CONSTRAINTS)).isEqualTo(MergingStrategy.INCLUDING);
    assertThat(mergingStrategies.get(FeatureOption.GENERATED)).isEqualTo(MergingStrategy.EXCLUDING);
    assertThat(mergingStrategies.get(FeatureOption.METADATA)).isEqualTo(MergingStrategy.EXCLUDING);
