@Test
public void testAlterCatalog() {
    // test alter catalog options
    final String sql1 = "ALTER CATALOG cat2 SET ('K1' = 'V1', 'k2' = 'v2', 'k2' = 'v2_new')";
    final Map<String, String> expectedOptions = new HashMap<>();
    expectedOptions.put("K1", "V1");
    expectedOptions.put("k2", "v2_new");
    Operation operation = parse(sql1);
    assertThat(operation).isInstanceOf(AlterCatalogOptionsOperation.class).asInstanceOf(InstanceOfAssertFactories.type(AlterCatalogOptionsOperation.class)).extracting(AlterCatalogOptionsOperation::getCatalogName, AlterCatalogOptionsOperation::asSummaryString, AlterCatalogOptionsOperation::getProperties).containsExactly("cat2", "ALTER CATALOG cat2\n  SET 'K1' = 'V1',\n  SET 'k2' = 'v2_new'", expectedOptions);
    // test alter catalog reset
    final Set<String> expectedResetKeys = Collections.singleton("K1");
    operation = parse("ALTER CATALOG cat2 RESET ('K1')");
    assertThat(operation).isInstanceOf(AlterCatalogResetOperation.class).asInstanceOf(InstanceOfAssertFactories.type(AlterCatalogResetOperation.class)).extracting(AlterCatalogResetOperation::getCatalogName, AlterCatalogResetOperation::asSummaryString, AlterCatalogResetOperation::getResetKeys).containsExactly("cat2", "ALTER CATALOG cat2\n  RESET 'K1'", expectedResetKeys);
