@Test
public void testAlterTable() throws Exception {
    prepareTable(false);
    final String[] renameTableSqls = new String[] { "alter table cat1.db1.tb1 rename to tb2", "alter table db1.tb1 rename to tb2", "alter table tb1 rename to cat1.db1.tb2" };
    final ObjectIdentifier expectedIdentifier = ObjectIdentifier.of("cat1", "db1", "tb1");
    final ObjectIdentifier expectedNewIdentifier = ObjectIdentifier.of("cat1", "db1", "tb2");
    // test rename table converter
    for (String renameTableSql : renameTableSqls) {
        Operation operation = parse(renameTableSql);
        assertThat(operation).isInstanceOf(AlterTableRenameOperation.class);
        final AlterTableRenameOperation alterTableRenameOperation = (AlterTableRenameOperation) operation;
        assertThat(alterTableRenameOperation.getTableIdentifier()).isEqualTo(expectedIdentifier);
        assertThat(alterTableRenameOperation.getNewTableIdentifier()).isEqualTo(expectedNewIdentifier);
    }
    // test alter nonexistent table
    checkAlterNonExistTable("alter table %s nonexistent rename to tb2");
    // test alter table options
    checkAlterNonExistTable("alter table %s nonexistent set ('k1' = 'v1', 'K2' = 'V2')");
    Operation operation = parse("alter table if exists cat1.db1.tb1 set ('k1' = 'v1', 'K2' = 'V2')");
    Map<String, String> expectedOptions = new HashMap<>();
    expectedOptions.put("connector", "dummy");
    expectedOptions.put("k", "v");
    expectedOptions.put("k1", "v1");
    expectedOptions.put("K2", "V2");
    assertAlterTableOptions(operation, expectedIdentifier, expectedOptions, Arrays.asList(TableChange.set("k1", "v1"), TableChange.set("K2", "V2")), "ALTER TABLE IF EXISTS cat1.db1.tb1\n  SET 'k1' = 'v1',\n  SET 'K2' = 'V2'");
    // test alter table reset
    checkAlterNonExistTable("alter table %s nonexistent reset ('k')");
    operation = parse("alter table if exists cat1.db1.tb1 reset ('k')");
    assertAlterTableOptions(operation, expectedIdentifier, Collections.singletonMap("connector", "dummy"), Collections.singletonList(TableChange.reset("k")), "ALTER TABLE IF EXISTS cat1.db1.tb1\n  RESET 'k'");
    assertThatThrownBy(() -> parse("alter table cat1.db1.tb1 reset ('connector')")).isInstanceOf(ValidationException.class).hasMessageContaining("ALTER TABLE RESET does not support changing 'connector'");
    assertThatThrownBy(() -> parse("alter table cat1.db1.tb1 reset ()")).isInstanceOf(ValidationException.class).hasMessageContaining("ALTER TABLE RESET does not support empty key");
}

@Test
public void testAlterTableRenameColumn() throws Exception {
    prepareTable("tb1", false, true, 3);
    // rename pk column c
    Operation operation = parse("alter table tb1 rename c to c1");
    assertThat(operation).isInstanceOf(AlterTableChangeOperation.class);
    assertThat(operation.asSummaryString()).isEqualTo("ALTER TABLE cat1.db1.tb1\n  MODIFY `c` TO `c1`");
    assertThat(((AlterTableChangeOperation) operation).getNewTable().getUnresolvedSchema()).isEqualTo(Schema.newBuilder().column("a", DataTypes.INT().notNull()).column("b", DataTypes.BIGINT().notNull()).column("c1", DataTypes.STRING().notNull()).withComment("column comment").columnByExpression("d", "a*(b+2 + a*b)").column("e", DataTypes.ROW(DataTypes.STRING(), DataTypes.INT(), DataTypes.ROW(DataTypes.DOUBLE(), DataTypes.ARRAY(DataTypes.FLOAT())))).columnByExpression("f", "e.f1 + e.f2.f0").columnByMetadata("g", DataTypes.STRING(), null, true).column("ts", DataTypes.TIMESTAMP(3)).withComment("just a comment").watermark("ts", "ts - interval '5' seconds").primaryKeyNamed("ct1", "a", "b", "c1").build());
    // rename computed column
    operation = parse("alter table tb1 rename f to f1");
    assertThat(operation).isInstanceOf(AlterTableChangeOperation.class);
    assertThat(operation.asSummaryString()).isEqualTo("ALTER TABLE cat1.db1.tb1\n  MODIFY `f` TO `f1`");
    assertThat(((AlterTableChangeOperation) operation).getNewTable().getUnresolvedSchema()).isEqualTo(Schema.newBuilder().column("a", DataTypes.INT().notNull()).column("b", DataTypes.BIGINT().notNull()).column("c", DataTypes.STRING().notNull()).withComment("column comment").columnByExpression("d", "a*(b+2 + a*b)").column("e", DataTypes.ROW(DataTypes.STRING(), DataTypes.INT(), DataTypes.ROW(DataTypes.DOUBLE(), DataTypes.ARRAY(DataTypes.FLOAT())))).columnByExpression("f1", "e.f1 + e.f2.f0").columnByMetadata("g", DataTypes.STRING(), null, true).column("ts", DataTypes.TIMESTAMP(3)).withComment("just a comment").watermark("ts", "ts - interval '5' seconds").primaryKeyNamed("ct1", "a", "b", "c").build());
    // rename column c that is used in a computed column
    assertThatThrownBy(() -> parse("alter table tb1 rename a to a1")).isInstanceOf(ValidationException.class).hasMessageContaining("The column `a` is referenced by computed column `d`.");
    // rename column used in the watermark expression
    assertThatThrownBy(() -> parse("alter table tb1 rename ts to ts1")).isInstanceOf(ValidationException.class).hasMessageContaining("The column `ts` is referenced by watermark expression.");
    // rename nested column
    assertThatThrownBy(() -> parse("alter table tb1 rename e.f1 to e.f11")).isInstanceOf(UnsupportedOperationException.class).hasMessageContaining("Alter nested row type e.f1 is not supported yet.");
    // rename column with duplicate name
    assertThatThrownBy(() -> parse("alter table tb1 rename c to a")).isInstanceOf(ValidationException.class).hasMessageContaining("The column `a` already existed in table schema.");
    // rename column e test computed column expression is ApiExpression which doesn't implement
    // the equals method
    CatalogTable catalogTable2 = CatalogTable.newBuilder().schema(Schema.newBuilder().column("a", DataTypes.STRING().notNull()).column("b", DataTypes.INT().notNull()).column("e", DataTypes.STRING()).columnByExpression("j", $("e").upperCase()).columnByExpression("g", "TO_TIMESTAMP(e)").primaryKey("a", "b").build()).comment("tb2").partitionKeys(Collections.singletonList("a")).build();
    catalogManager.getCatalog("cat1").get().createTable(new ObjectPath("db1", "tb2"), catalogTable2, true);
    assertThatThrownBy(() -> parse("alter table `cat1`.`db1`.`tb2` rename e to e1")).isInstanceOf(ValidationException.class).hasMessageContaining("Failed to execute ALTER TABLE statement.\nThe column `e` is referenced by computed column `g`, `j`.");
    // rename column used as partition key
    assertThatThrownBy(() -> parse("alter table tb2 rename a to a1")).isInstanceOf(ValidationException.class).hasMessageContaining("Failed to execute ALTER TABLE statement.\nThe column `a` is used as the partition keys.");
    checkAlterNonExistTable("alter table %s nonexistent rename a to a1");
    prepareTableWithDistribution("tb3");
    // rename column used as distribution key
    assertThatThrownBy(() -> parse("alter table tb3 rename c to a1")).isInstanceOf(ValidationException.class).hasMessageContaining("Failed to execute ALTER TABLE statement.\nThe column `c` is used as a distribution key.");
    checkAlterNonExistTable("alter table %s nonexistent rename a to a1");
}

