public void testFailedToAlterTableAddColumn() throws Exception {
    prepareTable("tb1", 0);
    // try to add a column with duplicated name
    assertThatThrownBy(() -> parse("alter table tb1 add a bigint")).isInstanceOf(ValidationException.class).hasMessageContaining("Try to add a column `a` which already exists in the table.");
    // try to add multiple columns with duplicated column name
    assertThatThrownBy(() -> parse("alter table tb1 add (x array<string>, x string)")).isInstanceOf(ValidationException.class).hasMessageContaining("Encounter duplicate column `x`.");
    // refer to a nonexistent column
    assertThatThrownBy(() -> parse("alter table tb1 add x bigint after y")).isInstanceOf(ValidationException.class).hasMessageContaining("Referenced column `y` by 'AFTER' does not exist in the table.");
    // refer to a new added column that appears in the post position
    assertThatThrownBy(() -> parse("alter table tb1 add (x bigint after y, y string first)")).isInstanceOf(ValidationException.class).hasMessageContaining("Referenced column `y` by 'AFTER' does not exist in the table.");
    // add a computed column based on nonexistent column
    assertThatThrownBy(() -> parse("alter table tb1 add m as n + 2")).isInstanceOf(ValidationException.class).hasMessageContaining("Invalid expression for computed column 'm'.");
    // add a computed column based on another computed column
    assertThatThrownBy(() -> parse("alter table tb1 add (m as b * 2, n as m + 2)")).isInstanceOf(ValidationException.class).hasMessageContaining("Invalid expression for computed column 'n'.");
    // invalid expression
    assertThatThrownBy(() -> parse("alter table tb1 add (m as 'hello' || b)")).isInstanceOf(ValidationException.class).hasMessageContaining("Invalid expression for computed column 'm'.");
    // add an inner field to a nested row
    assertThatThrownBy(() -> parse("alter table tb1 add (e.f3 string)")).isInstanceOf(UnsupportedOperationException.class).hasMessageContaining("Alter nested row type e.f3 is not supported yet.");
    // refer to a nested inner field
