    Operation operation = parse("alter table tb1 add constraint my_pk primary key (a, b) not enforced");
    assertThat(operation.asSummaryString()).isEqualTo("ALTER TABLE cat1.db1.tb1\n" + "  ADD CONSTRAINT `my_pk` PRIMARY KEY (`a`, `b`) NOT ENFORCED");
