    operation = parse("alter table tb1 add x bigint primary key not enforced");
    assertThat(operation.asSummaryString()).isEqualTo("ALTER TABLE cat1.db1.tb1\n" + "  ADD `x` BIGINT NOT NULL ,\n" + "  ADD CONSTRAINT `PK_x` PRIMARY KEY (`x`) NOT ENFORCED");
    assertAlterTableSchema(operation, tableIdentifier, Schema.newBuilder().fromSchema(originalSchema).column("x", DataTypes.BIGINT().notNull()).primaryKey("x").build());
