@Test
void testAlterMaterializedTableAsQuery() throws TableNotExistException {
    String sql = "ALTER MATERIALIZED TABLE base_mtbl AS SELECT a, b, c, d, d as e, cast('123' as string) as f FROM t3";
    Operation operation = parse(sql);
    assertThat(operation).isInstanceOf(AlterMaterializedTableAsQueryOperation.class);
    AlterMaterializedTableAsQueryOperation op = (AlterMaterializedTableAsQueryOperation) operation;
    assertThat(op.getTableChanges()).isEqualTo(Arrays.asList(TableChange.add(Column.physical("e", DataTypes.VARCHAR(Integer.MAX_VALUE))), TableChange.add(Column.physical("f", DataTypes.VARCHAR(Integer.MAX_VALUE))), TableChange.modifyDefinitionQuery("SELECT `t3`.`a`, `t3`.`b`, `t3`.`c`, `t3`.`d`, `t3`.`d` AS `e`, CAST('123' AS STRING) AS `f`\n" + "FROM `builtin`.`default`.`t3`")));
    assertThat(operation.asSummaryString()).isEqualTo("ALTER MATERIALIZED TABLE builtin.default.base_mtbl AS SELECT `t3`.`a`, `t3`.`b`, `t3`.`c`, `t3`.`d`, `t3`.`d` AS `e`, CAST('123' AS STRING) AS `f`\n" + "FROM `builtin`.`default`.`t3`");
    // new table only difference schema & definition query with old table.
    CatalogMaterializedTable oldTable = (CatalogMaterializedTable) catalog.getTable(new ObjectPath(catalogManager.getCurrentDatabase(), "base_mtbl"));
    CatalogMaterializedTable newTable = op.getNewMaterializedTable();
    assertThat(oldTable.getUnresolvedSchema()).isNotEqualTo(newTable.getUnresolvedSchema());
    assertThat(oldTable.getUnresolvedSchema().getPrimaryKey()).isEqualTo(newTable.getUnresolvedSchema().getPrimaryKey());
    assertThat(oldTable.getUnresolvedSchema().getWatermarkSpecs()).isEqualTo(newTable.getUnresolvedSchema().getWatermarkSpecs());
    assertThat(oldTable.getDefinitionQuery()).isNotEqualTo(newTable.getDefinitionQuery());
    assertThat(oldTable.getDefinitionFreshness()).isEqualTo(newTable.getDefinitionFreshness());
    assertThat(oldTable.getRefreshMode()).isEqualTo(newTable.getRefreshMode());
    assertThat(oldTable.getRefreshStatus()).isEqualTo(newTable.getRefreshStatus());
    assertThat(oldTable.getSerializedRefreshHandler()).isEqualTo(newTable.getSerializedRefreshHandler());
    List<Schema.UnresolvedColumn> addedColumn = newTable.getUnresolvedSchema().getColumns().stream().filter(column -> !oldTable.getUnresolvedSchema().getColumns().contains(column)).collect(Collectors.toList());
    // added column should be a nullable column.
    assertThat(addedColumn).isEqualTo(Arrays.asList(new Schema.UnresolvedPhysicalColumn("e", DataTypes.VARCHAR(Integer.MAX_VALUE)), new Schema.UnresolvedPhysicalColumn("f", DataTypes.VARCHAR(Integer.MAX_VALUE))));
}

