@Test
void testAlterMaterializedTableAsQueryWithUnsupportedColumnChange() {
    // 1. delete existing column
    String sql1 = "ALTER MATERIALIZED TABLE base_mtbl AS SELECT a, b FROM t3";
    assertThatThrownBy(() -> parse(sql1)).isInstanceOf(ValidationException.class).hasMessageContaining("Failed to modify query because drop column is unsupported. When modifying a query, you can only append new columns at the end of original schema. The original schema has 4 columns, but the newly derived schema from the query has 2 columns.");
    // 2. swap column position
    String sql2 = "ALTER MATERIALIZED TABLE base_mtbl AS SELECT a, b, d, c FROM t3";
    assertThatThrownBy(() -> parse(sql2)).isInstanceOf(ValidationException.class).hasMessageContaining("When modifying the query of a materialized table, currently only support appending columns at the end of original schema, dropping, renaming, and reordering columns are not supported.\n" + "Column mismatch at position 2: Original column is [`c` INT], but new column is [`d` STRING].");
    // 3. change existing column type
    String sql3 = "ALTER MATERIALIZED TABLE base_mtbl AS SELECT a, b, c, cast(d as int) as d FROM t3";
    assertThatThrownBy(() -> parse(sql3)).isInstanceOf(ValidationException.class).hasMessageContaining("When modifying the query of a materialized table, currently only support appending columns at the end of original schema, dropping, renaming, and reordering columns are not supported.\n" + "Column mismatch at position 3: Original column is [`d` STRING], but new column is [`d` INT].");
    // 4. change existing column nullability
    String sql4 = "ALTER MATERIALIZED TABLE base_mtbl AS SELECT a, b, c, cast('d' as string) as d FROM t3";
    assertThatThrownBy(() -> parse(sql4)).isInstanceOf(ValidationException.class).hasMessageContaining("When modifying the query of a materialized table, currently only support appending columns at the end of original schema, dropping, renaming, and reordering columns are not supported.\n" + "Column mismatch at position 3: Original column is [`d` STRING], but new column is [`d` STRING NOT NULL].");
}

