@Test
void testCallStatement() {
    // test call the procedure which accepts primitive types as arguments
    String sql = "call `system`.primitive_arg(1, 2)";
    verifyCallOperation(sql, "CALL PROCEDURE:" + " (procedureIdentifier: [`p1`.`system`.`primitive_arg`]," + " inputTypes: [INT NOT NULL, BIGINT NOT NULL], outputTypes: [INT NOT NULL], arguments: [1, 2])");
    // test call the procedure which has different type mapping for single method
    // call with int
    sql = "call `system`.different_type_mapping(1)";
    verifyCallOperation(sql, "CALL PROCEDURE:" + " (procedureIdentifier: [`p1`.`system`.`different_type_mapping`]," + " inputTypes: [INT], outputTypes: [INT], arguments: [1])");
    // call with bigint
    sql = "call `system`.different_type_mapping(cast(1 as bigint))";
    verifyCallOperation(sql, "CALL PROCEDURE:" + " (procedureIdentifier: [`p1`.`system`.`different_type_mapping`]," + " inputTypes: [BIGINT], outputTypes: [BIGINT], arguments: [1])");
    // test call the procedure which has var arguments
    sql = "call `system`.var_arg(1)";
    verifyCallOperation(sql, "CALL PROCEDURE:" + " (procedureIdentifier: [`p1`.`system`.`var_arg`]," + " inputTypes: [INT NOT NULL], outputTypes: [STRING], arguments: [1])");
    sql = "call `system`.var_arg(1, 2)";
    verifyCallOperation(sql, "CALL PROCEDURE:" + " (procedureIdentifier: [`p1`.`system`.`var_arg`]," + " inputTypes: [INT NOT NULL, INT NOT NULL], outputTypes: [STRING], arguments: [1, 2])");
    sql = "call `system`.var_arg(1, 2, 1 + 2)";
    verifyCallOperation(sql, "CALL PROCEDURE:" + " (procedureIdentifier: [`p1`.`system`.`var_arg`]," + " inputTypes: [INT NOT NULL, INT NOT NULL, INT NOT NULL], outputTypes: [STRING], arguments: [1, 2, 3])");
    // test call the procedure with row as result and decimal as argument as well as
    // explict/implicit cast
    sql = "call `system`.row_result(cast(1.2 as decimal))";
    verifyCallOperation(sql, "CALL PROCEDURE:" + " (procedureIdentifier: [`p1`.`system`.`row_result`]," + " inputTypes: [DECIMAL(10, 2)], outputTypes: [ROW<`i` INT>], arguments: [1.20])");
    sql = "call `system`.row_result(1.2)";
    verifyCallOperation(sql, "CALL PROCEDURE:" + " (procedureIdentifier: [`p1`.`system`.`row_result`]," + " inputTypes: [DECIMAL(10, 2)], outputTypes: [ROW<`i` INT>], arguments: [1.20])");
    // test call the procedure with pojo as result
    sql = "call p1.`system`.pojo_result('name', 1)";
    verifyCallOperation(sql, "CALL PROCEDURE:" + " (procedureIdentifier: [`p1`.`system`.`pojo_result`]," + " inputTypes: [STRING, BIGINT NOT NULL]," + " outputTypes: [*org.apache.flink.table.planner.operations.SqlNodeToCallOperationTest$MyPojo<`name` STRING, `id` BIGINT NOT NULL>*]," + " arguments: [name, 1])");
    // test call the procedure with timestamp as arguments
    sql = "call p1.`system`.timestamp_arg(timestamp '2023-04-22 00:00:00.300', " + "timestamp '2023-04-22 00:00:00.300' +  INTERVAL '1' day ) ";
    verifyCallOperation(sql, String.format("CALL PROCEDURE:" + " (procedureIdentifier: [`p1`.`system`.`timestamp_arg`]," + " inputTypes: [TIMESTAMP(3), TIMESTAMP(3)], outputTypes: [TIMESTAMP(3)]," + " arguments: [%s, %s])", LocalDateTime.parse("2023-04-22T00:00:00.300"), LocalDateTime.parse("2023-04-23T00:00:00.300")));
    // should throw exception when the signature doesn't match
    assertThatThrownBy(() -> parse("call `system`.primitive_arg(1)")).hasMessageContaining("No match found for function signature primitive_arg(<NUMERIC>)");
    // should throw exception when the expression argument can't be reduced
    // to literal
    assertThatThrownBy(() -> parse("call `system`.row_result(cast((1.2 + 2.4) as decimal))")).hasMessageContaining("The argument at position 0 CAST(CAST(1.2 + 2.4 AS DECIMAL) AS DECIMAL(10, 2)) for calling procedure can't be converted to literal.");
}

