@Test
void testTimeTravelWithUnsupportedExpression() {
    assertThatThrownBy(() -> util.tableEnv().executeSql("SELECT
" + "    *
" + "FROM
" + "    t1 FOR SYSTEM_TIME AS OF TO_TIMESTAMP_LTZ (0, 3)")).isInstanceOf(ValidationException.class).hasMessageContaining("SQL validation failed. Unsupported time travel expression: `TO_TIMESTAMP_LTZ`(0, 3) for the expression can not be reduced to a constant by Flink.");
    assertThatThrownBy(() -> util.tableEnv().executeSql("SELECT
" + "    *
" + "FROM
" + "    t1 FOR SYSTEM_TIME AS OF PROCTIME()")).isInstanceOf(ValidationException.class).hasMessageContaining("Unsupported time travel expression: PROCTIME() for the expression can not be reduced to a constant by Flink.");
