    util.tableEnv().executeSql("CREATE TABLE\n" + "    t2 (f1 VARCHAR, f2 TIMESTAMP(3))\n" + "WITH\n" + "    ('connector'='values', 'bounded'='true')");
    // select snapshot with identifier only support in lookup join or temporal join.
    // The following query can't generate a validate execution plan.
    assertThatThrownBy(() -> util.tableEnv().executeSql("SELECT\n" + "    *\n" + "FROM\n" + "    t2 FOR SYSTEM_TIME AS OF f2")).isInstanceOf(TableException.class).hasMessageContaining("Cannot generate a valid execution plan for the given query");
}

