@Test
void testJoinHintsOnSameViewWithoutReusingViewBecauseDifferentJoinHints() {
    util.tableEnv().getConfig().set(OptimizerConfigOptions.TABLE_OPTIMIZER_REUSE_OPTIMIZE_BLOCK_WITH_DIGEST_ENABLED, true);
    // the build side in this view is left
    util.tableEnv().executeSql(String.format("create view V2 as select /*+ %s(T1)*/ T1.* from T1 join T2 on T1.a1 = T2.a2", getTestSingleJoinHint()));
    // the build side in this view is left
    // V2 and V3 have different join hints
    util.tableEnv().executeSql(String.format("create view V3 as select /*+ %s(T1)*/ T1.* from T1 join T2 on T1.a1 = T2.a2", getOtherJoinHints().get(0)));
    util.tableEnv().executeSql("CREATE TABLE S1 (\n" + "  a1 BIGINT,\n" + "  b1 VARCHAR\n" + ") WITH (\n" + " 'connector' = 'values',\n" + " 'bounded' = 'true'\n" + ")");
    util.tableEnv().executeSql("CREATE TABLE S2 (\n" + "  a1 BIGINT,\n" + "  b1 VARCHAR\n" + ") WITH (\n" + " 'connector' = 'values',\n" + " 'bounded' = 'true'\n" + ")");
    StatementSet set = util.tableEnv().createStatementSet();
    // the calc will not be pushed down because the view has different digest
    set.addInsertSql(String.format("insert into S1 select /*+ %s(V2)*/ T1.* from T1 join V2 on T1.a1 = V2.a1 where V2.a1 > 2", getTestSingleJoinHint()));
