@Test
void testCheckPipelinedPath() {
    // P = InputProperty.DamBehavior.PIPELINED, E = InputProperty.DamBehavior.END_INPUT B =
    // InputProperty.DamBehavior.BLOCKING
    //
    // 0 -P-> 1 ----E----\
    //         \-P-\      \
    // 2 ----E----> 3 -P-> 4
    // 5 -P-> 6 -B-/
    TestingBatchExecNode[] nodes = new TestingBatchExecNode[7];
