    assertThat(asyncLookupOptions.asyncOutputMode).isSameAs(AsyncDataStream.OutputMode.ORDERED);
    assertThat(asyncLookupOptions.asyncTimeout).isEqualTo(ExecutionConfigOptions.TABLE_EXEC_ASYNC_LOOKUP_TIMEOUT.defaultValue().toMillis());
    assertThat(asyncLookupOptions.asyncBufferCapacity).isEqualTo(ExecutionConfigOptions.TABLE_EXEC_ASYNC_LOOKUP_BUFFER_CAPACITY.defaultValue());
    TableConfig userConf = TableConfig.getDefault();
    userConf.set(ExecutionConfigOptions.TABLE_EXEC_ASYNC_LOOKUP_OUTPUT_MODE, ExecutionConfigOptions.AsyncOutputMode.ALLOW_UNORDERED);
    userConf.set(ExecutionConfigOptions.TABLE_EXEC_ASYNC_LOOKUP_BUFFER_CAPACITY, 300);
    Map<String, String> kvOptions = new HashMap<>();
    kvOptions.put(LookupJoinHintOptions.ASYNC_LOOKUP.key(), "true");
    kvOptions.put(LookupJoinHintOptions.ASYNC_CAPACITY.key(), "1000");
    asyncLookupOptions = LookupJoinUtil.getMergedAsyncOptions(RelHint.builder(JoinStrategy.LOOKUP.getJoinHintName()).hintOptions(kvOptions).build(), userConf, ChangelogMode.insertOnly());
    assertThat(asyncLookupOptions.asyncOutputMode).isSameAs(AsyncDataStream.OutputMode.UNORDERED);
    assertThat(asyncLookupOptions.asyncTimeout).isEqualTo(ExecutionConfigOptions.TABLE_EXEC_ASYNC_LOOKUP_TIMEOUT.defaultValue().toMillis());
    assertThat(asyncLookupOptions.asyncBufferCapacity).isEqualTo(1000);
    asyncLookupOptions = LookupJoinUtil.getMergedAsyncOptions(RelHint.builder(JoinStrategy.LOOKUP.getJoinHintName()).hintOptions(kvOptions).build(), userConf, ChangelogMode.all());
    assertThat(asyncLookupOptions.asyncOutputMode).isSameAs(AsyncDataStream.OutputMode.ORDERED);
}

