@Test
void testSerde() throws IOException {
    SerdeContext serdeCtx = JsonSerdeTestUtil.configuredSerdeContext();
    ObjectReader objectReader = CompiledPlanSerdeUtil.createJsonObjectReader(serdeCtx);
    ObjectWriter objectWriter = CompiledPlanSerdeUtil.createJsonObjectWriter(serdeCtx);
    assertThat(objectReader.readValue(objectWriter.writeValueAsString(RexWindowBounds.CURRENT_ROW), RexWindowBound.class)).isEqualTo(RexWindowBounds.CURRENT_ROW);
    assertThat(objectReader.readValue(objectWriter.writeValueAsString(RexWindowBounds.UNBOUNDED_FOLLOWING), RexWindowBound.class)).isEqualTo(RexWindowBounds.UNBOUNDED_FOLLOWING);
    assertThat(objectReader.readValue(objectWriter.writeValueAsString(RexWindowBounds.UNBOUNDED_PRECEDING), RexWindowBound.class)).isEqualTo(RexWindowBounds.UNBOUNDED_PRECEDING);
    RexBuilder builder = new RexBuilder(serdeCtx.getTypeFactory());
    RexWindowBound windowBound = RexWindowBounds.following(builder.makeLiteral("test"));
    assertThat(objectReader.readValue(objectWriter.writeValueAsString(windowBound), RexWindowBound.class)).isEqualTo(windowBound);
    windowBound = RexWindowBounds.preceding(builder.makeLiteral("test"));
    assertThat(objectReader.readValue(objectWriter.writeValueAsString(windowBound), RexWindowBound.class)).isEqualTo(windowBound);
}

