@ParameterizedTest
@MethodSource("createSpecs")
@Order(1)
void testRestore(TableTestProgram program, Path planPath, String savepointPath) throws Exception {
    final EnvironmentSettings settings = EnvironmentSettings.inStreamingMode();
    final SavepointRestoreSettings restoreSettings;
    if (afterRestoreSource == AfterRestoreSource.NO_RESTORE) {
        restoreSettings = SavepointRestoreSettings.none();
    } else {
        restoreSettings = SavepointRestoreSettings.forPath(savepointPath, false, RecoveryClaimMode.NO_CLAIM);
    }
    SavepointRestoreSettings.toConfiguration(restoreSettings, settings.getConfiguration());
    settings.getConfiguration().set(StateBackendOptions.STATE_BACKEND, "rocksdb");
    final TableEnvironment tEnv = TableEnvironment.create(settings);
    tEnv.getConfig().set(TableConfigOptions.PLAN_RESTORE_CATALOG_OBJECTS, TableConfigOptions.CatalogPlanRestore.IDENTIFIER);
    program.getSetupConfigOptionTestSteps().forEach(s -> s.apply(tEnv));
    for (SourceTestStep sourceTestStep : program.getSetupSourceTestSteps()) {
        final Collection<Row> data = afterRestoreSource == AfterRestoreSource.NO_RESTORE ? sourceTestStep.dataBeforeRestore : sourceTestStep.dataAfterRestore;
        final String id = TestValuesTableFactory.registerData(data);
        final Map<String, String> options = new HashMap<>();
        options.put("connector", "values");
        options.put("data-id", id);
        options.put("runtime-source", "NewSource");
        if (afterRestoreSource == AfterRestoreSource.INFINITE) {
            options.put("terminating", "false");
        }
        sourceTestStep.apply(tEnv, options);
    }
    final List<CompletableFuture<?>> futures = new ArrayList<>();
    for (SinkTestStep sinkTestStep : program.getSetupSinkTestSteps()) {
        if (afterRestoreSource == AfterRestoreSource.INFINITE) {
            registerSinkObserver(futures, sinkTestStep, false);
        }
        final Map<String, String> options = new HashMap<>();
        options.put("connector", "values");
        options.put("disable-lookup", "true");
        options.put("sink-insert-only", "false");
        sinkTestStep.apply(tEnv, options);
    }
    program.getSetupFunctionTestSteps().forEach(s -> s.apply(tEnv));
    program.getSetupTemporalFunctionTestSteps().forEach(s -> s.apply(tEnv));
    final byte[] compiledPlanAsSmileBytes = tEnv.loadPlan(PlanReference.fromFile(planPath)).asSmileBytes();
    final CompiledPlan compiledPlan = tEnv.loadPlan(PlanReference.fromSmileBytes(compiledPlanAsSmileBytes));
    if (afterRestoreSource == AfterRestoreSource.INFINITE) {
        final TableResult tableResult = compiledPlan.execute();
        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).get();
        tableResult.getJobClient().get().cancel().get();
    } else {
        compiledPlan.execute().await();
        for (SinkTestStep sinkTestStep : program.getSetupSinkTestSteps()) {
            List<String> expectedResults = getExpectedResults(sinkTestStep, sinkTestStep.name);
            assertThat(expectedResults).containsExactlyInAnyOrder(Stream.concat(sinkTestStep.getExpectedBeforeRestoreAsStrings().stream(), sinkTestStep.getExpectedAfterRestoreAsStrings().stream()).toArray(String[]::new));
        }
    }
}

@Test
public void testMissingRestoreTest() throws IOException, NoSuchMethodException, InstantiationException, IllegalAccessException, InvocationTargetException {
    Map<ExecNodeNameVersion, Class<? extends ExecNode<?>>> versionedExecNodes = ExecNodeMetadataUtil.getVersionedExecNodes();
    Set<ClassPath.ClassInfo> classesInPackage = ClassPath.from(this.getClass().getClassLoader()).getTopLevelClassesRecursive("org.apache.flink.table.planner.plan.nodes.exec.stream").stream().filter(x -> RestoreTestBase.class.isAssignableFrom(x.load())).collect(Collectors.toSet());
    Set<Class<? extends ExecNode<?>>> execNodesWithRestoreTests = new HashSet<>();
    for (ClassPath.ClassInfo classInfo : classesInPackage) {
        Class<?> restoreTest = classInfo.load();
        Class<? extends ExecNode<?>> execNode = getExecNode(restoreTest);
        execNodesWithRestoreTests.add(execNode);
        List<Class<? extends ExecNode<?>>> childExecNodes = getChildExecNodes(restoreTest);
        for (Class<? extends ExecNode<?>> childExecNode : childExecNodes) {
            execNodesWithRestoreTests.add(childExecNode);
        }
    }
    for (Map.Entry<ExecNodeNameVersion, Class<? extends ExecNode<?>>> entry : versionedExecNodes.entrySet()) {
        ExecNodeNameVersion execNodeNameVersion = entry.getKey();
        Class<? extends ExecNode<?>> execNode = entry.getValue();
        if (!SKIP_EXEC_NODES.contains(execNode)) {
            final String msg = "Missing restore test for " + execNodeNameVersion + "\nPlease add a restore test for " + execNode.toString();
            Assertions.assertTrue(execNodesWithRestoreTests.contains(execNode), msg);
        }
    }
}

