@Test
void testLargeQueryPlanShouldNotOutOfMemoryWithTableApi() {
    // TABLE_OPTIMIZER_DYNAMIC_FILTERING_ENABLED is already enabled
    List<String> selectStmts = new ArrayList<>();
    for (int i = 0; i < 100; i++) {
        util.tableEnv().executeSql("CREATE TABLE IF NOT EXISTS table" + i + "(att STRING,filename STRING) " + "with(" + "     'connector' = 'values', " + "     'runtime-source' = 'NewSource', " + "     'bounded' = 'true'" + ")");
        selectStmts.add("select att,filename from table" + i);
    }
    final String countName = "CNM";
    Table allUnionTable = util.tableEnv().sqlQuery(String.join(" UNION ALL ", selectStmts));
    Table res = allUnionTable.join(allUnionTable.groupBy(col("att")).select(col("att"), col("att").count().as(countName)).filter(col(countName).isGreater(1)).select(col("att").as("l_key")), col("att").isEqual(col("l_key")));
    util.verifyExecPlan(res);
    // clear resources
    for (int i = 0; i < 100; i++) {
        util.tableEnv().executeSql("DROP TABLE IF EXISTS table" + i);
    }
}

@Test
void testLargeQueryPlanShouldNotOutOfMemoryWithSqlApi() {
    // TABLE_OPTIMIZER_DYNAMIC_FILTERING_ENABLED is already enabled
    List<String> selectStmts = new ArrayList<>();
    for (int i = 0; i < 100; i++) {
        util.tableEnv().executeSql("CREATE TABLE IF NOT EXISTS table" + i + "(att STRING,filename STRING) " + "with(" + "     'connector' = 'values', " + "     'runtime-source' = 'NewSource', " + "     'bounded' = 'true'" + ")");
        selectStmts.add("select att,filename from table" + i);
    }
    final String countName = "CNM";
    final String unionSelectStmts = String.join(" UNION ALL ", selectStmts);
    final String groupedUnionStmt = String.format("SELECT att as l_key, COUNT(att) AS %s " + "FROM (%s) " + "GROUP BY att " + "HAVING COUNT(att) > 1 ", countName, unionSelectStmts);
    final String joinedUnionStmt = String.format("SELECT * FROM (%s) as t1 INNER JOIN (%s) as t2 ON t1.att = t2.l_key", unionSelectStmts, groupedUnionStmt);
    Table resultTable = util.tableEnv().sqlQuery(joinedUnionStmt);
    util.verifyExecPlan(resultTable);
    // clear resources
    for (int i = 0; i < 100; i++) {
        util.tableEnv().executeSql("DROP TABLE IF EXISTS table" + i);
    }
}

