@Test
void testTypeInferenceWithNestedTypes() {
    util.tableEnv().executeSql("CREATE TABLE t1 (" + "  `mapWithStrings` MAP<STRING, STRING>," + "  `mapWithBytes` MAP<STRING, BYTES>" + ") WITH (" + "   'connector' = 'values'" + ")");
    // As https://issues.apache.org/jira/browse/CALCITE-4603 says
    // before Calcite 1.27.0 it derived the type of nested collection based on the last element,
    // thus the type of the last element is narrower than the type of element in the middle
    util.verifyExecPlanInsert("INSERT INTO t1 VALUES " + "(MAP['a', '123', 'b', '123456'], MAP['k1', X'C0FFEE', 'k2', X'BABE']), " + "(CAST(NULL AS MAP<STRING, STRING>), CAST(NULL AS MAP<STRING, BYTES>)), " + "(MAP['a', '1', 'b', '1'], MAP['k1', X'10', 'k2', X'20'])");
}

