@Test
void testMultipleAnnotations() {
    // Using MultipleExecNodeMetadata annotation
    ExecNodeMetadataUtil.addTestNode(DummyNode.class);
    assertThat(ExecNodeMetadataUtil.retrieveExecNode("dummy-node", 1)).isSameAs(DummyNode.class);
    assertThat(ExecNodeMetadataUtil.retrieveExecNode("dummy-node", 2)).isSameAs(DummyNode.class);
    assertThat(ExecNodeMetadataUtil.retrieveExecNode("dummy-node", 3)).isSameAs(DummyNode.class);
    assertThat(ExecNodeMetadataUtil.latestAnnotation(DummyNode.class)).has(new Condition<>(m -> m.version() == 3, "version")).has(new Condition<>(m -> m.minPlanVersion() == FlinkVersion.v1_15, "minPlanVersion")).has(new Condition<>(m -> m.minPlanVersion() == FlinkVersion.v1_15, "minStateVersion"));
    Configuration config = new Configuration();
    config.set(OPTION_1, 1);
    config.set(OPTION_2, 2);
    config.set(OPTION_3, 3);
    config.set(OPTION_4, 4);
    config.set(OPTION_5, 5);
    config.set(OPTION_6, 6);
    ReadableConfig persistedConfig = ExecNodeMetadataUtil.newPersistedConfig(DummyNode.class, config, Stream.of(OPTION_1, OPTION_2, OPTION_3, OPTION_4, OPTION_5, OPTION_6));
    assertThat(persistedConfig.get(OPTION_1)).isEqualTo(1);
    assertThat(persistedConfig.get(OPTION_2)).isEqualTo(OPTION_2.defaultValue());
    assertThat(persistedConfig.get(OPTION_3)).isEqualTo(3);
    assertThat(persistedConfig.get(OPTION_4)).isEqualTo(4);
    assertThat(persistedConfig.get(OPTION_5)).isEqualTo(5);
    assertThat(persistedConfig.get(OPTION_6)).isEqualTo(OPTION_6.defaultValue());
    // Using multiple individual ExecNodeMetadata annotations
    ExecNodeMetadataUtil.addTestNode(DummyNodeMultipleAnnotations.class);
    assertThat(ExecNodeMetadataUtil.retrieveExecNode("dummy-node-multiple-annotations", 1)).isSameAs(DummyNodeMultipleAnnotations.class);
    assertThat(ExecNodeMetadataUtil.retrieveExecNode("dummy-node-multiple-annotations", 2)).isSameAs(DummyNodeMultipleAnnotations.class);
    assertThat(ExecNodeMetadataUtil.retrieveExecNode("dummy-node-multiple-annotations", 3)).isSameAs(DummyNodeMultipleAnnotations.class);
    assertThat(ExecNodeMetadataUtil.latestAnnotation(DummyNodeMultipleAnnotations.class)).has(new Condition<>(m -> m.version() == 3, "version")).has(new Condition<>(m -> m.minPlanVersion() == FlinkVersion.v1_15, "minPlanVersion")).has(new Condition<>(m -> m.minPlanVersion() == FlinkVersion.v1_15, "minStateVersion"));
    assertThatThrownBy(() -> ExecNodeContext.newPersistedConfig(DummyNodeMultipleAnnotations.class, config)).isInstanceOf(IllegalStateException.class).hasMessage("ExecNode: org.apache.flink.table.planner.plan.utils." + "ExecNodeMetadataUtilTest.DummyNodeMultipleAnnotations, " + "consumedOption: option111 not listed in [TableConfigOptions, " + "ExecutionConfigOptions].");
}

