@Test
void testStreamExecNodeJsonSerdeCoverage() {
    Set<Class<? extends ExecNode<?>>> subClasses = ExecNodeMetadataUtil.execNodes();
    List<Class<? extends ExecNode<?>>> classesWithoutJsonCreator = new ArrayList<>();
    List<Class<? extends ExecNode<?>>> classesWithJsonCreatorInUnsupportedList = new ArrayList<>();
    for (Class<? extends ExecNode<?>> clazz : subClasses) {
        boolean hasJsonCreator = ExecNodeMetadataUtil.hasJsonCreatorAnnotation(clazz);
        if (hasJsonCreator && UNSUPPORTED_JSON_SERDE_CLASSES.contains(clazz)) {
            classesWithJsonCreatorInUnsupportedList.add(clazz);
        }
        if (!hasJsonCreator && !UNSUPPORTED_JSON_SERDE_CLASSES.contains(clazz)) {
            classesWithoutJsonCreator.add(clazz);
        }
    }
    assertThat(classesWithoutJsonCreator).as("%s do not support json serialization/deserialization, " + "please refer the implementation of the other StreamExecNodes.", classesWithoutJsonCreator.stream().map(Class::getSimpleName).collect(Collectors.joining(","))).isEmpty();
    assertThat(classesWithJsonCreatorInUnsupportedList).as("%s have support for json serialization/deserialization, " + "but still in UNSUPPORTED_JSON_SERDE_CLASSES list. " + "please move them from UNSUPPORTED_JSON_SERDE_CLASSES.", classesWithJsonCreatorInUnsupportedList.stream().map(Class::getSimpleName).collect(Collectors.joining(","))).isEmpty();
}

@Test
void testSmallestKey() {
    assertThat(UpsertKeyUtil.getSmallestKey(null)).isEqualTo(emptyKey);
    assertThat(UpsertKeyUtil.getSmallestKey(new HashSet<>())).isEqualTo(emptyKey);
    ImmutableBitSet smallestKey = ImmutableBitSet.of(0, 1);
    ImmutableBitSet middleKey = ImmutableBitSet.of(0, 2);
    ImmutableBitSet longKey = ImmutableBitSet.of(0, 1, 2);
    Set<ImmutableBitSet> upsertKeys = new HashSet<>();
    upsertKeys.add(smallestKey);
    upsertKeys.add(middleKey);
    assertThat(UpsertKeyUtil.getSmallestKey(upsertKeys)).isEqualTo(smallestKey.toArray());
    upsertKeys.clear();
    upsertKeys.add(smallestKey);
    upsertKeys.add(longKey);
    assertThat(UpsertKeyUtil.getSmallestKey(upsertKeys)).isEqualTo(smallestKey.toArray());
}

@Test
void testParallelismSettingAfterSingletonShuffleRemove() {
    util.getTableEnv().executeSql("CREATE TABLE MySink (\n" + "  b bigint\n" + ") with (\n" + "  'connector' = 'values',\n" + "  'sink-insert-only' = 'false',\n" + "  'table-sink-class' = 'DEFAULT')");
    // the exec plan:
    // Sink(table=[default_catalog.default_database.MySink], fields=[EXPR$0])
    // +- HashAggregate(isMerge=[false], select=[MAX(b) AS EXPR$0])
    //   +- HashAggregate(isMerge=[true], select=[Final_SUM(sum$0) AS b])
    //      +- Exchange(distribution=[single])
    //         +- LocalHashAggregate(select=[Partial_SUM(b) AS sum$0])
    //            +- TableSourceScan(table=[[MyTable, project=[b])
    Transformation<?> sink = generateTransformation("INSERT INTO MySink SELECT MAX(b) FROM (SELECT SUM(b) AS b FROM MyTable)");
    Transformation<?> topAgg = sink.getInputs().get(0);
    assertThat(topAgg.getParallelism()).isEqualTo(1);
    assertThat(topAgg.getMaxParallelism()).isEqualTo(1);
    Transformation<?> bottomAgg = topAgg.getInputs().get(0);
    assertThat(bottomAgg.getParallelism()).isEqualTo(1);
    assertThat(bottomAgg.getMaxParallelism()).isEqualTo(1);
}

