    // orderBy=[a ASC, c ASC], global=[false], select=[a, b, c])
    //                +- Sort(orderBy=[a ASC, c ASC])
    //                   +- TableSourceScan(table=[[default_catalog, default_database,
    // MyTable]], fields=[a, b, c])
    Transformation<?> sink = generateTransformation("INSERT INTO MySink SELECT * FROM " + "(SELECT a, b, RANK() OVER (ORDER BY a, c) rk FROM MyTable) t " + "WHERE rk = 2");
    Transformation<?> calc = sink.getInputs().get(0);
