    tEnv().createTemporaryTable("T", TableFactoryHarness.newBuilder().schema(Schema.newBuilder().build()).source(new TableFactoryHarness.ScanSourceBase() {

        @Override
        public ScanRuntimeProvider getScanRuntimeProvider(ScanContext runtimeProviderContext) {
            throw new UnsupportedOperationException("Discovered factory should not be used");
        }
    }).build());
    final Table table = tEnv().from("T");
