@Test
void testCreateTemporaryCatalogFunction() {
    String ddl1 = "create temporary function default_catalog.default_database.f4" + " as '" + TEST_FUNCTION + "'";
    String ddl2 = "create temporary function if not exists default_catalog.default_database.f4" + " as '" + TEST_FUNCTION + "'";
    String ddl3 = "drop temporary function default_catalog.default_database.f4";
    String ddl4 = "drop temporary function if exists default_catalog.default_database.f4";
    tEnv().executeSql(ddl1);
    assertThat(Arrays.asList(tEnv().listFunctions())).contains("f4");
    tEnv().executeSql(ddl2);
    assertThat(Arrays.asList(tEnv().listFunctions())).contains("f4");
    tEnv().executeSql(ddl3);
    assertThat(Arrays.asList(tEnv().listFunctions())).doesNotContain("f4");
    tEnv().executeSql(ddl1);
    assertThatThrownBy(() -> tEnv().executeSql(ddl1)).isInstanceOf(ValidationException.class).hasMessage("Could not register temporary catalog function. A function 'default_catalog.default_database.f4' does already exist.");
    tEnv().executeSql(ddl3);
    tEnv().executeSql(ddl4);
    assertThatThrownBy(() -> tEnv().executeSql(ddl3)).isInstanceOf(ValidationException.class).hasMessage("Temporary catalog function `default_catalog`.`default_database`.`f4`" + " doesn't exist");
}

