@Test
void testComplexScalarFunction() throws Exception {
    final List<Row> sourceData = Arrays.asList(Row.of(1, new byte[] { 1, 2, 3 }), Row.of(2, new byte[] { 2, 3, 4 }), Row.of(3, new byte[] { 3, 4, 5 }), Row.of(null, null));
    final List<Row> sinkData = Arrays.asList(Row.of(1, "1+2012-12-12 12:12:12.123456789", "[1, 2, 3]+2012-12-12 12:12:12.123456789", new BigDecimal("123.40"), ByteBuffer.wrap(new byte[] { 1, 2, 3 })), Row.of(2, "2+2012-12-12 12:12:12.123456789", "[2, 3, 4]+2012-12-12 12:12:12.123456789", new BigDecimal("123.40"), ByteBuffer.wrap(new byte[] { 2, 3, 4 })), Row.of(3, "3+2012-12-12 12:12:12.123456789", "[3, 4, 5]+2012-12-12 12:12:12.123456789", new BigDecimal("123.40"), ByteBuffer.wrap(new byte[] { 3, 4, 5 })), Row.of(null, "null+2012-12-12 12:12:12.123456789", "null+2012-12-12 12:12:12.123456789", new BigDecimal("123.40"), null));
    TestCollectionTableFactory.reset();
    TestCollectionTableFactory.initData(sourceData);
    final RawType<Object> rawType = new RawType<>(Object.class, new KryoSerializer<>(Object.class, new SerializerConfigImpl()));
    tEnv().executeSql("CREATE TABLE SourceTable(i INT, b BYTES) " + "WITH ('connector' = 'COLLECTION')");
    tEnv().executeSql("CREATE TABLE SinkTable(" + "  i INT, " + "  s1 STRING, " + "  s2 STRING, " + "  d DECIMAL(5, 2)," + "  r " + rawType.asSerializableString() + ") " + "WITH ('connector' = 'COLLECTION')");
    tEnv().createTemporarySystemFunction("ComplexScalarFunction", ComplexScalarFunction.class);
    tEnv().executeSql("INSERT INTO SinkTable " + "SELECT " + "  i, " + "  ComplexScalarFunction(i, TIMESTAMP '2012-12-12 12:12:12.123456789'), " + "  ComplexScalarFunction(b, TIMESTAMP '2012-12-12 12:12:12.123456789')," + "  ComplexScalarFunction(), " + "  ComplexScalarFunction(b) " + "FROM SourceTable").await();
    assertThat(TestCollectionTableFactory.getResult()).isEqualTo(sinkData);
}

