@Test
void testCallProcedure() {
    // test call procedure can run a flink job
    TableResult tableResult = tEnv().executeSql("call `system`.generate_n(4)");
    verifyTableResult(tableResult, Arrays.asList(Row.of(0), Row.of(1), Row.of(2), Row.of(3)), ResolvedSchema.of(Column.physical("result", DataTypes.BIGINT().notNull().bridgedTo(long.class))));
    // call a procedure which will run in batch mode
    tableResult = tEnv().executeSql("call `system`.generate_n(4, 'BATCH')");
    verifyTableResult(tableResult, Arrays.asList(Row.of(0), Row.of(1), Row.of(2), Row.of(3)), ResolvedSchema.of(Column.physical("result", DataTypes.BIGINT().notNull().bridgedTo(long.class))));
    // check the runtime mode in current env is still streaming
    assertThat(tEnv().getConfig().get(ExecutionOptions.RUNTIME_MODE)).isEqualTo(RuntimeExecutionMode.STREAMING);
    // test call procedure with var-args as well as output data type hint
    tableResult = tEnv().executeSql("call `system`.sum_n(5.5, 1.2, 3.3)");
    verifyTableResult(tableResult, Collections.singletonList(Row.of("10.00", 3)), ResolvedSchema.of(Column.physical("sum_value", DataTypes.DECIMAL(10, 2)), Column.physical("count", DataTypes.INT())));
    // test call procedure with timestamp as input
    tableResult = tEnv().executeSql("call `system`.get_year(timestamp '2023-04-22 00:00:00', timestamp '2024-04-22 00:00:00.300')");
    verifyTableResult(tableResult, Arrays.asList(Row.of(2023), Row.of(2024)), ResolvedSchema.of(Column.physical("result", DataTypes.STRING())));
    // test call procedure with pojo as return type
    tableResult = tEnv().executeSql("call `system`.generate_user('yuxia', 18)");
    verifyTableResult(tableResult, Collections.singletonList(Row.of("yuxia", 18)), ResolvedSchema.of(Column.physical("name", DataTypes.STRING()), Column.physical("age", DataTypes.INT().notNull().bridgedTo(int.class))));
}

