@Test
void testBatchStreamExchangeMode() {
    final Configuration configuration = new Configuration();
    assertThat(getBatchStreamExchangeMode(configuration, null)).isEqualTo(StreamExchangeMode.BATCH);
    configuration.set(ExecutionOptions.BATCH_SHUFFLE_MODE, BatchShuffleMode.ALL_EXCHANGES_BLOCKING);
    assertThat(getBatchStreamExchangeMode(configuration, null)).isEqualTo(StreamExchangeMode.BATCH);
    configuration.set(ExecutionOptions.BATCH_SHUFFLE_MODE, BatchShuffleMode.ALL_EXCHANGES_HYBRID_FULL);
    assertThat(getBatchStreamExchangeMode(configuration, null)).isEqualTo(StreamExchangeMode.HYBRID_FULL);
    configuration.set(ExecutionOptions.BATCH_SHUFFLE_MODE, BatchShuffleMode.ALL_EXCHANGES_HYBRID_SELECTIVE);
    assertThat(getBatchStreamExchangeMode(configuration, null)).isEqualTo(StreamExchangeMode.HYBRID_SELECTIVE);
    configuration.set(ExecutionOptions.BATCH_SHUFFLE_MODE, BatchShuffleMode.ALL_EXCHANGES_PIPELINED);
    assertThat(getBatchStreamExchangeMode(configuration, null)).isEqualTo(StreamExchangeMode.UNDEFINED);
    configuration.set(ExecutionOptions.BATCH_SHUFFLE_MODE, BatchShuffleMode.ALL_EXCHANGES_PIPELINED);
    assertThat(getBatchStreamExchangeMode(configuration, StreamExchangeMode.BATCH)).isEqualTo(StreamExchangeMode.BATCH);
}

