@Test
void testInputSideHasNoUniqueKey() throws Exception {
    // +--------------------------+----------------------------+----------------------------+
    // |   Before the last        |       Last record          |          Result            |
    // |--------------------------|----------------------------|----------------------------|
    // |    -U/-D                 |        +U/+I               |       Clear both           |
    // |--------------------------|----------------------------|----------------------------|
    // |    +I/+U                 |        -U/-D               |       Clear both           |
    // +--------------------------+----------------------------+----------------------------+
    buffer = new InputSideHasNoUniqueKeyBundle();
    List<RowData> records = Stream.of(deleteRecord("Ord#9", "LineOrd#9", // z
    "11 Bellevue Drive, Pottstown, PI 19464"), insertRecord("Ord#1", "LineOrd#2", // xx
    "4 Bellevue Drive, Pottstown, PB 19464"), updateBeforeRecord("Ord#90", "LineOrd#90", // yyyy
    "110 Bellevue Drive, Pottstown, PI 19464"), insertRecord("Ord#3", "LineOrd#3", // x
    "5 Bellevue Drive, Pottstown, PD 19464"), updateBeforeRecord("Ord#9", "LineOrd#9", // y
    "11 Bellevue Drive, Pottstown, PI 19464"), updateAfterRecord("Ord#3", "LineOrd#1", // s
    "3 Bellevue Drive, Pottstown, PA 19464"), updateAfterRecord("Ord#10", "LineOrd#10", // zz
    "14 Bellevue Drive, Pottstown, PJ 19464"), insertRecord("Ord#9", "LineOrd#9", // y  -U +I
    "11 Bellevue Drive, Pottstown, PI 19464"), deleteRecord("Ord#1", "LineOrd#2", // xx   +I -D
    "4 Bellevue Drive, Pottstown, PB 19464"), updateAfterRecord("Ord#90", "LineOrd#90", // yyyy  -U +U
    "110 Bellevue Drive, Pottstown, PI 19464"), updateBeforeRecord("Ord#3", "LineOrd#3", // x  +I -U
    "5 Bellevue Drive, Pottstown, PD 19464"), deleteRecord("Ord#3", "LineOrd#1", // s +U -D
    "3 Bellevue Drive, Pottstown, PA 19464"), deleteRecord("Ord#6", "LineOrd#6", // yy
    "8 Bellevue Drive, Pottstown, PF 19464"), updateBeforeRecord("Ord#10", "LineOrd#10", // zz +U -U
    "14 Bellevue Drive, Pottstown, PJ 19464"), insertRecord("Ord#6", "LineOrd#6", // yy   -D +I
    "8 Bellevue Drive, Pottstown, PF 19464"), updateAfterRecord("Ord#9", "LineOrd#9", // z -D +U
    "11 Bellevue Drive, Pottstown, PI 19464")).map(StreamRecord::getValue).collect(Collectors.toList());
    addRecordsToBuffer(records);
    assertRecords(Collections.emptyList(), records.size());
}

