    testHarness.processElement1(deleteRecord("Ord#3", "LineOrd#x3", // left -D
    "x5 Bellevue Drive, Pottstown, PCxx 19464"));
    testHarness.processElement1(insertRecord("Ord#3", "LineOrd#x3", // left +I
    "x5 Bellevue Drive, Pottstown, PCxx 19464"));
    testHarness.processElement1(insertRecord("Ord#10", "LineOrd#100y", // left +I
    "14y0 Bellevue Drive, Pottstown, PJyy 19464"));
