@Test
void testLeftSemiJoinWithDifferentStateRetentionTime() throws Exception {
    testHarness.setStateTtlProcessingTime(1);
    testHarness.processElement1(insertRecord("Ord#1", "LineOrd#1", "3 Bellevue Drive, Pottstown, PA 19464"));
    assertor.shouldEmitNothing(testHarness);
    testHarness.processElement1(insertRecord("Ord#1", "LineOrd#2", "3 Bellevue Drive, Pottstown, PA 19464"));
    assertor.shouldEmitNothing(testHarness);
    testHarness.setStateTtlProcessingTime(3001);
