    unionWrapper.addInput(calcWrapper1, 1);
    unionWrapper.addInput(calcWrapper2, 2);
    TableOperatorWrapper<?> outputWrapper = createWrapper(join, 0, 1.0 / 3);
    outputWrapper.addInput(unionWrapper, 2);
    assertThat(generator.getInputTransformAndInputSpecPairs()).isEqualTo(Arrays.asList(Pair.of(source1, new InputSpec(1, 1, calcWrapper1, 1)), Pair.of(source2, new InputSpec(2, 1, calcWrapper2, 1)), Pair.of(source3, new InputSpec(3, 0, outputWrapper, 2))));
    assertThat(unionWrapper.getInputEdges()).isEqualTo(Arrays.asList(new TableOperatorWrapper.Edge(calcWrapper1, unionWrapper, 1), new TableOperatorWrapper.Edge(calcWrapper2, unionWrapper, 2)));
