@Test
void testWindowAssignment() {
    SlidingWindowAssigner assigner = SlidingWindowAssigner.of(Duration.ofMillis(5000), Duration.ofMillis(1000));
    assertThat(assigner.assignWindows(ELEMENT, 0L)).containsExactlyInAnyOrder(new TimeWindow(-4000, 1000), new TimeWindow(-3000, 2000), new TimeWindow(-2000, 3000), new TimeWindow(-1000, 4000), new TimeWindow(0, 5000));
    assertThat(assigner.assignWindows(ELEMENT, 4999L)).containsExactlyInAnyOrder(new TimeWindow(0, 5000), new TimeWindow(1000, 6000), new TimeWindow(2000, 7000), new TimeWindow(3000, 8000), new TimeWindow(4000, 9000));
    assertThat(assigner.assignWindows(ELEMENT, 5000L)).containsExactlyInAnyOrder(new TimeWindow(1000, 6000), new TimeWindow(2000, 7000), new TimeWindow(3000, 8000), new TimeWindow(4000, 9000), new TimeWindow(5000, 10000));
    // test pane
    assertThat(new TimeWindow(0, 1000)).isEqualTo(assigner.assignPane(ELEMENT, 0L));
    assertThat(new TimeWindow(4000, 5000)).isEqualTo(assigner.assignPane(ELEMENT, 4999L));
    assertThat(new TimeWindow(5000, 6000)).isEqualTo(assigner.assignPane(ELEMENT, 5000L));
    assertThat(assigner.splitIntoPanes(new TimeWindow(0, 5000))).contains(new TimeWindow(0, 1000), new TimeWindow(1000, 2000), new TimeWindow(2000, 3000), new TimeWindow(3000, 4000), new TimeWindow(4000, 5000));
    assertThat(assigner.splitIntoPanes(new TimeWindow(3000, 8000))).contains(new TimeWindow(3000, 4000), new TimeWindow(4000, 5000), new TimeWindow(5000, 6000), new TimeWindow(6000, 7000), new TimeWindow(7000, 8000));
    assertThat(new TimeWindow(4000, 9000)).isEqualTo(assigner.getLastWindow(new TimeWindow(4000, 5000)));
    assertThat(new TimeWindow(2000, 7000)).isEqualTo(assigner.getLastWindow(new TimeWindow(2000, 3000)));
}

