@Test
@Timeout(30)
void testSnapshot() throws Exception {
    ValidatingSourceOutput output = new ValidatingSourceOutput();
    // Add a split to start the fetcher.
    List<SplitT> splits = getSplits(numSplits, NUM_RECORDS_PER_SPLIT, Boundedness.CONTINUOUS_UNBOUNDED);
    try (SourceReader<Integer, SplitT> reader = consumeRecords(splits, output, totalNumRecords)) {
