@ParameterizedTest(name = "Retrying with {0}")
@MethodSource("retryTestProvider")
void testRetryFailsWithExpectedExceptionAfterNumberOfRetries(final Throwable expectedException) {
    final int numberOfRetries = 1;
    RetryOnExceptionStrategy retryOnExceptionStrategy = new RetryOnExceptionStrategy(numberOfRetries, expectedException.getClass());
    // All attempts that permit a retry should be a TestAbortedException.  When retries are no
    // longer permitted, the handled exception should be propagated.
    for (int j = 0; j <= numberOfRetries; j++) {
        final int attemptIndex = j;
        assertThatThrownBy(() -> retryOnExceptionStrategy.handleException("Any test name", attemptIndex, expectedException)).isInstanceOf(j == numberOfRetries ? expectedException.getClass() : TestAbortedException.class);
    }
}

