@Test
void testWritingDocumentsInBatchMode(@TempDir File tempDir) throws Exception {
    TableEnvironment tEnv = TableEnvironment.create(EnvironmentSettings.inBatchMode());
    String format = "json";
    File outputFile = new File(tempDir, "records.out");
    String outputFilepath = outputFile.toString();
    final String createTable = String.format("CREATE TABLE UpsertFileSinkTable (\n" + "    user_id INT,\n" + "    user_name STRING,\n" + "    user_count BIGINT,\n" + "    PRIMARY KEY (user_id) NOT ENFORCED\n" + "  ) WITH (\n" + "    'connector' = '%s',\n" + "    'key.format' = '%s',\n" + "    'value.format' = '%s',\n" + "    'output-filepath' = '%s'\n" + "  );", UpsertTestDynamicTableSinkFactory.IDENTIFIER, format, format, outputFilepath);
    tEnv.executeSql(createTable);
    String insertSql = "INSERT INTO UpsertFileSinkTable\n" + "SELECT user_id, user_name, COUNT(*) AS user_count\n" + "FROM (VALUES (1, 'Bob'), (22, 'Tom'), (42, 'Kim'), (42, 'Kim'), (42, 'Kim'), (1, 'Bob'))\n" + "  AS UserCountTable(user_id, user_name)\n" + "GROUP BY user_id, user_name";
    tEnv.executeSql(insertSql).await();
    /*
        | user_id | user_name | user_count |
        | ------- | --------- | ---------- |
        |    1    |    Bob    |     2      |
        |   22    |    Tom    |     1      |
        |   42    |    Kim    |     3      |
        */
    int numberOfResultRecords = UpsertTestFileUtil.getNumberOfRecords(outputFile);
    assertThat(numberOfResultRecords).isEqualTo(3);
    DeserializationSchema<String> deserializationSchema = new SimpleStringSchema();
    Map<String, String> records = UpsertTestFileUtil.readRecords(outputFile, deserializationSchema, deserializationSchema);
    Map<String, String> expected = new HashMap<>();
    expected.put("{\"user_id\":1}", "{\"user_id\":1,\"user_name\":\"Bob\",\"user_count\":2}");
    expected.put("{\"user_id\":22}", "{\"user_id\":22,\"user_name\":\"Tom\",\"user_count\":1}");
    expected.put("{\"user_id\":42}", "{\"user_id\":42,\"user_name\":\"Kim\",\"user_count\":3}");
    assertThat(records).isEqualTo(expected);
}

