@Test
void testIsMetaspaceOutOfMemoryError(@TempDir File temporaryFolderForCompiledClasses) throws IOException, InterruptedException {
    final int classCount = 10;
    // compile the classes first
    final String sourcePattern = "public class %s { @Override public String toString() { return \"dummy\"; } }";
    final ClassLoaderBuilder classLoaderBuilder = ClassLoaderUtils.withRoot(temporaryFolderForCompiledClasses);
    for (int i = 0; i < classCount; i++) {
        final String dummyClassName = "DummyClass" + i;
        final String source = String.format(sourcePattern, dummyClassName);
        classLoaderBuilder.addClass(dummyClassName, source);
    }
    classLoaderBuilder.generateSourcesAndCompile();
    // load only one class and record required Metaspace
    final String className = DummyClassLoadingProgram.class.getName();
    final RunResult initialRun = run(className, -1, INITIAL_BIG_METASPACE_SIZE, 1, temporaryFolderForCompiledClasses.getAbsolutePath());
    // multiply the Metaspace size to stabilize the test - relying solely on the Metaspace size
    // of the initial run might cause OOMs to appear in the main thread (due to JVM-specific
    // artifacts being loaded)
    long okMetaspace = 3 * Long.parseLong(initialRun.getStandardOut());
    assertThat(initialRun.getErrorOut()).as("No error is expected.").isEmpty();
    // load more classes to cause 'OutOfMemoryError: Metaspace'
    final RunResult outOfMemoryErrorRun = run(className, -1, okMetaspace, classCount, temporaryFolderForCompiledClasses.getAbsolutePath());
    assertThat(outOfMemoryErrorRun.getStandardOut()).as("OutOfMemoryError: Metaspace errors are caught and don't generate any output.").isEmpty();
    assertThat(outOfMemoryErrorRun.getErrorOut()).as("Nothing should have been printed to stderr.").isEmpty();
}

