@Test
public void testNonMaterialization() throws Exception {
    File checkpointFolder = TEMPORARY_FOLDER.newFolder();
    SharedReference<JobID> jobID = sharedObjects.add(generateJobID());
    SharedReference<MiniCluster> miniCluster = sharedObjects.add(cluster.getMiniCluster());
    SharedReference<AtomicBoolean> hasMaterialization = sharedObjects.add(new AtomicBoolean(true));
    StreamExecutionEnvironment env = getEnv(checkpointFolder, 1000, 1, 10, 0);
    env.getConfig().enablePeriodicMaterialize(false);
    waitAndAssert(buildJobGraph(delegatedStateBackend, env, new ControlledSource() {

        @Override
        protected void beforeElement(SourceContext<Integer> ctx) throws Exception {
            if (getRuntimeContext().getTaskInfo().getAttemptNumber() == 0 && currentIndex == TOTAL_ELEMENTS / 2) {
                waitWhile(() -> completedCheckpointNum.get() <= 0);
                hasMaterialization.get().compareAndSet(true, !getAllStateHandleId(jobID.get(), miniCluster.get()).isEmpty());
                throwArtificialFailure();
            }
        }
    }, jobID.get()));
    Preconditions.checkState(!hasMaterialization.get().get());
}

/**
 * Recovery from checkpoint containing non-materialized state and materialized state.
 */
@Test
public void testMaterialization() throws Exception {
    File checkpointFolder = TEMPORARY_FOLDER.newFolder();
    SharedReference<JobID> jobID = sharedObjects.add(generateJobID());
    SharedReference<MiniCluster> miniCluster = sharedObjects.add(cluster.getMiniCluster());
    SharedReference<AtomicInteger> currentCheckpointNum = sharedObjects.add(new AtomicInteger());
    SharedReference<Set<StateHandleID>> currentMaterializationId = sharedObjects.add(ConcurrentHashMap.newKeySet());
    StreamExecutionEnvironment env = getEnv(checkpointFolder, 100, 2, 200, 0);
    waitAndAssert(buildJobGraph(delegatedStateBackend, env, new ControlledSource() {

        @Override
        protected void beforeElement(SourceContext<Integer> ctx) throws Exception {
            Preconditions.checkState(getRuntimeContext().getTaskInfo().getAttemptNumber() <= 2);
            if (getRuntimeContext().getTaskInfo().getAttemptNumber() == 0 && currentIndex == TOTAL_ELEMENTS / 4) {
                waitWhile(() -> {
                    if (completedCheckpointNum.get() <= 0) {
                        return true;
                    }
                    Set<StateHandleID> allMaterializationId = getAllStateHandleId(jobID.get(), miniCluster.get());
                    if (!allMaterializationId.isEmpty()) {
                        currentMaterializationId.get().addAll(allMaterializationId);
                        currentCheckpointNum.get().compareAndSet(0, completedCheckpointNum.get());
                        return false;
                    }
                    return true;
                });
                throwArtificialFailure();
            } else if (getRuntimeContext().getTaskInfo().getAttemptNumber() == 1 && currentIndex == TOTAL_ELEMENTS / 2) {
                waitWhile(() -> {
                    if (completedCheckpointNum.get() <= currentCheckpointNum.get().get()) {
                        return true;
                    }
                    Set<StateHandleID> allMaterializationId = getAllStateHandleId(jobID.get(), miniCluster.get());
                    return allMaterializationId.isEmpty() || currentMaterializationId.get().equals(allMaterializationId);
                });
                throwArtificialFailure();
            }
        }
    }, jobID.get()));
}

@Test
public void testFailedMaterialization() throws Exception {
    File checkpointFolder = TEMPORARY_FOLDER.newFolder();
    SharedReference<JobID> jobID = sharedObjects.add(generateJobID());
    SharedReference<MiniCluster> miniCluster = sharedObjects.add(cluster.getMiniCluster());
    SharedReference<AtomicBoolean> hasFailed = sharedObjects.add(new AtomicBoolean());
    SharedReference<Set<StateHandleID>> currentMaterializationId = sharedObjects.add(ConcurrentHashMap.newKeySet());
    StreamExecutionEnvironment env = getEnv(checkpointFolder, 100, 0, 10, 1);
    env.setParallelism(1);
    waitAndAssert(buildJobGraph(StateBackendTestUtils.wrapStateBackendWithSnapshotFunction(delegatedStateBackend, snapshotResultFuture -> {
        if (hasFailed.get().compareAndSet(false, true)) {
            return ExceptionallyDoneFuture.of(new RuntimeException());
        } else {
            return snapshotResultFuture;
        }
    }), env, new ControlledSource() {

        @Override
        protected void beforeElement(SourceContext<Integer> ctx) throws Exception {
            if (currentIndex == TOTAL_ELEMENTS / 8) {
                waitWhile(() -> !hasFailed.get().get());
            } else if (currentIndex == TOTAL_ELEMENTS / 4) {
                waitWhile(() -> {
                    Set<StateHandleID> allMaterializationId = getAllStateHandleId(jobID.get(), miniCluster.get());
                    if (!allMaterializationId.isEmpty()) {
                        currentMaterializationId.get().addAll(allMaterializationId);
                        return false;
                    }
                    return true;
                });
            } else if (currentIndex == TOTAL_ELEMENTS / 2) {
                waitWhile(() -> {
                    Set<StateHandleID> allMaterializationId = getAllStateHandleId(jobID.get(), miniCluster.get());
                    return allMaterializationId.isEmpty() || currentMaterializationId.get().equals(allMaterializationId);
                });
            }
        }
    }, jobID.get()));
}

