    DataStream<Long> source = env.fromSource(new NumberSequenceSourceWithWaitForCheckpoint(2, NUM_RECORDS - 1, NUM_SPLITS), WatermarkStrategy.noWatermarks(), "non-backlog-source");
    final DataStream<Long> stream = source.union(source2).transform("CheckpointRecordingOperator", Types.LONG, new CheckpointRecordingOperator<>());
    final List<Long> result = new ArrayList<>();
    try (CloseableIterator<Long> iterator = stream.executeAndCollect()) {
        while (iterator.hasNext()) {
            result.add(iterator.next());
        }
    }
    Collections.sort(result);
    assertThat(result).containsExactly(EXPECTED_RESULT.toArray(new Long[0]));
}

