@Test
public void testTumblingProcessingTimeWindow() {
    final int numElements = 3000;
    try {
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(PARALLELISM);
        env.getConfig().setAutoWatermarkInterval(10);
        env.enableCheckpointing(100);
        RestartStrategyUtils.configureFixedDelayRestartStrategy(env, 1, 0L);
        SinkValidatorUpdaterAndChecker updaterAndChecker = new SinkValidatorUpdaterAndChecker(numElements, 1);
        env.addSource(new FailingSource(new Generator(), numElements, true)).rebalance().keyBy(x -> x.f0).window(TumblingProcessingTimeWindows.of(Duration.ofMillis(100))).apply(new RichWindowFunction<Tuple2<Long, IntType>, Tuple2<Long, IntType>, Long, TimeWindow>() {

            private boolean open = false;

            @Override
            public void open(OpenContext openContext) {
                assertEquals(PARALLELISM, getRuntimeContext().getTaskInfo().getNumberOfParallelSubtasks());
                open = true;
            }

            @Override
            public void apply(Long l, TimeWindow window, Iterable<Tuple2<Long, IntType>> values, Collector<Tuple2<Long, IntType>> out) {
                // validate that the function has been opened properly
                assertTrue(open);
                for (Tuple2<Long, IntType> value : values) {
                    assertEquals(value.f0.intValue(), value.f1.value);
                    out.collect(new Tuple2<>(value.f0, new IntType(1)));
                }
            }
        }).addSink(new ValidatingSink<>(updaterAndChecker, updaterAndChecker, true)).setParallelism(1);
        tryExecute(env, "Tumbling Window Test");
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

