public void testJobStatusChangedForSucceededApplication() throws Exception {
    Configuration configuration = createConfiguration();
    try (StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment(configuration)) {
        List<String> sourceValues = Arrays.asList("a", "b", "c");
        List<String> resultValues = new ArrayList<>();
        try (CloseableIterator<String> iterator = env.fromCollection(sourceValues).executeAndCollect()) {
            while (iterator.hasNext()) {
                resultValues.add(iterator.next());
            }
        }
        assertThat(resultValues).containsExactlyInAnyOrder(sourceValues.toArray(new String[0]));
    }
    verifyEventMetaData();
    statusChangedEvents.forEach(event -> {
        if (event instanceof DefaultJobExecutionStatusEvent) {
            JobExecutionStatusEvent status = (JobExecutionStatusEvent) event;
            assertThat((status.oldStatus() == JobStatus.CREATED && status.newStatus() == JobStatus.RUNNING) || (status.oldStatus() == JobStatus.RUNNING && status.newStatus() == JobStatus.FINISHED)).isTrue();
        } else {
            DefaultJobCreatedEvent createdEvent = (DefaultJobCreatedEvent) event;
            assertThat(createdEvent.executionMode()).isEqualTo(RuntimeExecutionMode.STREAMING);
        }
    });
}

