        waitForAllTaskRunning(MINI_CLUSTER.getMiniCluster(), jobID, false);
        Thread.sleep(100);
        client.cancel(jobID).get();
        while (!client.getJobStatus(jobID).get().equals(JobStatus.CANCELED)) {
        }
    }
    verifyEventMetaData();
    statusChangedEvents.forEach(event -> {
        JobExecutionStatusEvent status = (JobExecutionStatusEvent) event;
        assertThat((status.oldStatus() == JobStatus.CREATED && status.newStatus() == JobStatus.RUNNING) || (status.oldStatus() == JobStatus.RUNNING && status.newStatus() == JobStatus.CANCELLING) || (status.oldStatus() == JobStatus.CANCELLING && status.newStatus() == JobStatus.CANCELED)).isTrue();
