            LineageGraph lineageGraph = ((JobCreatedEvent) event).lineageGraph();
            assertThat(lineageGraph.sources().size()).isEqualTo(1);
            assertThat(lineageGraph.sinks().size()).isEqualTo(1);
        }
    });
}

