public void testGlobalReduce() throws Exception {
    final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
    env.setRuntimeMode(RuntimeExecutionMode.BATCH);
    if (objectReuse) {
        env.getConfig().enableObjectReuse();
    } else {
        env.getConfig().disableObjectReuse();
    }
    DataStreamSource<Tuple2<String, Integer>> input = env.fromData(REDUCE_DATA);
    DataStream<Tuple2<String, Integer>> result = input.windowAll(GlobalWindows.createWithEndOfStreamTrigger()).reduce(new ReduceFunction<Tuple2<String, Integer>>() {

        @Override
        public Tuple2<String, Integer> reduce(Tuple2<String, Integer> value1, Tuple2<String, Integer> value2) {
            if (value1.f1 % 3 == 0) {
                value1.f1 += value2.f1;
                return value1;
            } else {
                value2.f1 += value1.f1;
                return value2;
            }
        }
    });
    Tuple2<String, Integer> res = result.executeAndCollect().next();
    assertEquals(new Tuple2<>("a", 60), res);
}

