void testRescaledJobGraphsWillBeRecoveredCorrectly(@TempDir Path tmpFolder) throws Exception {
    final Configuration configuration = new Configuration();
    final JobVertex jobVertex = new JobVertex("operator");
    jobVertex.setParallelism(1);
    jobVertex.setInvokableClass(BlockingNoOpInvokable.class);
    final JobGraph jobGraph = JobGraphTestUtils.streamingJobGraph(jobVertex);
    final JobID jobId = jobGraph.getJobID();
    // We need to have a restart strategy set, to prevent the job from failing during the first
    // cluster shutdown when TM disconnects.
    configuration.set(RestartStrategyOptions.RESTART_STRATEGY, FIXED_DELAY.getMainValue());
    configuration.set(RestartStrategyOptions.RESTART_STRATEGY_FIXED_DELAY_ATTEMPTS, Integer.MAX_VALUE);
    configuration.set(RestartStrategyOptions.RESTART_STRATEGY_FIXED_DELAY_DELAY, Duration.ofMillis(100));
    // The test is only supposed to pass with AdaptiveScheduler enabled.
    configuration.set(JobManagerOptions.SCHEDULER, JobManagerOptions.SchedulerType.Adaptive);
    // High-Availability settings.
    configuration.set(HighAvailabilityOptions.HA_MODE, "zookeeper");
    configuration.set(HighAvailabilityOptions.HA_ZOOKEEPER_QUORUM, ZOOKEEPER_EXTENSION.getCustomExtension().getConnectString());
    configuration.set(HighAvailabilityOptions.HA_STORAGE_PATH, tmpFolder.toFile().getAbsolutePath());
    final MiniClusterConfiguration miniClusterConfiguration = new MiniClusterConfiguration.Builder().setConfiguration(configuration).setNumSlotsPerTaskManager(2).build();
    final RestClusterClient<?> restClusterClient = new RestClusterClient<>(configuration, "foobar");
    final MiniCluster miniCluster = new MiniCluster(miniClusterConfiguration);
    miniCluster.start();
    assertThatFuture(restClusterClient.submitJob(jobGraph)).eventuallySucceeds();
    ClientUtils.waitUntilJobInitializationFinished(() -> restClusterClient.getJobStatus(jobId).get(), () -> restClusterClient.requestJobResult(jobId).get(), getClass().getClassLoader());
    assertThatFuture(restClusterClient.updateJobResourceRequirements(jobGraph.getJobID(), JobResourceRequirements.newBuilder().setParallelismForJobVertex(jobVertex.getID(), 1, 2).build())).eventuallySucceeds();
    assertThatFuture(miniCluster.closeAsyncWithoutCleaningHighAvailabilityData()).eventuallySucceeds();
    LOG.info("Start second mini cluster to recover the persisted job.");
    try (final MiniCluster recoveredMiniCluster = new MiniCluster(miniClusterConfiguration)) {
        recoveredMiniCluster.start();
        UpdateJobResourceRequirementsITCase.waitForRunningTasks(restClusterClient, jobId, 2);
    }
}

