void testAdaptiveOptimizeStreamGraph() throws Exception {
    final Configuration configuration = createConfiguration();
    configuration.set(StreamGraphOptimizationStrategy.STREAM_GRAPH_OPTIMIZATION_STRATEGY, List.of(TestingStreamGraphOptimizerStrategy.class.getName()));
    final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment(configuration);
    env.setRuntimeMode(RuntimeExecutionMode.BATCH);
    env.disableOperatorChaining();
    env.setParallelism(8);
    SingleOutputStreamOperator<Long> source1 = env.fromSequence(0, NUMBERS_TO_PRODUCE - 1).setParallelism(SOURCE_PARALLELISM_1).name("source1");
    SingleOutputStreamOperator<Long> source2 = env.fromSequence(0, NUMBERS_TO_PRODUCE - 1).setParallelism(SOURCE_PARALLELISM_2).name("source2");
    source1.keyBy(i -> i % SOURCE_PARALLELISM_1).map(i -> i).name("map1").rebalance().union(source2).rebalance().map(new NumberCounter()).name("map2").setParallelism(1);
    StreamGraph streamGraph = env.getStreamGraph();
    StreamNode sourceNode1 = streamGraph.getStreamNodes().stream().filter(node -> node.getOperatorName().contains("source1")).findFirst().get();
    StreamNode mapNode1 = streamGraph.getStreamNodes().stream().filter(node -> node.getOperatorName().contains("map1")).findFirst().get();
    TestingStreamGraphOptimizerStrategy.convertToRescaleEdgeIds.add(sourceNode1.getOutEdges().get(0).getEdgeId());
    TestingStreamGraphOptimizerStrategy.convertToBroadcastEdgeIds.add(mapNode1.getOutEdges().get(0).getEdgeId());
    env.execute(streamGraph);
    Map<Long, Long> numberCountResultMap = numberCountResults.stream().flatMap(map -> map.entrySet().stream()).collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue, Long::sum));
    // One part comes from source1, while the other parts come from the broadcast results of
    // source2.
    Map<Long, Long> expectedResult = LongStream.range(0, NUMBERS_TO_PRODUCE).boxed().collect(Collectors.toMap(Function.identity(), i -> 2L));
    assertThat(numberCountResultMap).isEqualTo(expectedResult);
}

