@Test
public void testGlobalFailureOnRestart() throws Exception {
    final MiniCluster miniCluster = MINI_CLUSTER_WITH_CLIENT_RESOURCE.getMiniCluster();
    final JobVertexID jobVertexId = new JobVertexID();
    final JobVertex jobVertex = new JobVertex("jobVertex", jobVertexId);
    jobVertex.setInvokableClass(FailingInvokable.class);
    jobVertex.addOperatorCoordinator(new SerializedValue<>(new FailingCoordinatorProvider(OperatorID.fromJobVertexID(jobVertexId))));
    jobVertex.setParallelism(1);
    final JobGraph jobGraph = JobGraphBuilder.newStreamingJobGraphBuilder().addJobVertices(Collections.singletonList(jobVertex)).build();
    RestartStrategyUtils.configureFixedDelayRestartStrategy(jobGraph, 1, Duration.ofHours(1L));
    miniCluster.submitJob(jobGraph).join();
    // We rely on waiting in restarting state (see the restart strategy above)
    CommonTestUtils.waitUntilCondition(() -> miniCluster.getJobStatus(jobGraph.getJobID()).join() == JobStatus.RESTARTING);
    FailingCoordinatorProvider.JOB_RESTARTING.countDown();
    assertThatFuture(getJobExceptions(jobGraph.getJobID(), MINI_CLUSTER_WITH_CLIENT_RESOURCE)).eventuallySucceeds();
    miniCluster.cancelJob(jobGraph.getJobID());
    CommonTestUtils.waitUntilCondition(() -> miniCluster.getJobStatus(jobGraph.getJobID()).join() == JobStatus.CANCELED);
    final JobExceptionsInfoWithHistory jobExceptions = getJobExceptions(jobGraph.getJobID(), MINI_CLUSTER_WITH_CLIENT_RESOURCE).get();
    // there should be exactly 1 root exception in the history from the failing vertex,
    // as the global coordinator failure should be treated as a concurrent exception
    assertThat(jobExceptions.getExceptionHistory().getEntries()).hasSize(1).allSatisfy(rootExceptionInfo -> assertThat(rootExceptionInfo.getStacktrace()).contains(FailingInvokable.localExceptionMsg).doesNotContain(FailingCoordinatorProvider.globalExceptionMsg)).allSatisfy(rootExceptionInfo -> assertThat(rootExceptionInfo.getConcurrentExceptions()).anySatisfy(exceptionInfo -> assertThat(exceptionInfo.getStacktrace()).contains(FailingCoordinatorProvider.globalExceptionMsg)));
}

