@Test
void testRescaleOnCheckpoint(@InjectMiniCluster MiniCluster miniCluster, @InjectClusterClient RestClusterClient<?> restClusterClient) throws Exception {
    final Configuration config = new Configuration();
    final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment(config);
    env.setParallelism(BEFORE_RESCALE_PARALLELISM);
    env.fromSequence(0, Integer.MAX_VALUE).sinkTo(new DiscardingSink<>());
    final JobGraph jobGraph = env.getStreamGraph().getJobGraph();
    final Iterator<JobVertex> jobVertexIterator = jobGraph.getVertices().iterator();
    assertThat(jobVertexIterator.hasNext()).as("There needs to be at least one JobVertex.").isTrue();
    final JobVertexID jobVertexId = jobVertexIterator.next().getID();
    final JobResourceRequirements jobResourceRequirements = JobResourceRequirements.newBuilder().setParallelismForJobVertex(jobVertexId, 1, AFTER_RESCALE_PARALLELISM).build();
    assertThat(jobVertexIterator.hasNext()).as("This test expects to have only one JobVertex.").isFalse();
    restClusterClient.submitJob(jobGraph).join();
    final JobID jobId = jobGraph.getJobID();
    try {
        LOG.info("Waiting for job {} to reach parallelism of {} for vertex {}.", jobId, BEFORE_RESCALE_PARALLELISM, jobVertexId);
        waitForRunningTasks(restClusterClient, jobId, BEFORE_RESCALE_PARALLELISM);
        LOG.info("Job {} reached parallelism of {} for vertex {}. Updating the vertex parallelism next to {}.", jobId, BEFORE_RESCALE_PARALLELISM, jobVertexId, AFTER_RESCALE_PARALLELISM);
        restClusterClient.updateJobResourceRequirements(jobId, jobResourceRequirements).join();
        // timeout to allow any unexpected rescaling to happen anyway
        Thread.sleep(REQUIREMENT_UPDATE_TO_CHECKPOINT_GAP.toMillis());
        // verify that the previous timeout didn't result in a change of parallelism
        LOG.info("Checking that job {} hasn't changed its parallelism even after some delay, yet.", jobId);
        waitForRunningTasks(restClusterClient, jobId, BEFORE_RESCALE_PARALLELISM);
        miniCluster.triggerCheckpoint(jobId);
        LOG.info("Waiting for job {} to reach parallelism of {} for vertex {}.", jobId, AFTER_RESCALE_PARALLELISM, jobVertexId);
        waitForRunningTasks(restClusterClient, jobId, AFTER_RESCALE_PARALLELISM);
        final int expectedFreeSlotCount = NUMBER_OF_SLOTS - AFTER_RESCALE_PARALLELISM;
        LOG.info("Waiting for {} slot(s) to become available due to the scale down.", expectedFreeSlotCount);
        waitForAvailableSlots(restClusterClient, expectedFreeSlotCount);
        LOG.info("{} free slot(s) detected. Finishing test.", expectedFreeSlotCount);
    } finally {
        restClusterClient.cancel(jobGraph.getJobID()).join();
    }
}

