    // Step 1
    combiner.combineWatermark(EventTimeExtension.EVENT_TIME_WATERMARK_DECLARATION.newWatermark(1), 0, outputWatermarks::add);
    checkOutputEventTimeWatermarkValues();
    // Step 2
    combiner.combineWatermark(EventTimeExtension.IDLE_STATUS_WATERMARK_DECLARATION.newWatermark(true), 1, outputWatermarks::add);
    checkOutputEventTimeWatermarkValues(1L);
    // Step 3
    combiner.combineWatermark(EventTimeExtension.EVENT_TIME_WATERMARK_DECLARATION.newWatermark(2), 0, outputWatermarks::add);
    checkOutputEventTimeWatermarkValues(1L, 2L);
