    combiner.combineWatermark(EventTimeExtension.IDLE_STATUS_WATERMARK_DECLARATION.newWatermark(false), 1, outputWatermarks::add);
    checkOutputEventTimeWatermarkValues(1L, 2L);
    // Step 5
    combiner.combineWatermark(EventTimeExtension.EVENT_TIME_WATERMARK_DECLARATION.newWatermark(3), 1, outputWatermarks::add);
    checkOutputEventTimeWatermarkValues(1L, 2L);
    // Step 6
    combiner.combineWatermark(EventTimeExtension.EVENT_TIME_WATERMARK_DECLARATION.newWatermark(4), 0, outputWatermarks::add);
    checkOutputEventTimeWatermarkValues(1L, 2L, 3L);
    checkOutputIdleStatusWatermarkValues();
}

