@Test
void testOneInputWindowFunctionUseWindowStateToAgg() throws Exception {
    NonKeyedPartitionStream<ValueWithTimestamp> source = getSource("source", 0, 0, true);
    OneInputStreamProcessFunction<ValueWithTimestamp, ValueWithTimestamp> windowProcessFunction = BuiltinFuncs.window(WindowStrategy.tumbling(Duration.ofSeconds(5)), new OneInputWindowStreamProcessFunction<ValueWithTimestamp, ValueWithTimestamp>() {

        private ValueStateDeclaration<Long> sumStateDeclaration = StateDeclarations.valueState("sum", TypeDescriptors.LONG);

        private ValueStateDeclaration<Long> countStateDeclaration = StateDeclarations.valueState("count", TypeDescriptors.LONG);

        @Override
        public Set<StateDeclaration> useWindowStates() {
            return Set.of(sumStateDeclaration, countStateDeclaration);
        }

        @Override
        public void onRecord(ValueWithTimestamp record, Collector<ValueWithTimestamp> output, PartitionedContext<ValueWithTimestamp> ctx, OneInputWindowContext<ValueWithTimestamp> windowContext) throws Exception {
            Optional<ValueState<Long>> countState = windowContext.getWindowState(countStateDeclaration);
            if (countState.isPresent() && countState.get().value() != null) {
                countState.get().update(countState.get().value() + 1);
            } else {
                countState.get().update(1L);
            }
            Optional<ValueState<Long>> sumState = windowContext.getWindowState(sumStateDeclaration);
            long sum = 0;
            if (sumState.isPresent() && sumState.get().value() != null) {
                sum = sumState.get().value();
            }
            sumState.get().update(sum + record.getValue());
        }

        @Override
        public void onTrigger(Collector<ValueWithTimestamp> output, PartitionedContext<ValueWithTimestamp> ctx, OneInputWindowContext<ValueWithTimestamp> windowContext) throws Exception {
            Optional<ValueState<Long>> countState = windowContext.getWindowState(countStateDeclaration);
            assertThat(countState.get().value()).isEqualTo(5);
            Optional<ValueState<Long>> sumState = windowContext.getWindowState(sumStateDeclaration);
            output.collect(new ValueWithTimestamp(sumState.get().value(), -1L));
        }
    });
    source.keyBy(x -> 0).process(windowProcessFunction).process(new TestCollectResultProcessFunction()).withParallelism(1).toSink(new WrappedSink<>(new DiscardingSink<>()));
    env.execute("testOneInputWindowFunctionUseWindowStateToAgg");
    assertThat(TestCollectResultProcessFunction.elementSum).isEqualTo(EXPECTED_ELEMENT_SUM_PER_SOURCE);
    assertThat(TestCollectResultProcessFunction.elementCount).isEqualTo(NUM_ELEMENT_PER_SOURCE / 5);
}

