@Test
public void testMetrics() throws Exception {
    StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
    int numSplits = Math.max(1, env.getParallelism() - 2);
    int numRecordsPerSplit = 10;
    // make sure all parallel instances have processed the same amount of records before
    // validating metrics
    SharedReference<CyclicBarrier> beforeBarrier = sharedObjects.add(new CyclicBarrier(numSplits + 1));
    SharedReference<CyclicBarrier> afterBarrier = sharedObjects.add(new CyclicBarrier(numSplits + 1));
    int stopAtRecord1 = 4;
    int stopAtRecord2 = numRecordsPerSplit - 1;
    env.fromSequence(0, numSplits - 1).<Long>flatMap((split, collector) -> LongStream.range(0, numRecordsPerSplit).forEach(collector::collect)).returns(BasicTypeInfo.LONG_TYPE_INFO).map(i -> {
        if (i % numRecordsPerSplit == stopAtRecord1 || i % numRecordsPerSplit == stopAtRecord2) {
            beforeBarrier.get().await();
            afterBarrier.get().await();
        }
        return i;
    }).sinkTo(TestSinkV2.<Long>newBuilder().setWriter(new MetricWriter()).build()).name(TEST_SINK_NAME);
    JobClient jobClient = env.executeAsync();
    final JobID jobId = jobClient.getJobID();
    beforeBarrier.get().await();
    assertSinkMetrics(jobId, stopAtRecord1, numSplits);
    afterBarrier.get().await();
    beforeBarrier.get().await();
    assertSinkMetrics(jobId, stopAtRecord2, numSplits);
    afterBarrier.get().await();
    jobClient.getJobExecutionResult().get();
}

@Test
public void testCommitterMetrics() throws Exception {
    final int numCommittables = 7;
    StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
    // make sure all parallel instances have processed the records once before validating
    // metrics
    SharedReference<CountDownLatch> beforeLatch = sharedObjects.add(new CountDownLatch(numCommittables));
    SharedReference<CountDownLatch> afterLatch = sharedObjects.add(new CountDownLatch(1));
    TestSinkV2<Long> sink = TestSinkV2.<Long>newBuilder().setCommitter(new MetricCommitter(beforeLatch, afterLatch), TestSinkV2.RecordSerializer::new).build();
    env.fromSequence(0, numCommittables - 1).returns(BasicTypeInfo.LONG_TYPE_INFO).sinkTo(sink).name(TEST_SINK_NAME);
    JobClient jobClient = env.executeAsync();
    final JobID jobId = jobClient.getJobID();
    // Run until every committer finished with 1 commit round - everything should be retried and
    // pending
    beforeLatch.get().await();
    assertSinkCommitterMetrics(jobId, ImmutableMap.of(MetricNames.ALREADY_COMMITTED_COMMITTABLES, 0L, MetricNames.FAILED_COMMITTABLES, 0L, MetricNames.RETRIED_COMMITTABLES, 7L, MetricNames.SUCCESSFUL_COMMITTABLES, 0L, MetricNames.TOTAL_COMMITTABLES, 7L, MetricNames.PENDING_COMMITTABLES, 7L));
    afterLatch.get().countDown();
    // Run until finished
    jobClient.getJobExecutionResult().get();
    assertSinkCommitterMetrics(jobId, ImmutableMap.of(MetricNames.ALREADY_COMMITTED_COMMITTABLES, 1L, MetricNames.FAILED_COMMITTABLES, 2L, MetricNames.RETRIED_COMMITTABLES, 10L, MetricNames.SUCCESSFUL_COMMITTABLES, 4L, MetricNames.TOTAL_COMMITTABLES, 7L, MetricNames.PENDING_COMMITTABLES, 0L));
}

