/**
 * Verify that the user-specified state backend is used even if checkpointing is disabled.
 */
@Test
public void testStateBackendWithoutCheckpointing() throws Exception {
    StreamExecutionEnvironment see = StreamExecutionEnvironment.getExecutionEnvironment();
    see.setParallelism(1);
    StateBackendUtils.configureStateBackendWithFactory(see, "org.apache.flink.test.streaming.runtime.StateBackendITCase$FailingStateBackendFactory");
    RestartStrategyUtils.configureNoRestartStrategy(see);
    see.fromData(new Tuple2<>("Hello", 1)).keyBy(x -> x.f0).map(new RichMapFunction<Tuple2<String, Integer>, String>() {

        private static final long serialVersionUID = 1L;

        @Override
        public void open(OpenContext openContext) throws Exception {
            super.open(openContext);
            getRuntimeContext().getState(new ValueStateDescriptor<>("Test", Integer.class));
        }

        @Override
        public String map(Tuple2<String, Integer> value) throws Exception {
            return value.f0;
        }
    }).print();
    try {
        see.execute();
        fail();
    } catch (JobExecutionException e) {
        assertTrue(ExceptionUtils.findThrowable(e, SuccessException.class).isPresent());
    }
}

@Test
public void testSequentialReading() throws Exception {
    StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
    env.setParallelism(1);
    DataStream<String> source0 = env.addSource(new TestStringSource("Source0", new String[] { "Hello-1", "Hello-2", "Hello-3", "Hello-4", "Hello-5", "Hello-6" }));
    DataStream<Integer> source1 = env.addSource(new TestIntegerSource("Source1", new Integer[] { 1, 2, 3 })).setParallelism(2);
    TestListResultSink<String> resultSink = new TestListResultSink<>();
    TestSequentialReadingStreamOperator twoInputStreamOperator = new TestSequentialReadingStreamOperator("Operator0");
    source0.connect(source1).transform("Custom Operator", BasicTypeInfo.STRING_TYPE_INFO, twoInputStreamOperator).addSink(resultSink);
    env.execute("Selective reading test");
    List<String> result = resultSink.getResult();
    List<String> expected1 = Arrays.asList("[Operator0-1]: [Source0-0]: Hello-1", "[Operator0-1]: [Source0-0]: Hello-2", "[Operator0-1]: [Source0-0]: Hello-3", "[Operator0-1]: [Source0-0]: Hello-4", "[Operator0-1]: [Source0-0]: Hello-5", "[Operator0-1]: [Source0-0]: Hello-6");
    List<String> expected2 = Arrays.asList("[Operator0-2]: 1", "[Operator0-2]: 2", "[Operator0-2]: 3", "[Operator0-2]: 2", "[Operator0-2]: 4", "[Operator0-2]: 6");
    Collections.sort(expected2);
    assertEquals(expected1.size() + expected2.size(), result.size());
    assertEquals(expected1, result.subList(0, expected1.size()));
    List<String> result2 = result.subList(expected1.size(), expected1.size() + expected2.size());
    Collections.sort(result2);
    assertEquals(expected2, result2);
}

