@Test
void testTerminationWaitsOnContainerStopSuccess() throws Exception {
    new Context() {

        {
            final CompletableFuture<ContainerId> containerIdFuture = new CompletableFuture<>();
            testingYarnNMClientAsyncBuilder.setStopContainerAsyncConsumer((containerId, ignored, callbackHandler) -> containerIdFuture.complete(containerId));
            resetYarnNodeManagerClientFactory();
            runTest(() -> {
                // acquire a resource so we have something to release
                final CompletableFuture<YarnWorkerNode> yarnWorkerFuture = runInMainThread(() -> getDriver().requestResource(testingTaskExecutorProcessSpec)).thenCompose(Function.identity());
                resourceManagerClientCallbackHandler.onContainersAllocated(ImmutableList.of(testingContainer));
                final YarnWorkerNode worker = yarnWorkerFuture.get();
                // release the resource -- it will be blocked
                // terminate driver this should wait on the callback
                final CompletableFuture<Void> driverHasTerminatedFuture = runInMainThread(() -> {
                    getDriver().releaseResource(worker);
                    getDriver().terminate();
                });
                assertThatThrownBy(() -> driverHasTerminatedFuture.get(20, TimeUnit.MILLISECONDS)).isInstanceOf(TimeoutException.class);
                nodeManagerClientCallbackHandler.onContainerStopped(containerIdFuture.get());
                // wait for completion of termination
                // if this blocks forever, then our implementation is wrong
                driverHasTerminatedFuture.get();
            });
        }
    };
}

