    assertThat(DeployParser.parseDeployOutput(Stream.of("[INFO] --- maven-deploy-plugin:2.8.2:deploy (default-deploy) @ flink-parent ---", "[INFO] Using alternate deployment repository.../tmp/flink-validation-deployment"))).containsExactly("flink-parent");
}

@Test
void testParseDeployOutputDetectsSkippedDeployments() {
    assertThat(DeployParser.parseDeployOutput(Stream.of("[INFO] --- maven-deploy-plugin:2.8.2:deploy (default-deploy) @ flink-parent ---", "[INFO] Skipping artifact deployment"))).isEmpty();
}

@Test
void testParseNoticeFileCommonPath() {
    final String module = "some-module";
    final Dependency dependency1 = Dependency.create("groupId1", "artifactId1", "version1", null);
    final Dependency dependency2 = Dependency.create("groupId2", "artifactId2", "version2", "classifier2");
    final Dependency dependency3 = Dependency.create("org.codehaus.woodstox", "stax2-api", "4.2.1", null);
    final List<String> noticeContents = Arrays.asList(module, "", "Some text about the applicable license", "- groupId1:artifactId1:version1", "- groupId2:artifactId2:classifier2:version2", "- org.codehaus.woodstox:stax2-api:4.2.1 (https://github.com/FasterXML/stax2-api/tree/stax2-api-4.2.1)", "", "some epilogue");
    assertThat(NoticeParser.parseNoticeFile(noticeContents)).hasValueSatisfying(contents -> {
        assertThat(contents.getNoticeModuleName()).isEqualTo(module);
        assertThat(contents.getDeclaredDependencies()).containsExactlyInAnyOrder(dependency1, dependency2, dependency3);
    });
}

@Test
void testParseNoticeFileBundlesPath() {
    final String module = "some-module";
    final Dependency dependency = Dependency.create("groupId", "artifactId", "version", "classifier");
    final List<String> noticeContents = Arrays.asList(module, "", "Something bundles \"groupId:artifactId:classifier:version\"");
    assertThat(NoticeParser.parseNoticeFile(noticeContents)).hasValueSatisfying(contents -> {
        assertThat(contents.getNoticeModuleName()).isEqualTo(module);
        assertThat(contents.getDeclaredDependencies()).containsExactlyInAnyOrder(dependency);
    });
}

@Test
void testParseNoticeFileMalformedDependencyIgnored() {
    final String module = "some-module";
    final Dependency dependency = Dependency.create("groupId", "artifactId", "version", null);
    final List<String> noticeContents = Arrays.asList(module, "- " + dependency, "- a:b");
    assertThat(NoticeParser.parseNoticeFile(noticeContents)).hasValueSatisfying(contents -> {
        assertThat(contents.getNoticeModuleName()).isEqualTo(module);
        assertThat(contents.getDeclaredDependencies()).containsExactlyInAnyOrder(dependency);
    });
}

@Test
void testParsing() {
    final Map<String, Set<Dependency>> dependenciesByModule = ShadeParser.parseShadeOutput(getTestDependencyCopy());
    assertThat(dependenciesByModule).containsOnlyKeys("m1", "m2");
    assertThat(dependenciesByModule.get("m1")).containsExactlyInAnyOrder(Dependency.create("external", "dependency1", "2.1", null), Dependency.create("external", "dependency4", "2.4", "classifier"));
    assertThat(dependenciesByModule.get("m2")).containsExactlyInAnyOrder(Dependency.create("internal", "m1", "1.1", null));
}

